window.UNITE_DATA=[{"name":"Cinderace","slug":"cinderace","role":"Penyerang","damage":"Physical","range":"Ranged","difficulty":"Pemula","evolutions":"Scorbunny (Lv1) → Raboot (Lv5) → Cinderace (Lv7)","tagline":"Ranged auto-attacker lincah yang hidup dari boosted attack dan kiting; lemah di awal, monster di late game.","passive":{"name":"Blaze","desc":"Setiap habis pakai move, basic attack berikutnya langsung jadi boosted attack. Musuh yang kena serangan dapat 'cinder'; kalau terus dipukul, cinder-nya meledak jadi damage tambahan. Saat HP lo setengah atau kurang, crit rate dan attack speed naik sebentar."},"basicAttack":"Basic attack ranged, tiap serangan ketiga jadi boosted attack yang lebih sakit. Boosted juga bisa dipancing instan lewat passive Blaze: tekan move apa pun, lalu langsung auto.","lanes":["Jungle","Top","Bottom"],"laneNote":"Jungle paling enak karena bisa farm aman sampai Lv7 tanpa diganggu; Top oke kalau jungler tim udah ada. Bottom paling berat karena early game lo lemah.","earlyGame":"Menit 0-2 lo cuma Scorbunny yang rapuh: fokus last-hit wild Pokémon pakai Ember + boosted, jangan ladenin trade panjang. Kalau kena gank, mundur ke goal zone atau pakai Low Sweep buat jaga jarak. Target: cepat Lv5 (Raboot) dan Lv7 (Cinderace) sebelum fight serius.","powerSpike":"Lv7 (evolusi + Pyro Ball/Blaze Kick) adalah spike pertama; Lv9 (Unite) dan Lv11 (upgrade slot 1) bikin lo jadi carry sungguhan.","slot1":{"base":{"name":"Ember","level":1,"desc":"Tembak api ke musuh, kasih burn dan nurunin Attack mereka sebentar; poke ranged utama di early."},"choices":[{"name":"Pyro Ball","level":7,"upgradeLevel":11,"desc":"Tendang bola api jarak jauh ke arah yang dituju, damage tinggi plus burn; bisa nembus dinding tipis.","when":"Tekan buat poke musuh yang lagi mundur, nge-secure objective dari jauh, atau buka fight sebelum lawan nyampe ke lo. Selalu ikuti dengan boosted attack (Blaze).","avoid":"Jangan buang Pyro Ball ke tank yang lagi full HP di depan kalau carry musuh ada di belakang; dan jangan tembak asal, skillshot ini ada cooldown-nya.","upgradeNote":"Lv11: kalau Pyro Ball kena, cooldown Flame Charge/Feint dipotong, jadi lo lebih sering bisa reposisi."},{"name":"Blaze Kick","level":7,"upgradeLevel":11,"desc":"Lompat tendang api ke target: selalu critical hit, dorong musuh, dan lo invincible sebentar selama animasi.","when":"Tekan saat lo mau burst satu target yang HP-nya udah tipis, atau buat dodge CC/ult musuh (invincible frame-nya berguna).","avoid":"Jangan Blaze Kick masuk ke tengah 3 musuh kalau lo nggak punya Feint/Eject buat keluar; ini move melee yang nempatin lo di garis depan.","upgradeNote":"Lv11: attack speed naik setelah move kena, cocok buat auto-attack build."}]},"slot2":{"base":{"name":"Low Sweep","level":1,"desc":"Tendangan rendah jarak dekat yang nurunin movement speed musuh; alat kabur/kejar di early."},"choices":[{"name":"Flame Charge","level":8,"upgradeLevel":13,"desc":"Dash ke arah yang dipilih sambil kasih damage ke musuh yang dilewati, lalu boosted attack berikutnya ikut nge-slow.","when":"Pakai buat ngejar target, reposisi cepat, atau ngelewatin dinding tipis saat kabur; dash-nya pendek jadi hitung jaraknya.","avoid":"Jangan dash maju ke arah musuh cuma buat damage kecil kalau lo belum punya jalan keluar; ini mobility, bukan nuke.","upgradeNote":"Lv13: boosted attack setelah dash juga nurunin movement speed musuh, kiting jadi lebih gampang."},{"name":"Feint","level":8,"upgradeLevel":13,"desc":"Lo invincible sebentar dan movement speed naik; semua damage dan CC nggak masuk selama durasinya.","when":"Tekan pas lihat ult musuh atau CC besar datang (Snorlax, Blastoise, Gengar), atau buat lewatin tim musuh saat kabur.","avoid":"Jangan tekan Feint cuma buat jalan lebih cepat ke lane; simpen buat dodge burst, dan jangan tekan kecepetan sebelum ult lawan keluar.","upgradeNote":"Lv13: setelah Feint, basic attack yang kena musuh ngembaliin HP lo (maksimal 3 kali)."}]},"unite":{"name":"Blazing Bicycle Kick","level":9,"desc":"Bikin bola api raksasa dan tendang ke area target; meledak kasih damage area besar, dan kalau kena movement speed lo naik.","when":"Pakai buat finishing musuh yang numpuk di objective (Rayquaza/Regieleki) atau buat burst carry musuh yang udah kena poke. Bagus juga buat secure last hit objective dari jauh.","avoid":"Jangan buang ke tank full HP atau pas semua musuh udah menyebar; delay-nya cukup buat musuh keluar dari area."},"builds":[{"name":"Pyro Ball + Feint — Sniper Aman","moves":["Pyro Ball","Feint"],"recommended":true,"style":"Kiting dari belakang, poke pakai Pyro Ball + boosted, Feint buat dodge semua CC; paling aman buat solo queue.","heldItems":[{"name":"Muscle Band","why":"Basic attack lo adalah damage utama; Muscle Band nambah damage per auto berdasarkan HP musuh."},{"name":"Scope Lens","why":"Crit rate dan crit damage naik, sinergi sama Blaze yang nambah crit saat HP rendah."},{"name":"Attack Weight","why":"Nambah Attack permanen tiap score; Cinderace gampang nyelip score di jungle/lane."}],"battleItem":{"name":"Eject Button","why":"Reposisi instan buat keluar dari gank; Feint + Eject bikin lo hampir mustahil ditangkep."},"combo":["Pyro Ball ke target dari jarak maksimal (passive Blaze aktif).","Langsung boosted attack, lalu 2 auto biasa buat ledakin cinder.","Kalau musuh ngejar, Feint sambil tetap auto; Pyro Ball lagi begitu cooldown balik.","Tutup dengan Blazing Bicycle Kick kalau target udah di bawah setengah HP."],"comboNote":"Jangan tahan Pyro Ball: makin sering kena, makin sering Feint balik (upgrade Lv11)."},{"name":"Blaze Kick + Flame Charge — Agresif Jungle","moves":["Blaze Kick","Flame Charge"],"recommended":false,"style":"Auto-attack bruiser: masuk, burst satu target dengan crit terjamin, lalu dash keluar; cocok kalau lo jungle dan tim punya frontline.","heldItems":[{"name":"Muscle Band","why":"Tetap item wajib auto-attacker."},{"name":"Scope Lens","why":"Blaze Kick selalu crit; Scope Lens bikin crit damage makin sakit."},{"name":"Rapid-Fire Scarf","why":"Attack speed naik setelah auto, numpuk sama upgrade Blaze Kick Lv11."}],"battleItem":{"name":"X Speed","why":"Nggak punya Feint, jadi butuh speed buat kejar/kabur; rekomendasi game8 untuk build ini."},"combo":["Flame Charge mendekat ke target (atau lewatin dinding).","Boosted attack dari Blaze, lalu Blaze Kick saat target mau kabur atau ult musuh keluar.","Auto 2-3 kali buat ledakin cinder, Flame Charge lagi buat keluar.","Unite buat finishing kalau lebih dari satu musuh numpuk."],"comboNote":"Build ini melee-ish dan rapuh; tanpa Feint lo harus disiplin soal jalan keluar."}],"situations":{"gank":"Saat lo nge-gank: tunggu CC dari tim dulu, baru Pyro Ball + boosted ke target yang kena CC. Saat dikeroyok: Feint dulu (atau Flame Charge keluar), jangan coba fight balik sebelum tim datang.","escape":"Feint untuk nolak semua damage sambil jalan ke arah tim; Eject Button lewatin dinding; Flame Charge dash pendek. Jangan lari lurus di lane terbuka, lewati semak/dinding supaya musuh kehilangan vision.","objective":"Berdiri di belakang tank, tembak Pyro Ball ke Rayquaza/Regieleki hanya buat secure terakhir (damage-nya besar); selain itu fokus kill carry musuh yang mendekat. Simpan Feint buat ult musuh yang biasanya keluar di pit.","duel":"1v1 lo menang lawan hampir semua ranged sebelum mereka Lv9 asal jaga jarak: auto-boosted-auto, Pyro Ball pas mereka nggak bisa dodge. Lawan melee dive (Zeraora, Absol) jangan trade di tempat; kite mundur ke goal.","teamfight":"Posisi paling belakang, sejajar supporter. Prioritas: carry musuh yang masuk jangkauan, kalau nggak ada tembak frontline yang paling dekat biar cinder nambah. Jangan pernah jadi orang pertama yang masuk."},"mistakes":["Fight sebelum Lv7: Scorbunny/Raboot kalah trade sama hampir semua Pokémon.","Nahan Pyro Ball nunggu 'momen sempurna' padahal cooldown-nya pendek dan tiap hit ngisi Feint.","Buang Feint buat jalan cepat, terus nggak punya jawaban saat ult musuh keluar.","Lupa boosted attack setelah move: Blaze adalah sumber damage terbesar lo.","Berdiri sejajar frontline di teamfight dan kena CC pertama."],"counters":{"hardFor":[{"name":"Zoroark","why":"Burst melee dari semak yang bisa ngabisin lo sebelum Feint ditekan.","how":"Jalan dekat tim, simpan Feint, jangan farm di jungle musuh sendirian."},{"name":"Gengar","why":"Masuk cepat lewat Shadow Ball + Hex dan nge-reset kalau lo kena poison.","how":"Feint pas dia masuk, mundur ke tank; Gengar lemah saat Hex-nya miss."},{"name":"Darkrai","why":"Sleep dari jauh lalu burst; CC-nya ngunci lo sebelum sempat kite.","how":"Berdiri di belakang tank biar Dark Void kena mereka, Feint kalau lihat animasinya."},{"name":"Blaziken","why":"Dash berulang bikin lo nggak bisa jaga jarak.","how":"Tunggu dia buang dash, lalu Pyro Ball + boosted saat dia mundur."},{"name":"Mega Mewtwo X","why":"Dive tanky dengan burst dan CC.","how":"Jangan duel; poke dari jauh dan kabur kalau Mega aktif."}],"goodAgainst":[{"name":"Glaceon","why":"Lo lebih cepat dan bisa burst dia sebelum ice crystal-nya numpuk (game8 nyebut Cinderace sebagai counter Glaceon)."},{"name":"Venusaur","why":"Lambat dan pasif; lo bisa kite di luar jangkauan Sludge Bomb dan poke terus."},{"name":"Snorlax","why":"Tank lambat, cinder numpuk gampang, dan lo bisa kite di luar jangkauan Heavy Slam."}]},"cinderace":{"similarity":10,"note":"Tips lanjutan buat lo yang udah nyaman Cinderace: (1) Latih 'weaving': move → boosted → auto → auto, jangan pernah spam move tanpa auto di antaranya; cinder yang meledak itu damage gratis. (2) Hitung Feint sebagai 'ult counter', bukan speed boost: ambil kebiasaan nunggu animasi ult lawan 0,5 detik sebelum tekan. (3) Setelah Lv11 Pyro Ball, mainkan loop Pyro Ball → Feint lebih agresif karena cooldown Feint dipotong tiap hit. (4) Di patch 1.22.1.5 (Mar 2026) Blaze, boosted, dan Ember dapat buff; early game lo sedikit lebih bertenaga, tapi tetap jangan trade sebelum Lv5."},"sources":["https://serebii.net/pokemonunite/pokemon/cinderace.shtml","https://bulbapedia.bulbagarden.net/wiki/Cinderace_(UNITE)","https://game8.co/games/Pokemon-UNITE/archives/335482","https://www.pokemonunite.jp/en/topics/battle/20260304-1/","https://game8.co/games/Pokemon-UNITE/archives/527073","https://www.pockettactics.com/pokemon-unite/cinderace"],"confidence":"high","notes":"Nama move, level (Ember/Low Sweep Lv1, Pyro Ball/Blaze Kick Lv7, Flame Charge/Feint Lv8, Unite Lv9, upgrade Lv11/13) cocok antara Serebii dan Bulbapedia. Patch terbaru: 1.19.1.2 (Jun 2025) HP naik + animasi auto lebih cepat; 1.22.1.5 (Mar 2026) Blaze +17% damage, boosted +8%, Ember +15%, Low Sweep cooldown turun. Tidak ada perubahan Cinderace di patch Agustus/September 2026. Build: game8 (A rank) merekomendasikan Blaze Kick + Flame Charge (jungle) dan Pyro Ball + Flame Charge; versi Pyro Ball + Feint di sini adalah kombinasi klasik solo-queue yang lebih aman, pilihan lane/aggresivitas tergantung tim. Counter list dari game8.","image":"img/cinderace.webp","status":"Owned"},{"name":"Glaceon","slug":"glaceon","role":"Penyerang","damage":"Special","range":"Ranged","difficulty":"Menengah","evolutions":"Eevee (Lv1) → Glaceon (Lv4)","tagline":"Special attacker yang nabung 'ice crystal' lewat basic attack lalu ngelepasnya sebagai burst; punya satu kartu anti-CC gratis.","passive":{"name":"Snow Cloak","desc":"Saat lo kena hindrance (CC), CC-nya dibatalin dan lo masuk stealth + invincible sebentar. Cooldown-nya panjang, jadi anggap ini 'Feint otomatis' yang cuma keluar sekali per fight besar."},"basicAttack":"Basic attack ranged; tiap serangan ketiga jadi boosted yang lebih sakit dan ngasih ice crystal (maks 8). Crystal ini amunisi buat Icicle Spear/Icy Wind, jadi auto bukan cuma damage tapi juga 'ngisi peluru'.","lanes":["Jungle","Top","Bottom"],"laneNote":"Jungle disarankan karena Glaceon evolusi di Lv4, jadi dia cepat kuat dan bisa gank duluan; Top/Bottom juga oke sebagai carry yang dijaga.","earlyGame":"Eevee cuma sampai Lv4, jadi farm 2 camp pertama atau 2 wild pertama di lane dan lo udah Glaceon. Setelah evolusi, trade agresif pakai auto + Swift/Tail Whip ke lawan yang masih belum evolusi. Jangan buang Snow Cloak buat hal kecil.","powerSpike":"Lv4 (evolusi + Icicle Spear/Icy Wind) spike super awal; Lv6 slot 2 melengkapi; Lv8 Unite; Lv10 upgrade slot 1 (damage % max HP).","slot1":{"base":{"name":"Swift","level":1,"desc":"Bikin bintang yang ikut nembak saat basic attack, damage tambahan di early."},"choices":[{"name":"Icicle Spear","level":4,"upgradeLevel":10,"desc":"Lepas semua ice crystal yang lo simpan beruntun ke target; tiap crystal pecah jadi damage area kecil. Lo tetap bisa gerak sambil nembak.","when":"Tekan saat crystal udah banyak (idealnya penuh) dan target nggak bisa kabur; sambil nembak, jalan mundur buat kite.","avoid":"Jangan tekan dengan 1-2 crystal cuma karena cooldown-nya ada; damage-nya proporsional sama jumlah crystal.","upgradeNote":"Lv10: tiap crystal juga ngasih damage tambahan sebesar persentase max HP musuh, jadi makin sakit ke tank."},{"name":"Icy Wind","level":4,"upgradeLevel":10,"desc":"Dash pendek, lalu basic attack berikutnya ngelepas crystal yang nge-slow musuh; damage lewat auto, bukan channel.","when":"Tekan buat reposisi/dash lalu langsung auto ke target; cocok kalau lo lebih suka main mobile dan nge-slow musuh.","avoid":"Jangan dash maju ke arah musuh yang masih punya CC; dash-nya pendek dan Snow Cloak cuma sekali.","upgradeNote":"Lv10: crystal yang dilepas juga ngasih damage persentase max HP."}]},"slot2":{"base":{"name":"Tail Whip","level":1,"desc":"Serang target: Defense, Sp. Def, dan movement speed-nya turun."},"choices":[{"name":"Ice Shard","level":6,"upgradeLevel":12,"desc":"Movement speed dan attack speed naik sebentar; basic attack lo ngelempar bongkahan es yang ngasih crystal lebih cepat.","when":"Tekan di awal fight buat ngisi crystal cepat (auto beberapa kali), lalu Icicle Spear; juga buat kite karena ada speed.","avoid":"Jangan tekan setelah crystal udah penuh; itu buang-buang generator crystal lo.","upgradeNote":"Lv12: attack speed juga naik selama efeknya, isi crystal makin cepat."},{"name":"Freeze-Dry","level":6,"upgradeLevel":12,"desc":"Tembak udara beku yang ninggalin zona es: musuh di dalamnya di-slow dan bisa freeze; ledakannya juga ngasih damage.","when":"Tekan ke area yang bakal dilewati musuh (pit objective, jalur kabur) atau ke musuh yang nempel buat freeze lalu auto/Icy Wind.","avoid":"Jangan tembak ke area kosong 'buat jaga-jaga'; cooldown-nya cukup panjang dan ini CC utama lo.","upgradeNote":"Lv12: tiap musuh yang kena ledakannya ngasih lo 1 ice crystal."}]},"unite":{"name":"Glacial Stage","level":8,"desc":"Lompat tinggi dan bikin arena es: damage ke musuh di dalamnya, lo dapat shield, movement/attack speed naik, dan crystal keisi cepat selama di arena.","when":"Pakai buat buka fight di objective (crystal langsung penuh → Icicle Spear) atau sebagai 'panic button' karena ada shield + speed.","avoid":"Jangan pakai cuma buat damage ult-nya; nilainya ada di crystal dan buff, jadi harus langsung disusul auto + Icicle Spear."},"builds":[{"name":"Icicle Spear + Ice Shard — Burst Standar","moves":["Icicle Spear","Ice Shard"],"recommended":true,"style":"Ice Shard buat ngisi crystal cepat, Icicle Spear buat ngeluarin semuanya; sederhana dan paling umum.","heldItems":[{"name":"Wise Glasses","why":"Sp. Atk flat buat auto dan tiap crystal."},{"name":"Slick Spoon","why":"Nembus Sp. Def, Icicle Spear tetap sakit ke tank."},{"name":"Energy Amplifier","why":"Unite lebih sering dan damage naik setelah Unite; Glacial Stage adalah engine burst lo."}],"battleItem":{"name":"Eject Button","why":"Lo nggak punya dash di build ini; Eject + Snow Cloak jadi escape lo."},"combo":["Ice Shard → auto 3-4 kali (crystal naik cepat).","Icicle Spear ke target sambil jalan mundur.","Lanjut auto buat boosted + crystal lagi.","Glacial Stage kalau fight panjang: crystal penuh lagi → Icicle Spear kedua."],"comboNote":"Setelah Icicle Spear, lo 'kosong'; mundur sebentar sambil auto sebelum masuk lagi."},{"name":"Icy Wind + Freeze-Dry — Mobile Kiter","moves":["Icy Wind","Freeze-Dry"],"recommended":false,"style":"Lebih mobile dan punya CC: Freeze-Dry buat slow/freeze, Icy Wind dash + auto crystal; cocok buat yang suka kiting aktif.","heldItems":[{"name":"Slick Spoon","why":"Penetrasi Sp. Def buat auto crystal."},{"name":"Shell Bell","why":"Heal tiap move kena, cooldown dipotong; lo lebih sering pakai move di build ini."},{"name":"Energy Amplifier","why":"Unite lebih sering, dan Glacial Stage ngisi crystal buat Icy Wind."}],"battleItem":{"name":"X Speed","why":"Nambah kiting; Eject Button juga valid (saran game8/unite-guide)."},"combo":["Freeze-Dry ke jalur musuh (slow/freeze).","Icy Wind dash ke posisi aman → auto yang ngelepas crystal.","Auto terus buat boosted + crystal, ulangi Icy Wind saat cooldown balik.","Glacial Stage saat musuh numpuk di zona Freeze-Dry."],"comboNote":"Damage-nya lebih merata, bukan satu burst; sabar kite."}],"situations":{"gank":"Saat nge-gank: datang dengan crystal udah penuh (farm dulu), Freeze-Dry/auto dulu, baru Icicle Spear saat tim ngunci target. Saat dikeroyok: biarin Snow Cloak nolak CC pertama, langsung Eject/Icy Wind keluar, jangan nunggu CC kedua.","escape":"Snow Cloak (otomatis saat kena CC: stealth + invincible), Eject Button, Icy Wind (dash pendek), Ice Shard (speed). Kabur ke semak saat stealth Snow Cloak aktif biar musuh kehilangan lo.","objective":"Farm crystal sampai penuh sebelum timer boss; berdiri di belakang tank. Glacial Stage ke pit saat fight pecah, auto buat crystal, Icicle Spear ke boss buat secure atau ke carry musuh. Freeze-Dry di jalur masuk pit.","duel":"1v1: jangan buka dengan Icicle Spear kosong. Auto dulu (Ice Shard aktif), kite, lalu Icicle Spear saat lawan commit. Lawan assassin: tunggu dia buang dash dulu, Snow Cloak nolak CC-nya, baru burst.","teamfight":"Backline. Prioritas target: carry musuh yang masuk jangkauan; kalau nggak ada, Icicle Spear ke tank karena upgrade Lv10 ngasih damage % max HP. Jangan masuk arena Glacial Stage sendirian tanpa tank."},"mistakes":["Icicle Spear dengan crystal sedikit: damage-nya kecil banget.","Lupa Snow Cloak lagi cooldown dan nekat nerjang musuh yang punya CC.","Ice Shard saat crystal udah penuh (buang generator).","Berdiri terlalu dekat frontline; Glaceon rapuh banget.","Pakai Glacial Stage sebagai nuke, bukan sebagai pengisi crystal + shield."],"counters":{"hardFor":[{"name":"Talonflame","why":"Dive dari udara dan burst sebelum crystal lo numpuk.","how":"Jalan dekat tank, simpan Eject, auto dia saat dia mendarat."},{"name":"Cinderace","why":"Lebih cepat dan DPS auto-nya ngabisin lo di trade panjang.","how":"Jangan trade auto lawan auto; Freeze-Dry/slow dulu, burst Icicle Spear saat dia Feint-nya udah kepake."},{"name":"Urshifu","why":"Combo gap-closer + burst dan CC ganda (Snow Cloak cuma nolak satu).","how":"Mundur sebelum dia dekat, tunggu dia buang dash lalu Eject."},{"name":"Zeraora","why":"Dash berulang dan burst melee ke backline.","how":"Kite ke arah tank, Snow Cloak nolak CC-nya lalu Icicle Spear saat dia di-peel (inferensi mekanik)."}],"goodAgainst":[{"name":"Snorlax","why":"Tank lambat; Icicle Spear Lv10 ngasih damage % max HP dan Snow Cloak nolak Yawn/Block."},{"name":"Decidueye","why":"Sama-sama ranged tapi lo punya Snow Cloak + burst yang lebih cepat kalau crystal penuh."},{"name":"Venusaur","why":"Lambat dan nggak punya escape; lo kite dan burst dia (inferensi mekanik)."}]},"cinderace":{"similarity":7,"note":"Kiting dan auto-attack dari Cinderace langsung kepake, dan boosted attack bahkan lebih penting karena ngasih crystal. Yang beda: damage lo bukan dari tiap auto, tapi dari ledakan Icicle Spear setelah nabung; jadi bawa kesabaran 'ngisi' dulu. Feint lo digantikan Snow Cloak yang otomatis dan cuma sekali: lo nggak bisa milih kapan keluar, jadi jangan pancing CC kecil kalau ult musuh belum keluar."},"sources":["https://serebii.net/pokemonunite/pokemon/glaceon.shtml","https://bulbapedia.bulbagarden.net/wiki/Glaceon_(UNITE)","https://game8.co/games/Pokemon-UNITE/archives/382859","https://unite-guide.com/pokemon/glaceon/","https://community.pokemon.com/en-us/discussion/21267/the-roar-of-sea-and-sky-ver-1-21-1-2-patch-notes"],"confidence":"medium","notes":"Perbedaan antar sumber: Unite move Glacial Stage Lv8 (Bulbapedia, game8) vs Lv9 (ringkasan Serebii); dipakai Lv8 karena konsisten dengan evolusi Lv4. Level lain cocok: Swift/Tail Whip Lv1, Icicle Spear/Icy Wind Lv4 (upgrade Lv10), Ice Shard/Freeze-Dry Lv6 (upgrade Lv12). Patch: 1.21.1.2 (Des 2025) buff durability (stat naik) dan cooldown move dipotong; sebelumnya 1.14.1.5 nerf Ice Shard attack speed dan Icicle Spear+ damage. Tidak ada perubahan di patch Mar/Agu/Sep 2026. Build dari game8 dan unite-guide (serupa). Counter list hard dari game8; Zeraora dan sebagian goodAgainst adalah inferensi mekanik.","image":"img/glaceon.webp","status":"Owned"},{"name":"Greninja","slug":"greninja","role":"Penyerang","damage":"Physical","range":"Ranged","difficulty":"Ahli","evolutions":"Froakie (Lv1) → Frogadier (Lv5) → Greninja (Lv7)","tagline":"Attacker hibrida ranged/melee ala assassin: nipu pakai decoy, nyelinap, lalu finishing target yang HP-nya tipis.","passive":{"name":"Torrent","desc":"Saat HP lo setengah atau kurang, Attack dan movement speed naik. Artinya Greninja justru paling berbahaya saat kelihatan sekarat, tapi jangan jadi alasan buat nekat."},"basicAttack":"Basic attack berubah tergantung jarak: dari jauh (ranged) kurangi cooldown Bubble/Water Shuriken/Surf dan boosted-nya nge-slow; dari dekat (melee) damage-nya makin besar makin tipis HP musuh. Tiap serangan ketiga jadi boosted.","lanes":["Jungle","Top","Bottom"],"laneNote":"Jungle paling cocok: stealth dan mobility bikin gank enak, dan lo butuh level cepat. Top oke kalau ada jungler lain; Bottom berat.","earlyGame":"Froakie lemah: farm pakai Bubble dari jauh dan Substitute buat kabur, jangan trade lama. Di jungle, bersihin camp sampai Lv5 lalu cari gank yang gampang; kalau lane, last-hit pakai auto ranged dan hindari duel. Target utama: Lv7 secepat mungkin.","powerSpike":"Lv7 (Greninja + Water Shuriken/Surf) spike utama; Lv9 Unite buat teamfight; Lv11 upgrade slot 1 bikin sustain-nya nyata.","slot1":{"base":{"name":"Bubble","level":1,"desc":"Tembak gelembung ke area, musuh yang kena jadi lambat; poke ranged early."},"choices":[{"name":"Water Shuriken","level":7,"upgradeLevel":11,"desc":"Lempar beberapa shuriken air beruntun ke target; tiap hit ngembaliin HP sedikit dan nambah movement speed lo.","when":"Tekan dari jarak aman buat poke, sustain, dan kite; bagus buat clear objective dan farm cepat. Spam begitu cooldown balik.","avoid":"Jangan nembak dari jarak terlalu dekat kalau nggak perlu; build ini ranged, jangan ikut-ikutan masuk melee.","upgradeNote":"Lv11: jumlah shuriken nambah, jadi damage dan heal per cast lebih besar."},{"name":"Surf","level":7,"upgradeLevel":11,"desc":"Naik ombak maju, damage area dekat, heal lo, dan damage lebih besar ke musuh ber-HP rendah; kalau dapet KO cooldown-nya reset.","when":"Tekan buat finishing target yang udah di bawah setengah HP, atau buat dodge sambil reposisi. Idealnya dari stealth Smokescreen.","avoid":"Jangan buka fight pakai Surf ke musuh full HP di tengah tim lawan; tanpa reset lo bakal nyangkut di depan.","upgradeNote":"Lv11: HP yang dipulihkan Surf naik."}]},"slot2":{"base":{"name":"Substitute","level":1,"desc":"Dash maju sambil ninggalin boneka decoy yang narik perhatian; alat kabur/nipu early."},"choices":[{"name":"Double Team","level":5,"upgradeLevel":13,"desc":"Dash dan bikin beberapa bayangan ilusi yang ikut nyerang dan ngalihin target musuh; boneka-nya juga bisa narik serangan AI dan wild Pokémon.","when":"Tekan saat musuh mau fokus lo di teamfight, buat kabur, atau buat nambah DPS di objective (ilusi ikut mukul).","avoid":"Jangan tekan pas nggak ada musuh di sekitar cuma buat jalan; cooldown-nya panjang dan ini escape utama lo.","upgradeNote":"Lv13: cooldown Double Team berkurang."},{"name":"Smokescreen","level":5,"upgradeLevel":13,"desc":"Lo masuk stealth dan movement speed naik; basic attack berikutnya jadi boosted dan Attack naik saat keluar stealth.","when":"Tekan buat setup gank (jalan nggak kelihatan ke carry musuh) atau buat putus kejar-kejaran saat kabur.","avoid":"Jangan masuk stealth di depan musuh yang punya AoE/reveal, dan jangan tekan sebelum area-nya aman; stealth bukan invincible.","upgradeNote":"Lv13: durasi/efek stealth dan buff Attack-nya ditingkatkan (cooldown dipotong per 1.22.1.5)."}]},"unite":{"name":"Waterburst Shuriken","level":9,"desc":"Lempar shuriken air raksasa ke area: damage + slow, lalu meledak kasih damage lagi dan ngelempar musuh; lo bisa lompat mundur setelahnya.","when":"Pakai ke 2+ musuh yang numpuk di objective atau buat ngunci carry yang kabur; ledakannya cocok buat secure Regieleki/Rayquaza.","avoid":"Jangan buang ke satu tank full HP; dan jangan pakai saat musuh udah menyebar, delay ledakannya cukup lama."},"builds":[{"name":"Water Shuriken + Double Team — Ranged Carry","moves":["Water Shuriken","Double Team"],"recommended":true,"style":"Main kayak ranged carry: kite dari belakang, spam shuriken, Double Team kalau ditarget; paling mirip Cinderace.","heldItems":[{"name":"Muscle Band","why":"Basic attack lo sering dan ranged; item inti auto-attacker."},{"name":"Attack Weight","why":"Greninja gampang nyelip score berkat mobility; Attack permanen nambah tiap goal."},{"name":"Focus Band","why":"Sustain tambahan saat HP rendah, sinergi sama Torrent yang aktif di HP setengah."}],"battleItem":{"name":"X Attack","why":"Burst damage dan attack speed sesaat, rekomendasi game8; Eject Button juga valid kalau tim lo kurang peel."},"combo":["Auto ranged ke target buat potong cooldown Water Shuriken.","Water Shuriken → boosted attack → auto.","Kalau musuh ngejar: Double Team, lalu lanjut auto dari belakang ilusi.","Waterburst Shuriken ke kerumunan, lompat mundur, lanjut shuriken."],"comboNote":"Rhythm-nya mirip Cinderace: move, boosted, auto, ulangi."},{"name":"Surf + Smokescreen — Assassin Jungle","moves":["Surf","Smokescreen"],"recommended":false,"style":"Masuk dari stealth, burst target tipis, reset Surf lewat KO, keluar lagi; butuh jam terbang dan koordinasi.","heldItems":[{"name":"Muscle Band","why":"Melee auto-nya makin sakit ke musuh ber-HP rendah."},{"name":"Scope Lens","why":"Crit nambah burst saat lo keluar stealth dengan Attack naik."},{"name":"Attack Weight","why":"Score cepat lewat stealth, Attack permanen numpuk."}],"battleItem":{"name":"X Attack","why":"Burst tambahan saat keluar stealth; Eject Button kalau lo sering ketangkep."},"combo":["Smokescreen, jalan ke carry musuh dari belakang.","Keluar stealth dengan boosted attack (Attack naik) → auto melee.","Surf saat target di bawah setengah HP; kalau KO, Surf reset.","Lanjut ke target berikutnya atau Unite buat lompat keluar."],"comboNote":"Kalau target nggak mati setelah Surf, keluar; jangan paksa trade di tengah tim lawan."}],"situations":{"gank":"Saat nge-gank: datang dari semak/stealth, tunggu target buang mobility-nya, baru Surf/Shuriken + boosted. Saat dikeroyok: Double Team/Smokescreen dulu, kabur ke arah tim, jangan ngandelin Torrent buat fight balik.","escape":"Double Team bikin musuh salah target, Smokescreen bikin lo hilang; keduanya ada dash. Lompatan setelah Unite juga escape darurat. Kabur lewat dinding/semak supaya ilusi atau stealth kerja.","objective":"Build Shuriken: diri di belakang, spam shuriken ke boss dan carry musuh; Unite saat musuh numpuk. Build Surf: jaga di sisi, tunggu fight kacau lalu Surf ke yang tipis; Surf reset cocok buat ngejar sisa-sisa.","duel":"Dari jauh kite pakai auto ranged + Shuriken; kalau musuh masuk dan HP-nya udah di bawah setengah, auto melee lo lebih sakit. Lawan assassin (Zeraora, Absol) tekan Double Team dulu buat ngalihin burst mereka.","teamfight":"Backline di build Shuriken, flank di build Surf. Target: carry/supporter musuh yang paling tipis. Jangan masuk sebelum CC musuh (Snorlax, Slowbro) sudah dibuang."},"mistakes":["Nekat fight pas HP rendah karena 'Torrent aktif': buff-nya kecil dibanding risiko mati.","Buang Double Team/Smokescreen sebelum fight mulai, terus nggak ada escape saat ditarget.","Lupa auto ranged buat ngisi cooldown Shuriken, malah spam melee.","Buka fight pakai Surf ke target full HP dan nyangkut di depan.","Farm jungle musuh sendirian tanpa vision di early."],"counters":{"hardFor":[{"name":"Gengar","why":"Burst dan reset Hex ngabisin lo sebelum ilusi berguna.","how":"Jalan dekat tim, simpan Double Team buat momen dia masuk, jangan kena poison."},{"name":"Espeon","why":"Serangan sure-hit-nya nembus ilusi dan stealth.","how":"Poke dari jarak Shuriken, serang saat dia buang Stored Power/Psyshock."},{"name":"Clefable","why":"CC dan heal tim bikin burst lo nggak nutup kill.","how":"Fokus carry-nya, bukan Clefable; masuk saat Moonlight/Gravity-nya baru dipakai."},{"name":"Darkrai","why":"Sleep dari jauh, lalu burst saat lo nggak bisa Double Team.","how":"Berdiri di belakang tank; Smokescreen sebelum dia nemu lo."},{"name":"Meowscarada","why":"Assassin yang lebih cepat dan bisa reveal/ngejar lewat stealth.","how":"Jangan jalan sendirian, Double Team saat dia lompat ke lo."}],"goodAgainst":[{"name":"Venusaur","why":"Lambat, nggak punya escape; Shuriken kite dari luar jangkauan atau Surf finishing saat dia low."},{"name":"Glaceon","why":"Rapuh dan butuh waktu numpuk crystal; stealth + burst lo ngabisin dia duluan."},{"name":"Decidueye","why":"Nggak punya mobility; flank dari Smokescreen dan Surf di jarak dekat (inferensi dari mekanik)."}]},"cinderace":{"similarity":7,"note":"Build Water Shuriken + Double Team rasanya 70% Cinderace: move → boosted → auto, kiting dari belakang. Bedanya: lo nggak punya Feint (invincible), jadi escape lo bergantung nipu musuh (ilusi/stealth), bukan nolak damage; dan auto-nya berubah jadi melee kalau musuh deket, jadi jangan panik dan mundur terus, kadang justru tetap mukul dari dekat lebih sakit saat musuh low. Kalau lo pilih Surf + Smokescreen, itu udah assassin, bukan sniper."},"sources":["https://serebii.net/pokemonunite/pokemon/greninja.shtml","https://bulbapedia.bulbagarden.net/wiki/Greninja_(UNITE)","https://game8.co/games/Pokemon-UNITE/archives/335468","https://www.pokemonunite.jp/en/topics/battle/20260304-1/","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"high","notes":"Level move cocok di Serebii dan Bulbapedia (Bubble/Substitute Lv1, Double Team/Smokescreen Lv5, Water Shuriken/Surf Lv7, Unite Lv9, upgrade Lv11/13). Riwayat patch: 1.18.1.4 (Mar 2025) HP naik, heal Water Shuriken turun, damage ilusi Double Team naik; 1.19.1.2 (Mei/Jun 2025) HP naik lagi; 1.21.1.5 (Jan 2026) nerf basic attack, Surf, dan ilusi Double Team; 1.22.1.5 (Mar 2026) buff HP, Sp. Def, boosted +8%, Bubble +10%, Smokescreen cooldown 13→12s dan speed 10→30%. Tidak ada perubahan di patch Agustus/September 2026. Build dan hard counter dari game8 (A rank); goodAgainst sebagian inferensi mekanik.","image":"img/greninja.webp","status":"Owned"},{"name":"Toxtricity","slug":"toxtricity","role":"Penyerang","damage":"Special","range":"Ranged","difficulty":"Menengah","evolutions":"Toxtricity (tidak berevolusi; langsung Toxtricity dari Lv1)","tagline":"Auto-attacker special dengan dua 'timbre' (Poison buat burst, Electric buat sustain) yang lo ganti-ganti pakai Shift Gear.","passive":{"name":"Punk Rock","desc":"Tiap basic attack yang kena musuh nambah attack speed lo, numpuk sampai 5. Basic attack yang kena musuh yang lagi slow juga ngembaliin HP lo. Intinya: makin lama lo mukul, makin cepat dan makin awet."},"basicAttack":"Basic attack ranged dengan efek beda per timbre: Poison timbre bikin musuh poisoned (numpuk sampai 5), Electric timbre jangkauannya lebih panjang, nge-slow, dan ngembaliin HP. Tiap serangan ketiga jadi boosted dengan damage ekstra dan efek timbre yang lebih kuat.","lanes":["Top","Jungle","Bottom"],"laneNote":"Top atau Jungle disarankan: Toxtricity nggak berevolusi jadi dia nggak selemah starter lain di early, dan jungle bikin dia cepat Lv5 (Shift Gear) dan Lv7 (Overdrive).","earlyGame":"Lo sudah Toxtricity dari Lv1, jadi trade awal lo lebih kuat dari kebanyakan attacker: poke pakai Charge + boosted dan Growl buat slow. Tetap jangan overextend, target cepat Lv5 buat Shift Gear. Di jungle, clear camp pakai auto stack Punk Rock.","powerSpike":"Lv5 (Shift Gear) buka mekanik dua timbre; Lv7 Overdrive jadi burst/CC utama; Lv9 Unite.","slot1":{"base":{"name":"Charge","level":1,"desc":"Movement speed naik sebentar dan basic attack berikutnya lebih sakit plus nge-slow musuh."},"choices":[{"name":"Shift Gear","level":5,"upgradeLevel":11,"desc":"Ganti timbre: ke Poison (attack speed naik, auto bikin poison numpuk) atau ke Electric (movement speed naik, auto lebih jauh, nge-slow, dan heal lo). Cooldown pendek.","when":"Poison saat lo mau burst satu target yang nggak bisa kabur; Electric saat lo butuh kite, kabur, atau sustain di fight panjang. Ganti sesuai situasi, bukan sekali di awal.","avoid":"Jangan lupa ganti timbre: main satu timbre terus bikin lo kehilangan setengah kit; dan jangan ganti ke Poison saat lo lagi dikejar.","upgradeNote":"Lv11: basic attack berikutnya setelah Shift Gear langsung jadi boosted attack."}]},"slot2":{"base":{"name":"Growl","level":1,"desc":"Serangan suara ke depan yang kasih damage dan nurunin movement speed musuh."},"choices":[{"name":"Overdrive","level":7,"upgradeLevel":13,"desc":"Serangan area yang efeknya ikut timbre: Poison = ledakan racun burst besar; Electric = stun singkat dan damage listrik yang nyambung antar musuh.","when":"Electric Overdrive buat buka fight/nge-stun musuh yang numpuk atau nyelametin diri; Poison Overdrive buat finishing target yang poison-nya udah numpuk.","avoid":"Jangan tembak Overdrive sebelum ngecek timbre yang aktif; stun yang lo harapkan bisa jadi cuma racun, atau sebaliknya.","upgradeNote":"Lv13: kalau Overdrive kena, lo langsung dapat efek Punk Rock (stack attack speed) tanpa harus mukul dulu."}]},"unite":{"name":"Venom Distortion","level":9,"desc":"Lo 'manggung' beberapa detik: nggak bisa basic attack tapi bisa pakai move, cooldown Shift Gear dipotong, dan rentetan ledakan suara ngehantam musuh di sekitar dengan efek timbre.","when":"Pakai di tengah teamfight saat musuh numpuk di sekitar lo dan tank lo di depan; ganti timbre berulang selama ult buat dapet dua efek (stun + racun).","avoid":"Jangan pakai saat lo sendirian jauh dari tim atau saat musuh udah menyebar; durasi performance-nya bikin lo gampang di-fokus."},"builds":[{"name":"Shift Gear + Overdrive — Special Auto-Attacker (standar)","moves":["Shift Gear","Overdrive"],"recommended":true,"style":"Kite pakai Electric, burst pakai Poison; damage utama dari basic attack yang makin cepat, Overdrive buat CC atau finishing.","heldItems":[{"name":"Wise Glasses","why":"Sp. Atk flat buat auto dan Overdrive."},{"name":"Slick Spoon","why":"Nembus Sp. Def; auto spam lo jadi tetap sakit ke tank."},{"name":"Drive Lens","why":"Sp. Atk dan damage tambahan yang cocok buat attacker yang sering nge-hit (rekomendasi gamingonphone)."}],"battleItem":{"name":"Eject Button","why":"Lo nggak punya dash; Eject satu-satunya escape instan."},"combo":["Shift Gear ke Electric, auto dari jauh buat stack Punk Rock dan slow target.","Overdrive (Electric) buat stun saat musuh ngedeket.","Shift Gear ke Poison → boosted (Lv11) → auto cepat buat numpuk racun.","Begitu Overdrive balik, tembak Poison Overdrive buat finishing; Unite kalau musuh banyak."],"comboNote":"Cooldown Shift Gear pendek, jadi loop Electric → Poison → Electric adalah ritme utama."},{"name":"Shift Gear + Overdrive — Sustain Kiter","moves":["Shift Gear","Overdrive"],"recommended":false,"style":"Lebih banyak di Electric timbre: kite, slow, dan heal lewat Punk Rock; cocok kalau tim lo kurang frontline dan lo sering ditarget.","heldItems":[{"name":"Wise Glasses","why":"Sp. Atk inti."},{"name":"Rapid-Fire Scarf","why":"Attack speed tambahan di atas stack Punk Rock, auto Electric lebih sering = heal lebih sering."},{"name":"Focus Band","why":"Sustain tambahan saat HP rendah di fight panjang."}],"battleItem":{"name":"X Speed","why":"Kite lebih jauh di Electric timbre; alternatif dari gamingonphone."},"combo":["Electric timbre, auto dari jarak maksimal, biarin slow + heal kerja.","Electric Overdrive buat stun saat ada yang nyoba dive.","Kalau target udah low dan nggak bisa kabur, Shift Gear ke Poison dan finishing pakai boosted + Overdrive.","Balik ke Electric sebelum musuh berikutnya datang."],"comboNote":"Build ini kurang burst; menangnya lewat fight panjang."}],"situations":{"gank":"Saat nge-gank: Electric Overdrive buat stun, lalu Poison buat burst. Saat dikeroyok: Electric Overdrive ke yang paling dekat, Shift Gear Electric buat speed, Eject keluar.","escape":"Shift Gear ke Electric (speed naik), Electric Overdrive buat stun pengejar, Eject Button. Auto Electric sambil mundur juga nge-slow mereka dan heal lo.","objective":"Berdiri di belakang tank; auto Electric dari jauh buat nge-slow musuh yang masuk pit, Electric Overdrive buat stun saat fight pecah, lalu Poison buat finishing. Unite di tengah kerumunan hanya kalau tank lo masih hidup.","duel":"Mulai di Electric buat slow + heal, lalu ganti Poison saat lawan commit dan nggak bisa kabur. Lawan melee dengan dash: tahan Electric Overdrive buat stun saat mereka masuk.","teamfight":"Backline/midline di belakang tank. Target: siapa pun yang kena stun Overdrive, lalu carry musuh. Jangan 'manggung' Unite sebelum CC besar musuh keluar."},"mistakes":["Nggak pernah ganti timbre; Toxtricity yang stuck di satu timbre cuma setengah Pokémon.","Nembak Overdrive tanpa ngecek timbre yang aktif.","Pakai Venom Distortion jauh dari tim dan di-fokus karena nggak bisa auto.","Fight sebelum stack Punk Rock jalan; lo paling lemah di 3 auto pertama.","Overextend karena ngerasa kuat di early (nggak berevolusi) tanpa escape selain Eject."],"counters":{"hardFor":[{"name":"Ceruledge","why":"Dive cepat dan burst yang ngabisin lo sebelum stack jalan.","how":"Tahan Electric Overdrive buat stun pas dia masuk, mundur ke tank."},{"name":"Zeraora","why":"Dash berulang bikin lo nggak bisa kite.","how":"Jangan jalan sendirian; stun saat dia Spark, lalu Eject keluar."},{"name":"Snorlax","why":"CC panjang (Block/Yawn) ngunci lo buat timnya.","how":"Jaga jarak lebih jauh dari biasanya, auto Electric dari luar jangkauan."},{"name":"Mamoswine","why":"CC chain yang bikin lo nggak bisa gerak.","how":"Berdiri di belakang tank, simpan Eject buat setelah CC pertama."},{"name":"Slowbro","why":"Telekinesis/Amnesia ngunci dan ngehabisin lo pelan-pelan.","how":"Jangan fokus Slowbro, poke dari jauh dan hindari jangkauan Telekinesis."}],"goodAgainst":[{"name":"Decidueye","why":"Immobile; slow Electric bikin dia nggak bisa jaga jarak dan racun numpuk."},{"name":"Pikachu","why":"Rapuh dan lambat, kalah di trade auto panjang."},{"name":"Venusaur","why":"Lambat; kite di Electric dan finishing pakai Poison."}]},"cinderace":{"similarity":7,"note":"Feel-nya mirip Cinderace: ranged auto-attacker yang hidup dari boosted dan ritme auto. Bedanya: lo special attacker (item beda total), nggak punya dash atau invincible (Feint), jadi kite lo bergantung slow dari Electric timbre dan stun Overdrive, dan ada 'resource' tambahan yang harus dikelola yaitu timbre. Bawa kebiasaan weaving auto dari Cinderace, tambahin kebiasaan ngecek timbre sebelum tiap Overdrive."},"sources":["https://bulbapedia.bulbagarden.net/wiki/Toxtricity_(UNITE)","https://serebii.net/pokemonunite/pokemon/toxtricity.shtml","https://gamingonphone.com/guides/pokemon-unite-toxtricity-guide-best-builds-held-items-moveset-and-gameplay-tips","https://www.pokemonunite.jp/en/topics/battle/20260902-1/"],"confidence":"medium","notes":"Toxtricity baru rilis 24 September 2026, jadi data meta masih tipis. Level: Charge/Growl Lv1, Shift Gear Lv5, Overdrive Lv7, Unite Lv9, upgrade Lv11/13 (Bulbapedia + gamingonphone); halaman Serebii menampilkan level yang kacau (Unite 'Lv15'), diabaikan. Game8 Toxtricity guide tidak bisa diakses (robots). Build item (Wise Glasses, Drive Lens, Slick Spoon; Eject/X Speed) dan counter list dari gamingonphone (29 Sep 2026); build kedua adalah variasi item/gaya karena cuma ada 1 kombinasi move. Detail persis efek timbre pada boosted attack dan efek Unite sedikit beda redaksi antar sumber. Belum ada patch balance untuk Toxtricity.","image":"img/toxtricity.webp","status":"Owned"},{"name":"Decidueye","slug":"decidueye","role":"Penyerang","damage":"Physical","range":"Ranged","difficulty":"Menengah","evolutions":"Rowlet (Lv1) → Dartrix (Lv5) → Decidueye (Lv7)","tagline":"Sniper backline tanpa mobility: makin jauh dari musuh makin sakit, tapi sekali ketangkep hampir pasti mati.","passive":{"name":"Long Reach","desc":"Damage ke musuh yang jauh dari lo lebih besar. Jadi posisi = damage; berdiri di jarak maksimal bukan cuma aman, tapi juga lebih sakit."},"basicAttack":"Basic attack ranged; tiap hit nambah attack speed sementara (bisa numpuk). Tiap serangan ketiga jadi boosted: beberapa detik lo nembak banyak duri sekaligus (per duri lebih kecil, total lebih besar).","lanes":["Bottom","Top","Jungle"],"laneNote":"Bottom/Top sebagai carry yang dijagain supporter atau defender paling masuk akal; jungle bisa tapi lo nggak punya mobility buat gank.","earlyGame":"Rowlet lemah dan lambat: farm dari jarak jauh pakai Leafage, last-hit pakai auto, dan jangan maju lewat tengah lane. Minta partner lane yang tanky buat jadi tameng. Kalau musuh ada Zeraora/Absol, main super pasif sampai Lv7.","powerSpike":"Lv7 (evolusi + Razor Leaf/Spirit Shackle) adalah lompatan besar; Lv9 Nock Nock dan Lv11 upgrade slot 1 bikin lo jadi ancaman di objective.","slot1":{"base":{"name":"Leafage","level":1,"desc":"Lempar daun ke area kecil di depan, damage ringan; poke dan farm early."},"choices":[{"name":"Razor Leaf","level":7,"upgradeLevel":11,"desc":"Daun berputar di sekeliling lo: Attack dan attack speed naik, basic attack jadi bisa kena beberapa musuh sekaligus selama durasinya.","when":"Tekan saat lo udah di posisi aman dan punya target yang nggak bisa kabur (objective, musuh yang kena CC, teamfight di choke).","avoid":"Jangan aktifin lalu jalan-jalan nyari target; durasinya kebuang. Dan jangan aktifin saat lo lagi dikejar, ini bukan escape.","upgradeNote":"Lv11: damage basic attack ke musuh ber-HP tinggi naik; bagus buat ngegerus tank dan boss."},{"name":"Spirit Shackle","level":7,"upgradeLevel":11,"desc":"Tahan tombol buat charge panah; makin lama di-charge makin sakit dan makin jauh. Musuh yang kena jadi lambat dan 'dipaku' bayangannya: kalau mereka jalan menjauh, mereka kena damage tambahan.","when":"Tekan dari jarak maksimal ke carry musuh yang lagi lurus (saat kabur atau datang ke objective); full charge buat snipe sisa HP.","avoid":"Jangan charge terlalu lama di depan musuh yang bisa dive; dan jangan tembak asal ke tank di depan kalau carry-nya ada di belakang.","upgradeNote":"Lv11: damage ke musuh ber-HP rendah naik, jadi makin cocok buat finishing."}]},"slot2":{"base":{"name":"Astonish","level":1,"desc":"Serangan sure-hit ke satu musuh yang nurunin movement speed; buat ngejar/kabur early."},"choices":[{"name":"Leaf Storm","level":8,"upgradeLevel":13,"desc":"Badai daun di depan lo: damage dan slow, musuh yang terlalu dekat didorong mundur.","when":"Tekan saat melee musuh nyampe ke lo buat ngedorong mereka keluar jangkauan, lalu lanjut auto; juga buat nahan musuh di zona objective.","avoid":"Jangan tekan ke musuh yang masih jauh; efek dorong-nya cuma kena di jarak dekat.","upgradeNote":"Lv13: durasi slow-nya lebih panjang."},{"name":"Shadow Sneak","level":8,"upgradeLevel":13,"desc":"Serangan sure-hit ke satu target: movement speed dan Defense target turun, movement speed lo naik.","when":"Tekan ke target yang mau lo snipe (Defense turun = Spirit Shackle lebih sakit) atau buat nambah speed saat reposisi/kabur.","avoid":"Jangan buang ke tank cuma buat speed boost kalau carry musuh ada di jangkauan; ini juga alat finishing lo.","upgradeNote":"Lv13: penurunan Defense-nya lebih besar."}]},"unite":{"name":"Nock Nock","level":9,"desc":"Tembak rentetan duri ke arah yang dipilih, ditutup satu panah besar; damage ekstra ke musuh ber-HP rendah. Selama ult lo kebal CC tapi nggak bisa gerak.","when":"Pakai dari jarak jauh saat 2+ musuh numpuk di garis lurus (pit objective, lane sempit) dan lo yakin nggak ada yang bisa dive ke lo dalam beberapa detik ke depan.","avoid":"Jangan pakai saat ada assassin musuh yang belum kelihatan; lo diam di tempat dan jadi sasaran empuk."},"builds":[{"name":"Spirit Shackle + Shadow Sneak — Sniper","moves":["Spirit Shackle","Shadow Sneak"],"recommended":true,"style":"Snipe dari jarak maksimal, Shadow Sneak buat lemahin target dan kabur; main di luar jangkauan musuh.","heldItems":[{"name":"Muscle Band","why":"Basic attack dan boosted multi-duri lo masih bagian besar damage."},{"name":"Attack Weight","why":"Attack permanen tiap score; lo biasanya di lane dan sering bisa score setelah menang trade."},{"name":"Charging Charm","why":"Nambah damage boosted attack, dan boosted Decidueye keluar sering berkat attack speed stack (rekomendasi unite-guide; Accel Bracer dari dittobase juga valid)."}],"battleItem":{"name":"Eject Button","why":"Satu-satunya 'mobility' lo; wajib buat lari dari dive."},"combo":["Shadow Sneak ke carry musuh (Defense turun, lo dapat speed).","Charge Spirit Shackle dari jarak jauh, lepas saat mereka lurus/kabur.","Boosted attack + auto sambil tetap jaga jarak.","Nock Nock buat finishing kalau target di bawah setengah HP dan jalur aman."],"comboNote":"Kalau musuh yang kena Shackle lari menjauh, damage pakunya nambah; jangan kejar, biarin mereka 'bayar' sendiri."},{"name":"Razor Leaf + Leaf Storm — DPS Objective","moves":["Razor Leaf","Leaf Storm"],"recommended":false,"style":"Auto-attack DPS sustained: aktifin Razor Leaf, pukul semua yang lewat, Leaf Storm buat dorong melee; terbaik di tim dengan frontline kuat.","heldItems":[{"name":"Muscle Band","why":"Tiap auto Razor Leaf kena banyak musuh, Muscle Band numpuk."},{"name":"Scope Lens","why":"Crit di auto yang super cepat bikin DPS melonjak."},{"name":"Rapid-Fire Scarf","why":"Attack speed tambahan di atas stack passive dan Razor Leaf."}],"battleItem":{"name":"Eject Button","why":"Tetap butuh escape; Full Heal kalau musuh banyak CC (saran unite-guide)."},"combo":["Posisi di belakang tank dekat objective.","Razor Leaf saat fight mulai → auto nonstop ke frontline/boss.","Leaf Storm saat melee musuh nempel buat dorong + slow.","Nock Nock saat musuh terkunci di pit."],"comboNote":"Build ini DPS tinggi tapi jaraknya lebih pendek dari Shackle; lo lebih gampang kena dive."}],"situations":{"gank":"Lo bukan ganker; saat tim nge-gank, lo ikut dari belakang dan Shackle target yang kena CC. Saat dikeroyok: Shadow Sneak ke yang paling dekat buat speed, Eject lewatin dinding, lari ke tank; jangan coba fight balik.","escape":"Shadow Sneak (speed boost) + Eject Button. Leaf Storm bisa dorong satu melee yang nempel. Selain itu lo nggak punya apa-apa, jadi escape terbaik adalah nggak pernah berdiri di posisi yang perlu kabur.","objective":"Berdiri di jarak maksimal dari pit, di belakang defender. Shackle/auto ke boss buat secure atau ke carry musuh yang masuk; Nock Nock dari jauh saat musuh numpuk di pit. Jangan pernah jadi yang paling depan di Rayquaza.","duel":"1v1 lawan ranged: Shadow Sneak → Shackle → auto, jaga jarak terus. Lawan melee: kalau mereka punya dash, lo kalah; mundur ke goal duluan. Leaf Storm bisa menangin duel lawan melee tanpa dash.","teamfight":"Posisi paling belakang, biasanya di belakang supporter. Prioritas: siapa pun yang paling jauh dari lo tapi masih dalam jangkauan (Long Reach), terutama carry musuh. Nock Nock cuma kalau assassin musuh udah kelihatan dan sibuk."},"mistakes":["Mendekat ke musuh buat 'bantu' padahal damage lo justru turun kalau deket (Long Reach).","Nock Nock saat assassin musuh belum kelihatan; lo diam dan mati.","Charge Spirit Shackle di tempat terbuka sambil dikejar.","Aktifin Razor Leaf sebelum ada target, durasinya kebuang.","Jalan sendirian ke jungle musuh atau rotasi tanpa partner."],"counters":{"hardFor":[{"name":"Zoroark","why":"Dive dari semak, burst cepat, dan lo nggak punya escape.","how":"Berdiri dekat tank, simpan Eject, Leaf Storm buat dorong saat dia nempel."},{"name":"Dodrio","why":"Speedster yang lari lebih cepat dari Shadow Sneak lo.","how":"Jangan trade sendirian; tunggu dia buang dash lalu Shackle."},{"name":"Zacian","why":"Tanky, cepat, dan bisa ngejar lo lewat dinding.","how":"Main di belakang tim, kabur duluan saat dia muncul."},{"name":"Tsareena","why":"Dash berulang dan CC bikin lo nggak bisa jaga jarak.","how":"Leaf Storm saat dia nempel, Eject keluar, biarkan tank yang ngurus."},{"name":"Blastoise","why":"CC jarak menengah (Surf/Hydro Pump) ngunci lo buat timnya.","how":"Jaga jarak lebih dari biasanya, poke dia pakai Shackle dari luar jangkauan."}],"goodAgainst":[{"name":"Pikachu","why":"Sama-sama immobile tapi jangkauan Shackle lo lebih panjang."},{"name":"Gardevoir","why":"Lambat dan rapuh; Long Reach bikin lo menang trade dari jauh."},{"name":"Duraludon","why":"Immobile dan gampang dipaku Shackle; lo nembak lebih jauh."}]},"cinderace":{"similarity":6,"note":"Kebiasaan jaga jarak dan auto-attack dari Cinderace langsung kepake, bahkan lebih penting karena damage naik kalau jauh. Yang harus diubah: lo nggak punya Feint atau Flame Charge, jadi 'mundur sambil nembak' bukan pilihan, lo harus mundur SEBELUM musuh dekat dan ngandelin tim buat peel. Boosted attack juga beda: bukan satu pukulan sakit, tapi burst durasi pendek, jadi jangan reposisi saat boosted lagi aktif."},"sources":["https://serebii.net/pokemonunite/pokemon/decidueye.shtml","https://bulbapedia.bulbagarden.net/wiki/Decidueye_(UNITE)","https://www.dittobase.com/unite/pokemon/decidueye","https://unite-guide.com/pokemon/decidueye/","https://game8.co/games/Pokemon-UNITE/archives/572348"],"confidence":"medium","notes":"Level move cocok antara Serebii dan Bulbapedia (Leafage/Astonish Lv1, Razor Leaf/Spirit Shackle Lv7, Leaf Storm/Shadow Sneak Lv8, Unite Lv9, upgrade Lv11/13); dittobase menulis slot moves 'Lv1' tapi itu cara tampil situsnya, bukan level asli. Patch terbaru: 1.21.1.7 (Des 2025) HP naik besar (3000-5152 → 3200-6000) sebagai buff durability; 1.19.1.2 (Jun 2025) hanya bug fix. Tidak ada perubahan di patch Mar/Agu/Sep 2026. Game8 guide Decidueye tidak bisa diakses (robots), jadi counter list dari unite-guide.com (sudah tidak di-maintain) dan sebagian inferensi mekanik; detail isi upgrade Lv11/Lv13 dari Bulbapedia saja. Item: Charging Charm vs Accel Bracer beda antar sumber (unite-guide vs dittobase).","image":"img/decidueye.webp","status":"Owned"},{"name":"Sylveon","slug":"sylveon","role":"Penyerang","damage":"Special","range":"Ranged","difficulty":"Pemula","evolutions":"Eevee (Lv1) → Sylveon (Lv4)","tagline":"Attacker ranged yang bandel: damage-nya nambah sambil berantem dan bisa heal diri sendiri, jadi lebih maafin kesalahan posisi.","passive":{"name":"Pixilate","desc":"Tiap lo ngasih atau nerima damage, Sp. Atk dan Sp. Def lo naik sebentar, bisa numpuk beberapa kali. Artinya lo makin kuat kalau terus-terusan ikut fight, jangan diem nganggur."},"basicAttack":"Basic attack ranged. Tiap serangan ke-3 boosted: damage lebih gede dan lo dapet movement speed sebentar pas kena. Pakai buat kite atau ngejar.","lanes":["Top","Bottom"],"laneNote":"Top atau Bottom sama-sama bagus. Sylveon kuat di lane karena sustain (Draining Kiss) dan early Lv4 evolusi cepat. Jungle bisa, tapi bukan pilihan utama.","earlyGame":"Lv1-3 sebagai Eevee lo lemah: poke pakai Swift, Baby-Doll Eyes buat ngerem musuh yang maju, dan prioritas farm sampai Lv4. Begitu jadi Sylveon lo langsung bisa trade. Jangan tukar HP sebelum evolusi.","powerSpike":"Lv4 (evolusi + Mystical Fire/Hyper Voice) adalah spike pertama dan paling kerasa; Lv6 move 2 bikin lo stabil, Lv8 Fairy Frolic (Unite-nya lebih awal dari kebanyakan) buat ngelibas lane.","slot1":{"base":{"name":"Swift","level":1,"desc":"Nembak bintang ke musuh dari jauh."},"choices":[{"name":"Mystical Fire","level":4,"upgradeLevel":10,"desc":"Lo maju sedikit (dash pendek) sambil bikin beberapa api yang satu per satu nembak musuh terdekat, nurunin Sp. Atk mereka.","when":"Buat trade di lane dan nge-kite: tekan pas musuh dalam jangkauan, apinya ngejar sendiri. Dash-nya juga bisa buat lewatin musuh/kabur jarak pendek.","avoid":"Jangan dash maju ke arah gerombolan musuh buat 'ngambil api', arahkan dash-nya ke samping/belakang.","upgradeNote":"Lv10: jumlah api nambah satu, damage total naik."},{"name":"Hyper Voice","level":4,"upgradeLevel":10,"desc":"Nembak beberapa gelombang suara berturut-turut ke arah kerucut lebar; makin jauh musuhnya dari lo, makin sakit, dan musuh kena slow.","when":"Teamfight dan objective: berdiri di jarak maksimal, tembak ke tumpukan musuh. Ini move yang bikin Sylveon jadi 'AoE sniper'.","avoid":"Jangan pakai pas musuh udah nempel; damage-nya kecil di jarak dekat dan lo malah kebuka.","upgradeNote":"Lv10: satu gelombang tambahan dan nurunin Sp. Def musuh yang kena, damage total naik banyak."}]},"slot2":{"base":{"name":"Baby-Doll Eyes","level":1,"desc":"Natap musuh: damage kecil, nurunin Attack dan movement speed mereka sebentar."},"choices":[{"name":"Draining Kiss","level":6,"upgradeLevel":12,"desc":"Ciuman yang bolak-balik antara lo dan target (sure-hit): tiap balik ke lo, HP lo pulih; musuh kena damage dan slow.","when":"Pas lagi trade dan HP lo turun, atau buat ngejar musuh yang kabur (slow-nya ngebantu). Ini alasan lo bisa tahan di lane tanpa balik ke goal.","avoid":"Jangan tekan ke target yang mau mati/hilang dari pandangan, bounce-nya kebuang; dan jangan andelin buat nahan burst, heal-nya bertahap.","upgradeNote":"Lv12: HP yang dipulihin lebih banyak."},{"name":"Calm Mind","level":6,"upgradeLevel":12,"desc":"Buff diri: Sp. Atk, Sp. Def, dan movement speed naik sebentar.","when":"Tekan tepat sebelum nembak Hyper Voice di teamfight, atau buat ngejar/kabur dengan movement speed-nya.","avoid":"Jangan buang Calm Mind pas nggak ada musuh; cooldown-nya kebuang dan lo masuk fight tanpa buff.","upgradeNote":"Lv12: dapet shield yang nahan satu serangan move musuh, bikin lo lebih aman pas casting."}]},"unite":{"name":"Fairy Frolic","level":8,"desc":"Lompat ke udara dan jadi invincible sebentar; pas mendarat ngasih damage area dan heal HP lo. Beberapa detik setelahnya, sebagian damage move lo diubah jadi HP.","when":"Dua fungsi: dodge (lompat pas skill besar musuh keluar, misal Unite move mereka) atau sustain di tengah fight panjang. Charge-nya cepat, pakai sering.","avoid":"Jangan pakai cuma buat damage awal; nilainya ada di invincible + heal, jadi tunggu momen lo diserang."},"builds":[{"name":"Hyper Voice + Calm Mind — AoE Sniper","moves":["Hyper Voice","Calm Mind"],"recommended":true,"style":"Berdiri jauh di belakang, buff dulu, lalu semprot teamfight dengan Hyper Voice; kuat di objective.","heldItems":[{"name":"Wise Glasses","why":"Sp. Atk flat, scaling Hyper Voice bagus."},{"name":"Choice Specs","why":"Hyper Voice banyak hit, tiap cast dapet burst tambahan."},{"name":"Slick Spoon","why":"Penetrasi Sp. Def biar tetap sakit ke Defender di depan."}],"battleItem":{"name":"X Speed","why":"Nggak ada escape asli, X Speed + Calm Mind buat jaga jarak ideal."},"combo":["Calm Mind pas musuh mulai ngumpul","Mundur ke jarak maksimal lalu Hyper Voice","Boosted basic attack sambil cooldown","Fairy Frolic kalau ada yang nge-dive lo"],"comboNote":"Kunci build ini jarak: makin jauh Hyper Voice-nya, makin sakit."},{"name":"Mystical Fire + Draining Kiss — Sustain Brawler","moves":["Mystical Fire","Draining Kiss"],"recommended":false,"style":"Lane bully yang susah mati: trade terus, heal pakai Draining Kiss, kite pakai dash Mystical Fire.","heldItems":[{"name":"Wise Glasses","why":"Sp. Atk buat semua move dan heal yang scaling-nya ikut damage."},{"name":"Shell Bell","why":"Heal tambahan tiap move kena; Mystical Fire + Draining Kiss sering kena, jadi heal numpuk."},{"name":"Focus Band","why":"Bertahan pas HP tipis, cocok dengan gaya main tukar HP."}],"battleItem":{"name":"Potion","why":"Sustain tambahan buat tetep di lane; ganti Eject Button kalau lawan banyak assassin."},"combo":["Mystical Fire ke arah samping (api ngejar musuh)","Basic attack sampai boosted","Draining Kiss pas HP mulai turun","Fairy Frolic buat dodge burst lalu lanjut trade"],"comboNote":"Pixilate stack naik tiap kena/nerima damage, jadi build ini makin kuat makin lama fight."}],"situations":{"gank":"Kalau lo nge-gank: masuk pas musuh udah pakai move, Hyper Voice/Mystical Fire + boosted, Draining Kiss buat slow kalau dia kabur. Kalau dikeroyok: Fairy Frolic pas burst mereka keluar, lalu Mystical Fire dash/X Speed ke arah tim.","escape":"Fairy Frolic = tombol selamat (invincible + heal). Mystical Fire dash pendek ke arah aman, boosted attack ngasih movement speed, Calm Mind/X Speed buat lari. Jangan tunggu HP tipis baru lompat.","objective":"Rayquaza/Regieleki: berdiri jauh di belakang Defender, Hyper Voice ke pit tiap cooldown habis. Simpan Fairy Frolic buat dodge Unite move musuh pas mereka mau steal.","duel":"Lo menang kebanyakan duel lane karena sustain. Trade pakai move + boosted, Draining Kiss pas HP turun, kite mundur sambil Mystical Fire. Lawan Speedster/burst: jangan duel di luar lane, tunggu mereka buang move lalu Fairy Frolic.","teamfight":"Baris belakang, jarak maksimal. Prioritas target: siapa pun yang di jangkauan Hyper Voice (AoE), lalu Supporter/Attacker rapuh. Jangan maju ke depan Defender walaupun HP lo masih penuh."},"mistakes":["Trade HP sebagai Eevee sebelum Lv4, padahal Eevee lemah.","Hyper Voice dari jarak dekat, damage-nya kecil dan lo kebuka.","Nyimpen Fairy Frolic buat damage, bukan buat dodge/heal.","Ngerasa tanky karena Draining Kiss lalu dive sendirian ke 2-3 musuh."],"counters":{"hardFor":[{"name":"Talonflame","why":"Masuk dari atas dan burst sebelum stack Pixilate lo jalan.","how":"Jangan jauh dari tim; Fairy Frolic pas dia Fly/Brave Bird, lalu balas."},{"name":"Zacian","why":"Tanky, cepat, dan damage-nya nggak keburu lo heal.","how":"Jangan trade 1v1, kite ke arah tim dan tunggu Defender nahan dia."},{"name":"Gengar / Absol / Darkrai","why":"Assassin yang nggak ngasih waktu lo nembak Hyper Voice.","how":"Simpan Fairy Frolic dan Calm Mind shield (Lv12) buat momen mereka masuk; jangan farm sendirian."},{"name":"Slowbro","why":"CC panjang (Telekinesis/Amnesia) yang bikin lo diem di tempat terus dihajar timnya.","how":"Berdiri di luar jangkauan tariknya, fokus ke target lain."}],"goodAgainst":[{"name":"Supporter (Blissey, Clefable, Comfey, Eldegoss)","why":"Hyper Voice ngehabisin mereka dari jauh, dan Draining Kiss slow bikin mereka nggak bisa kabur."},{"name":"Melee tanpa gap-closer bagus (Snorlax, Mamoswine, Trevenant)","why":"Lo kite terus dari jauh dan heal, mereka nggak pernah nyentuh lo."}]},"cinderace":{"similarity":6,"note":"Ini Pokémon paling gampang buat pindah dari Cinderace: ranged, kiting, boosted attack ngasih movement speed, dan Mystical Fire mirip Feint buat dash pendek. Bedanya: damage lo lebih banyak dari move (apalagi Hyper Voice) daripada dari auto-attack, dan lo punya sustain, jadi lo boleh lebih berani tukar HP di lane. Jangan bawa kebiasaan 'auto-attack doang' dari Cinderace."},"sources":["https://bulbapedia.bulbagarden.net/wiki/Sylveon_(UNITE)","https://serebii.net/pokemonunite/pokemon/sylveon.shtml","https://game8.co/games/Pokemon-UNITE/archives/342821","https://www.dittobase.com/unite/pokemon/sylveon"],"confidence":"high","notes":"Nama move, level Lv4/Lv6, upgrade Lv10/Lv12, Unite Lv8 cocok antara Bulbapedia, Serebii, dan dittobase. Serebii melabeli 'Physical Attacker' tapi itu salah; Sylveon Special. Hyper Voice direwok di v1.16.1.2 (Sep 2024): kerucut jauh lebih lebar dan nambah slow, jadi sekarang jadi build utama. Item: Game8 (Wise Glasses/Choice Specs/Slick Spoon) vs dittobase (Curse Incense/Shell Bell/Drive Lens) buat Hyper Voice; gw pilih Game8. Difficulty: Bulbapedia 'Novice', Serebii 'Intermediate'; gw pakai Pemula.","image":"img/sylveon.webp","status":"Owned"},{"name":"Alolan Ninetales","slug":"alolan-ninetales","role":"Penyerang","damage":"Special","range":"Ranged","difficulty":"Pemula","evolutions":"Alolan Vulpix (Lv1) → Alolan Ninetales (Lv4)","tagline":"Attacker es yang kerjanya ngontrol lane: slow, freeze, bikin tembok, dan ngehajar musuh yang kebeku.","passive":{"name":"Snow Warning","desc":"Serangan lo numpuk 'salju' ke musuh: tiap kena, musuh dapet damage tambahan dan slow sebentar. Kena beberapa kali berturut-turut ke target yang sama, musuh itu kebeku (freeze) sebentar."},"basicAttack":"Basic attack ranged. Tiap serangan ke-3 boosted: lempar salju yang ngasih damage area ke musuh di sekitar target dan nge-slow mereka. Boosted ini ikut numpuk stack Snow Warning, jadi penting buat ngejar freeze.","lanes":["Top","Bottom"],"laneNote":"Top atau Bottom sama kuatnya. Ninetales kuat di early karena Powder Snow + Icy Wind udah ada dari Lv1, dan nilainya di lane bareng partner buat setup freeze.","earlyGame":"Lv1-3 lo lebih kuat dari kebanyakan lawan lane: poke pakai Powder Snow, kalau musuh maju ke partner lo pakai Icy Wind buat nge-slow + dorong. Farm sampai Lv4 (evolusi + move 1 upgrade), lalu mulai ambil kill bareng partner. Jangan tukar HP sembarangan, lo tipis.","powerSpike":"Lv4 (evolusi + Avalanche/Dazzling Gleam) udah kerasa, tapi spike utama Lv6 pas dapet Blizzard/Aurora Veil; Lv9 Snow Globe ngasih burst besar ke musuh yang kebeku.","slot1":{"base":{"name":"Powder Snow","level":1,"desc":"Tiupan salju ke area depan, damage plus slow."},"choices":[{"name":"Avalanche","level":4,"upgradeLevel":11,"desc":"Bikin tembok es di area target yang ngeblok jalan; tembok hancur setelah beberapa saat dan ngasih damage + slow ke musuh di sekitarnya.","when":"Buat nutup jalan kabur musuh, misahin musuh dari timnya, atau nahan jalur masuk ke pit Rayquaza. Juga buat setup Blizzard: musuh yang didorong ke tembok kena damage ekstra.","avoid":"Jangan taruh tembok di tengah jalan tim lo sendiri atau di depan Defender lo yang mau maju; tembok ini ngeblok dua arah.","upgradeNote":"Lv11: cooldown lebih pendek dan damage runtuhannya naik, jadi bisa lebih sering dipakai buat zoning."},{"name":"Dazzling Gleam","level":4,"upgradeLevel":11,"desc":"Nembak kerucut cahaya ke depan; musuh yang kena jadi nggak bisa bertindak (stun) sebentar.","when":"Buat ngerem Speedster/All-Rounder yang nge-dive ke lo, atau buat nahan musuh biar partner lo bisa follow-up. Di build Aurora Veil ini CC utama lo.","avoid":"Jangan tembak asal; kerucutnya nggak lebar, tunggu musuh deket atau lurus di depan lo.","upgradeNote":"Lv11: durasi stun/damage naik."}]},"slot2":{"base":{"name":"Icy Wind","level":1,"desc":"Angin es ke area, damage, slow, dan ngedorong musuh menjauh."},"choices":[{"name":"Blizzard","level":6,"upgradeLevel":13,"desc":"Badai salju dua tahap ke area: damage, slow, dan dorong musuh. Kalau musuh kedorong nabrak tembok/obstacle (termasuk tembok Avalanche), kena damage tambahan.","when":"Combo utama lo: Avalanche dulu, lalu Blizzard buat dorong musuh ke tembok. Juga buat ngusir musuh dari pit objective atau dari goal lo.","avoid":"Jangan dorong musuh menjauh pas tim lo lagi ngejar/mau finishing; lo malah nyelametin dia.","upgradeNote":"Lv13: damage naik, terutama bagian nabrak obstacle."},{"name":"Aurora Veil","level":6,"upgradeLevel":13,"desc":"Bikin aurora di sekitar lo: lo dan teman di dalamnya dapet damage reduction, lo dapet movement speed, dan basic attack lo jadi boosted terus (dengan lifesteal) selama efeknya.","when":"Tekan sebelum teamfight dimulai atau pas tim ngumpul di objective, lalu spam basic attack dari dalam aurora. Juga buat bantu Defender lo bertahan.","avoid":"Jangan aktifin terlalu awal pas musuh belum ada, atau pas lo sendirian di tempat berbahaya; cooldown-nya lama.","upgradeNote":"Lv13: damage reduction dan efeknya lebih kuat, jadi jadi 'tombol teamfight' tim."}]},"unite":{"name":"Snow Globe","level":9,"desc":"Ledakan salju dan es di area besar di sekitar lo. Damage-nya jauh lebih sakit ke musuh yang lagi kebeku.","when":"Pas musuh kebeku atau abis kena Blizzard/Dazzling Gleam dan masih ngumpul. Di objective, pakai setelah tim lo ngasih CC.","avoid":"Jangan pakai cuma buat 1 musuh yang HP-nya tipis atau pas nggak ada yang kebeku; nilainya jauh di bawah potensinya."},"builds":[{"name":"Avalanche + Blizzard — Freeze Burst","moves":["Avalanche","Blizzard"],"recommended":true,"style":"Mage kontrol dari belakang: bikin tembok, dorong musuh ke tembok, freeze, lalu Snow Globe.","heldItems":[{"name":"Wise Glasses","why":"Sp. Atk flat buat semua move dan boosted attack."},{"name":"Choice Specs","why":"Burst tiap move kena, Blizzard + Avalanche jadi makin sakit."},{"name":"Slick Spoon","why":"Penetrasi Sp. Def biar tetap sakit ke Defender di objective."}],"battleItem":{"name":"Eject Button","why":"Ninetales nggak punya dash sama sekali, Eject satu-satunya escape dari dive."},"combo":["Avalanche di belakang/samping musuh","Blizzard dorong musuh ke tembok","Basic attack sampai boosted buat numpuk stack freeze","Snow Globe pas mereka kebeku"],"comboNote":"Kalau musuh udah nempel tembok map, nggak perlu Avalanche; langsung Blizzard aja."},{"name":"Dazzling Gleam + Aurora Veil — Support Auto-Attacker","moves":["Dazzling Gleam","Aurora Veil"],"recommended":false,"style":"Berdiri di dalam aurora, spam boosted attack buat freeze beruntun, stun yang nge-dive pakai Dazzling Gleam; cocok kalau tim lo kurang frontline.","heldItems":[{"name":"Muscle Band","why":"Attack speed + damage per hit buat boosted attack spam di dalam aurora."},{"name":"Rapid-Fire Scarf","why":"Attack speed naik abis move, makin cepat numpuk stack Snow Warning."},{"name":"Slick Spoon","why":"Boosted attack lo tetap special, penetrasi Sp. Def tetap kepake."}],"battleItem":{"name":"X Attack","why":"Attack speed tambahan buat window Aurora Veil; alternatif Eject Button kalau sering di-dive."},"combo":["Aurora Veil pas musuh mau engage","Basic attack (semua jadi boosted) ke target terdekat","Dazzling Gleam pas Speedster masuk","Snow Globe pas musuh kebeku"],"comboNote":"Jangan jalan keluar aurora; semua kekuatan build ini ada di dalam lingkaran."}],"situations":{"gank":"Kalau lo yang nge-gank: Avalanche nutup jalan kabur dulu, baru Blizzard. Kalau lo yang dikeroyok: Blizzard/Icy Wind buat dorong mereka menjauh, lalu Eject ke tim.","escape":"Lo nggak punya dash. Dorong musuh pakai Blizzard ke arah belakang mereka, taruh Avalanche di antara lo dan mereka, lalu jalan/Eject. Slow dari passive bantu, tapi dari Speedster tetap harus Eject.","objective":"Rayquaza/Regieleki: berdiri di belakang Defender di tepi pit. Avalanche buat nutup jalur masuk musuh ke pit atau ngehalangin steal, Blizzard buat ngusir musuh dari pit. Snow Globe pas tim lo udah CC mereka di dalam pit.","duel":"Lo kuat di early duel: poke pakai Powder Snow, kalau musuh maju Icy Wind. Setelah Lv6, jangan ladenin melee dari dekat: dorong pakai Blizzard, tembok Avalanche, lalu basic attack dari jauh sampai freeze.","teamfight":"Baris belakang, dekat Defender. Prioritas: musuh yang kebeku atau yang kena CC tim, lalu Attacker/Supporter rapuh. Avalanche buat misahin tank musuh dari backline mereka."},"mistakes":["Naruh Avalanche yang malah ngeblok tim sendiri atau nyelametin musuh.","Blizzard ngedorong musuh yang sebenarnya hampir mati keluar dari jangkauan tim.","Pakai Snow Globe pas nggak ada yang kebeku.","Maju ke depan karena ngerasa punya CC, padahal nggak punya dash dan tipis."],"counters":{"hardFor":[{"name":"Talonflame","why":"Masuk langsung dari atas dan burst sebelum lo numpuk freeze.","how":"Simpan Dazzling Gleam/Icy Wind buat dia, dan jangan jauh dari Defender; Eject kalau dia udah Fly."},{"name":"Gengar / Darkrai / Greninja","why":"Assassin yang masuk dari belakang dan bisa ngilang; lo nggak sempet reaksi.","how":"Berdiri di tengah tim, jangan farm sendirian, Avalanche buat nutup jalur masuk mereka."},{"name":"Aegislash","why":"Dash berulang + bisa blok damage lo.","how":"Dorong pakai Blizzard pas dia abis dash, jangan ladenin dari dekat."},{"name":"Mew","why":"Range sama tapi lebih fleksibel dan bisa teleport dari CC lo.","how":"Jangan tukar poke 1v1, tunggu dia buang move lalu masuk bareng tim."}],"goodAgainst":[{"name":"All-Rounder melee (Blaziken, Dragonite, Garchomp)","why":"Mereka harus deket buat damage; slow + tembok + freeze bikin mereka nggak nyampe atau kebeku di depan tim lo."},{"name":"Speedster yang harus nempel (Dodrio, Zeraora)","why":"Begitu masuk, kena Icy Wind/Blizzard + Dazzling Gleam dan kebeku sebelum sempat keluar."}]},"cinderace":{"similarity":5,"note":"Mirip di hal posisi: lo tetap backline ranged yang harus jaga jarak, dan boosted attack tetap penting. Bedanya besar di tempo: Ninetales main 'setup dulu' (tembok, dorong, freeze), bukan DPS auto-attack konstan, dan sama sekali nggak punya dash kayak Feint. Jadi bawa kebiasaan kiting-nya, tapi buang kebiasaan 'maju ngejar kill'."},"sources":["https://bulbapedia.bulbagarden.net/wiki/Alolan_Ninetales_(UNITE)","https://serebii.net/pokemonunite/pokemon/alolanninetales.shtml","https://game8.co/games/Pokemon-UNITE/archives/335478","https://www.dittobase.com/unite/pokemon/ninetales"],"confidence":"high","notes":"Slug Serebii yang benar: 'alolanninetales' (bukan 'ninetales', itu 404). Nama move, level (Lv4/Lv6, upgrade Lv11/Lv13), Unite Lv9 cocok antara Bulbapedia dan Serebii. Game8 bilang Dazzling Gleam dipasangkan dengan Aurora Veil; dittobase juga. Item build Freeze: Game8 (Wise Glasses/Choice Specs/Slick Spoon) vs dittobase (Slick Spoon/Wise Glasses/Drive Lens); gw pakai Game8. Patch terakhir yang tercatat di Game8: Jan 2025 nerf kecil boosted attack & Blizzard wall damage. Serebii menandai 'Physical Attacker' tapi itu salah label fetch, Ninetales jelas Special.","image":"img/alolan-ninetales.webp","status":"Owned"},{"name":"Dragonite","slug":"dragonite","role":"Serba-Bisa","damage":"Physical","range":"Ranged","difficulty":"Menengah","evolutions":"Dratini (Lv1) → Dragonair (Lv5) → Dragonite (Lv8)","tagline":"All-Rounder ranged yang lambat berkembang tapi jadi monster auto-attack di late game, dengan Unite yang bisa terbang nyebrang map.","passive":{"name":"Multiscale","desc":"Sebagai Dragonite: tiap beberapa saat, damage yang lo terima dikurangin sebentar (lalu cooldown). Sebelum evolusi akhir passive-nya Marvel Scale: Defense naik pas lo kena status/CC."},"basicAttack":"Basic attack ranged. Sebagai Dragonite, tiap serangan ke-3 boosted dan bergantian tipe: air (heal lo), listrik (paralisis musuh), api (damage ekstra). Boosted attack juga ngurangin cooldown move, jadi terus nembak itu inti gameplay-nya.","lanes":["Bottom","Jungle"],"laneNote":"Bottom paling disaranin (Game8) karena bisa farm aman sampai Lv8 bareng partner; Jungle juga oke buat ngejar Lv8 lebih cepat, tapi lo lemah kalau di-invade sebelum evolusi.","earlyGame":"Lv1-7 lo lemah (Dratini/Dragonair). Fokus farm, pakai Twister buat slow dan last-hit dari jauh, Dragon Breath buat boosted attack biar clear cepat. Hindari fight 2v2 yang nggak perlu; kalau partner lo kepaksa fight, bantu dari belakang pakai Twister. Target: Lv8 secepat mungkin.","powerSpike":"Lv8 (jadi Dragonite + Hyper Beam/Outrage + Multiscale + boosted bergantian) adalah spike-nya, dan Lv9 Draco Impact bikin lo bisa pindah posisi/nge-dive dari jauh.","slot1":{"base":{"name":"Twister","level":1,"desc":"Nembak angin puyuh ke area, damage dan slow."},"choices":[{"name":"Dragon Dance","level":5,"upgradeLevel":11,"desc":"Dash pendek sambil nari; tiap pakai lo dapet stack buff Attack, attack speed, dan movement speed (sampai beberapa stack), dan cooldown-nya berkurang kalau basic attack lo kena.","when":"Pakai buat kiting: dash samping/mundur sambil nembak, numpuk stack, lalu Hyper Beam yang udah diperkuat stack. Juga buat reposisi di teamfight.","avoid":"Jangan buang semua stack buat ngejar satu musuh ke dalam tim mereka; dash-nya pendek dan lo bisa kejebak.","upgradeNote":"Lv11: buff per stack lebih besar."},{"name":"Extreme Speed","level":5,"upgradeLevel":11,"desc":"Lompat ke target, nge-throw dia, dan nge-slow. Kalau kena, cooldown Multiscale di-reset.","when":"Buat misahin satu target (throw ke arah tim lo) atau buat masuk/keluar fight; kena = Multiscale balik, jadi lo lebih aman.","avoid":"Jangan lompat ke target yang dikelilingi timnya; lo All-Rounder, bukan Defender.","upgradeNote":"Lv11: damage/efek naik, dan slow-nya lebih kuat."}]},"slot2":{"base":{"name":"Dragon Breath","level":1,"desc":"Semburan napas naga ke depan; serangan berikutnya langsung jadi boosted."},"choices":[{"name":"Hyper Beam","level":8,"upgradeLevel":13,"desc":"Charge sebentar (lo nggak bisa gerak, tapi damage yang diterima dikurangin), lalu nembak sinar jarak jauh dengan damage gede plus persen max HP musuh; makin banyak stack Dragon Dance, makin sakit.","when":"Setelah numpuk stack Dragon Dance, dari jarak aman, ke tank/Defender atau ke tumpukan musuh di objective. Juga buat finishing musuh yang kabur lurus.","avoid":"Jangan charge pas Speedster musuh deket; lo diem di tempat dan jadi sasaran empuk.","upgradeNote":"Lv13: damage naik dan cooldown lebih pendek."},{"name":"Outrage","level":8,"upgradeLevel":13,"desc":"Ngamuk beberapa detik: damage area di awal, basic attack lo jadi melee dan SEMUA jadi boosted (air/listrik/api bergantian) dengan attack speed tinggi.","when":"Setelah Extreme Speed nge-throw target, atau pas musuh udah nempel; ini DPS terbesar lo di brawl.","avoid":"Jangan aktifin pas target masih jauh; durasinya kebuang buat jalan, dan lo jadi melee yang bisa di-kite.","upgradeNote":"Lv13: durasi/damage boosted naik."}]},"unite":{"name":"Draco Impact","level":9,"desc":"Terbang ke area yang lo pilih (bisa jauh, lintas tembok), lalu nukik bareng komet: damage area + throw musuh, dan lo kebal CC selama efeknya. Makin jauh terbangnya, makin lama cooldown Unite berikutnya.","when":"Buat gabung fight dari jauh, ngedive backline musuh di objective, atau nyusul tim yang kalah jumlah. Juga buat kabur: terbang ke goal lo.","avoid":"Jangan dive sendirian ke 5 musuh; abis nukik lo masih harus hidup di sana. Dan jangan terbang jauh kalau nggak perlu, cooldown-nya jadi lebih panjang."},"builds":[{"name":"Extreme Speed + Outrage — Brawler","moves":["Extreme Speed","Outrage"],"recommended":true,"style":"Lompat ke satu target, throw ke tim lo, lalu Outrage sampai dia mati; main di depan tapi pilih target.","heldItems":[{"name":"Muscle Band","why":"Attack speed + damage per hit, Outrage itu basic attack spam."},{"name":"Weakness Policy","why":"Attack naik tiap lo kena damage, pas buat brawler yang sering ditembak."},{"name":"Focus Band","why":"Bertahan pas HP tipis di tengah Outrage."}],"battleItem":{"name":"Full Heal","why":"Lepas dari CC pas lagi Outrage; X Attack alternatif buat DPS murni."},"combo":["Extreme Speed ke target (throw, reset Multiscale)","Outrage langsung (damage area + boosted spam)","Habisin semua boosted, cooldown Extreme Speed balik","Extreme Speed lagi buat ngejar/kabur, ulang"],"comboNote":"Kalau musuh ngumpul rapi, buka pakai Draco Impact dulu baru urutan di atas."},{"name":"Dragon Dance + Hyper Beam — Kiting Cannon","moves":["Dragon Dance","Hyper Beam"],"recommended":false,"style":"Nembak dari jarak sambil numpuk stack Dragon Dance, lalu Hyper Beam gede; cocok buat lawan tim yang banyak melee.","heldItems":[{"name":"Muscle Band","why":"Attack speed buat numpuk boosted dan ngurangin cooldown Dragon Dance."},{"name":"Razor Claw","why":"Damage ekstra + slow di basic attack setelah move, bantu kiting."},{"name":"Focus Band","why":"Bertahan kalau ada yang masuk pas lo charge Hyper Beam."}],"battleItem":{"name":"Eject Button","why":"Dragon Dance dash-nya pendek, Eject buat lepas dari dive; X Attack kalau lo pede."},"combo":["Dragon Dance (stack 1) sambil basic attack","Dragon Dance lagi tiap cooldown balik (stack 2-3)","Hyper Beam ke target dari jarak maksimal","Lanjut basic attack sampai boosted buat heal/paralisis"],"comboNote":"Stack Dragon Dance = damage Hyper Beam. Jangan Hyper Beam tanpa stack kecuali buat finishing."}],"situations":{"gank":"Kalau lo nge-gank: Draco Impact dari jauh ke backline atau Extreme Speed throw target ke tim lo, lalu Outrage. Kalau dikeroyok: Multiscale nahan burst pertama, Extreme Speed ke arah tim (throw yang ngejar), Full Heal kalau kena CC.","escape":"Draco Impact ke arah goal lo adalah escape terbaik (kebal CC + jauh). Kalau nggak ada: Extreme Speed/Dragon Dance ke arah tim, boosted air buat heal, Twister/Hyper Beam buat slow yang ngejar.","objective":"Rayquaza/Regieleki: Hyper Beam build berdiri di belakang nembak pit; Outrage build nunggu musuh masuk pit lalu Extreme Speed + Outrage ke Attacker mereka. Simpan Draco Impact buat ngusir yang mau steal: throw-nya ngelempar musuh keluar pit.","duel":"Sebelum Lv8 hindari duel. Setelah Lv8 lo menang kebanyakan 1v1: kite pakai Dragon Dance sambil boosted (listrik = paralisis, air = heal), atau Extreme Speed throw lalu Outrage. Lawan Defender tanky pakai Hyper Beam (max HP damage).","teamfight":"Posisi baris kedua: di belakang Defender tapi cukup dekat buat Outrage/Extreme Speed masuk. Prioritas target: Attacker/Supporter musuh yang bisa lo pisahin pakai Extreme Speed/Draco Impact, atau yang udah kena CC tim lo."},"mistakes":["Fight sebelum Lv8 karena ngerasa All-Rounder; Dratini/Dragonair lemah banget.","Draco Impact dive sendirian ke tengah musuh tanpa tim.","Charge Hyper Beam pas Speedster musuh udah di muka.","Lupa boosted attack bergantian: nembak terus ke wild Pokémon pas sebenarnya butuh boosted air buat heal di fight."],"counters":{"hardFor":[{"name":"Trevenant","why":"CC panjang + tanky, motong ritme Outrage/Hyper Beam lo.","how":"Jangan buang Outrage ke dia; fokus ke backline-nya dan Full Heal pas kena CC."},{"name":"Leafeon","why":"Burst cepat yang bisa ngehabisin lo sebelum Lv8 dan ngekite Outrage.","how":"Farm aman sampai Lv8; setelah itu Extreme Speed throw dia lalu Outrage, dia rapuh."},{"name":"Mr. Mime / Supporter CC","why":"Barrier dan CC mereka bikin lo nggak bisa nyentuh target.","how":"Masuk lewat Draco Impact (kebal CC), jangan jalan kaki ke arah mereka."},{"name":"Speedster early (Zeraora, Talonflame) saat invade","why":"Lo lemah dan lambat sebelum evolusi.","how":"Jangan farm jauh dari partner sebelum Lv8; Twister slow lalu mundur."}],"goodAgainst":[{"name":"Ranged rapuh (Chandelure, Cramorant, Decidueye, Gardevoir)","why":"Extreme Speed/Draco Impact langsung ke muka mereka dan Outrage ngehabisin sebelum mereka kabur; atau kite mereka pakai range lo."},{"name":"Garchomp dan melee All-Rounder lain","why":"Lo bisa kite dari jarak dengan Dragon Dance + Hyper Beam, atau adu brawl dengan Multiscale + boosted heal."}]},"cinderace":{"similarity":5,"note":"Dragonite ranged dan ngandelin basic attack kayak Cinderace, jadi insting auto-attack + boosted lo kepake banget (apalagi build Dragon Dance yang mirip kite Feint). Bedanya: early game jauh lebih lemah (sabar sampai Lv8), lo lebih tebal dan boleh masuk fight, dan build Outrage bikin lo melee sementara. Ubah mindset dari 'kill dari jauh' jadi 'pilih target lalu commit'."},"sources":["https://bulbapedia.bulbagarden.net/wiki/Dragonite_(UNITE)","https://serebii.net/pokemonunite/pokemon/dragonite.shtml","https://game8.co/games/Pokemon-UNITE/archives/352950","https://www.dittobase.com/unite/pokemon/dragonite"],"confidence":"medium","notes":"Nama move, level (Lv5 slot 1, Lv8 slot 2, Unite Lv9) cocok antara Bulbapedia, Serebii, dan dittobase. Level upgrade Lv11/Lv13 TIDAK disebut eksplisit di hasil fetch; gw pakai pola standar Pokémon 3 tahap (ambil Lv5/Lv8 → upgrade Lv11/Lv13), jadi cek ulang. Outrage direwok sekitar akhir 2023 jadi melee boosted spam; Game8 catat nerf Outrage dan boosted listrik di v1.16.2.6 (Okt 2024). Tier Game8 'B'. Difficulty: Serebii 'Novice', Bulbapedia 'Intermediate'; gw pilih Menengah karena early game-nya susah. Item build dari Game8; dittobase pakai Rapid-Fire Scarf/Focus Band/Choice Scarf buat Outrage (Choice Scarf item yang relatif baru, belum gw verifikasi).","image":"img/dragonite.webp","status":"Trial"},{"name":"Leafeon","slug":"leafeon","role":"Pelari Cepat","damage":"Physical","range":"Melee","difficulty":"Menengah","evolutions":"Eevee (Lv1) → Leafeon (Lv4)","tagline":"Speedster yang paling cepat jadi kuat (Lv4!), main di luar semak buat ngisi Chlorophyll, lalu dash-tebas-dash sepanjang game.","passive":{"name":"Chlorophyll","desc":"Selama lo NGGAK di dalam tall grass, gauge Chlorophyll lo ngisi. Gauge penuh = movement speed naik dan basic attack berikutnya jadi boosted spesial (ngabisin gauge): damage ekstra + slow. Jadi Leafeon kebalikan assassin biasa: jangan nongkrong di semak."},"basicAttack":"Basic attack melee, tiap serangan ketiga boosted. Kalau Chlorophyll penuh, auto berikutnya langsung jadi boosted yang lebih sakit dan nge-slow musuh, dan gauge-nya habis. Pakai itu buat buka tiap engage.","lanes":["Jungle","Top","Bottom"],"laneNote":"Jungle paling enak karena Lv4 dateng super cepat dan lo bisa langsung gank. Tapi Leafeon juga layak di lane (Top/Bottom) karena evolusi Lv4 bikin lo lebih kuat dari hampir semua laner di menit 1-2.","earlyGame":"Lo Eevee cuma sebentar: Swift buat poke dan last-hit, Quick Attack buat jarak. Begitu Lv4 (Leafeon + Razor Leaf / Solar Blade) lo langsung bisa trade agresif dan bahkan nge-dive laner musuh yang masih level rendah. Jangan sembunyi di semak nunggu gank, gauge lo nggak ngisi di situ.","powerSpike":"Lv4 (evolusi + slot 1) adalah spike paling awal di game, manfaatin buat snowball; Lv6 (Aerial Ace / Leaf Blade) ngelengkapin combo; Lv8 Emerald Two-Step datang satu level lebih cepat dari kebanyakan Pokémon.","slot1":{"base":{"name":"Swift","level":1,"desc":"Tembak bintang ke arah musuh; poke ranged kecil buat Eevee."},"choices":[{"name":"Razor Leaf","level":4,"upgradeLevel":10,"desc":"Lempar 5 daun ke arah yang dipilih, daunnya nancep di tanah; tekan lagi buat narik daunnya balik dan kena damage lagi. Kalau kelima daun kena satu target, lo dapet shield.","when":"Lempar ke target yang lagi lari lurus (biar kelima daun kena satu Pokémon = shield), terus posisikan diri lo supaya tarikannya ngelewatin musuh lagi. Enak buat poke dari jarak sebelum masuk.","avoid":"Jangan lupa tekan kedua buat narik daun; kalau dibiarin lo buang setengah damage. Dan jangan lempar ke kerumunan kalau lo butuh shield-nya (daun kesebar, shield nggak keluar).","upgradeNote":"Lv10: damage naik dan efek tambahan daunnya lebih kuat (Mar 2025 Razor Leaf juga dapat penyesuaian)."},{"name":"Solar Blade","level":4,"upgradeLevel":10,"desc":"Mulai ngumpulin cahaya ke pedang; tekan lagi buat nebas ke bawah dengan damage sesuai lama ngisinya. Kalau Chlorophyll penuh, bisa langsung ditebas dengan damage maksimal.","when":"Pakai saat Chlorophyll penuh biar nggak perlu charge: dash masuk (Leaf Blade), lalu Solar Blade instan ke carry. Juga bagus buat nge-secure objective dari jarak dekat karena burst-nya besar.","avoid":"Jangan mulai charge Solar Blade di depan musuh tanpa gauge penuh; lo gampang dipotong CC atau musuhnya tinggal jalan keluar dari tebasan.","upgradeNote":"Lv10: damage dan efisiensi charge-nya naik (May 2025 juga dapat buff), jadi burst Solar Blade versi gauge-penuh makin sakit."}]},"slot2":{"base":{"name":"Quick Attack","level":1,"desc":"Dash cepat ke arah yang dipilih sambil kasih damage; alat kabur/kejar Eevee."},"choices":[{"name":"Aerial Ace","level":6,"upgradeLevel":12,"desc":"Dash sambil nebas; auto berikutnya tambah sakit. Bisa nyimpen sampai 2 charge, jadi lo punya 2 dash berturut-turut.","when":"Pakai satu charge buat masuk/ngejar dan simpan satu buat keluar. Setelah tiap Aerial Ace, langsung auto biar bonus damage-nya nggak sia-sia.","avoid":"Jangan buang kedua charge buat masuk; Leafeon nggak punya CC dan HP tipis, charge kedua itu nyawa lo.","upgradeNote":"Lv12: damage naik dan recharge-nya lebih cepat, lo bisa dash lebih sering."},{"name":"Leaf Blade","level":6,"upgradeLevel":12,"desc":"Dash lalu muter nebas di sekitar lo. Kalau musuh kena di LINGKARAN LUAR tebasan, damage naik, mereka di-slow, dan Chlorophyll lo ngisi.","when":"Dash ke posisi yang bikin musuh ada di tepi tebasan (bukan nempel badan lo) biar dapet slow + isi gauge, lalu langsung Solar Blade versi penuh. Ini mesin isi gauge lo.","avoid":"Jangan dash sampai nempel ke target; kalau musuh di ring dalam, lo kehilangan slow dan isi gauge. Butuh latihan jarak.","upgradeNote":"Lv12: damage naik dan efek ring luar lebih kuat (slow lebih lama / gauge lebih banyak)."}]},"unite":{"name":"Emerald Two-Step","level":8,"desc":"Lo lompat ke satu musuh, kasih damage + slow, lalu lompat lagi dan mendarat keras dengan damage area; musuh yang lebih dekat ke titik mendarat kena lebih sakit.","when":"Pakai buat ngunci dan ngabisin carry yang mau kabur, atau sebagai dash tambahan buat nyebrang dinding / masuk ke objective pit. Dateng di Lv8 jadi lo sering punya ult duluan di fight pertama.","avoid":"Jangan lompat ke tank di depan tim musuh kalau target asli lo di belakang; dan jangan pakai cuma sebagai escape kalau damage-nya bisa nyelesaiin fight."},"builds":[{"name":"Solar Blade + Leaf Blade — Burst Bruiser","moves":["Solar Blade","Leaf Blade"],"recommended":true,"style":"Leaf Blade (ring luar) isi gauge → Solar Blade instan versi penuh. Burst tertinggi Leafeon dan loop-nya bisa diulang terus.","heldItems":[{"name":"Attack Weight","why":"Lv4 spike bikin lo gampang score di early; stack Attack cepat penuh."},{"name":"Energy Amplifier","why":"Emerald Two-Step dateng Lv8 dan sering; damage bonus setelah ult + ult lebih cepat ngisi."},{"name":"Weakness Policy","why":"Lo melee dan bakal dipukul; Attack bonusnya nambah damage Solar Blade."}],"battleItem":{"name":"Eject Button","why":"Leafeon nggak punya CC dan sustain; satu escape ekstra buat keluar setelah burst."},"combo":["Jalan di luar semak sampai Chlorophyll penuh (speed naik).","Leaf Blade dengan target di ring luar: slow + gauge keisi lagi.","Solar Blade instan (gauge penuh) ke target, lalu boosted auto (versi gauge) buat slow dan finishing; Emerald Two-Step kalau dia lari."],"comboNote":"Kalau gauge belum penuh, mulai charge Solar Blade dari balik tembok sambil nunggu gauge."},{"name":"Razor Leaf + Aerial Ace — Poke Skirmisher","moves":["Razor Leaf","Aerial Ace"],"recommended":false,"style":"Lebih aman dan lebih mobile: poke Razor Leaf, dash masuk-keluar pakai 2 charge Aerial Ace, shield gratis dari 5 daun.","heldItems":[{"name":"Razor Claw","why":"Tiap habis move, auto berikutnya tambah sakit + slow; build ini sering nyentuh musuh lewat auto."},{"name":"Attack Weight","why":"Stack Attack dari score cepat di early."},{"name":"Accel Bracer","why":"Attack speed + buff saat HP tinggi, cocok buat gaya auto setelah Aerial Ace."}],"battleItem":{"name":"X Attack","why":"Burst auto lebih sakit saat lo udah punya 2 charge Aerial Ace buat masuk-keluar."},"combo":["Razor Leaf ke target yang lari lurus (5 daun kena = shield).","Aerial Ace masuk → auto (bonus damage) → tekan Razor Leaf lagi buat narik daun lewat musuh.","Aerial Ace kedua buat ngejar atau keluar, auto lagi."],"comboNote":"Jaga posisi supaya tarikan daun selalu ngelewatin target."}],"situations":{"gank":"Saat nge-gank: datang dari jalur TERBUKA (bukan semak) biar gauge penuh pas sampai, Leaf Blade ring luar buat slow, Solar Blade instan. Saat dikeroyok: Leaf Blade / Aerial Ace keluar dulu, jangan coba trade; lo nggak punya CC dan HP-nya tipis.","escape":"Aerial Ace (simpan charge kedua) atau Leaf Blade buat dash lewatin dinding tipis, movement speed dari gauge penuh buat lari, Eject Button buat darurat. Setelah lepas, jangan sembunyi di semak kalau mau gauge-nya ngisi lagi.","objective":"Di Rayquaza / Regieleki: Solar Blade versi penuh adalah alat secure lo, simpan gauge dan cooldown-nya buat last-hit. Posisi di tepi pit, Leaf Blade masuk pas HP objective mau habis, Solar Blade instan. Emerald Two-Step buat ngelompat ke carry musuh yang lagi secure.","duel":"1v1 lo menang lawan hampir semua laner di early karena Lv4; di late game Solar Blade penuh + boosted gauge ngabisin squishy. Lawan Pokémon sustain (Blastoise, Tsareena, Umbreon) jangan diladenin lama, poke pakai Razor Leaf atau pergi.","teamfight":"Posisi di sisi, di luar semak biar gauge ngisi. Masuk setelah CC musuh keluar, target Attacker/Supporter di belakang. Satu loop Leaf Blade → Solar Blade → boosted, lalu Aerial Ace / Leaf Blade keluar. Jangan jadi frontline."},"mistakes":["Nongkrong di semak nunggu musuh; Chlorophyll nggak ngisi di tall grass, jadi lo masuk fight tanpa speed dan tanpa boosted spesial.","Charge Solar Blade di depan musuh tanpa gauge penuh, gampang dipotong atau di-dodge.","Leaf Blade nempel ke target (ring dalam) sehingga nggak dapet slow dan isi gauge.","Lupa tekan Razor Leaf kedua buat narik daun.","Nggak manfaatin spike Lv4; Leafeon yang main pasif di menit 1-3 buang keunggulan terbesarnya."],"counters":{"hardFor":[{"name":"Blastoise","why":"Rapid Spin + Surf nge-CC lo berkali-kali, HP tebal, dan dia bisa nge-stall sampai lo kehabisan gauge.","how":"Jangan target dia; masuk dari sisi setelah Surf keluar, ke carry di belakangnya."},{"name":"Umbreon","why":"Snarl nurunin Attack lo, Mean Look ngunci lo, dan dia nggak bisa lo burst.","how":"Jauhi dia sama sekali; Razor Leaf poke dari luar, atau tunggu dia pakai Mean Look ke orang lain."},{"name":"Tsareena","why":"Stomp ngunci lo tengah combo, Queenly Majesty bikin slow lo nggak berarti, dan dia sustain.","how":"Poke pakai Razor Leaf, masuk hanya setelah dia buang Stomp dan Trop Kick."},{"name":"Greninja","why":"Smokescreen + Double Team ngilangin target Solar Blade lo, dan burst-nya ngalahin HP tipis lo.","how":"Tunggu dia pakai Smokescreen dulu, baru Leaf Blade (slow) dan Solar Blade."}],"goodAgainst":[{"name":"Pikachu","why":"HP tipis, nggak bisa kabur dari slow Leaf Blade; Solar Blade penuh hampir pasti bunuh."},{"name":"Venusaur","why":"Lambat dan lemah di early; Lv4 spike lo bisa nge-bully dia sebelum Lv5."},{"name":"Decidueye","why":"Attacker tanpa escape yang berdiri di belakang; Emerald Two-Step + Solar Blade nyampe ke dia."}]},"cinderace":{"similarity":5,"note":"Yang paling mirip dari daftar ini: Leafeon juga ngandelin boosted attack spesial (versi gauge) dan dash pendek, mirip Pyro Ball + Flame Charge. Yang bisa lo bawa: kebiasaan auto setelah move, dan main di 'pinggir' fight. Yang harus diubah: lo melee, HP lebih tipis, dan 'ammo' lo bukan boosted ketiga melainkan gauge yang ngisi di luar semak; dan lo kuat dari Lv4, jadi main agresif lebih awal, bukan nunggu Lv7."},"sources":["https://www.serebii.net/pokemonunite/pokemon/leafeon.shtml","https://bulbapedia.bulbagarden.net/wiki/Leafeon_(UNITE)","https://www.dittobase.com/unite/pokemon/leafeon","https://www.sportskeeda.com/pokemon/pokemon-unite-leafeon-guide-best-movesets-builds-items","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"high","notes":"Level move konsisten di Bulbapedia + dittobase (slot 1 Lv4/upgrade 10, slot 2 Lv6/upgrade 12, Unite Lv8); Serebii nulis 'Swift Level 15' yang jelas salah. Tidak ada rework 2026; perubahan terakhir Mar 2025 (Defense Penetration ditambah, Razor Leaf + Leaf Blade disesuaikan), Apr 2025 (nerf), May 2025 (Solar Blade + Leaf Blade dibuff). Detail upgradeNote Lv10/12 bersifat umum (damage/efek naik) karena sumber nggak merinci efek upgrade. Counter adalah inferensi mekanik, bukan tabel counter resmi.","image":"img/leafeon.webp","status":"Owned"},{"name":"Pikachu","slug":"pikachu","role":"Penyerang","damage":"Special","range":"Ranged","difficulty":"Pemula","evolutions":"Pikachu (Lv1, tidak berevolusi)","tagline":"Mage burst jarak jauh yang penuh CC: nge-stun dulu, baru dihajar sampai habis.","passive":{"name":"Static","desc":"Tiap Pikachu kena damage, musuh di dekatnya kena paralisis sebentar. Lumayan buat bikin musuh yang nempel jadi lambat, tapi jangan diandelin buat kabur."},"basicAttack":"Basic attack ranged biasa. Tiap serangan ke-3 jadi boosted: damage lebih gede dan bikin musuh paralisis sebentar. Pakai boosted buat nahan musuh yang mau kabur.","lanes":["Top","Bottom"],"laneNote":"Top atau Bottom, sama-sama oke. Pikachu rapuh dan lambat, jadi butuh partner lane (Defender/Supporter) buat ngejagain. Jungle nggak disaranin karena clear-nya lambat dan gampang di-invade.","earlyGame":"Lv1-3 lo udah punya Thunder Shock + Electroweb, jadi lo kuat di early. Farm wild Pokémon di lane, poke musuh pakai Thunder Shock dari jauh, Electroweb kalau mereka maju nyerang partner lo. Jangan maju sendirian ke depan goal musuh; begitu Lv4 dapet Thunder/Electro Ball, lo mulai bisa ambil kill.","powerSpike":"Lv4 (move slot 1 upgrade) udah ngerasa beda, tapi spike aslinya Lv6 waktu dapet Thunderbolt/Volt Tackle; Lv9 Thunderstorm bikin lo bisa ngelibas teamfight.","slot1":{"base":{"name":"Thunder Shock","level":1,"desc":"Nembak listrik ke area, damage plus paralisis sebentar."},"choices":[{"name":"Electro Ball","level":4,"upgradeLevel":11,"desc":"Lempar bola listrik ke satu target. Makin tipis HP musuh, makin sakit damage-nya.","when":"Buat finishing: tekan pas HP musuh udah di bawah setengah, atau setelah musuh ke-stun Thunderbolt/Volt Tackle biar pasti kena.","avoid":"Jangan buang di awal fight waktu HP musuh masih penuh, damage-nya biasa aja dan lo nggak punya finisher pas dibutuhin.","upgradeNote":"Lv11: cooldown lebih pendek jadi bisa lebih sering dipakai buat eksekusi."},{"name":"Thunder","level":4,"upgradeLevel":11,"desc":"Nurunin beberapa petir ke area di sekitar lo (lebih dari satu kali hit) selama beberapa detik.","when":"Teamfight dan objective (Rayquaza/Regieleki): tekan saat musuh ngumpul atau abis ke-stun Thunderbolt, lalu tetep nembakin basic attack sambil petir jalan.","avoid":"Jangan pakai buat 1v1 lawan target yang gesit, mereka tinggal jalan keluar area petirnya.","upgradeNote":"Lv11: jumlah petir nambah, damage total di teamfight naik."}]},"slot2":{"base":{"name":"Electroweb","level":1,"desc":"Lempar jaring listrik ke area, musuh yang kena jadi nggak bisa gerak sebentar."},"choices":[{"name":"Volt Tackle","level":6,"upgradeLevel":13,"desc":"Pikachu nge-dash ke depan sambil listrikan, musuh yang kena dilempar (throw) dan lo dapet tambahan movement speed sebentar.","when":"Dua fungsi: kabur (dash ke arah tim lo) atau buka combo dengan nge-throw musuh terus langsung Electro Ball/Thunderstorm.","avoid":"Jangan dash maju ke tengah 5 musuh buat 'inisiasi', lo bukan Defender; abis dash lo nggak punya escape lagi.","upgradeNote":"Lv13: damage naik dan efeknya lebih kuat, tapi fungsi utamanya tetap mobilitas + throw."},{"name":"Thunderbolt","level":6,"upgradeLevel":13,"desc":"Ledakan listrik di area target, musuh yang kena nggak bisa bergerak dan bertindak (stun) sebentar.","when":"Buka setiap fight dengan ini: kena stun, lalu lanjut Thunder/Electro Ball + basic attack. Juga buat nahan musuh yang ngejar partner lo.","avoid":"Jangan tembak ke musuh yang lagi dash/mobile, gampang miss; tunggu dia berhenti atau kejebak CC tim lo.","upgradeNote":"Lv13: damage Thunderbolt naik, jadi buka combo-nya makin sakit."}]},"unite":{"name":"Thunderstorm","level":9,"desc":"Petir gede nyambar musuh di sekitar lo, lalu beberapa detik berikutnya petir terus nyambar dua musuh terdekat. Lo juga dapet shield + movement speed selama efeknya.","when":"Masuk teamfight pas musuh udah ngumpul (abis Thunderbolt stun) atau pas lo dikejar dan butuh shield + damage buat balik keadaan. Charge-nya cepet, jadi jangan disimpen lama.","avoid":"Jangan aktifin dari jauh di belakang, petirnya cuma nyambar musuh yang DEKAT lo; harus di radius musuh dulu."},"builds":[{"name":"Thunder + Thunderbolt — AoE Teamfight","moves":["Thunder","Thunderbolt"],"recommended":true,"style":"Build teamfight: stun segerombol musuh, lalu timpa petir dari belakang Defender lo.","heldItems":[{"name":"Wise Glasses","why":"Sp. Atk flat, Pikachu scaling-nya special dan hampir semua damage-nya dari move."},{"name":"Choice Specs","why":"Nambah burst tiap move kena, cocok karena Pikachu spam move terus."},{"name":"Slick Spoon","why":"Nembus Sp. Def musuh, bikin damage lo tetap sakit ke Defender."}],"battleItem":{"name":"Eject Button","why":"Pikachu nggak punya dash di build ini, Eject satu-satunya cara kabur dari Speedster."},"combo":["Thunderbolt ke gerombolan musuh (stun)","Langsung Thunder di tempat yang sama","Basic attack sampai boosted keluar sambil petir jalan","Kalau fight besar: Thunderstorm pas mereka masih ngumpul"],"comboNote":"Urutan kuncinya stun dulu. Thunder tanpa Thunderbolt gampang di-dodge."},{"name":"Electro Ball + Volt Tackle — Single-Target Burst","moves":["Electro Ball","Volt Tackle"],"recommended":false,"style":"Build eksekusi: lebih mobile, fokus matiin satu target yang udah tipis.","heldItems":[{"name":"Choice Specs","why":"Burst per move, Electro Ball jadi finisher yang makin sakit."},{"name":"Slick Spoon","why":"Penetrasi Sp. Def biar eksekusi tetap jalan ke target tanky."},{"name":"Energy Amplifier","why":"Thunderstorm charge cepat; ini nambah damage abis Unite dan ngisi gauge lebih cepat."}],"battleItem":{"name":"Eject Button","why":"Double escape bareng Volt Tackle, atau buat nyusul target yang mau kabur."},"combo":["Volt Tackle ke target (throw)","Electro Ball pas dia masih di udara/baru jatuh","Boosted basic attack buat paralisis","Thunderstorm kalau dia belum mati dan ada temennya"],"comboNote":"Build ini lebih enak di lane buat duel; di teamfight besar Thunder+Thunderbolt biasanya lebih bernilai."}],"situations":{"gank":"Kalau lo yang nge-gank: Thunderbolt dulu buat stun, baru Thunder/Electro Ball. Kalau lo yang dikeroyok: Thunderbolt/Electroweb ke yang paling deket buat ngerem mereka, lalu Eject/Volt Tackle ke arah tim.","escape":"Pikachu lambat banget. Simpan Eject Button khusus buat Speedster (Talonflame, Zeraora). Static dan boosted attack ngasih paralisis, pakai buat ngejauh sedikit, tapi jangan ngarep bisa lari dari dash.","objective":"Rayquaza/Regieleki: berdiri di belakang Defender, di luar jangkauan dash musuh. Jaga Thunderbolt buat waktu musuh masuk pit atau coba steal, lalu Thunder di pit. Thunderstorm pas kedua tim ngumpul.","duel":"Jaga jarak, poke pakai basic attack sampai boosted. Begitu musuh maju: Thunderbolt stun, Electro Ball/Thunder, boosted attack. Kalau musuh melee punya dash, mundur ke arah goal/tim, jangan ladenin di tengah.","teamfight":"Posisi di baris belakang. Prioritas target: Attacker/Supporter rapuh yang keluar posisi, atau siapa pun yang kena CC tim lo. Jangan kejar Defender yang berdiri di depan kecuali target lain nggak ada."},"mistakes":["Maju terlalu depan karena ngerasa damage gede, padahal Pikachu tipis dan nggak ada mobilitas.","Nembak Thunder/Electro Ball tanpa setup CC, hasilnya di-dodge terus.","Nyimpen Thunderstorm kelamaan, padahal charge-nya cepat dan shield-nya bisa nyelametin lo.","Pilih Volt Tackle terus dipakai buat 'nyerbu' ke tengah musuh, bukan buat kabur/pick."],"counters":{"hardFor":[{"name":"Talonflame","why":"Terbang langsung ke muka lo dan burst sebelum lo sempet bereaksi.","how":"Jaga Thunderbolt/Electroweb khusus buat dia, dan simpen Eject Button; berdiri dekat Defender."},{"name":"Lucario","why":"Dash berulang + burst fisik, susah di-kite.","how":"Jangan duel sendirian, main dekat tim; stun dia pas dia abis pakai dash."},{"name":"Blastoise","why":"Tanky, punya CC (Surf/Rapid Spin) dan bisa narik lo keluar posisi.","how":"Jaga jarak lebih jauh dari biasanya, fokus ke target lain, pakai Static/boosted buat kabur kalau dia nempel."},{"name":"Gengar / Zeraora","why":"Assassin yang masuk dari belakang dan nggak ngasih waktu casting.","how":"Selalu simpan satu CC dan Eject; jangan farm sendirian di jungle musuh."}],"goodAgainst":[{"name":"Supporter (Clefable, Comfey, Eldegoss, Hoopa, Mr. Mime)","why":"Mereka rapuh dan sering ngumpul; Thunderbolt + Thunder ngehabisin mereka sebelum healing jalan."},{"name":"Melee tanpa gap-closer bagus (Snorlax, Mamoswine)","why":"Lo bisa poke dan stun dari jauh, mereka nggak bisa nyentuh lo kalau lo kite dengan benar."}]},"cinderace":{"similarity":5,"note":"Sama-sama ranged attacker rapuh yang harus jaga jarik, jadi insting posisi dan 'jangan masuk duluan' dari Cinderace kepake. Bedanya: damage Pikachu dari MOVE, bukan basic attack, dan nggak ada Feint buat kabur, jadi lo harus mikir dua kali sebelum maju. Ganti kebiasaan auto-attack jadi 'stun dulu, baru move damage'."},"sources":["https://bulbapedia.bulbagarden.net/wiki/Pikachu_(UNITE)","https://serebii.net/pokemonunite/pokemon/pikachu.shtml","https://game8.co/games/Pokemon-UNITE/archives/335464","https://www.dittobase.com/unite/pokemon/pikachu"],"confidence":"high","notes":"Nama move, level (Lv4 / Lv6, upgrade Lv11 / Lv13), Unite Lv9 cocok antara Bulbapedia dan Game8; Serebii-nya cuma sebagian (ringkasan fetch Serebii bilang Thunderbolt 'Lv13' tapi itu level upgrade, bukan level ambil). Item: Game8 pakai Wise Glasses/Choice Specs/Slick Spoon, dittobase pakai Energy Amplifier/Curse Incense/Drive Lens; gw ambil Game8 sebagai utama dan Energy Amplifier dari dittobase. Patch terakhir yang tercatat di Game8 (v1.20.3.10, Okt 2025): Electro Ball damage diturunin sedikit. Tier Game8 'S' mungkin tidak up-to-date.","image":"img/pikachu.webp","status":"Owned"},{"name":"Scizor","slug":"scizor","role":"Serba-Bisa","damage":"Physical","range":"Melee","difficulty":"Menengah","evolutions":"Scyther (Lv1) → Scizor (Lv5, HANYA kalau lo pilih Bullet Punch; pilih Dual Wingbeat = tetap Scyther sampai akhir match)","tagline":"Bruiser dash-heavy dengan dua kepribadian: Scyther lincah-rapuh (Dual Wingbeat) atau Scizor tebal-nempel (Bullet Punch), dipilih di Lv5.","passive":{"name":"Technician","desc":"Tiap habis pakai move, basic attack berikutnya jadi dua pukulan berturut (yang kedua lebih kecil). Jadi pola idealnya: move, basic, move, basic."},"basicAttack":"Melee, tiap serangan ketiga jadi boosted. Scyther: boosted nambah damage dan speed gerak lo. Scizor: boosted nge-slow musuh dan naikin Defense lo (bisa numpuk). Selipin basic attack setelah tiap move biar Technician jalan.","lanes":["Top","Jungle"],"laneNote":"Jungle paling enak karena spike Lv5 (pilih bentuk) dan Lv7 (Double Hit/Swords Dance) cepat kecapai. Top juga jalan sebagai bruiser.","earlyGame":"Lv1 ambil Fury Cutter (dua tebasan kerucut) dan Quick Attack (dash). Pola move-basic-move-basic ke wild biar Technician kepake. Scyther awal lumayan sakit, boleh contest wild lane, tapi tipis, jadi jangan trade sampai sekarat. Putuskan bentuk sebelum Lv5.","powerSpike":"Lv5 pilih bentuk: Dual Wingbeat (tetap Scyther, burst + heal) atau Bullet Punch (jadi Scizor, sustain + shield). Lv7 Double Hit/Swords Dance bikin pola serangan lengkap, Lv9 Unite Green/Red Illusion Dive.","slot1":{"base":{"name":"Fury Cutter","level":1,"desc":"Tebas dua kali di area kerucut depan, tebasan kedua lebih sakit."},"choices":[{"name":"Dual Wingbeat","level":5,"upgradeLevel":11,"desc":"SCYTHER (gak evolve). Tebas area berbentuk X di depan; kalau bagian tengah kena, HP lo pulih. Kalau kena, bisa ditekan lagi buat dash ke satu arah yang makin sakit kalau HP musuh makin rendah.","when":"Tekan dari jarak nempel supaya bagian tengah X kena (heal), lalu dash susulan buat ngabisin target yang HP-nya udah turun.","avoid":"Jangan buang dash susulannya ke target HP penuh, bonus damage-nya ngikut HP rendah. Ingat: pilih ini = lo tetap Scyther yang tipis sampai match selesai.","upgradeNote":"Lv11 damage naik."},{"name":"Bullet Punch","level":5,"upgradeLevel":11,"desc":"EVOLVE jadi SCIZOR. Dash pendek lalu pukul 3 kali; tiap kena, cooldown berkurang dan HP lo pulih sesuai damage. Tekan lagi buat nambah pukulan sampai 5.","when":"Tekan terus-terusan pas nempel musuh: cooldown-nya pendek dan tiap kena makin cepat balik, jadi ini sumber damage + sustain utama lo.","avoid":"Jangan tekan ke arah kosong buat kabur, dash-nya pendek dan lo kehilangan heal.","upgradeNote":"Lv11 (beberapa sumber bilang Lv10) tiap kena lo dapat shield."}]},"slot2":{"base":{"name":"Quick Attack","level":1,"desc":"Dash ke depan, damage ke musuh yang kelewatin."},"choices":[{"name":"Double Hit","level":7,"upgradeLevel":13,"desc":"Lompat ke satu arah dan nge-mark musuh yang kena, lalu bisa lompat lagi. Setelah mendarat, boosted attack berikutnya otomatis nerjang musuh terdekat. KO musuh yang di-mark = semua cooldown lo berkurang.","when":"Tekan buat engage (dua lompatan) atau kabur. Pas target di-mark udah tipis, kejar dia: KO-nya bikin cooldown lo balik buat target berikutnya.","avoid":"Jangan pakai dua lompatan sekaligus buat masuk kalau lo belum yakin bisa bunuh, lo kehabisan jalan keluar.","upgradeNote":"Lv13 (beberapa sumber bilang Lv12) cooldown lebih pendek."},{"name":"Swords Dance","level":7,"upgradeLevel":13,"desc":"Dash pendek dan Attack lo naik sebentar. Selama buff, basic attack kedelapan jadi serangan area garis yang nembus.","when":"Tekan tepat sebelum nempel musuh buat buff Attack, lalu spam basic attack + Bullet Punch biar pukulan kedelapan keluar.","avoid":"Jangan tekan jauh dari fight, buff-nya habis sebelum lo nyampe. Patch Des 2025 nurunin buff Attack-nya.","upgradeNote":"Lv13 damage yang lo terima pas dash berkurang."}]},"unite":{"name":"Green Illusion Dive (Scyther) / Red Illusion Dive (Scizor)","level":9,"desc":"Scyther (Green): dash ke satu musuh, muncul 5 bayangan yang nyebar lalu balik, damage + mark; bisa ditekan lagi buat dash. Scizor (Red): dash ke satu musuh, pukul berkali-kali sambil slow, pukulan terakhir ngeluarin 5 bayangan; tekan lagi buat dash + hantam tanah area, dan kalau lo nabrak musuh pas dash, dia ke-grab dan bisa di-stun bayangan.","when":"Scyther: pakai buat burst carry yang misah, KO target yang di-mark bikin cooldown balik. Scizor: pakai buat lock carry musuh di tengah fight (slow + grab + stun).","avoid":"Jangan tekan ke tank; Unite dua-duanya single-target yang nilainya ada di bunuh/ngunci carry."},"builds":[{"name":"Bullet Punch + Swords Dance — Scizor Sustain Brawler","moves":["Bullet Punch","Swords Dance"],"recommended":true,"style":"Jadi Scizor, nempel musuh, spam Bullet Punch + basic attack buat heal/shield/Defense stack, Swords Dance buat buff.","heldItems":[{"name":"Accel Bracer","why":"Attack dan heal naik tiap KO/assist, nambah sustain brawler."},{"name":"Attack Weight","why":"Scaling Attack dari score."},{"name":"Razor Claw","why":"Basic attack setelah move dapat bonus damage + slow; Scizor nyelipin basic attack setelah tiap move (Technician)."}],"battleItem":{"name":"Full Heal","why":"Scizor harus nempel; lepas CC biar rantai Bullet Punch gak putus."},"combo":["Swords Dance ke arah musuh (Attack naik).","Bullet Punch, basic attack (Technician double hit), Bullet Punch lagi begitu cooldown balik, ulang.","Red Illusion Dive ke carry pas dia nyoba kabur, tekan lagi buat grab + stun."],"comboNote":"Energy Amplifier bisa gantiin Razor Claw kalau lo sering pakai Unite."},{"name":"Bullet Punch + Double Hit — Scizor Mobile","moves":["Bullet Punch","Double Hit"],"recommended":false,"style":"Scizor yang lebih lincah: Double Hit buat masuk/keluar dan reset cooldown lewat KO, Bullet Punch buat sustain.","heldItems":[{"name":"Accel Bracer","why":"Sustain dan Attack dari KO."},{"name":"Attack Weight","why":"Scaling dari score."},{"name":"Energy Amplifier","why":"Unite lebih sering dan lebih sakit; Red Illusion Dive sering jadi finisher."}],"battleItem":{"name":"Full Heal","why":"Anti CC."},"combo":["Double Hit lompat ke target (mark), basic attack boosted otomatis nerjang.","Bullet Punch spam + basic attack sampai target tipis.","Red Illusion Dive buat finish; KO target yang di-mark bikin cooldown balik, lanjut target berikutnya."],"comboNote":"Eject Button jadi flex kalau tim musuh minim CC."},{"name":"Dual Wingbeat + Double Hit — Scyther Assassin","moves":["Dual Wingbeat","Double Hit"],"recommended":false,"style":"Tetap Scyther: lebih cepat, lebih sakit, lebih rapuh. Masuk, burst carry, KO buat reset cooldown, keluar.","heldItems":[{"name":"Muscle Band","why":"Scyther banyak basic attack cepat, Muscle Band nambah damage per hit."},{"name":"Attack Weight","why":"Scaling dari score."},{"name":"Razor Claw","why":"Bonus damage basic attack setelah tiap move, cocok sama Technician."}],"battleItem":{"name":"Full Heal","why":"Scyther mati kalau ke-CC, Full Heal buat lepas dan lanjut combo."},"combo":["Double Hit lompat ke carry (mark), boosted attack nerjang.","Dual Wingbeat dari jarak nempel (tengah X kena = heal), tekan lagi buat dash finisher ke target HP rendah.","Green Illusion Dive kalau target belum mati, KO yang di-mark bikin semua cooldown balik, langsung ke target berikutnya."],"comboNote":"Dittobase juga list Accel Bracer + Energy Amplifier dan Charging Charm sebagai varian; Scyther rapuh, jangan masuk tanpa jalan keluar."}],"situations":{"gank":"Nge-gank: Double Hit/Quick Attack masuk, langsung ke carry, Bullet Punch (Scizor) atau Dual Wingbeat (Scyther) spam. Dikeroyok: Scizor bisa tahan sebentar dengan heal/shield Bullet Punch dan Defense stack, lalu keluar pakai Double Hit/Swords Dance dash; Scyther harus langsung keluar.","escape":"Double Hit (dua lompatan) atau Swords Dance dash, Full Heal kalau ke-CC. Scyther: Dual Wingbeat dash susulan juga bisa dipakai buat lari. Jangan andelin Bullet Punch buat kabur.","objective":"Di Rayquaza, lo bukan yang stay di pit; lo yang flank dan bunuh carry/jungler musuh di tepi. Simpan Unite buat jungler musuh yang mau steal (Red Illusion Dive grab-nya ngunci dia). Scizor boleh ikut nempel Rayquaza buat Defense stack dari boosted attack.","duel":"Scizor 1v1 kuat lawan melee: Bullet Punch heal + shield + Defense stack bikin lo menang trade panjang. Scyther 1v1 harus cepat: burst dulu, kalau gak mati dalam dua rotasi, mundur.","teamfight":"Masuk dari samping setelah tank engage. Target: carry musuh, bukan tank. Scizor: lock dia pakai Red Illusion Dive dan spam Bullet Punch. Scyther: Double Hit ke carry, burst, KO buat reset cooldown, cabut."},"mistakes":["Gak sadar Dual Wingbeat ngunci lo jadi Scyther selamanya, lalu heran kenapa gampang mati di late game.","Lupa pola move-basic-move-basic, Technician gak kepake dan damage lo setengah.","Ngehajar tank di teamfight, Unite dan Bullet Punch lo buat carry.","Pakai dua lompatan Double Hit sekaligus buat masuk tanpa jalan keluar."],"counters":{"hardFor":[{"name":"Umbreon","why":"Mean Look ngunci lo yang andelin dash, Fake Tears turunin Def, dan Inner Focus bikin grab Unite lo gak jalan.","how":"Jangan 1v1 dia, pakai Double Hit buat lewatin dia ke carry."},{"name":"Lapras","why":"Bubble Beam stun + slow terus-terusan bikin lo gak bisa nempel, dan heal lo kalah sama damage area-nya.","how":"Tunggu Bubble Beam-nya kebuang, baru masuk."},{"name":"Mewtwo Y","why":"Burst special dari jauh, Defense stack Scizor gak nolong lawan special, dan dia teleport pas lo lompat.","how":"Masuk cuma pas dia habis pakai mobility-nya, Full Heal buat lepas CC."}],"goodAgainst":[{"name":"Cinderace","why":"Tipis dan harus kiting; Double Hit lompatan ganda nyusul Feint, Bullet Punch slow bikin dia gak bisa lari."},{"name":"Delphox","why":"Lambat dan rapuh, satu rotasi Double Hit + Bullet Punch/Dual Wingbeat udah hampir mati."},{"name":"Azumarill","why":"Scizor sustain + Defense stack bikin trade melee lawan dia seimbang, dan Red Illusion Dive ngunci dia yang gak punya escape."}]},"cinderace":{"similarity":5,"note":"Ini yang paling mirip di daftar ini: sama-sama mobile, sama-sama basic attack penting, dan pola 'move lalu auto' dari Cinderace langsung kepake lewat Technician. Bedanya lo melee dan harus nempel, bukan kiting. Kalau lo mau feel yang paling dekat dengan Cinderace, main Scyther (Dual Wingbeat) yang lincah tapi rapuh; kalau mau lebih pemaaf, pilih Scizor (Bullet Punch) yang bisa nempel lama."},"sources":["https://serebii.net/pokemonunite/pokemon/scizor.shtml","https://bulbapedia.bulbagarden.net/wiki/Scizor_(UNITE)","https://www.dittobase.com/unite/pokemon/scizor","https://www.dittobase.com/unite/pokemon/scyther","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"medium","notes":"Level upgrade beda antar sumber: Serebii bilang Bullet Punch+ Lv10 dan Double Hit+ Lv12, Bulbapedia dan Dittobase bilang Lv11 dan Lv13; gw pakai 11/13 (pola standar game). Patch 1.21.1.2 (Des 2025) nerf Scizor: Defense stack boosted attack 50% → 40%, Swords Dance buff 20% → 15%, Double Hit heal naik 10%. Unite move beda nama per bentuk (Green Illusion Dive = Scyther, Red Illusion Dive = Scizor), dua-duanya Lv9. Counter adalah inferensi dari mekanik.","image":"img/scizor.webp","status":"Owned"},{"name":"Azumarill","slug":"azumarill","role":"Serba-Bisa","damage":"Physical","range":"Melee","difficulty":"Menengah","evolutions":"Marill (Lv1) → Azumarill (Lv4)","tagline":"Duelist melee yang selalu crit kalau cuma ngehajar satu target, jago sustain dan ngejar.","passive":{"name":"Huge Power","desc":"Kalau basic attack/move/Unite lo cuma kena SATU musuh, hit-nya pasti crit. Kalau kena dua musuh atau lebih, gak pernah crit. Jadi Azumarill paling sakit di 1v1."},"basicAttack":"Melee biasa. Tiap serangan ketiga jadi boosted: pukulan area kerucut ke depan dengan damage lebih gede. Inget: kalau boosted kena 2 musuh, crit-nya hilang.","lanes":["Top","Bottom","Jungle"],"laneNote":"Jungle paling cocok karena level cepat dan lo gank buat 1v1 (crit pasti). Top/Bottom juga bisa sebagai bruiser lane.","earlyGame":"Lv1 ambil Tackle (dash + stun) dan Bubble (slow). Marill lemah, jadi farm aman sampai Lv4 evolve. Setelah evolve dan dapat Whirlpool/Aqua Tail baru mulai cari 1v1 di lane.","powerSpike":"Lv4 (Azumarill + Whirlpool/Aqua Tail) sustain mulai jalan. Lv6 dapat Play Rough/Water Pulse, Lv8 Unite Belly Bash buat all-in. Lv10/12 upgrade bikin lo bruiser penuh.","slot1":{"base":{"name":"Tackle","level":1,"desc":"Nerjang ke depan, damage dan bikin musuh gak bisa gerak sebentar."},"choices":[{"name":"Whirlpool","level":4,"upgradeLevel":10,"desc":"Empat pusaran air muter di sekeliling lo, ngasih damage ke musuh yang kena dan heal HP lo tiap kena.","when":"Tekan pas lo nempel musuh (1v1 atau pas dikeroyok) biar damage dan heal jalan terus selama lo nempel.","avoid":"Jangan tekan dari jauh sebelum nempel, pusarannya cuma kena kalau musuh dekat.","upgradeNote":"Lv10 heal/damage pusarannya naik."},{"name":"Aqua Tail","level":4,"upgradeLevel":10,"desc":"Tiga basic attack berikutnya jadi lebih cepat dan areanya lebih luas; kalau kena dari jarak agak jauh, lo heal dan cooldown move lain berkurang.","when":"Tekan sebelum mulai nge-trade basic attack, lalu pukul dari ujung jangkauan biar heal dan cooldown reduction-nya kena.","avoid":"Jangan aktifin lalu nempel terlalu rapat, bonus heal-nya cuma keluar kalau hit dari jarak agak jauh.","upgradeNote":"Lv10 efek tiga basic attack-nya lebih kuat."}]},"slot2":{"base":{"name":"Bubble","level":1,"desc":"Semprot gelembung kerucut ke depan, damage dan slow."},"choices":[{"name":"Play Rough","level":6,"upgradeLevel":12,"desc":"Speed lo naik sebentar dan basic attack berikutnya berubah: lo nerjang satu musuh, mukul berkali-kali, dan dia gak bisa gerak sebentar.","when":"Tekan buat ngejar dan ngunci satu target (carry musuh yang kabur) atau buat nutup jarak di 1v1. Kena satu target = crit pasti.","avoid":"Jangan tekan pas musuh ngumpul rapat, basic attack boosted-nya bisa kena lebih dari satu dan crit-nya hilang.","upgradeNote":"Lv12 damage/durasi gak bisa gerak naik. Patch April 2026 buff damage Play Rough cukup besar."},{"name":"Water Pulse","level":6,"upgradeLevel":12,"desc":"Tembak bola air yang slow dan mantul ke beberapa musuh (sampai 3 target).","when":"Tekan buat poke dari jarak, slow musuh yang kabur, atau pas ada beberapa musuh biar mantul.","avoid":"Jangan tekan ke 1 target pas lo mau burst, mantulannya kebuang dan damage-nya kalah dari Play Rough.","upgradeNote":"Lv12 bisa mantul ke 5 target."}]},"unite":{"name":"Belly Bash","level":8,"desc":"Lo nepuk perut 3 kali: dapat shield, tiap tepukan ngorbanin sedikit HP buat naikin Attack. Lalu pilih target dan nerjang, damage dan lempar semua musuh yang kena.","when":"Pakai buat buka 1v1 atau duel di mana lo pasti nempel: tepuk perut di tempat aman (belakang tembok) lalu dive carry musuh.","avoid":"Jangan tekan pas HP udah tipis (tepukannya makan HP) atau pas lo dikeroyok, Attack buff-nya gak kepake kalau lo mati."},"builds":[{"name":"Aqua Tail + Water Pulse — Lane Bruiser","moves":["Aqua Tail","Water Pulse"],"recommended":true,"style":"Trade basic attack dari ujung jangkauan Aqua Tail, poke dan slow pakai Water Pulse, sustain lewat heal dan cooldown reduction.","heldItems":[{"name":"Attack Weight","why":"Attack naik tiap score, Azumarill gampang score karena sustain."},{"name":"Scope Lens","why":"Huge Power bikin lo selalu crit di single target, Scope Lens bikin crit-nya makin sakit."},{"name":"Accel Bracer","why":"Attack dan heal naik tiap KO/assist, cocok buat bruiser yang sering 1v1."}],"battleItem":{"name":"X Speed","why":"Azumarill gak punya dash setelah Tackle hilang, X Speed buat ngejar dan kabur."},"combo":["Water Pulse buat slow target dari jauh.","Aqua Tail, lalu 3 basic attack dari jarak agak jauh biar heal dan cooldown reduction keluar.","Ulangi Water Pulse (cooldown udah turun), Belly Bash kalau target mau kabur."],"comboNote":"Muscle Band bisa gantiin Accel Bracer kalau lo mau damage basic attack lebih stabil dari awal."},{"name":"Whirlpool + Play Rough — Duelist Jungle","moves":["Whirlpool","Play Rough"],"recommended":false,"style":"Gank 1v1: Play Rough buat nempel dan ngunci, Whirlpool buat sustain sambil ngehajar.","heldItems":[{"name":"Attack Weight","why":"Scaling Attack dari score."},{"name":"Scope Lens","why":"Crit pasti di 1v1 jadi makin sakit."},{"name":"Weakness Policy","why":"Attack naik pas lo kena damage, cocok buat gaya nempel musuh."}],"battleItem":{"name":"X Speed","why":"Nutup jarak ke target gank."},"combo":["Whirlpool begitu mau nempel (pusarannya mulai damage + heal).","Play Rough ke satu target, basic attack berikutnya ngunci dia.","Basic attack terus sampai boosted keluar, Belly Bash kalau dia hampir kabur."],"comboNote":"Full Heal bisa gantiin X Speed kalau tim musuh banyak CC."}],"situations":{"gank":"Nge-gank: Play Rough ke target yang sendirian (crit pasti), Whirlpool/Aqua Tail buat sustain sambil ngabisin. Dikeroyok: Water Pulse/Bubble buat slow, mundur sambil Whirlpool buat heal, jangan nekat.","escape":"X Speed atau Play Rough ke wild/musuh terdekat buat speed boost, Water Pulse buat slow yang ngejar. Gak ada dash asli setelah Lv4, jadi jangan masuk terlalu dalam.","objective":"Di Rayquaza, cari carry musuh yang misah dan 1v1 dia (crit pasti). Hindari ngehajar area yang ada 2 musuh (crit hilang). Belly Bash buat lempar musuh keluar dari pit pas tim mau secure.","duel":"Ini kekuatan utama lo. Nempel, basic attack, Whirlpool/Aqua Tail buat heal, Play Rough buat ngunci. Hampir semua Pokémon kalah 1v1 lawan lo kalau level setara.","teamfight":"Jangan masuk ke tengah 5 musuh. Masuk dari samping/belakang, cari carry yang terpisah, isolasi dia. Belly Bash pas lo udah dapet 1 target yang pasti."},"mistakes":["Ngehajar area dengan 2+ musuh terus heran kenapa damage-nya kecil (Huge Power matiin crit).","Belly Bash pas HP udah tipis atau pas dikeroyok.","Main kayak tank di teamfight, padahal lo duelist yang harus isolasi target.","Nempel terlalu rapat pas pakai Aqua Tail, padahal heal-nya butuh hit dari jarak agak jauh."],"counters":{"hardFor":[{"name":"Umbreon","why":"Tank anti-CC yang bisa ngunci lo pakai Mean Look dan damage-nya ngikut Attack lo (Foul Play).","how":"Jangan buang waktu 1v1 lawan dia, cari carry-nya."},{"name":"Mewtwo Y","why":"Burst dari jauh dan mobile, lo gak pernah nempel dan HP lo ketarik duluan.","how":"Tunggu dia pakai teleport/CC, lalu Play Rough buat ngunci dan all-in."},{"name":"Blissey","why":"Dia ngasih shield + unstoppable ke carry yang lo kejar, Play Rough lock lo gak jalan.","how":"Targetin pas Safeguard-nya habis, atau ganti target ke Blissey-nya kalau dia misah."}],"goodAgainst":[{"name":"Cinderace","why":"Attacker tipis tanpa escape setelah Feint; Play Rough ngunci dia dan crit pasti bikin dia mati cepat."},{"name":"Delphox","why":"Rapuh dan lambat; begitu lo nempel pakai Play Rough, dia gak punya jawaban."},{"name":"Zacian","why":"1v1 crit pasti + sustain Whirlpool bikin lo bisa out-trade dia kalau level setara."}]},"cinderace":{"similarity":4,"note":"Sama-sama basic attack carry yang ngeburst satu target, jadi feel 'auto-attack sambil nunggu boosted' kebawa. Bedanya lo melee, gak ada Feint buat kabur, dan lo justru harus nempel bukan kiting. Yang paling perlu diubah: kebiasaan nembak ke kerumunan, karena Huge Power cuma crit kalau kena satu musuh."},"sources":["https://bulbapedia.bulbagarden.net/wiki/Azumarill_(UNITE)","https://serebii.net/pokemonunite/pokemon/azumarill.shtml","https://www.dittobase.com/unite/pokemon/azumarill","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"high","notes":"Ekstrak Serebii ngebalikin urutan slot/level secara membingungkan (Bubble Lv6, Play Rough Lv12); Bulbapedia dan Dittobase konsisten: Tackle → Whirlpool/Aqua Tail Lv4 (+Lv10), Bubble → Play Rough/Water Pulse Lv6 (+Lv12), Unite Lv8. Gw pakai versi Bulbapedia. Patch 1.21.1.5 (April 2026) buff Whirlpool heal, Play Rough damage, dan Belly Bash. Difficulty: Serebii bilang Intermediate, Dittobase bilang Novice. Counter adalah inferensi dari mekanik.","image":"img/azumarill.webp","status":"Owned"},{"name":"Dodrio","slug":"dodrio","role":"Pelari Cepat","damage":"Physical","range":"Melee","difficulty":"Ahli","evolutions":"Doduo (Lv1) → Dodrio (Lv5)","tagline":"Speedster paling cepat di game yang hidup dari sprint gauge: lari, tabrak, score, kabur, ulangi.","passive":{"name":"Run Away","desc":"Movement speed lo naik kalau ada musuh di dekat. Selama lo gerak, sprint gauge lo ngisi; kalau lo berhenti atau terlalu lambat, gauge-nya turun. Bonus: saat score, energi lo dibagi jadi 3 bagian (Doduo: 2), jadi lo bisa score bertahap dan susah dicegat."},"basicAttack":"Basic attack melee, serangan ketiga jadi boosted (patuk beruntun). Kalau sprint gauge penuh, basic attack berikutnya berubah jadi charge/tabrak ke arah lo hadap sambil ngabisin gauge; kalau tabrakannya kena, semua cooldown move lo dipotong. Jadi auto lo pada dasarnya adalah dash.","lanes":["Jungle","Top","Bottom"],"laneNote":"Jungle paling enak: Lv5 cepat, dan Dodrio emang dibuat buat muter map, score, dan ngejar. Lane bisa (score-nya dipecah 3 bikin lo aman nge-dunk), tapi early Doduo lemah banget di trade.","earlyGame":"Sebagai Doduo, jangan trade; last-hit pakai Peck dan Quick Attack, terus lari terus biar sprint gauge ngisi. Target Lv5 secepat mungkin (Tri Attack / Drill Peck). Begitu Dodrio, mulai cari musuh yang over-extend atau score cepat di goal yang kosong; lo nggak harus menang fight, cukup menang energi.","powerSpike":"Lv5 (evolusi + Drill Peck / Tri Attack) langsung terasa karena sprint-charge mulai jalan; Lv7 (Jump Kick / Agility) kasih CC atau immunity; Lv9 Triple Trample bikin lo bisa engage sambil immune CC.","slot1":{"base":{"name":"Peck","level":1,"desc":"Patuk ke depan; kalau sprint gauge penuh, berubah jadi charge yang ngabisin gauge."},"choices":[{"name":"Tri Attack","level":5,"upgradeLevel":11,"desc":"Serangan kerucut ke depan dengan efek acak (burn / paralyze / slow). Kalau gauge penuh, nembak 3 proyektil sekaligus dengan efek sesuai warnanya, dan auto berikutnya tambah sakit + heal. Bisa nyimpen 2 charge.","when":"Tekan pas sprint gauge penuh buat poke dari jarak agak jauh sebelum masuk, atau buat nge-slow/paralyze musuh yang kabur. Enak buat ngejar dan buat nyentuh musuh tanpa nempel.","avoid":"Jangan pakai Tri Attack pas gauge kosong buat 'damage'; versi kosongnya lemah dan efek acaknya nggak bisa diandelin buat setup.","upgradeNote":"Lv11: damage dan efek bonusnya naik, jadi versi 3-proyektil lebih nyakitin."},{"name":"Drill Peck","level":5,"upgradeLevel":11,"desc":"Patuk beruntun ke depan (multi-hit); kalau sprint gauge penuh, lo dash sambil nyeruduk dan ngedorong musuh. Tiap kena, cooldown dipotong dan lo heal sebagian dari damage.","when":"Tekan ke satu target yang mau lo matiin, idealnya pas gauge penuh biar lo sekalian dash masuk dan dorong dia menjauh dari timnya. Ini sumber damage dan heal utama build agresif.","avoid":"Jangan Drill Peck ke arah kerumunan musuh kalau lo nggak punya Jump Kick / Agility siap; dorongannya bisa bawa lo masuk ke tengah tim mereka.","upgradeNote":"Lv11: damage dan heal-nya naik; versi gauge-penuh lebih nyakitin."}]},"slot2":{"base":{"name":"Quick Attack","level":1,"desc":"Dash ke depan dengan movement speed naik dan damage kecil; cooldown dipotong kalau kena."},"choices":[{"name":"Agility","level":7,"upgradeLevel":13,"desc":"Hapus status negatif, bikin lo immune hindrance sebentar, movement speed naik, dan sprint gauge ngisi lebih cepat.","when":"Tekan pas lo kena slow/stun mau masuk (bersihin CC), pas mau lari dari gank, atau buat ngisi gauge instan sebelum Drill Peck / Tri Attack versi penuh.","avoid":"Jangan tekan duluan sebelum musuh pakai CC; ini move reaktif, pakainya SETELAH mereka buang stun, bukan sebagai pembuka.","upgradeNote":"Lv13: sprint gauge langsung penuh saat Agility dipakai, jadi combo 'Agility → auto charge → Drill Peck' instan."},{"name":"Jump Kick","level":7,"upgradeLevel":13,"desc":"Lompat ke depan; kalau kena musuh, lo lompat lagi (bisa lewatin rintangan) dan injak, kasih damage + slow. Kena = sprint gauge ngisi dan cooldown dipotong.","when":"Tekan buat ngejar target yang kabur ke balik dinding, atau buat ngunci carry musuh sebelum Drill Peck. Juga alat kabur: Jump Kick kena minion/musuh lalu lompat lewatin tembok.","avoid":"Jangan Jump Kick ke ruang kosong; tanpa kena target lo nggak dapat lompatan kedua, nggak dapat gauge, dan cooldown-nya penuh.","upgradeNote":"Lv13: injakannya bikin musuh nggak bisa bergerak sebentar (stun), bukan cuma slow."}]},"unite":{"name":"Triple Trample","level":9,"desc":"Lo lari ke titik yang dipilih, immune hindrance selama lari, kasih damage + ngelempar musuh yang ditabrak. Sampai tujuan, Attack lo naik, dapat shield, dan sprint gauge ngisi lebih cepat sebentar.","when":"Pakai buat nembus CC musuh ke carry mereka di belakang, buat ngelempar musuh yang lagi secure objective, atau buat kabur sambil nabrak. Setelah mendarat lo dapet buff damage, jadi langsung lanjut Drill Peck + auto.","avoid":"Jangan pakai cuma buat jalan lebih cepat ke goal tanpa nabrak siapa pun; dan jangan ult ke tengah 5 musuh kalau tim lo nggak ikut, shield-nya nggak sebesar itu."},"builds":[{"name":"Drill Peck + Jump Kick — Assassin","moves":["Drill Peck","Jump Kick"],"recommended":true,"style":"Isolasi satu target: Jump Kick kunci, Drill Peck habisin, lari pergi. Build paling kuat sejak buff Sep 2026.","heldItems":[{"name":"Attack Weight","why":"Dodrio score bertahap dan sering, jadi stack Attack-nya gampang penuh."},{"name":"Razor Claw","why":"Habis move, auto berikutnya tambah sakit + slow; pas dengan pola Jump Kick → auto charge → Drill Peck."},{"name":"Muscle Band","why":"Auto lo sering (boosted + charge), damage persen HP bantu lawan tank."}],"battleItem":{"name":"X Attack","why":"Burst damage + attack speed buat ngabisin carry dalam satu kali masuk."},"combo":["Lari sampai sprint gauge penuh (passive), dekati target dari balik dinding.","Jump Kick kena target → lompat kedua + injak (slow / stun di Lv13).","Auto charge (gauge penuh) kena → cooldown kepotong, lalu Drill Peck versi penuh buat damage + heal. Ulangi Jump Kick kalau dia lari, atau lari pergi."],"comboNote":"Kuncinya: Dodrio nggak berhenti gerak. Berdiri diam = gauge habis = lo cuma burung lemah."},{"name":"Tri Attack + Agility — Hit and Run / Scorer","moves":["Tri Attack","Agility"],"recommended":false,"style":"Poke dari jarak sedang, score cepat, dan nggak pernah kena CC; cocok buat yang lebih suka main aman dan menang lewat energi.","heldItems":[{"name":"Attack Weight","why":"Build ini score terus-terusan; stack Attack cepat penuh."},{"name":"Accel Bracer","why":"Attack speed dan buff pas HP tinggi, bantu boosted attack lebih sering keluar."},{"name":"Float Stone","why":"Movement speed di luar combat bikin lo muter map dan ngisi gauge lebih cepat."}],"battleItem":{"name":"Full Heal","why":"Lapisan kedua anti-CC kalau Agility lagi cooldown; speedster yang nggak bisa gerak = mati."},"combo":["Agility (gauge langsung penuh di Lv13) sebelum nyentuh musuh.","Tri Attack versi penuh dari jarak: 3 proyektil + efek, lalu auto buat damage bonus + heal.","Kalau musuh ngejar, lari (gauge isi lagi), putar, Tri Attack lagi; kalau goal kosong, dunk bertahap."],"comboNote":"Tri Attack efeknya acak, jadi jangan nunggu paralyze; anggap semua bonus sebagai hadiah."}],"situations":{"gank":"Saat nge-gank: datang dari belakang musuh pas gauge penuh, Jump Kick ke carry, auto charge, Drill Peck. Saat dikeroyok: jangan lawan, Agility (bersihin CC) atau Jump Kick lewatin dinding, terus lari; passive bikin lo makin cepat kalau musuh dekat.","escape":"Lari aja, serius: Dodrio hampir nggak bisa dikejar kalau gauge-nya ada. Agility buat hapus slow/stun, Jump Kick ke minion/musuh terdekat buat lompat lewatin tembok, Triple Trample kalau bener-bener terkepung (immune hindrance selama lari).","objective":"Di Rayquaza / Regieleki: Dodrio bukan yang secure, lo yang ganggu. Muter ke belakang musuh, Jump Kick carry mereka, atau Triple Trample buat ngelempar yang lagi last-hit. Kalau tim lo kalah objective, langsung backdoor score di goal musuh yang kosong, score 3 tahap lo susah dicegat.","duel":"1v1 lawan squishy lo menang kalau gauge penuh: Jump Kick → charge → Drill Peck → auto, sambil terus gerak. Lawan tank/All-Rounder (Tsareena, Machamp, Blastoise) jangan lama-lama; tabrak lalu pergi.","teamfight":"Jangan di depan, jangan juga ikut dari awal. Tunggu CC musuh keluar, baru masuk dari sisi ke Attacker/Supporter. Prioritas: siapa pun yang paling jauh dari tank mereka. Setelah 1 kill, keluar, isi gauge, masuk lagi."},"mistakes":["Berdiri diam buat auto-attack kayak Attacker biasa; sprint gauge lo habis dan semua combo lo mati.","Trade sebagai Doduo di early; lo bakal kalah dan ketinggalan level.","Jump Kick atau charge ke ruang kosong (nggak kena target) sehingga nggak dapat gauge, cooldown reduction, atau lompatan kedua.","Masuk fight duluan sebelum CC musuh keluar; Dodrio tanpa Agility/Full Heal mati sekali kena Snorlax atau Blastoise.","Lupa kalau score lo dibagi 3 tahap: lo bisa dunk sedikit-sedikit, nggak perlu nunggu 50 energi."],"counters":{"hardFor":[{"name":"Snorlax","why":"Block ngehentiin dash lo, Yawn / Heavy Slam ngunci lo di tempat; begitu diam, lo mati.","how":"Jangan lewat dia, Jump Kick lewatin dinding ke carry di belakangnya; simpan Agility / Full Heal buat Yawn."},{"name":"Blastoise","why":"Rapid Spin + Hydro Pump / Surf nge-CC berkali-kali dan dia nggak bisa lo burst.","how":"Masuk hanya setelah Surf keluar; Triple Trample buat immune lewat area dia."},{"name":"Slowbro","why":"Telekinesis dan Amnesia / Scald bikin lo kebuntet dan ult-nya ngunci lo total.","how":"Jauhin dia, pakai Tri Attack poke dari luar jangkauan; kalau ke-Telekinesis, Agility / Full Heal."},{"name":"Mimikyu","why":"Play Rough ngunci lo, dan dia sustain + punya Disguise jadi nggak bisa lo habisin cepat.","how":"Jangan duel; tabrak sekali, lari, biarin tim lo yang ngurus."}],"goodAgainst":[{"name":"Pikachu","why":"Lambat, HP tipis, dan nggak bisa kabur dari Jump Kick + Drill Peck."},{"name":"Decidueye","why":"Attacker tanpa dash; Dodrio nyampe sebelum dia selesai nembak."},{"name":"Comfey","why":"Supporter kecil yang nempel ke carry; begitu dipisah atau dilempar Triple Trample, dia tinggal 2 patukan."}]},"cinderace":{"similarity":4,"note":"Cinderace nge-kite mundur sambil auto; Dodrio nge-kite MAJU dan muter, karena berhenti berarti kehilangan gauge. Yang bisa lo bawa: insting target squishy, dan kebiasaan ngitung boosted attack (di sini: ngitung gauge). Yang harus diubah: lo nggak nunggu musuh dateng, lo yang milih kapan dan dari arah mana nyentuh mereka, dan lo harus belajar score bertahap karena itu kekuatan terbesar Dodrio."},"sources":["https://www.serebii.net/pokemonunite/pokemon/dodrio.shtml","https://bulbapedia.bulbagarden.net/wiki/Dodrio_(UNITE)","https://www.dittobase.com/unite/pokemon/dodrio","https://gamewith.net/pokemon-unite/article/show/35393","https://www.sportskeeda.com/pokemon/pokemon-unite-dodrio-guide-best-movesets-builds-items","https://www.pokemonunite.jp/en/topics/battle/20260902-1/"],"confidence":"high","notes":"Patch 3 Sep 2026: Jump Kick cooldown turun, Drill Peck damage naik, energi Triple Trample turun, jadi build Drill Peck + Jump Kick lagi kuat. Dittobase nulis 'Level 11 upgrades' untuk Tri Attack/Drill Peck tapi itu level UPGRADE (move-nya sendiri Lv5, konsisten di Serebii/Bulbapedia/gamewith). Build dittobase pakai Charging Charm; gw ganti ke Muscle Band/Razor Claw karena Charging Charm cuma ngasih value kalau lo sering score penuh, sedangkan Dodrio score bertahap. Counter adalah inferensi mekanik (speedster rapuh vs CC berat), bukan dari tabel counter resmi.","image":"img/dodrio.webp","status":"Owned"},{"name":"Espeon","slug":"espeon","role":"Penyerang","damage":"Special","range":"Ranged","difficulty":"Menengah","evolutions":"Eevee (Lv1) → Espeon (Lv4)","tagline":"Burst mage jarak jauh yang kebal CC sekali per cooldown: nembak dari belakang, eksekusi musuh yang udah tipis.","passive":{"name":"Magic Bounce","desc":"Hindrance (stun, slow, dsb.) pertama yang mau kena lo dibatalin, lo jadi kebal CC sebentar, dan musuh yang nyoba CC lo kena damage + slow. Setelah itu masuk cooldown lama, jadi jangan 'minta' CC sembarangan."},"basicAttack":"Basic attack ranged biasa. Boosted-nya BUKAN tiap 3 hit tapi berdasarkan waktu (gauge): tiap gauge penuh, serangan berikutnya nembak sinar ke depan dengan damage gede + slow. Perhatiin gauge-nya, jangan buang boosted ke wild Pokémon pas mau fight.","lanes":["Bottom","Top"],"laneNote":"Bottom paling disaranin (Game8), Top juga oke. Espeon rapuh dan nggak punya dash sama sekali, jadi butuh partner lane yang bisa peel.","earlyGame":"Lv1-3 lo Eevee: poke Swift dari jauh, Growl buat slow musuh yang nyerang partner, fokus farm sampai Lv4. Setelah evolusi, Psyshock/Stored Power bikin lo bisa trade, tapi tetap jangan maju ke depan goal musuh tanpa partner.","powerSpike":"Lv4 evolusi + move 1 spike pertama, Lv6 move 2 (Psybeam/Future Sight) bikin damage lo ngebut, dan Lv8 Psychic Solare (Unite-nya lebih awal) buat ngelibas lane.","slot1":{"base":{"name":"Swift","level":1,"desc":"Nembak bintang ke musuh dari jauh."},"choices":[{"name":"Psyshock","level":4,"upgradeLevel":10,"desc":"Lempar beberapa proyektil psikis ke target; kalau semuanya kena target yang sama, musuh itu stun sebentar.","when":"Buat ngasih CC ke satu target: musuh yang nge-dive lo, atau buat nahan target biar tim lo follow-up. Paling enak ke musuh yang lagi slow/diam.","avoid":"Jangan lempar ke musuh yang lagi dash; sebagian proyektil miss dan stun-nya nggak keluar.","upgradeNote":"Lv10: damage naik dan stun-nya lebih konsisten."},{"name":"Stored Power","level":4,"upgradeLevel":10,"desc":"Nembak bola energi ke musuh acak di sekitar; damage-nya jauh lebih gede ke musuh yang HP-nya udah di bawah sekitar setengah, dan lo dapet movement speed.","when":"Ini finisher lo: tekan pas musuh udah tipis, atau setelah Psybeam/Psychic Solare buat eksekusi. Movement speed-nya juga buat kite.","avoid":"Jangan buang pas musuh HP penuh; damage normalnya kecil dan lo kehilangan finisher pas dibutuhin. Juga hati-hati: target-nya acak, jadi di tengah 3 musuh nggak selalu kena yang lo mau.","upgradeNote":"Lv10: damage bonus ke musuh tipis makin gede."}]},"slot2":{"base":{"name":"Growl","level":1,"desc":"Teriak ke satu musuh: damage kecil dan slow."},"choices":[{"name":"Psybeam","level":6,"upgradeLevel":12,"desc":"Nembak sinar jauh ke depan; setelah kena musuh pertama, sinar pecah ke beberapa arah ngenain musuh lain. Damage ekstra ke musuh yang kena hindrance.","when":"Move damage utama lo di build Stored Power: tembak setelah musuh kena CC (slow dari boosted attack, Psyshock, atau CC tim), lalu Stored Power buat finishing.","avoid":"Jangan tembak lurus ke Defender yang berdiri di depan; aim ke sudut biar pecahannya ngenain backline musuh.","upgradeNote":"Lv12: damage naik, cooldown lebih pendek."},{"name":"Future Sight","level":6,"upgradeLevel":12,"desc":"Nandain area/target; setelah jeda beberapa detik, meledak ngasih damage besar (sebagian berdasarkan max HP). Kalau lo ngenain target yang ditandai pakai move lain, cooldown-nya berkurang.","when":"Buat poke jarak jauh dan ngehajar Defender tanky (karena max HP damage). Tandai, lalu spam Stored Power/Psyshock ke target yang sama biar Future Sight cepat balik.","avoid":"Jangan pasang Future Sight ke musuh yang pasti bakal pindah/kabur; ledakannya telat dan nggak ngenain siapa-siapa.","upgradeNote":"Lv12: damage naik, bonus ke target yang ditandai lebih besar."}]},"unite":{"name":"Psychic Solare","level":8,"desc":"Ngangkat musuh di area dengan kekuatan psikis (mereka nggak bisa gerak sebentar), lalu meledak: damage gede dan ngedorong mereka.","when":"Buka teamfight pas 2-3 musuh ngumpul, lalu langsung Psybeam + Stored Power buat eksekusi. Juga buat ngusir musuh yang mau steal objective.","avoid":"Jangan pakai buat 1 musuh yang udah mau mati; charge-nya cepat tapi tetap sayang. Dan jangan pakai dari posisi depan, lo bakal nggak bisa mundur setelahnya."},"builds":[{"name":"Stored Power + Psybeam — Backline Executioner","moves":["Stored Power","Psybeam"],"recommended":true,"style":"Nembak dari jarak maksimal: Psybeam buat ngerusak, Stored Power buat ngehabisin yang udah tipis.","heldItems":[{"name":"Wise Glasses","why":"Sp. Atk flat, semua damage lo special dari move."},{"name":"Choice Specs","why":"Burst tiap move kena; Espeon spam move terus."},{"name":"Slick Spoon","why":"Penetrasi Sp. Def, biar Psybeam tetap sakit ke frontline."}],"battleItem":{"name":"Eject Button","why":"Espeon nggak punya dash sama sekali; Eject satu-satunya escape dari dive."},"combo":["Boosted attack (slow) ke target","Psybeam (bonus damage ke target yang kena hindrance)","Stored Power pas HP target udah tipis","Psychic Solare kalau musuh ngumpul, lalu ulang Psybeam + Stored Power"],"comboNote":"Stored Power nembak musuh acak; kalau mau yakin kena target tertentu, pastikan cuma dia yang di jangkauan atau dia yang paling dekat."},{"name":"Psyshock + Future Sight — Poke & Control","moves":["Psyshock","Future Sight"],"recommended":false,"style":"Poke dari jauh pakai Future Sight ke Defender, Psyshock buat stun yang nge-dive; lebih aman tapi butuh aim.","heldItems":[{"name":"Wise Glasses","why":"Sp. Atk buat semua move."},{"name":"Choice Specs","why":"Burst tiap move kena, Future Sight jadi makin sakit."},{"name":"Slick Spoon","why":"Penetrasi Sp. Def buat ngehajar tank di objective."}],"battleItem":{"name":"Eject Button","why":"Escape; X Speed alternatif kalau lawan nggak banyak assassin."},"combo":["Future Sight ke target (tandai)","Psyshock ke target yang sama (stun + ngurangin cooldown Future Sight)","Boosted attack sambil nunggu ledakan","Ulang Future Sight begitu balik"],"comboNote":"Loop-nya: tandai, hajar target yang ditandai, Future Sight balik cepat."}],"situations":{"gank":"Kalau lo nge-gank: tunggu partner CC dulu, lalu Psybeam + Stored Power buat eksekusi. Kalau dikeroyok: Magic Bounce bakal nahan CC pertama, manfaatin itu buat Eject ke tim, jangan nunggu CC kedua.","escape":"Nggak ada dash. Modal lo: Magic Bounce (kebal CC pertama + slow pelakunya), Stored Power (movement speed), boosted attack (slow), dan Eject Button. Mundur SEBELUM musuh nempel, bukan setelah.","objective":"Rayquaza/Regieleki: berdiri jauh di belakang Defender. Psybeam ke pit (pecahannya ngenain banyak), Psychic Solare buat ngusir yang mau steal. Jaga boosted gauge biar sinar siap pas fight mulai.","duel":"Jaga jarak dan poke, boosted attack buat slow, Psybeam/Future Sight, lalu Stored Power pas dia tipis. Lawan melee dengan dash: tunggu dia dash dulu (Magic Bounce nahan CC-nya), baru balas; jangan maju duluan.","teamfight":"Posisi paling belakang, dekat Defender. Prioritas: musuh yang HP-nya udah di bawah setengah (Stored Power), lalu backline rapuh via pecahan Psybeam. Jangan dekatin frontline musuh."},"mistakes":["Buang boosted attack (gauge) ke wild Pokémon tepat sebelum fight.","Stored Power dipakai pas musuh HP penuh, jadi finisher-nya nggak ada.","Ngerasa 'kebal CC' karena Magic Bounce lalu masuk ke tengah; passive-nya cuma nahan satu CC per cooldown.","Trade HP sebagai Eevee di Lv1-3."],"counters":{"hardFor":[{"name":"Talonflame","why":"Dive dari atas, burst cepat, dan lo nggak punya dash buat jawab.","how":"Berdiri dekat Defender, simpan Psyshock buat dia pas mendarat, Eject segera."},{"name":"Gengar","why":"Masuk dari belakang, Hex/Sludge Bomb burst sebelum lo nembak.","how":"Jangan farm sendirian setelah Lv5 dia; jaga Eject dan main dekat tim."},{"name":"Zeraora","why":"Dash berulang dan bisa ngilang-nyeruduk, susah di-aim pakai Psyshock.","how":"Tunggu dia buang dash, lalu Psyshock + Stored Power pas dia abis Spark."},{"name":"Blastoise / Mega Mewtwo Y","why":"Blastoise tanky + CC yang nembus setelah Magic Bounce; Mewtwo Y range lebih jauh dan lebih tebal.","how":"Jangan trade langsung; hajar target lain dan biarin Defender lo yang ngadepin mereka."}],"goodAgainst":[{"name":"Ranged rapuh (Duraludon, Greninja, Gardevoir)","why":"Range lo sama/lebih jauh dan Stored Power ngehabisin mereka begitu tipis; Magic Bounce nahan CC pertama mereka."},{"name":"Melee All-Rounder (Charizard, Garchomp)","why":"Mereka harus deket; boosted attack slow + Psybeam dari jauh bikin mereka nggak nyampe, dan Future Sight ngehajar HP tebal mereka."},{"name":"Supporter (Blissey, Clefable)","why":"Rapuh dan nggak bisa kabur dari Psybeam pecahan + Stored Power."}]},"cinderace":{"similarity":4,"note":"Posisi backline-nya sama, tapi feel-nya beda jauh: Espeon hampir nggak ngandelin auto-attack (kecuali boosted sinar yang berbasis gauge, bukan 3 hit), dan nggak punya Feint buat kabur. Bawa kebiasaan jaga jarak Cinderace, tapi ganti 'kite sambil nembak' jadi 'tunggu musuh tipis, lalu eksekusi'. Kalau lo biasanya ngejar kill pakai dash, di sini jangan."},"sources":["https://bulbapedia.bulbagarden.net/wiki/Espeon_(UNITE)","https://serebii.net/pokemonunite/pokemon/espeon.shtml","https://game8.co/games/Pokemon-UNITE/archives/377102","https://www.dittobase.com/unite/pokemon/espeon"],"confidence":"high","notes":"Nama move, level Lv4/Lv6, upgrade Lv10/Lv12, Unite Lv8 cocok antara Bulbapedia, dittobase, dan Game8; Serebii tidak menyebut Growl sebagai base slot 2 tapi Bulbapedia menyebutnya. Patch v1.20.3.11 (Nov 2025) buff HP/Def/Sp.Def Espeon, Stored Power threshold 'HP rendah' naik ke 50%, Future Sight bonus ke target ditandai naik ke 15%. Item build dari Game8 (Wise Glasses/Choice Specs/Slick Spoon) sama persis dengan dittobase (Slick Spoon/Wise Glasses/Drive Lens kecuali Drive Lens vs Choice Specs).","image":"img/espeon.webp","status":"Owned"},{"name":"Venusaur","slug":"venusaur","role":"Penyerang","damage":"Special","range":"Ranged","difficulty":"Pemula","evolutions":"Bulbasaur (Lv1) → Ivysaur (Lv5) → Venusaur (Lv7)","tagline":"Attacker lambat tapi tebal yang ngandelin move area dan sustain, bukan basic attack; raja zona objective.","passive":{"name":"Overgrow","desc":"Saat HP lo rendah, semua damage yang lo kasih naik. Bikin Venusaur berbahaya di akhir fight, tapi jangan sengaja nurunin HP."},"basicAttack":"Basic attack ranged biasa; tiap serangan ketiga jadi boosted yang narik musuh ke arah lo pakai sulur dan damage lebih besar. Boosted berguna buat nahan musuh yang mau kabur, tapi damage utama lo tetap dari move.","lanes":["Top","Bottom","Jungle"],"laneNote":"Top atau Bottom: Venusaur kuat di lane karena Razor Leaf/Seed Bomb clear cepat dan dia cukup tebal buat trade; jungle kurang cocok karena lambat buat gank.","earlyGame":"Bulbasaur sebenarnya nggak selemah starter lain: Seed Bomb + Razor Leaf clear wild cepat dan poke lawan. Trade pakai move dari jarak jauh, mundur kalau cooldown kosong. Jaga goal, jangan kejar sampai jauh karena lo lambat.","powerSpike":"Lv5 (Sludge Bomb/Giga Drain) spike pertama; Lv7 (Venusaur + Solar Beam/Petal Dance) spike utama; Lv9 Unite buat objective.","slot1":{"base":{"name":"Seed Bomb","level":1,"desc":"Lempar biji ke area, damage kecil; alat farm dan poke early."},"choices":[{"name":"Sludge Bomb","level":5,"upgradeLevel":11,"desc":"Lempar lumpur beracun ke area: damage over time, slow, dan Sp. Def musuh turun.","when":"Tekan ke kerumunan sebelum Solar Beam (Sp. Def turun = Beam lebih sakit) atau ke jalur musuh yang mau kabur buat slow.","avoid":"Jangan lempar ke satu musuh yang lagi gerak cepat; area-nya kecil dan delay-nya ada, lebih bagus ke musuh yang terkunci.","upgradeNote":"Lv11: area efeknya diperbesar."},{"name":"Giga Drain","level":5,"upgradeLevel":11,"desc":"Sedot HP musuh di sekitar lo: lo heal dan damage yang lo terima berkurang sebentar.","when":"Tekan saat musuh nempel atau saat lo mau masuk/tahan posisi di fight; ini tombol sustain, pakai pas HP mulai turun, bukan pas sekarat.","avoid":"Jangan tekan saat nggak ada musuh di sekitar; heal-nya bergantung kena target.","upgradeNote":"Lv11: jumlah HP yang dipulihkan naik."}]},"slot2":{"base":{"name":"Razor Leaf","level":1,"desc":"Tembak daun beruntun ke depan, damage area; clear dan poke early."},"choices":[{"name":"Solar Beam","level":7,"upgradeLevel":13,"desc":"Tembak sinar jarak jauh di garis lurus, damage area besar; ada delay singkat sebelum keluar.","when":"Tekan ke musuh yang numpuk di garis lurus (pit objective, lane) atau buat secure boss dari jauh; idealnya setelah Sludge Bomb kena.","avoid":"Jangan tembak ke satu musuh yang bebas gerak dari jarak dekat; delay-nya bikin gampang di-dodge, dan cooldown-nya sekarang lebih panjang.","upgradeNote":"Lv13: cooldown Solar Beam berkurang."},{"name":"Petal Dance","level":7,"upgradeLevel":13,"desc":"Kelopak berputar di sekitar lo: movement speed naik dan musuh di dekat lo kena damage terus-menerus; cooldown move lain dipotong.","when":"Tekan buat masuk ke musuh (speed), nempel ke carry lawan, atau buat kabur; combo bagus sama Giga Drain.","avoid":"Jangan tekan dari jarak jauh terus diam; damage-nya cuma kena musuh yang dekat lo.","upgradeNote":"Lv13: area kelopaknya diperbesar."}]},"unite":{"name":"Verdant Anger","level":9,"desc":"Lempar biji raksasa ke area target yang pecah jadi damage area besar dan nge-slow musuh; lo juga dapat shield dan movement speed.","when":"Pakai ke kerumunan di objective atau buat ngunci musuh yang mau kabur dari pit; slow-nya bikin Solar Beam gampang kena.","avoid":"Jangan buang ke satu target atau saat musuh udah menyebar; dan ingat area-nya ada delay."},"builds":[{"name":"Sludge Bomb + Solar Beam — Artillery","moves":["Sludge Bomb","Solar Beam"],"recommended":true,"style":"Poke dan nuke area dari jarak jauh; paling cocok di lane dan di objective.","heldItems":[{"name":"Energy Amplifier","why":"Unite lebih sering dan damage naik setelah Unite; Verdant Anger + Beam adalah combo objective lo."},{"name":"Slick Spoon","why":"Nembus Sp. Def, numpuk sama efek Sludge Bomb."},{"name":"Curse Incense","why":"Damage area berkala ke musuh di sekitar; nambah poke pasif (rekomendasi dittobase). Wise Glasses juga aman."}],"battleItem":{"name":"Eject Button","why":"Venusaur lambat dan nggak punya dash; Eject satu-satunya escape."},"combo":["Sludge Bomb ke kerumunan (slow + Sp. Def turun).","Solar Beam ke garis yang sama selagi mereka slow.","Boosted attack buat narik yang mau kabur.","Verdant Anger saat musuh numpuk di pit, lanjut Beam begitu cooldown balik."],"comboNote":"Urutan Sludge → Beam penting; Beam ke musuh yang nggak slow sering miss."},{"name":"Giga Drain + Petal Dance — Bruiser Sustain","moves":["Giga Drain","Petal Dance"],"recommended":false,"style":"Masuk ke tengah musuh, heal terus, damage area di sekitar lo; main kayak all-rounder tebal.","heldItems":[{"name":"Slick Spoon","why":"Tetap butuh penetrasi buat damage ke tank."},{"name":"Drive Lens","why":"Sp. Atk dan damage tambahan buat move yang sering kena (saran dittobase)."},{"name":"Focus Band","why":"Sustain tambahan saat HP rendah, sinergi sama Overgrow dan Giga Drain."}],"battleItem":{"name":"Full Heal","why":"Lo bakal berdiri di tengah CC musuh; Full Heal bikin lo nggak dikunci (alternatif dittobase)."},"combo":["Petal Dance buat speed, jalan ke tengah musuh.","Giga Drain saat 2+ musuh di sekitar (heal + damage reduction).","Auto + boosted buat narik carry musuh ke dalam kelopak.","Verdant Anger ke kerumunan, Giga Drain lagi saat cooldown balik (Petal Dance potong cooldown)."],"comboNote":"Build ini kuat lawan melee, lemah lawan tim yang full ranged."}],"situations":{"gank":"Saat nge-gank: Sludge Bomb dari jauh ke target yang kena CC, lalu Solar Beam; boosted buat narik kalau dia mau kabur. Saat dikeroyok: Giga Drain/Petal Dance kalau punya, kalau nggak Eject ke arah tim dan Sludge Bomb di belakang lo buat slow pengejar.","escape":"Eject Button adalah escape utama; Petal Dance kasih speed; Sludge Bomb/Unite buat slow pengejar. Venusaur lambat, jadi mulai mundur lebih awal dari Pokémon lain.","objective":"Ini panggung lo: Verdant Anger ke pit saat fight pecah, Sludge Bomb di pit, Solar Beam buat secure boss dari jarak jauh (damage-nya besar dan jangkauannya panjang). Berdiri di belakang tank tapi tetap dalam jangkauan Beam.","duel":"1v1 lawan ranged: Sludge Bomb → Beam dari jauh, mundur saat cooldown. Lawan melee: build Giga Drain menang trade panjang; build Beam harus jaga jarak dan ngandelin boosted buat narik lalu Beam.","teamfight":"Midline di belakang tank. Prioritas: kerumunan (bukan satu target), lalu carry musuh yang kena slow. Jangan maju ngejar; biarkan mereka datang ke area Sludge/Beam lo."},"mistakes":["Solar Beam ke target bebas dari jarak dekat; delay-nya bikin miss.","Jalan terlalu jauh dari tim; Venusaur paling lambat di antara attacker.","Giga Drain saat nggak ada musuh di sekitar (nggak heal).","Nganggap Overgrow sebagai alasan buat fight di HP rendah.","Nahan Unite nunggu sempurna; Verdant Anger balik cukup cepat dengan Energy Amplifier."],"counters":{"hardFor":[{"name":"Cinderace","why":"Kite di luar jangkauan Sludge Bomb dan Feint nolak Beam.","how":"Tahan posisi dekat goal, Sludge Bomb ke jalurnya, Beam cuma saat dia slow (inferensi mekanik)."},{"name":"Greninja","why":"Burst dari stealth dan lo nggak punya escape.","how":"Jalan dekat tank, simpan Eject, Giga Drain saat dia nempel."},{"name":"Toxtricity","why":"Slow Electric dan DPS auto panjang ngabisin lo yang lambat (gamingonphone nyebut Venusaur sebagai matchup bagus buat Toxtricity).","how":"Sludge Bomb buat nurunin Sp. Def-nya, Beam saat dia slow, jangan trade auto."},{"name":"Zeraora","why":"Dash berulang dan burst ke lo yang nggak bisa kabur.","how":"Build Giga Drain + Petal Dance lebih tahan; Eject saat dia Spark masuk."}],"goodAgainst":[{"name":"Snorlax","why":"Lambat dan besar: Sludge Bomb + Beam hampir selalu kena, Sp. Def-nya turun."},{"name":"Decidueye","why":"Immobile; Sludge Bomb slow lalu Beam dari jauh, jangkauan Beam cukup buat nyampe (inferensi mekanik)."},{"name":"Machamp","why":"Melee yang harus nempel; build Giga Drain menang trade dan boosted narik dia ke kelopak."}]},"cinderace":{"similarity":4,"note":"Ini beda jauh dari Cinderace: Venusaur lambat, nggak punya dash/invincible, dan basic attack cuma alat bantu (boosted buat narik), bukan sumber damage. Yang kepake dari kebiasaan Cinderace cuma disiplin posisi dan sabar nunggu musuh masuk jangkauan. Yang harus diubah: berhenti kiting mundur sambil auto; lo harus 'nahan zona' pakai Sludge/Beam dan mundur lebih awal karena lo pelan."},"sources":["https://serebii.net/pokemonunite/pokemon/venusaur.shtml","https://bulbapedia.bulbagarden.net/wiki/Venusaur_(UNITE)","https://www.dittobase.com/unite/pokemon/venusaur","https://www.serebii.net/pokemonunite/patch.shtml","https://gamingonphone.com/guides/pokemon-unite-toxtricity-guide-best-builds-held-items-moveset-and-gameplay-tips"],"confidence":"medium","notes":"Perbedaan antar sumber: ringkasan Serebii menyebut Venusaur 'Physical Attacker', tapi Bulbapedia dan dittobase menyebut Sp. Atk (benar: special, item Sp. Atk). Level cocok: Seed Bomb/Razor Leaf Lv1, Sludge Bomb/Giga Drain Lv5 (upgrade Lv11), Solar Beam/Petal Dance Lv7 (upgrade Lv13), Unite Lv9. Patch: 1.18.2.6 (Apr 2025) heal Giga Drain naik dan speed Petal Dance naik; 1.19.2.6 (Jul 2025) stat naik; 1.20.3.10 (Okt 2025) Solar Beam cooldown 7→8s dan damage turun (nerf). Tidak ada perubahan di patch Mar/Agu/Sep 2026. Game8 Venusaur guide tidak bisa diakses; build dari dittobase, counter list sebagian besar inferensi mekanik (kecuali Toxtricity dari gamingonphone).","image":"img/venusaur.webp","status":"Owned"},{"name":"Zeraora","slug":"zeraora","role":"Pelari Cepat","damage":"Physical","range":"Melee","difficulty":"Menengah","evolutions":"Zeraora (Lv1, tidak berevolusi)","tagline":"Jungler melee super lincah yang masuk-keluar fight pakai dash, nyedot HP lewat boosted attack, dan makin sakit kalau dipukul.","passive":{"name":"Volt Absorb","desc":"Tiap lo kena damage, sebagian damage itu diubah jadi Attack tambahan sementara (ada batas maksimalnya). Reset kalau lo nggak kena damage beberapa detik. Artinya: Zeraora justru paling sakit saat lagi ditembakin."},"basicAttack":"Basic attack melee; setiap serangan ketiga jadi boosted attack yang lebih sakit, bikin musuh paralyze sebentar, dan nge-heal sebagian HP lo yang hilang. Boosted ini sumber sustain utama lo, jangan diremehin.","lanes":["Jungle"],"laneNote":"Jungle hampir wajib: Zeraora butuh level cepat buat dapet Spark/Volt Switch (Lv5) dan Discharge/Wild Charge (Lv7), dan dia nggak punya ranged poke buat lane. Di lane dia cuma speedster tanpa tanggung jawab yang nyusahin tim.","earlyGame":"Clear jungle secepat mungkin: Agility buat attack speed, Slash buat damage. Jangan gank sebelum Lv5 kecuali lane lo udah 100% aman. Setelah Lv5 (Spark/Volt Switch), cari gank ke lane yang musuhnya over-extend, terus balik farm. Target: Lv7 sebelum objective pertama.","powerSpike":"Lv5 (Spark / Volt Switch) lo mulai bisa gank; Lv7 (Discharge / Wild Charge) lo jadi ancaman nyata; Lv9 Plasma Gale bikin lo bisa buka atau balikin teamfight.","slot1":{"base":{"name":"Agility","level":1,"desc":"Dash pendek dan attack speed naik sebentar; alat clear jungle dan reposisi awal."},"choices":[{"name":"Volt Switch","level":5,"upgradeLevel":11,"desc":"Dash cepat yang kasih damage dan naikin attack speed; dalam beberapa detik lo bisa tekan lagi buat dash BALIK ke posisi awal.","when":"Tekan buat masuk ke carry musuh, auto beberapa kali, terus tekan lagi buat kabur sebelum mereka bales. Juga enak buat dodge skillshot: dash masuk, dash balik.","avoid":"Jangan lupa dash baliknya ada batas waktu; kalau lo keasikan auto dan window-nya lewat, lo kejebak di tengah musuh tanpa jalan keluar.","upgradeNote":"Lv11: damage dan bonus attack speed-nya naik, jadi burst 'masuk-auto-keluar' lo lebih terasa."},{"name":"Spark","level":5,"upgradeLevel":11,"desc":"Lompat ke musuh sambil nyetrum; bisa dipakai sampai 3 kali berturut-turut sebelum masuk cooldown.","when":"Pakai buat ngejar target yang lari, lompat-lompat antar musuh di teamfight, atau lewatin dinding. Hemat 1 charge buat kabur kalau fight-nya nggak jalan.","avoid":"Jangan buang ketiga charge sekaligus ke tank cuma karena dia paling deket; lo bakal kehabisan mobility pas carry musuh muncul.","upgradeNote":"Lv11: tiap Spark yang kena juga nge-heal HP lo, jadi lo lebih betah di dalam fight."}]},"slot2":{"base":{"name":"Slash","level":1,"desc":"Terjang dan cakar beberapa kali; serangan terakhirnya ngelempar musuh. Damage tool utama di early."},"choices":[{"name":"Discharge","level":7,"upgradeLevel":13,"desc":"Ledakan listrik di sekitar lo yang kasih damage ke semua musuh di dekat dan ngasih lo shield.","when":"Tekan saat lo udah di tengah 2-3 musuh (habis Spark / Volt Switch masuk) atau pas lo butuh shield karena mau kena burst. Enak banget juga buat secure Rayquaza karena AoE instan.","avoid":"Jangan tekan dari jauh buat 'poke'; ini move area di sekitar badan lo, kalau nggak ada musuh di dalam lingkaran, lo cuma dapet shield kecil dan buang cooldown.","upgradeNote":"Lv13: musuh yang lagi paralyze (dari boosted attack lo) ditarik ke arah lo dan nggak bisa bergerak sebentar, jadi urutannya: boosted attack dulu, baru Discharge."},{"name":"Wild Charge","level":7,"upgradeLevel":13,"desc":"Terjang ke arah yang dipilih; kalau kena musuh, lo lanjut combo serangan beruntun (lo kena sedikit recoil). Kalau sebelumnya Spark / Volt Switch kena, combo-nya makin panjang.","when":"Tekan ke SATU target yang mau lo matiin, setelah Spark / Volt Switch kena biar combo-nya maksimal. Ini move eksekusi carry musuh.","avoid":"Jangan Wild Charge ke tank full HP di depan tim musuh; recoil-nya nyakitin lo sendiri dan lo bakal kehabisan HP di posisi terjelek.","upgradeNote":"Lv13: damage combo-nya naik dan lo lebih sulit dihentikan selama animasi."}]},"unite":{"name":"Plasma Gale","level":9,"desc":"Lo nembakin petir ke area: damage besar, semua musuh di dalamnya dilempar ke udara, lalu muncul zona plasma yang bikin basic attack range dan damage lo naik selama lo di dalamnya.","when":"Pakai saat 2+ musuh ngumpul (di objective atau pas mereka nyerbu goal), atau buat ngelempar musuh yang lagi channel ult/secure. Setelah itu TETAP di dalam zona dan spam auto, karena di situ lo jadi ranged sebentar.","avoid":"Jangan pakai cuma buat matiin satu target yang udah sekarat, dan jangan tekan lalu langsung dash keluar dari zonanya; bonus-nya cuma berlaku di dalam area."},"builds":[{"name":"Spark + Discharge — Teamfight Diver","moves":["Spark","Discharge"],"recommended":true,"style":"Lompat masuk ke kerumunan, ledakin Discharge buat damage + shield, terus lompat lagi ke target berikutnya; paling aman buat yang baru belajar Zeraora.","heldItems":[{"name":"Weakness Policy","why":"Lo bakal kena damage terus (passive Volt Absorb juga mau itu), jadi Attack tambahan + HP-nya pas banget."},{"name":"Razor Claw","why":"Tiap habis pakai move, auto berikutnya tambah sakit dan nge-slow; Zeraora pakai move hampir tiap detik."},{"name":"Buddy Barrier","why":"Shield tambahan saat Plasma Gale biar lo bisa tetap berdiri di zona dan spam auto."}],"battleItem":{"name":"X Attack","why":"Attack + attack speed sementara bikin boosted attack lo keluar lebih sering, berarti lebih banyak heal dan paralyze."},"combo":["Spark ke musuh terdekat (atau lewatin dinding) buat masuk.","Auto sampai boosted keluar (paralyze), lalu Discharge: musuh yang paralyze ketarik (Lv13) dan lo dapet shield.","Spark lagi ke carry yang coba kabur, auto sampai boosted, Spark ketiga buat finishing atau keluar."],"comboNote":"Selalu sisain satu charge Spark kalau lo belum yakin fight-nya menang."},{"name":"Volt Switch + Wild Charge — Assassin","moves":["Volt Switch","Wild Charge"],"recommended":false,"style":"Hit-and-run murni: masuk, hapus satu carry, dash balik keluar. Damage tertinggi tapi paling gampang mati kalau salah target.","heldItems":[{"name":"Muscle Band","why":"Combo Wild Charge dan auto lo semua physical; damage persen HP bagus lawan tank."},{"name":"Weakness Policy","why":"Attack naik tiap lo dipukul; cocok sama gaya nyemplung ke fight."},{"name":"Focus Band","why":"Heal saat HP tipis biar lo sempat dash balik keluar pakai Volt Switch."}],"battleItem":{"name":"Eject Button","why":"Jalan keluar cadangan kalau window dash balik Volt Switch keburu lewat."},"combo":["Volt Switch masuk ke carry musuh (attack speed naik).","Langsung Wild Charge ke target yang sama: combo-nya jadi lebih panjang karena Volt Switch udah kena.","Boosted attack buat paralyze + heal, lalu tekan Volt Switch lagi buat dash balik ke posisi awal."],"comboNote":"Kalau target belum mati setelah combo, jangan maksa: dash balik dan tunggu cooldown."}],"situations":{"gank":"Saat lo nge-gank: masuk pakai Spark / Volt Switch dari arah belakang musuh, auto sampai boosted (paralyze), baru Discharge / Wild Charge. Saat lo yang dikeroyok: tekan Discharge buat shield, boosted attack buat heal, lalu Spark / Volt Switch keluar; jangan coba lawan 1v3.","escape":"Spark lewatin dinding (sisain 1 charge!) atau Volt Switch balik. Discharge kasih shield kecil buat nahan satu hit. Kalau semua habis, Eject Button. Ingat HP lo tipis, jangan nunggu sampai 10% baru kabur.","objective":"Di Rayquaza / Regieleki: jangan jadi orang pertama yang masuk. Tunggu tank tim lo ngikat musuh, baru Spark masuk ke carry mereka atau tekan Plasma Gale pas mereka ngumpul di pit. Discharge instan AoE bagus buat steal last-hit kalau timing-nya pas.","duel":"1v1 lo kuat lawan squishy: Spark/Volt Switch masuk, boosted buat paralyze, Wild Charge/Discharge, boosted lagi buat heal. Lawan tank atau all-rounder sustain (Blastoise, Tsareena, Scizor) jangan diladenin lama, poke-dan-pergi aja.","teamfight":"Posisi di sisi atau belakang musuh, bukan di depan tank lo. Prioritas: Attacker/Supporter musuh yang HP-nya tipis. Masuk setelah CC musuh (Snorlax, Blastoise) udah keluar. Plasma Gale pas 3 musuh ngumpul, terus berdiri di zonanya dan auto."},"mistakes":["Gank sebelum Lv5 atau ninggalin jungle buat fight panjang; Zeraora tanpa level cuma speedster kurus.","Buang semua charge Spark buat masuk, nggak nyisain buat keluar.","Lupa boosted attack: boosted-nya nge-heal dan paralyze, kalau lo cuma spam move tanpa auto, sustain lo hilang.","Pakai Discharge dari jauh (nggak ada musuh di area) atau Wild Charge ke tank full HP.","Keluar dari zona Plasma Gale langsung setelah tekan ult, padahal bonus range + damage-nya cuma di dalam."],"counters":{"hardFor":[{"name":"Snorlax","why":"Block, Heavy Slam, dan Yawn ngunci lo di tempat; HP lo tipis dan dia nggak bisa lo burst.","how":"Tunggu dia buang Block/Yawn dulu, baru masuk ke carry di belakangnya; jangan pernah target Snorlax-nya."},{"name":"Blastoise","why":"Rapid Spin + Hydro Pump / Surf nge-CC lo berkali-kali dan dia tanky banget.","how":"Masuk dari sisi, jauhin area Surf-nya; pakai Volt Switch dash balik atau Spark buat dodge ult-nya."},{"name":"Tsareena","why":"Dia sustain, tahan CC (Queenly Majesty), dan Stomp bisa ngunci lo tengah combo.","how":"Jangan duel lama; poke pakai Spark lalu pergi, atau tunggu dia pakai Stomp dulu baru masuk."},{"name":"Greninja","why":"Smokescreen + Double Team bikin dia nggak bisa lo kejar, dan burst-nya ngabisin HP lo cepat.","how":"Masuk pas dia udah buang Smokescreen; boosted attack paralyze bikin dia nggak bisa dash."}],"goodAgainst":[{"name":"Pikachu","why":"HP tipis, mobility rendah; satu combo Spark + Wild Charge hampir pasti bunuh."},{"name":"Decidueye","why":"Attacker ranged tanpa escape; Spark lewatin dinding dan dia nggak bisa kabur dari paralyze."},{"name":"Mr. Mime","why":"Supporter lambat yang gampang diisolasi di belakang tim; Discharge pull bikin dia keluar posisi."}]},"cinderace":{"similarity":4,"note":"Bedanya besar: Cinderace nunggu di belakang dan nge-kite, Zeraora harus nyemplung dulu. Yang bisa lo bawa: kebiasaan nge-count boosted attack (di Zeraora boosted = heal + paralyze, sama pentingnya kayak di Cinderace) dan insting target squishy. Yang harus diubah: lo masuk fight bukan pas enak, tapi pas CC musuh udah habis, dan lo selalu harus nyisain satu dash buat keluar."},"sources":["https://www.serebii.net/pokemonunite/pokemon/zeraora.shtml","https://bulbapedia.bulbagarden.net/wiki/Zeraora_(UNITE)","https://www.dittobase.com/unite/pokemon/zeraora","https://gamewith.net/pokemon-unite/article/show/29548","https://www.pokemonunite.jp/en/topics/battle/20260415-1/","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"high","notes":"Patch 14 Apr 2026: Volt Switch cooldown turun + damage naik, Wild Charge damage naik, energi Plasma Gale diturunin (ult lebih sering keluar). Patch Apr 2025 sempat nerf Discharge. Difficulty: Serebii bilang Expert, Bulbapedia/dittobase bilang Intermediate; gw ikut yang lebih baru (Menengah). Gamewith (lama) nulis Lv6/8/10 untuk move, tapi Serebii, Bulbapedia, dan dittobase konsisten Lv5/7/9. Counter adalah inferensi mekanik + arahan umum gamewith ('Pokémon yang bisa ngunci Zeraora'), bukan tabel counter resmi.","image":"img/zeraora.webp","status":"Owned"},{"name":"Blastoise","slug":"blastoise","role":"Defender","damage":"Special","range":"Ranged","difficulty":"Menengah","evolutions":"Squirtle (Lv1) → Wartortle (Lv5) → Blastoise (Lv7)","tagline":"Defender ranged yang kerjanya ngegusur: dorong, lempar, dan pisahin musuh dari tim-nya pakai air, sambil tetap tebal.","passive":{"name":"Torrent","desc":"Saat HP lo setengah atau kurang, Attack dan Sp. Atk naik. Blastoise justru paling sakit saat lagi 'kelihatan sekarat'."},"basicAttack":"Basic attack ranged; tiap serangan ketiga jadi boosted yang damage bertahap dan nge-slow musuh. Habis boosted kena, cooldown move lo berkurang; jadi auto 3x sebelum fight itu penting. Dengan Rapid Spin, auto jadi damage melingkar di sekitar lo.","lanes":["Top","Bottom"],"laneNote":"Top atau Bottom sebagai tank lane ranged; Blastoise lemah banget sebelum Lv7, jadi butuh lane partner yang bisa jaga dia sampai evolusi.","earlyGame":"Squirtle adalah salah satu early game paling lemah: Water Gun buat dorong musuh yang terlalu maju dan Skull Bash buat stun sesekali, sisanya tahan di goal dan biarin partner farm. Jangan trade panjang sampai Lv5, dan baru agresif setelah Lv7.","powerSpike":"Lv5 (Hydro Pump/Water Spout) spike pertama, Lv7 jadi Blastoise dan dapat Surf/Rapid Spin, itu titik lo mulai ngatur fight; Lv9 Hydro Typhoon.","slot1":{"base":{"name":"Water Gun","level":1,"desc":"Semprot air ke depan: damage, dorong musuh, dan slow."},"choices":[{"name":"Hydro Pump","level":5,"upgradeLevel":11,"desc":"Semprotan air kencang di garis lurus: damage besar dan musuh kedorong jauh; selama Rapid Spin damage-nya naik.","when":"Tekan buat dorong carry musuh menjauh dari tim-nya (ke arah tim lo), atau buat gusur stealer keluar pit.","avoid":"Jangan dorong musuh ke arah yang nyelametin dia (menjauh dari tim lo) dan jangan buang ke tank.","upgradeNote":"Lv11: cooldown berkurang."},{"name":"Water Spout","level":5,"upgradeLevel":11,"desc":"Semburan air area yang nge-slow musuh; selama Rapid Spin nyembur beberapa kali.","when":"Tekan ke kerumunan yang numpuk (pit, lane sempit) dan pas Rapid Spin aktif biar hit-nya berlipat.","avoid":"Jangan pakai sebagai alat displacement; ini move damage/slow, bukan dorong.","upgradeNote":"Lv11: cooldown berkurang."}]},"slot2":{"base":{"name":"Skull Bash","level":1,"desc":"Dash nabrak musuh, yang kena stun sebentar."},"choices":[{"name":"Surf","level":7,"upgradeLevel":13,"desc":"Naik ombak ke depan, musuh yang kena kedorong dan nggak bisa bertindak; lo kebal CC selama di ombak dan dapat shield kalau kena.","when":"Tekan buat engage: masuk ke carry musuh, dorong dia ke tim lo, lanjut Hydro Pump; atau buat kabur karena kebal CC.","avoid":"Jangan Surf jauh ke belakang tim musuh tanpa Hydro Typhoon/Eject siap; ini satu-satunya dash lo.","upgradeNote":"Lv13: cooldown berkurang."},{"name":"Rapid Spin","level":7,"upgradeLevel":13,"desc":"Lo muter: damage terus-menerus ke musuh di sekitar, damage yang lo terima berkurang, dan basic attack serta move air berubah jadi lebih kuat.","when":"Tekan saat lo udah di tengah musuh atau sebelum Water Spout/Hydro Pump biar damage-nya berlipat.","avoid":"Jangan tekan dari jauh lalu jalan pelan ke musuh; efeknya habis sebelum lo nyampe.","upgradeNote":"Lv13: durasi Rapid Spin lebih lama."}]},"unite":{"name":"Hydro Typhoon","level":9,"desc":"Lo nyemprot air sambil muter: semua musuh di area besar dilempar, dan lo dapat shield.","when":"Pakai setelah Surf masuk ke kerumunan di pit, atau buat lempar musuh keluar dari area objective tepat sebelum mereka secure.","avoid":"Jangan buang ke satu musuh atau pas tim lo belum dekat; lemparannya pendek, musuh yang nggak di-follow-up tinggal jalan balik."},"builds":[{"name":"Hydro Pump + Surf — Displacer Tank","moves":["Hydro Pump","Surf"],"recommended":true,"style":"Tank yang ngatur posisi musuh: Surf masuk, dorong carry ke tim lo, Hydro Pump pisahin mereka.","heldItems":[{"name":"Focus Band","why":"Sustain saat HP rendah; sinergi sama Torrent yang aktif di HP setengah."},{"name":"Energy Amplifier","why":"Hydro Typhoon lebih sering dan damage naik setelah Unite (dittobase/game8)."},{"name":"Resonant Guard","why":"Shield buat lo dan sekutu pas engage (dittobase); Slick Spoon kalau mau lebih sakit (game8)."}],"battleItem":{"name":"Eject Button","why":"Reposisi sebelum Surf atau kabur setelah engage; semua sumber pakai ini."},"combo":["Auto 3x dulu (boosted ngurangin cooldown).","Surf ke carry musuh, dorong dia ke arah tim lo.","Hydro Pump lagi buat dorong lebih jauh/pisahin dari tank-nya.","Hydro Typhoon kalau 2+ musuh ikut, lalu Hydro Pump lagi begitu cooldown balik."],"comboNote":"Game8: 'Surf → Hydro Typhoon → Hydro Pump'. Arah dorongan adalah segalanya; dorong KE tim lo."},{"name":"Water Spout + Rapid Spin — Spinner Damage","moves":["Water Spout","Rapid Spin"],"recommended":false,"style":"Blastoise ofensif: muter di tengah musuh, semua auto dan Water Spout jadi area damage.","heldItems":[{"name":"Slick Spoon","why":"Nembus Sp. Def biar damage spin kena tank juga."},{"name":"Muscle Band","why":"Auto lo jadi area selama Rapid Spin; Muscle Band nambah tiap hit (dittobase)."},{"name":"Focus Band","why":"Lo berdiri di tengah musuh, butuh jaring pengaman."}],"battleItem":{"name":"X Speed","why":"Buat nyampe ke musuh sebelum Rapid Spin habis; Eject Button alternatif."},"combo":["Water Spout ke kerumunan (slow).","Rapid Spin, lalu jalan ke tengah mereka.","Selang-seling auto dan Water Spout selama muter.","Hydro Typhoon kalau HP mulai turun (shield + lempar)."],"comboNote":"Game8 nyebut 'Rapid Spin Spout'. Build ini kurang CC, jadi butuh tank lain di tim."}],"situations":{"gank":"Saat nge-gank: Surf dari samping/belakang target dan dorong dia ke tim lo, lanjut Hydro Pump. Saat dikeroyok: Surf (kebal CC) ke arah tim, Hydro Pump ke pengejar paling dekat, Hydro Typhoon buat lempar semuanya kalau terkepung.","escape":"Surf arah tim (kebal CC + shield kalau kena), Hydro Pump dorong pengejar ke belakang, Eject Button; auto boosted buat slow. Ingat Torrent: lo makin sakit di HP rendah, jadi kadang balik hajar lebih aman daripada lari.","objective":"Berdiri di bibir pit atau di dalam pit. Simpan Hydro Typhoon buat lempar musuh keluar pit saat objective mau mati, dan Hydro Pump buat dorong jungler musuh yang mau nyuri. Auto 3x sebelum fight mulai biar cooldown pendek.","duel":"Lawan melee: Skull Bash/Surf stun, Hydro Pump dorong, auto; lo menang trade karena tebal dan Torrent. Lawan ranged kiting: jangan dikejar, lo pelan; Surf cuma kalau yakin kena, kalau nggak mundur ke goal.","teamfight":"Frontline di depan carry. Prioritas: pisahin satu carry musuh dari tank-nya (Surf dorong ke tim lo), lalu Hydro Typhoon ke kerumunan. Kalau tim lo di belakang, pakai Hydro Pump buat dorong musuh menjauh dari carry lo (peel)."},"mistakes":["Dorong musuh ke arah yang salah (menjauh dari tim lo).","Fight di lane sebelum Lv7; Squirtle/Wartortle gampang mati.","Hydro Typhoon ke satu target atau pas tim nggak bisa follow-up.","Lupa auto 3x sebelum fight (cooldown lebih panjang).","Surf jauh ke belakang tim musuh tanpa jalan balik."],"counters":{"hardFor":[{"name":"Cinderace","why":"Kite dari jauh dengan damage tinggi dan Feint buat ngehindar (game8).","how":"Jangan dikejar; tahan posisi dekat goal, Surf cuma kalau dia maju terlalu dekat, biarin carry lo yang trade."},{"name":"Mega Mewtwo Y","why":"Jaga jarak dan teleport ngehindar dari Surf/Hydro Pump (game8).","how":"Fokus peel buat carry lo pakai Hydro Pump, jangan buang Surf ke dia."},{"name":"Glaceon","why":"Ranged yang nguras tank dari jauh sambil kite (inferensi dari matchup Glaceon vs defender lain di game8).","how":"Surf dorong dia ke tim lo saat dia maju, kalau miss mundur."}],"goodAgainst":[{"name":"Pikachu","why":"Ranged rapuh tanpa escape; Surf nutup jarak, Hydro Pump dorong, habis (game8)."},{"name":"Zeraora","why":"Glass cannon mobile; Skull Bash/Surf stun matiin combo-nya dan lo tebal (game8)."},{"name":"Gardevoir","why":"Rapuh dan pelan; Surf + Hydro Pump dorong dia ke tim lo (game8)."}]},"cinderace":{"similarity":3,"note":"Sama-sama ranged, tapi Blastoise bukan DPS: damage lo cuma bonus, kerjaan utama lo ngatur posisi musuh. Yang kebawa dari Cinderace: kebiasaan auto terus (di Blastoise auto 3x justru ngurangin cooldown) dan kesadaran siapa carry musuh. Yang harus diubah: lo masuk duluan, bukan mundur; dan tiap tombol lo punya arah dorongan yang harus mengarah KE tim lo."},"sources":["https://serebii.net/pokemonunite/pokemon/blastoise.shtml","https://bulbapedia.bulbagarden.net/wiki/Blastoise_(UNITE)","https://www.dittobase.com/unite/pokemon/blastoise","https://game8.co/games/Pokemon-UNITE/archives/336791","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"high","notes":"Beda antar sumber: Serebii nyebut 'Physical Attacker' dan Intermediate; Bulbapedia/dittobase nyebut Special dan Novice. Special pasti benar (semua build pakai Slick Spoon/Choice Specs). Difficulty gw pakai Menengah karena early game-nya susah dan displacement butuh arah; tandai sebagai beda sumber. Level cocok: Hydro Pump/Water Spout Lv5 (upgrade Lv11), Surf/Rapid Spin Lv7 (upgrade Lv13), Unite Lv9. Patch: 1.20.1.7 (Sep 2025) Surf dapat shield saat kena, Hydro Pump cooldown turun; 1.21.1.5 (Mei 2026) Hydro Pump dan Surf cooldown naik lagi (nerf). Item build game8 untuk Rapid Spin (Choice Specs/Wise Glasses/Sp. Atk Specs) kelihatan lama; gw pakai versi dittobase (Muscle Band/Slick Spoon/Focus Band). Counter Glaceon adalah inferensi.","image":"img/blastoise.webp","status":"Owned"},{"name":"Buzzwole","slug":"buzzwole","role":"Serba-Bisa","damage":"Physical","range":"Melee","difficulty":"Menengah","evolutions":"Buzzwole (tidak berevolusi, langsung Buzzwole dari Lv1)","tagline":"Bruiser pegulat yang ngumpulin 'muscle gauge' dari pukulan, lalu nge-grab dan ngebanting satu target.","passive":{"name":"Beast Boost","desc":"Tiap KO/assist, speed gerak dan speed basic attack lo naik sebentar. Lo juga punya muscle gauge (maks 6) yang keisi tiap basic attack/move kena; gauge ini bikin move lo lebih sakit tapi kosong lagi kalau lo keluar dari combat."},"basicAttack":"Melee biasa, tiap hit ngisi gauge 1. Tiap serangan ketiga jadi boosted: dua pukulan berturut-turut yang juga heal HP lo. Boosted attack baru di-buff September 2026.","lanes":["Top","Jungle"],"laneNote":"Top/Jungle sama-sama bagus. Jungle bikin lo cepat Lv5 (Superpower/Leech Life) dan gank-nya nakutin. Top kalau tim butuh frontliner.","earlyGame":"Lv1 ambil Mega Punch (area, buat clear wild) dan Fell Stinger (burst single target). Isi gauge dari wild dulu, lalu Fell Stinger ke musuh pas gauge penuh buat trade yang menang. Jangan all-in sebelum Lv5.","powerSpike":"Lv5 dapat Superpower/Leech Life, ini spike besar: lo udah bisa grab dan bunuh carry. Lv7 dapat Lunge/Smack Down, Lv9 Unite Ultra Swole Slam.","slot1":{"base":{"name":"Mega Punch","level":1,"desc":"Maju sedikit lalu gebuk tanah, damage area; tiap musuh yang kena ngisi gauge."},"choices":[{"name":"Lunge","level":7,"upgradeLevel":13,"desc":"Nerjang ke satu arah, damage dan nurunin Attack musuh yang kena. Punya 2 charge, jadi bisa dipakai dua kali.","when":"Tekan buat tutup jarak sebelum grab, atau buat nurunin Attack bruiser/attacker physical musuh pas fight dimulai.","avoid":"Jangan buang dua charge sekaligus buat kabur kalau lo belum perlu, simpan satu buat ngejar/lari.","upgradeNote":"Lv13 Attack lo naik berdasarkan jumlah musuh yang kena."},{"name":"Smack Down","level":7,"upgradeLevel":13,"desc":"Uppercut satu musuh ke udara, lalu tekan lagi buat banting dia ke tanah dan damage area di sekitar.","when":"Tekan ke carry musuh buat CC + burst, atau pas musuh ngumpul biar bantingannya kena rame-rame.","avoid":"Jangan uppercut tank yang gak penting pas carry musuh masih bebas.","upgradeNote":"Lv13 area bantingan lebih lebar dan gauge keisi lebih banyak."}]},"slot2":{"base":{"name":"Fell Stinger","level":1,"desc":"Pakai seluruh gauge buat tusuk satu musuh, damage gede dan bikin dia gak bisa gerak sebentar; kalau KO, HP lo pulih."},"choices":[{"name":"Leech Life","level":5,"upgradeLevel":11,"desc":"Grab satu musuh, tahan dia, nyedot HP-nya berkala sambil heal lo.","when":"Tekan ke carry yang misah atau pas lo butuh heal darurat di tengah fight; target kekunci selama dicekik.","avoid":"Jangan grab target yang masih dikelilingi 4 temannya, lo ikut diem di tempat selama nyedot.","upgradeNote":"Lv11 tiap tick damage-nya makin naik secara progresif."},{"name":"Superpower","level":5,"upgradeLevel":11,"desc":"Lari ke satu arah, grab musuh pertama yang kena, lalu banting dia. Lo dapat shield yang makin gede sesuai gauge.","when":"Tekan buat grab carry musuh dan banting dia ke arah tim lo, atau buat nyomot musuh dari pit objective.","avoid":"Jangan tekan pas gauge kosong, shield-nya kecil dan lo gak dapat reset cooldown.","upgradeNote":"Lv11 kalau gauge penuh, cooldown Superpower langsung reset. Cooldown-nya baru dikurangi di patch September 2026."}]},"unite":{"name":"Ultra Swole Slam","level":9,"desc":"Lo terbang cepat, damage ke semua musuh di area, lalu otomatis nargetin musuh yang HP-nya paling rendah dan nyungsep ke dia dari langit. Damage ikut gauge.","when":"Pakai buat ngabisin carry musuh yang udah tipis setelah grab, atau buat engage pas gauge penuh.","avoid":"Jangan tekan pas gauge kosong atau pas target paling tipis itu tank yang gak penting, Unite ini milih target sendiri."},"builds":[{"name":"Superpower + Smack Down — Grab & Slam","moves":["Superpower","Smack Down"],"recommended":true,"style":"CC berantai: grab dan banting pakai Superpower, uppercut dan banting lagi pakai Smack Down, carry musuh gak bisa ngapa-ngapain.","heldItems":[{"name":"Attack Weight","why":"Scaling Attack dari score, Buzzwole gampang score pas Beast Boost aktif."},{"name":"Weakness Policy","why":"Attack naik pas kena damage, cocok buat bruiser yang masuk duluan."},{"name":"Focus Band","why":"Heal pas kritis supaya bisa nyelesaiin combo."}],"battleItem":{"name":"Eject Button","why":"Reposisi buat nyusul target grab atau kabur setelah combo."},"combo":["Isi gauge dari wild/basic attack sebelum masuk.","Superpower ke carry musuh, banting dia ke arah tim lo.","Smack Down uppercut, tekan lagi buat banting, lalu Ultra Swole Slam kalau dia masih hidup."],"comboNote":"Kalau Lv11 dan gauge penuh, Superpower bisa dipakai lagi langsung."},{"name":"Superpower + Lunge — Mobile Bruiser","moves":["Superpower","Lunge"],"recommended":false,"style":"Lebih mobile dan lebih gampang: Lunge buat nyusul atau kabur, Superpower buat grab satu target.","heldItems":[{"name":"Attack Weight","why":"Scaling dari score."},{"name":"Muscle Band","why":"Basic attack lo banyak (ngisi gauge), Muscle Band nambah damage tiap hit."},{"name":"Weakness Policy","why":"Attack naik pas kena damage."}],"battleItem":{"name":"Eject Button","why":"Nambah mobility buat ngejar atau kabur."},"combo":["Lunge ke target (Attack dia turun), basic attack isi gauge.","Superpower grab dan banting ke tim lo.","Lunge charge kedua buat ngejar atau mundur, Unite kalau target tipis."],"comboNote":""},{"name":"Leech Life + Smack Down — Sustain Duelist","moves":["Leech Life","Smack Down"],"recommended":false,"style":"Buat yang suka 1v1 lama: Leech Life nyedot HP, Smack Down buat burst dan CC.","heldItems":[{"name":"Accel Bracer","why":"Attack dan heal naik tiap KO/assist, cocok buat duelist."},{"name":"Attack Weight","why":"Scaling dari score."},{"name":"Focus Band","why":"Sustain tambahan."}],"battleItem":{"name":"Full Heal","why":"Lepas CC biar Leech Life gak keputus."},"combo":["Smack Down uppercut target, banting.","Leech Life pas dia mendarat, sedot sampai HP lo balik.","Basic attack boosted buat heal tambahan, Unite buat finish."],"comboNote":"Dittobase juga list Leech Life + Lunge sebagai opsi."}],"situations":{"gank":"Nge-gank: masuk dengan gauge terisi, Superpower grab carry dan banting ke arah tim, Smack Down lanjutin. Dikeroyok: Lunge/Eject buat keluar, jangan nyoba grab di tengah 4 musuh.","escape":"Lunge (dua charge) atau Eject Button. Superpower juga dash, bisa dipakai buat lari kalau terpaksa. Boosted attack ke wild buat heal pas kabur.","objective":"Di Rayquaza: lo bisa Superpower nyomot musuh dari pit dan banting ke tim lo, itu nilai terbesar lo. Jaga gauge tetap terisi dengan basic attack ke Rayquaza. Ultra Swole Slam buat ngabisin jungler musuh yang mau steal.","duel":"1v1 lo kuat: isi gauge dari basic attack, Smack Down buat CC, Superpower/Leech Life buat grab. Beast Boost setelah KO bikin lo bisa langsung ngejar target berikutnya.","teamfight":"Masuk dari samping, target carry musuh. Grab dia dan seret ke tim lo, jangan kejar sampai ke tengah mereka. Setelah 1 KO, Beast Boost bikin lo bisa snowball."},"mistakes":["Masuk fight dengan gauge kosong: move lo lemah dan shield Superpower kecil.","Grab tank musuh padahal carry mereka bebas, atau grab target ke arah tim musuh bukan tim lo.","Leech Life di tengah 5 musuh, lo diem dan jadi target.","Nunggu kelamaan di luar combat sampai gauge habis sebelum engage."],"counters":{"hardFor":[{"name":"Lapras","why":"Tank ranged dengan slow terus-terusan; Shell Armor motong burst grab lo dan Bubble Beam ngunci lo.","how":"Jangan buang Superpower ke dia, cari carry-nya di belakang."},{"name":"Blissey","why":"Safeguard bikin carry mereka kebal grab lo, dan heal-nya ngimbangin damage.","how":"Tunggu Safeguard habis, atau grab Blissey-nya dulu kalau dia nempel carry."},{"name":"Mewtwo Y","why":"Burst special dari jauh dan mobile, susah di-grab, dan Weakness Policy lo gak nolong lawan damage special.","how":"Lunge buat tutup jarak pas dia baru pakai move, atau fokus carry lain."}],"goodAgainst":[{"name":"Cinderace","why":"Tipis dan harus kiting; Superpower grab dia dari jarak dash dan dia mati sebelum Feint balik."},{"name":"Delphox","why":"Lambat dan rapuh, grab + Smack Down udah cukup buat bunuh dia."},{"name":"Zacian","why":"Lunge nurunin Attack-nya dan grab lo motong combo-nya, lo lebih tebal buat trade."}]},"cinderace":{"similarity":3,"note":"Kebiasaan 'auto-attack terus' dari Cinderace kepake di sini karena basic attack ngisi gauge. Tapi lo melee tebal, tugas lo nyeret carry musuh ke tim, bukan ngerusak dari jauh. Ubah mindset dari 'jaga jarak' jadi 'cari sudut masuk, grab, banting ke arah tim gw'."},"sources":["https://serebii.net/pokemonunite/pokemon/buzzwole.shtml","https://bulbapedia.bulbagarden.net/wiki/Buzzwole_(UNITE)","https://www.dittobase.com/unite/pokemon/buzzwole","https://www.pokemonunite.jp/en/topics/battle/20260902-1/","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"high","notes":"Data move konsisten antar Serebii/Bulbapedia (Fell Stinger → Leech Life/Superpower Lv5 +Lv11; Mega Punch → Lunge/Smack Down Lv7 +Lv13; Unite Lv9). Patch 1.23.2.9 (3 Sept 2026) buff boosted attack dan turunin cooldown Superpower. Counter adalah inferensi dari mekanik (game8 gak bisa diakses).","image":"img/buzzwole.webp","status":"Owned"},{"name":"Hoopa","slug":"hoopa","role":"Suporter","damage":"Special","range":"Ranged","difficulty":"Ahli","evolutions":"Hoopa (tidak berevolusi; berubah sementara jadi Hoopa Unbound lewat Unite move Lv9)","tagline":"Support utilitas: teleport tim lintas map, curi berry lawan, lalu berubah jadi Hoopa Unbound buat nge-nuke objective fight.","passive":{"name":"Magician","desc":"Secara berkala Hoopa narik salah satu berry di sisi lawan (acak) lewat ring ke depan lo; kalau gak ada berry, Aeos energy yang ditarik. Hasilnya: lo dapet sustain gratis dan lawan kehilangan berry-nya."},"basicAttack":"Ranged. Serangan ke-3 jadi boosted (sinar), damage lebih gede. Saat Unbound, SEMUA basic attack jadi sinar yang bisa kena 2 lawan sekaligus.","lanes":["Bottom","Top"],"laneNote":"Lane mana pun yang ada carry; Hyperspace Hole bikin lo bisa pindah lane kapan aja, jadi Hoopa sebenarnya 'roamer' yang mulai dari lane.","earlyGame":"Nemenin carry, pakai Astonish buat stun lawan yang maju lalu carry lo bunuh. Berry dari Magician bisa lo kasih ke ally dengan berdiri dekat. Lv4 ambil Hyperspace Hole/Trick; mulai mikirin rotasi, bukan cuma lane.","powerSpike":"Lv6 (Phantom Force/Shadow Ball) kasih lo damage/mobility. Lv9 Rings Unbound adalah spike terbesar: Hoopa Unbound punya HP gede dan damage area yang nge-stun.","slot1":{"base":{"name":"Astonish","level":1,"desc":"Damage area kecil, lawan yang kena jadi gak bisa bergerak sebentar."},"choices":[{"name":"Phantom Force","level":6,"upgradeLevel":12,"desc":"Bikin ring di bawah lo dan warp ke lokasi tujuan, damage + dorong lawan di sekitar titik mendarat. Bisa ditekan lagi dalam waktu singkat buat balik ke ring awal.","when":"Buat nyelametin diri (masuk, balik), buat dorong lawan dari ally yang difokus, atau buat mendarat di sebelah carry lo yang lagi dikejar.","avoid":"Jangan warp ke tengah 5 lawan tanpa rencana balik; kalau ring hilang lo kejebak.","upgradeNote":"Lv12: efek ditingkatkan (detail gak dikonfirmasi 2 sumber; kemungkinan damage/cooldown)."},{"name":"Shadow Ball","level":6,"upgradeLevel":12,"desc":"Tembak bola bayangan ke depan: damage, slow, dan Sp. Def lawan turun. Kalau lawan yang sama kena lagi dalam waktu singkat, ada damage tambahan. Kalau lo lagi Trick ke ally, Shadow Ball juga ditembak dari posisi ally.","when":"Poke dari belakang carry, dan selalu dua kali ke target yang sama (ada bonus damage). Pakai pas lawan udah di-slow/stun.","avoid":"Jangan maju ke depan carry buat nembak, Hoopa tipis.","upgradeNote":"Lv12: efek ditingkatkan (detail gak dikonfirmasi 2 sumber)."}]},"slot2":{"base":{"name":"Confusion","level":1,"desc":"Lempar tenaga psikis yang meledak setelah jeda, damage + slow."},"choices":[{"name":"Hyperspace Hole","level":4,"upgradeLevel":10,"desc":"Bikin ring besar di lokasi: Hoopa dan ally yang masuk ring bisa warp balik ke base, dan ally yang di base bisa warp ke ring lo (dapet movement speed sesudahnya). Ini alat rotasi dan 'recall gratis' buat tim.","when":"Taruh di dekat objective (Rayquaza/Regieleki) sebelum fight supaya tim yang baru respawn/habis heal bisa langsung dateng; atau taruh di goal buat nyelametin ally yang mau mati.","avoid":"Jangan taruh ring di tengah lawan atau pas ally gak liat ping lo; ring yang gak dipakai = move terbuang.","upgradeNote":"Lv10: efek ditingkatkan (cooldown/durasi, gak dikonfirmasi detail)."},{"name":"Trick","level":4,"upgradeLevel":10,"desc":"Nyambungin lo dengan satu ally lewat ring: keduanya dapet movement speed dan shield. Selama tersambung, Shadow Ball lo juga keluar dari ally itu.","when":"Tekan ke carry sebelum dia engage atau pas dia mau kabur. Pasangin dengan Shadow Ball buat damage dobel.","avoid":"Jangan Trick ke ally yang lagi mundur jauh dari fight, speed-nya kebuang.","upgradeNote":"Lv10: efek ditingkatkan (shield/speed, gak dikonfirmasi detail)."}]},"unite":{"name":"Rings Unbound","level":9,"desc":"Berubah jadi Hoopa Unbound sebentar: max HP naik, basic attack jadi sinar yang kena 2 lawan, dan move lo berganti jadi Hyperspace Fury (barrage area yang bikin lawan gak bisa bergerak) dan Psybeam (sinar lebar ke depan, lo kebal CC selama nembak). Sambil itu muncul ring yang bisa dipakai tiap ally sekali buat warp ke posisi lo.","when":"Pas objective fight mulai: tim lo bisa warp ke lo, dan Hyperspace Fury di atas Rayquaza/goal bikin lawan gak bisa secure.","avoid":"Jangan Unbound di tempat sepi atau pas tim lo udah mati; Unbound gak bisa score dan Magician mati selama transformasi."},"builds":[{"name":"Trick + Shadow Ball — Battle Support","moves":["Trick","Shadow Ball"],"recommended":true,"style":"Nempel ke carry, kasih speed + shield, dan poke dobel Shadow Ball dari dua posisi.","heldItems":[{"name":"Exp. Share","why":"Carry lo level duluan; lo tetep dapet exp sambil nemenin."},{"name":"Muscle Band","why":"Basic attack Hoopa dihitung physical, dan boosted/Unbound beam-nya sering dipakai."},{"name":"Resonant Guard","why":"Shield buat lo dan ally sekitar, nambah peel; alternatif Focus Band (game8)."}],"battleItem":{"name":"Full Heal","why":"Hoopa tipis dan gampang di-lock sebelum sempet warp."},"combo":["Trick ke carry (speed + shield)","Shadow Ball ke target (keluar dari lo dan dari carry)","Shadow Ball kedua ke target yang sama buat bonus damage","Pas Lv9: Rings Unbound lalu Hyperspace Fury di tengah lawan, Psybeam buat finishing"],"comboNote":"Shadow Ball di-nerf Mei 2025, tapi tetep sumber damage utama Hoopa Confined."},{"name":"Hyperspace Hole + Phantom Force — Rotasi & Utilitas","moves":["Hyperspace Hole","Phantom Force"],"recommended":false,"style":"Support macro: teleport tim ke objective, selamatin ally dengan ring, dan Phantom Force buat dorong lawan.","heldItems":[{"name":"Exp. Share","why":"Standar support."},{"name":"Focus Band","why":"Lo sering jadi target pas ngatur ring."},{"name":"Rapid-Fire Scarf","why":"Basic attack boosted dan beam Unbound keluar lebih cepat; alternatif Muscle Band."}],"battleItem":{"name":"Eject Button","why":"Escape tambahan kalau Phantom Force lagi cooldown."},"combo":["Taruh Hyperspace Hole di dekat objective sebelum spawn","Ping tim buat masuk ring dari base","Phantom Force ke lawan yang mau secure buat dorong","Rings Unbound pas fight pecah, Hyperspace Fury di atas objective"],"comboNote":"game8 nyatet build ini minim damage; kalau tim lo kurang damage, ganti Phantom Force ke Shadow Ball."}],"situations":{"gank":"Lo yang bawa tim ke gank: Hyperspace Hole bikin 2 ally muncul tiba-tiba di lane. Setelah itu Astonish/Shadow Ball buat slow target.","escape":"Phantom Force masuk lalu tekan lagi buat balik ke ring, atau Hyperspace Hole buat warp ke base. Full Heal kalau di-CC.","objective":"Taruh Hyperspace Hole di belakang tim sebelum pit fight. Pas fight pecah, Rings Unbound: ally yang mati bisa warp balik lewat ring, dan Hyperspace Fury di pit bikin lawan gak bisa last hit.","duel":"Jangan. Hoopa Confined kalah dari hampir semua. Kalau punya Unite, Unbound bisa menang lawan 1 orang karena HP gede dan beam dobel.","teamfight":"Berdiri di belakang carry. Prioritas: Trick/shield ke carry yang difokus, Shadow Ball ke target yang udah di-CC, Unite pas tim udah berkumpul (atau buat ngumpulin mereka)."},"mistakes":["Nganggep Hoopa Unbound sebagai carry lalu Unite di tempat yang gak ada fight.","Taruh Hyperspace Hole tapi gak ping/komunikasi, ally gak tau bisa warp.","Phantom Force masuk ke tengah lawan dan lupa tekan lagi buat balik.","Lupa Magician: berry yang ditarik dibiarin, padahal bisa diambil ally yang sekarat."],"counters":{"hardFor":[{"name":"Dodrio","why":"Terlalu cepet buat lo kejar/kabur, dan burst-nya bunuh Hoopa Confined sebelum ring keluar.","how":"Astonish pas dia mendarat, tetep di belakang carry, Full Heal siap."},{"name":"Charizard","why":"Fire Spin ngunci lo dan dia bisa nungguin di sekitar ring Hyperspace Hole.","how":"Taruh ring lebih jauh dari fight, Phantom Force buat kabur dari Fire Spin."},{"name":"Snorlax","why":"Stun + knockback-nya matahin warp dan Hyperspace Fury.","how":"Unbound dulu (kebal CC pas Psybeam) sebelum dia bisa Heavy Slam."}],"goodAgainst":[{"name":"Blastoise","why":"Tank lambat; tim lo bisa ngeroyok lewat ring sebelum dia nyusul, dan Hyperspace Fury bikin dia diem."},{"name":"Lapras","why":"Pelan dan gampang kena Shadow Ball dobel; damage area Unbound ngehajar frontliner yang gak bisa kabur (inferensi)."}]},"cinderace":{"similarity":3,"note":"Sama-sama ranged dan basic attack lo berguna, tapi Hoopa gak punya kiting: lo cuma nembak dari belakang carry. Yang harus diubah total: pikiran lo di map (kapan taruh ring, siapa yang perlu warp), bukan di target. Unbound sedikit mirip Cinderace Unite: masuk, nuke, lalu keluar."},"sources":["https://serebii.net/pokemonunite/pokemon/hoopa.shtml","https://bulbapedia.bulbagarden.net/wiki/Hoopa_(UNITE)","https://www.dittobase.com/unite/pokemon/hoopa","https://game8.co/games/Pokemon-UNITE/archives/368852","https://www.wepc.com/gaming/pokemon/hoopa-confined-and-unbound-in-unite/"],"confidence":"medium","notes":"Slot: Astonish→Phantom Force/Shadow Ball Lv6 (up Lv12), Confusion→Hyperspace Hole/Trick Lv4 (up Lv10) per Bulbapedia & dittobase (ringkasan Serebii nukar slot). Mapping persis move Unbound ke tombol (Hyperspace Fury / Psybeam / apakah Shadow Ball-Phantom Force tetep bisa dipakai) gak konsisten antar sumber; game8 bilang move standar gak tersedia selama Unbound. Detail upgrade Lv10/12 gak terverifikasi jadi ditulis umum. Nerf Mei 2025: Trick speed turun, Shadow Ball damage turun; buff Feb 2025 (detail gak dikonfirmasi). Counter dari game8; goodAgainst sebagian inferensi.","image":"img/hoopa.webp","status":"Owned"},{"name":"Lapras","slug":"lapras","role":"Defender","damage":"Special","range":"Ranged","difficulty":"Menengah","evolutions":"Lapras (tidak berevolusi, langsung Lapras dari Lv1)","tagline":"Tank ranged yang nge-slow, nge-stun, dan bisa 'ngebus' teman ke objective pakai Unite-nya.","passive":{"name":"Shell Armor","desc":"Kalau kena satu serangan yang damage-nya gede banget (di atas persentase tertentu dari max HP), damage itu dipotong. Jadi Lapras tahan banget sama burst satu kali hit."},"basicAttack":"Basic attack ranged biasa. Tiap serangan ketiga jadi boosted: nyemprot air ke depan (area), kena musuh dan heal HP lo. Rajin basic attack biar sustain jalan.","lanes":["Top","Bottom"],"laneNote":"Paling enak di Bottom bareng attacker yang butuh peel. Top juga oke kalau tim butuh frontliner buat jaga Regieleki. Jangan jungle.","earlyGame":"Lv1 ambil Ice Shard (slow + poke jauh) dan Whirlpool buat clear wild. Lo tank, jadi maju duluan buat body block dan contest wild lane sambil nge-slow musuh pakai Ice Shard biar partner lo bisa farm aman. Jangan all-in sebelum Lv5, kerja lo bikin musuh gak nyaman farm.","powerSpike":"Lv5 dapet Water Pulse/Perish Song (damage mulai kerasa), Lv7 dapet Bubble Beam/Ice Beam (CC asli). Lv9 Unite Lapras Express bikin lo bisa engage dan antar teman ke objective.","slot1":{"base":{"name":"Whirlpool","level":1,"desc":"Bikin pusaran air di sekitar lo yang ngasih damage berkala ke musuh di dekat."},"choices":[{"name":"Water Pulse","level":5,"upgradeLevel":11,"desc":"Lepas gelombang air melingkar dari badan lo yang nge-slow musuh. Tiap musuh yang kena bikin gelombang tambahan (bisa berkali-kali).","when":"Tekan pas lo udah di tengah 2-3 musuh atau pas musuh nempel lo. Makin banyak yang kena, makin banyak gelombang susulan, makin sakit.","avoid":"Jangan dipakai dari jauh buat poke satu musuh, gelombang susulannya kebuang.","upgradeNote":"Lv11 jumlah gelombang tambahan nambah, jadi damage area di teamfight makin gede."},{"name":"Perish Song","level":5,"upgradeLevel":11,"desc":"Nyanyi 3 kali berturut-turut, tiap hit ngasih damage. Musuh yang kena 3 kali dan HP-nya di bawah batas tertentu langsung KO (execute).","when":"Tekan pas musuh udah setengah HP dan gak bisa kabur (kena stun Bubble Beam atau slow Ice Beam). Pastikan 3 hit-nya masuk semua ke target yang sama.","avoid":"Jangan buka fight dengan Perish Song, nyanyian pertama cuma damage biasa, musuh tinggal mundur.","upgradeNote":"Lv11 basic attack lo jadi boosted setelah nyanyian ketiga, nambah damage dan heal."}]},"slot2":{"base":{"name":"Ice Shard","level":1,"desc":"Lempar bongkahan es ke arah tertentu, damage dan ngasih efek freeze/slow."},"choices":[{"name":"Bubble Beam","level":7,"upgradeLevel":13,"desc":"Lo dapet shield, lalu semprot gelembung ke satu arah. Musuh yang kena kebungkus gelembung dan gak bisa gerak sebentar.","when":"Tekan pas musuh nge-dive teman lo (buat peel) atau pas carry musuh keluar posisi. Ini CC utama lo, simpan buat target yang penting.","avoid":"Jangan dipake asal buat farm atau ke tank musuh, cooldown-nya lama dan lo kehilangan alat peel.","upgradeNote":"Lv13 efek bungkusannya lebih kuat (durasi/shield naik)."},{"name":"Ice Beam","level":7,"upgradeLevel":13,"desc":"Tembak sinar es ke satu arah yang bikin lantai beku. Musuh di atas es kena damage berkala dan di-slow, sedangkan lo malah dapat tambahan speed di atas es.","when":"Tekan buat zoning area objective (Rayquaza pit, jalur mundur musuh) atau buat kejar/kabur karena lo jadi cepat di atas es.","avoid":"Jangan tembak ke arah yang musuh tinggal melipir keluar, zonanya lurus dan gampang dihindari kalau gak dikombinasi slow lain.","upgradeNote":"Lv13 durasi freeze/slow lebih panjang."}]},"unite":{"name":"Lapras Express","level":9,"desc":"Lo naik ombak dan ngebut ke depan, musuh yang kena dilempar. Satu teman bisa naik di punggung lo dan ikut dibawa, dan masih bisa pakai move dari atas punggung. Tekan lagi buat lepas ombak susulan.","when":"Pakai buat engage bareng carry (ajak Cinderace/attacker lo naik, lalu drop di posisi aman), buat nyelametin teman yang kepepet, atau buat rotasi cepat ke Rayquaza.","avoid":"Jangan nyemplung sendirian ke 5 musuh, Unite ini alat transport + engage, bukan burst damage."},"builds":[{"name":"Water Pulse + Bubble Beam — Tank Utility","moves":["Water Pulse","Bubble Beam"],"recommended":true,"style":"Frontliner standar: masuk, slow area pakai Water Pulse, stun carry pakai Bubble Beam, body block buat tim.","heldItems":[{"name":"Curse Incense","why":"Lapras sering nempel musuh, aura-nya nambah damage sambil ngurangin heal lawan."},{"name":"Resonant Guard","why":"Shield buat lo dan teman di dekat, cocok sama gaya main nempel carry."},{"name":"Focus Band","why":"Heal pas HP kritis, bikin lo tahan lebih lama di depan."}],"battleItem":{"name":"X Speed","why":"Lapras lambat, X Speed buat ngejar target Bubble Beam atau kabur."},"combo":["Dekatin musuh (X Speed kalau perlu), tekan Water Pulse pas udah nempel 2-3 musuh.","Bubble Beam ke carry musuh yang mau kabur atau yang nge-dive teman lo.","Basic attack terus biar boosted keluar dan heal jalan, ulang Water Pulse pas cooldown balik."],"comboNote":"Pakai Lapras Express buat masuk bareng carry kalau fight-nya besar."},{"name":"Perish Song + Bubble Beam — Executioner","moves":["Perish Song","Bubble Beam"],"recommended":false,"style":"Tank yang bisa ngabisin: stun dulu pakai Bubble Beam, lalu 3 nyanyian Perish Song buat execute.","heldItems":[{"name":"Sp. Atk. Specs","why":"Nambah Sp. Atk biar Perish Song-nya sakit dan ambang execute lebih gampang kecapai."},{"name":"Slick Spoon","why":"Nembus Sp. Def musuh, bagus buat damage ke tank lawan."},{"name":"Focus Band","why":"Biar lo gak gampang mati pas lagi nyanyi 3 kali."}],"battleItem":{"name":"X Speed","why":"Buat nempel target supaya 3 hit Perish Song masuk semua."},"combo":["Bubble Beam ke target yang HP-nya udah setengah.","Langsung Perish Song 3 kali ke target yang sama selagi dia kebungkus.","Kalau target masih hidup, basic attack boosted buat nambah damage dan heal."],"comboNote":"Dittobase list Perish Song + Ice Shard sebagai varian damage; di sini Bubble Beam dipilih karena stun-nya bikin 3 hit lebih pasti masuk."},{"name":"Water Pulse + Ice Beam — Zoner Objective","moves":["Water Pulse","Ice Beam"],"recommended":false,"style":"Lebih ke kontrol area: bikin lantai es di pit objective dan jalur musuh, musuh slow terus, lo lincah di atas es.","heldItems":[{"name":"Curse Incense","why":"Lo nempel musuh di area es, damage aura jalan terus."},{"name":"Slick Spoon","why":"Nambah damage tembus Sp. Def dari Water Pulse."},{"name":"Buddy Barrier","why":"Shield buat lo dan teman pas Lapras Express dipakai di objective."}],"battleItem":{"name":"Eject Button","why":"Reposisi cepat buat nyusul atau kabur, ganti X Speed kalau lo udah pede ngatur jarak."},"combo":["Ice Beam di jalur musuh atau pit Rayquaza biar mereka slow.","Maju di atas es (lo lebih cepat), Water Pulse pas nempel.","Basic attack sambil kiting di area es, Lapras Express kalau butuh kabur atau nyelametin teman."],"comboNote":""}],"situations":{"gank":"Pas nge-gank: masuk duluan, Bubble Beam ke target yang mau kabur, Water Pulse pas nempel. Pas dikeroyok: Bubble Beam ke yang paling sakit, Water Pulse buat slow semuanya, mundur sambil basic attack biar heal jalan.","escape":"Ice Beam ke arah lo mundur (lo cepat di es, musuh slow), atau Lapras Express buat kabur jauh sambil bawa teman. Eject Button/X Speed kalau Unite belum siap.","objective":"Di Rayquaza/Regieleki, lo berdiri di antara musuh dan carry lo. Simpan Bubble Beam buat musuh yang nyoba steal atau nge-dive. Lapras Express bisa antar carry lo ke posisi aman buat secure, atau lempar musuh keluar pit.","duel":"1v1 lo gak bakal bunuh cepat, tapi susah dibunuh. Slow terus, basic attack buat heal, dan tunggu target salah posisi. Lawan yang kabur, biarin, jangan ngejar jauh.","teamfight":"Posisi di depan carry, bukan di belakang. Prioritas: peel carry lo dulu (Bubble Beam ke yang nge-dive), baru damage area pakai Water Pulse. Lapras Express buat engage bareng atau buat narik fight ke posisi tim."},"mistakes":["Nge-chase musuh sampai jauh dari tim, Lapras lambat dan gampang dikeroyok balik.","Buang Bubble Beam ke tank atau buat farm, padahal itu satu-satunya stun lo.","Pakai Lapras Express buat damage sendirian tanpa teman yang ikut, padahal nilai utamanya transport dan engage bareng.","Lupa basic attack: boosted attack ketiga itu sumber heal lo, jangan cuma nunggu cooldown move."],"counters":{"hardFor":[{"name":"Blissey","why":"Dia ngasih shield dan unstoppable ke carry musuh, stun Bubble Beam lo jadi sia-sia dan slow lo diilangin.","how":"Jangan buang Bubble Beam pas Safeguard-nya aktif, tunggu habis baru stun."},{"name":"Mewtwo Y","why":"Burst special dari jauh yang ngelewatin batas Shell Armor, dan terlalu mobile buat dikejar Lapras.","how":"Tetep nempel tim, jangan jalan sendiri; manfaatin Lapras Express buat tutup jarak saat dia pakai move."},{"name":"Delphox","why":"Damage berkala dari jauh (bukan satu hit gede) jadi Shell Armor gak banyak nolong, plus slow lo gak nyampe.","how":"Pakai Ice Beam buat zoning dan paksa dia reposisi, atau tunggu dia keluar posisi lalu Bubble Beam."}],"goodAgainst":[{"name":"Zacian","why":"Shell Armor motong burst-nya dan Bubble Beam bisa ngunci dia di tengah tim lo."},{"name":"Buzzwole","why":"Melee all-rounder yang harus nempel; Water Pulse + Ice Beam bikin dia slow terus dan heal lo ngimbangin damage-nya."},{"name":"Charizard","why":"Harus dekat buat damage, gampang dikunci Bubble Beam dan kena execute Perish Song pas HP turun."}]},"cinderace":{"similarity":3,"note":"Sama-sama ranged dan basic attack-nya penting, jadi kebiasaan auto-attack sambil nunggu boosted bisa dibawa. Bedanya total: lo bukan mau kabur dari fight, lo yang maju duluan nerima damage. Jangan kiting terlalu jauh, carry lo butuh badan lo di depan, dan pikirin Unite sebagai 'bus' buat teman, bukan finisher."},"sources":["https://serebii.net/pokemonunite/pokemon/lapras.shtml","https://bulbapedia.bulbagarden.net/wiki/Lapras_(UNITE)","https://www.dittobase.com/unite/pokemon/lapras","https://www.serebii.net/pokemonunite/patch.shtml","https://www.gfinityesports.com/article/tier-list-best-pokemon"],"confidence":"high","notes":"Data move konsisten antara Serebii dan Bulbapedia. Patch 1.21.1.8 (Juni 2026) buff Lapras: Shell Armor potong 25%, heal boosted attack naik, Bubble Beam cooldown turun, speed di es Ice Beam naik 40%. Dittobase ngerekomendasiin Ice Shard (base) dibiarin di slot 2 untuk build damage; gw pilih Bubble Beam karena stun-nya jauh lebih berguna buat pemain kasual. Counter adalah inferensi dari mekanik, bukan dari tabel game8 (game8 gak bisa diakses).","image":"img/lapras.webp","status":"Owned"},{"name":"Meowscarada","slug":"meowscarada","role":"Pelari Cepat","damage":"Physical","range":"Melee","difficulty":"Menengah","evolutions":"Sprigatito (Lv1) → Floragato (Lv4) → Meowscarada (Lv6)","tagline":"Assassin kucing pesulap: nempelin bom bunga, lompat masuk pakai Trailblaze, ledakin, dan reset cooldown tiap dapat kill.","passive":{"name":"Overgrow","desc":"Saat HP lo turun ke setengah atau kurang, lo ngilang jadi daun sebentar (nggak bisa di-target), lalu movement speed dan damage lo naik, dan tiap hit ke musuh nge-heal lo. Ada cooldown setelah aktif, jadi nggak bisa diandelin dua kali dalam satu fight."},"basicAttack":"Basic attack melee, boosted attack keluar berkala: lo lompat ke musuh dan kasih damage tambahan. Hone Claws (early) bikin 3 auto berikutnya lebih cepat dan sakit.","lanes":["Jungle"],"laneNote":"Jungle hampir wajib: Sprigatito/Floragato lemah dan lo butuh Lv6 (Flower Trick / Night Slash) dan Lv7 (Double Team / Trailblaze) secepatnya. Di lane lo bakal kalah trade terus sampai evolusi terakhir.","earlyGame":"Farm jungle pakai Leafage (slow) + Hone Claws (auto cepat), jangan gank sebelum Lv6. Begitu Meowscarada, cari laner musuh yang HP-nya udah kepotong: Flower Trick scaling dari HP yang hilang, jadi target yang 'udah luka' itu makanan lo. Setelah kill, cooldown reset, lanjut ke target berikutnya atau balik farm.","powerSpike":"Lv6 (evolusi + Flower Trick / Night Slash) lo mulai bisa ngebunuh; Lv7 (Trailblaze / Double Team) ngasih cara masuk-keluar; Lv9 Floral Flourish bikin lo bisa nge-reset posisi dan nambah damage area.","slot1":{"base":{"name":"Leafage","level":1,"desc":"Tembak daun ke arah musuh, kasih damage dan slow; poke early buat last-hit."},"choices":[{"name":"Flower Trick","level":6,"upgradeLevel":11,"desc":"Nempelin bom bunga ke musuh (sure-hit); setelah beberapa saat atau kalau lo tekan lagi, bomnya meledak dengan damage yang makin besar sesuai persentase HP yang udah hilang dari target. Cooldown reset kalau target yang ditempelin mati.","when":"Tempelin ke target yang HP-nya udah di bawah setengah, auto beberapa kali, lalu ledakin buat finishing. Di teamfight, tempelin ke yang paling luka, bukan yang paling dekat.","avoid":"Jangan ledakin bom di target full HP; damage-nya kecil banget. Dan jangan tempel ke tank kalau ada carry musuh yang udah luka.","upgradeNote":"Lv11: damage ledakannya naik dan reset cooldown-nya makin konsisten, jadi rantai kill lebih mulus."},{"name":"Night Slash","level":6,"upgradeLevel":11,"desc":"Lempar gelombang tebasan ke depan yang nandain musuh; auto lo ke target yang ditandai punya crit rate lebih tinggi dan nge-heal lo (heal-nya turun kalau hit berulang di target yang sama).","when":"Tekan dari jarak agak jauh buat nandain carry musuh, lalu Trailblaze masuk dan auto spam ke yang ditandai. Cocok buat yang suka main crit + sustain.","avoid":"Jangan spam Night Slash ke target yang sama berulang-ulang; damage hit berikutnya ke target sama dikurangi (patch May 2026: 30% reduction), jadi sebar tandanya.","upgradeNote":"Lv11: damage dan crit bonus-nya naik, auto ke target yang ditandai makin sakit."}]},"slot2":{"base":{"name":"Hone Claws","level":1,"desc":"Asah cakar: 3 basic attack berikutnya lebih cepat dan lebih sakit; alat farm early."},"choices":[{"name":"Double Team","level":7,"upgradeLevel":13,"desc":"Lo dash sambil bikin ilusi (clone) yang jalan sendiri; tekan lagi buat tukar posisi sama clone-nya, dan pas tukar ada damage kelopak + CC ke musuh di sekitar.","when":"Dash masuk, auto, lalu tekan lagi buat tukar posisi dengan clone yang udah jauh = escape instan. Atau sebaliknya: kirim clone duluan ke musuh, tukar, dan muncul di tengah mereka buat ledakan Flower Trick.","avoid":"Jangan lupa clone-nya punya jarak dan waktu terbatas (patch May 2026: jalan 4m dulu baru nyari musuh, jangkauan cari 5m); kalau lo tekan swap terlalu telat, clone-nya udah hilang.","upgradeNote":"Lv13: damage dan efek saat tukar posisi naik, jadi swap bisa dipakai sebagai alat engage, bukan cuma kabur."},{"name":"Trailblaze","level":7,"upgradeLevel":13,"desc":"Lompat ke titik yang dipilih, kasih damage + paralyze musuh yang kena. Cooldown reset kalau lo dapat kill atau assist.","when":"Lompat dari semak (jangkauannya nambah kalau dari tall grass) ke carry musuh, paralyze, ledakin Flower Trick, auto. Setelah kill, Trailblaze reset: lompat ke target berikutnya atau keluar.","avoid":"Jangan Trailblaze masuk tanpa rencana keluar kalau lo belum yakin dapet kill; tanpa reset, lo kejebak di tengah musuh tanpa dash.","upgradeNote":"Lv13: damage naik dan paralyze-nya lebih lama."}]},"unite":{"name":"Floral Flourish","level":9,"desc":"Lo pindah instan ke titik yang dipilih dan bikin pusaran bunga di sekitar lo yang terus kasih damage ke musuh di dalamnya; bisa dibatalin dengan tekan lagi. Lo juga dapat movement speed dan shield.","when":"Pakai buat teleport masuk ke tengah 2-3 musuh yang udah luka (pusaran + Flower Trick ledak), atau sebagai escape instan lewat dinding. Shield-nya bikin lo bisa bertahan di pusaran sebentar.","avoid":"Jangan tekan ke musuh full HP yang ada tank-nya; pusarannya nggak sebesar itu dan lo cuma pindah ke tempat mati. Jangan juga pakai cuma buat jalan cepat tanpa damage atau escape."},"builds":[{"name":"Flower Trick + Trailblaze — Reset Assassin","moves":["Flower Trick","Trailblaze"],"recommended":true,"style":"Lompat dari semak, paralyze, tempel bom, ledak, kill, reset dua-duanya, ulangi. Build meta yang paling gampang dapet multi-kill.","heldItems":[{"name":"Razor Claw","why":"Habis move, auto lo tambah sakit + slow; lo pakai 2 move tiap engage jadi bonusnya hampir selalu aktif."},{"name":"Attack Weight","why":"Rantai kill bikin lo sering di goal musuh; stack Attack cepat penuh."},{"name":"Energy Amplifier","why":"Floral Flourish sering keluar dan damage bonus setelah ult nambah ledakan Flower Trick."}],"battleItem":{"name":"Eject Button","why":"Kalau kill-nya nggak dapet dan Trailblaze nggak reset, Eject adalah satu-satunya jalan keluar."},"combo":["Tunggu di semak sampai carry musuh HP-nya di bawah setengah (biarin tim lo yang nge-poke).","Trailblaze ke dia (paralyze) → Flower Trick nempel → auto boosted.","Tekan Flower Trick lagi buat ledakin. Kill → Trailblaze + Flower Trick reset → lompat ke target berikutnya atau keluar."],"comboNote":"Reset cuma terjadi kalau target bom-nya mati; kalau dicuri Kill Steal, tetap dapet reset Trailblaze dari assist."},{"name":"Night Slash + Trailblaze — Crit Skirmisher","moves":["Night Slash","Trailblaze"],"recommended":false,"style":"Tandain target dari jauh, lompat, auto crit sambil heal. Lebih konsisten lawan tim yang nggak gampang di-burst.","heldItems":[{"name":"Scope Lens","why":"Auto ke target yang ditandai crit lebih sering, Scope Lens ngegedein crit damage-nya."},{"name":"Razor Claw","why":"Bonus auto + slow setelah tiap move biar target yang ditandai nggak lepas."},{"name":"Attack Weight","why":"Stack Attack dari score setelah kill."}],"battleItem":{"name":"Eject Button","why":"Escape kalau Trailblaze nggak reset."},"combo":["Night Slash dari jarak ke 1-2 musuh (tanda).","Trailblaze ke target yang ditandai (paralyze), auto spam crit + heal.","Night Slash lagi ke target lain kalau yang pertama udah luka, biar tanda nyebar; keluar lewat Trailblaze reset atau Floral Flourish."],"comboNote":"Hit berulang ke target yang sama dikurangi damage-nya; sebar tanda ke 2 musuh."}],"situations":{"gank":"Saat nge-gank: tunggu laner tim lo nge-poke dulu, baru Trailblaze dari semak ke yang paling luka, Flower Trick, ledak. Saat dikeroyok: jangan lawan di bawah setengah HP, biarin Overgrow (ngilang + speed) bawa lo keluar, lalu Double Team swap / Floral Flourish / Eject.","escape":"Overgrow aktif otomatis di setengah HP (lo ngilang sebentar, speed naik): itu momen lari, bukan momen lanjut fight. Double Team swap ke clone yang jauh, Trailblaze lewatin dinding, Floral Flourish teleport, Eject Button. Jangan nunggu Overgrow kalau musuh punya burst yang bisa langsung ngelewatin setengah HP lo.","objective":"Di Rayquaza / Regieleki: lo bukan yang secure, lo yang nunggu di semak sampai carry musuh HP-nya turun gara-gara fight, lalu Trailblaze + Flower Trick ke dia. Floral Flourish ke pit pas 3 musuh ngumpul dan udah luka. Flower Trick juga bisa buat last-hit objective yang HP-nya tinggal dikit (damage scaling dari HP hilang).","duel":"1v1 lo menang lawan squishy kalau mulai dari semak: Trailblaze (paralyze) → Flower Trick → auto → ledak. Lawan full HP, poke dulu pakai Night Slash/auto sampai setengah baru ledakin. Lawan tank / sustain (Blastoise, Tsareena, Umbreon) nggak worth, pergi.","teamfight":"Masuk TERAKHIR dari semak atau sisi. Prioritas: Attacker/Supporter yang HP-nya paling rendah (bukan paling dekat). Satu kill = reset = target berikutnya. Floral Flourish pas 2-3 musuh ngumpul dan tim lo udah motong HP mereka."},"mistakes":["Masuk fight duluan atau sebelum Lv6; Floragato nggak punya damage dan Overgrow belum nyelametin lo dari burst.","Ledakin Flower Trick di target full HP; damage-nya tergantung HP yang hilang.","Trailblaze masuk tanpa rencana keluar (ngandelin reset yang belum tentu dapet).","Nongkrong di semak terus sampai timnya mati; lo harus masuk begitu musuh udah luka, bukan nunggu sempurna.","Ngelanjutin fight pas Overgrow aktif padahal HP udah setengah; speed boost-nya buat kabur atau finishing, bukan buat nge-tank."],"counters":{"hardFor":[{"name":"Gengar","why":"Dream Eater / Hex burst-nya ngelewatin setengah HP lo sebelum Overgrow sempat bantu, dan dia mobile.","how":"Jangan pernah masuk tanpa Trailblaze siap; tunggu dia buang Hex, paralyze dia, baru ledak."},{"name":"Pikachu","why":"Thunderbolt / Volt Tackle ngunci lo dari jauh, dan burst special-nya nembus HP tipis lo.","how":"Masuk dari semak di luar jangkauan Thunderbolt, Trailblaze dulu buat paralyze."},{"name":"Absol","why":"Speedster lain yang lebih cepat masuk-keluar dan burst-nya ngalahin lo di early.","how":"Jangan duel sebelum Lv9; main di dekat tim dan ledakin Flower Trick pas dia udah luka dari tank lo."},{"name":"Snorlax","why":"Block + Yawn ngunci lo setelah Trailblaze masuk, dan dia nggak bisa lo burst.","how":"Jangan lewat dia; Trailblaze ke carry di belakangnya, Eject Button buat Yawn."}],"goodAgainst":[{"name":"Decidueye","why":"Attacker tanpa escape yang sering sendirian; Trailblaze dari semak + Flower Trick kelar dalam 2 detik."},{"name":"Comfey","why":"Supporter rapuh; kalau dia lepas dari host-nya, paralyze + ledakan langsung bunuh."},{"name":"Venusaur","why":"Lambat dan nggak bisa kabur dari paralyze; begitu HP-nya setengah, Flower Trick ngabisin dia."}]},"cinderace":{"similarity":3,"note":"Cinderace nge-kite dan mukul dari jauh; Meowscarada nunggu, lompat, dan ledakin. Yang bisa lo bawa: insting nyari target yang paling luka (di Cinderace lo finishing pakai Pyro Ball, di sini pakai Flower Trick). Yang harus diubah: kesabaran, lo nggak boleh poke dari depan; lo diam di semak sampai ada yang HP-nya setengah, dan lo cuma masuk kalau ada jalan keluar."},"sources":["https://www.serebii.net/pokemonunite/pokemon/meowscarada.shtml","https://bulbapedia.bulbagarden.net/wiki/Meowscarada_(UNITE)","https://www.dittobase.com/unite/pokemon/meowscarada","https://ggrecon.com/guides/pokemon-unite-best-meowscarada-build","https://www.pokemonunite.jp/en/topics/battle/20260513-1/","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"medium","notes":"Level Unite move beda antar sumber: Serebii bilang Lv8, Bulbapedia dan dittobase bilang Lv9; gw pakai Lv9 (2 sumber). Patch 14 May 2026: Double Team (clone jalan 2m→4m sebelum nyari musuh, jangkauan cari 10m→5m) dan Night Slash (pengurangan damage hit berulang 50%→30%, heal auto ke target bertanda 100/50/10% → 100/50/20%). Feb-Mar 2025: Defense Penetration ditambah, Apr 2025 nerf. Detail efek upgrade Lv11/13 nggak dirinci di sumber, jadi upgradeNote bersifat umum. Counter: Gengar/Pikachu/Absol/Dodrio dari ggrecon, Snorlax inferensi mekanik.","image":"img/meowscarada.webp","status":"Owned"},{"name":"Sableye","slug":"sableye","role":"Suporter","damage":"Physical","range":"Melee","difficulty":"Menengah","evolutions":"Sableye (tidak berevolusi)","tagline":"Support nakal yang invisible: curi energy, pasang jebakan vision, dan bikin lawan nyerang temen sendiri.","passive":{"name":"Prankster","desc":"Kalau lo di luar jarak pandang lawan, lo masuk stealth dan jalan lebih cepet. Stealth-nya bertahan sebentar setelah lawan bisa liat lo (lebih lama kalau lo dateng dari belakang), dan pecah kalau lo nyerang."},"basicAttack":"Melee. Serangan ke-3 jadi boosted: damage + slow. Kalau boosted keluar dari stealth, lawan kena 'fear' (lari menjauh dari lo). Masuk stealth lagi nge-reset boosted-nya.","lanes":["Top","Bottom"],"laneNote":"Lane mana pun tapi Sableye sebenarnya roamer: dia paling bernilai pas pindah-pindah buat gank dan nyuri farm lawan.","earlyGame":"Jangan farm duluan, biarin carry. Pakai Thief ke lawan yang bawa energy buat nyuri dan slow, lalu balik ke grass. Astonish dari belakang lawan buat slow lebih lama. Lv4 ambil Knock Off/Shadow Sneak dan mulai roaming.","powerSpike":"Lv4 (Knock Off/Shadow Sneak) kasih lo CC asli; Lv6 (Confuse Ray/Feint Attack) kasih identitas; Lv8 Chaos Glower buat ngunci lawan rame-rame.","slot1":{"base":{"name":"Thief","level":1,"desc":"Dash ke lawan, damage + slow, nyuri Aeos energy dari dia (kalau dia gak bawa energy, dia dibikin gak bisa bergerak sebentar)."},"choices":[{"name":"Knock Off","level":4,"upgradeLevel":10,"desc":"Lo maju ke arah tertentu lalu balik lagi sambil nyerang sekeliling (dua tahap). Lawan yang kena gak bisa ngambil Aeos energy dan dibikin gak bisa bergerak sebentar. Ngumpulin energy yang jatuh setelahnya nyembuhin lo dan nambah speed.","when":"Pas 2+ lawan lagi rebutan energy di objective/goal, atau buat ngunci target yang mau kabur dari gank.","avoid":"Jangan tekan dari jauh pas lawan belum di jangkauan tahap balik-nya.","upgradeNote":"Lv10: efek ditingkatkan (durasi immobilize/cooldown, detail gak dikonfirmasi)."},{"name":"Shadow Sneak","level":4,"upgradeLevel":10,"desc":"Lo nyelinap lewat bayangan ke arah tertentu dan nyerang; kalau dari belakang lawan, damage dan efeknya lebih kuat.","when":"Buat masuk dari belakang backline lawan atau buat nyebrang ke goal lawan sambil tetep stealth.","avoid":"Jangan pakai buat kabur dari depan lawan, efek kuatnya cuma dari belakang.","upgradeNote":"Lv10: efek ditingkatkan (detail gak dikonfirmasi)."}]},"slot2":{"base":{"name":"Astonish","level":1,"desc":"Serangan kerucut ke depan + slow; dari belakang lawan damage dan slow-nya lebih gede."},"choices":[{"name":"Feint Attack","level":6,"upgradeLevel":12,"desc":"Taruh energy palsu (bisa sampai 5 titik, simpan maksimal 3 charge) yang kasih lo vision. Lawan yang ngambil kena damage bertahap + slow.","when":"Taruh di grass jalur gank, di dekat objective sebelum spawn, dan di goal lawan buat tau kapan aman score.","avoid":"Jangan taruh di tempat yang lawan udah jelas liat, dan jangan buang 3 charge di satu tempat.","upgradeNote":"Lv12: efek ditingkatkan (jumlah/durasi, detail gak dikonfirmasi)."},{"name":"Confuse Ray","level":6,"upgradeLevel":12,"desc":"Tembak sinar yang bikin lawan bingung: dipaksa nyerang Pokémon terdekat (termasuk temennya sendiri) dan di-slow.","when":"Ke carry lawan pas dia berdiri di sebelah temennya, atau ke tank lawan yang mau secure objective.","avoid":"Jangan tembak ke lawan yang sendirian jauh dari target lain, efek confuse-nya mubazir.","upgradeNote":"Lv12: efek ditingkatkan (durasi, detail gak dikonfirmasi)."}]},"unite":{"name":"Chaos Glower","level":8,"desc":"Tembak cahaya dari dua mata ke area di depan. Lawan yang menghadap lo kena 'fear' lebih berat: gak bisa bergerak lalu dipaksa mundur; yang membelakangi cuma di-slow.","when":"Dari arah DEPAN lawan pas mereka ngumpul di objective atau ngejar ally lo, supaya semua menghadap lo.","avoid":"Jangan tekan dari belakang lawan (cuma slow) atau pas tim lo gak siap follow up."},"builds":[{"name":"Knock Off + Confuse Ray — Hindrance Gank","moves":["Knock Off","Confuse Ray"],"recommended":true,"style":"Roam, masuk dari stealth, kunci target dengan Knock Off, bikin lawan saling pukul dengan Confuse Ray.","heldItems":[{"name":"Exp. Share","why":"Lo roaming, bukan farming."},{"name":"Float Stone","why":"Speed di luar combat + Prankster = nyampe gank duluan."},{"name":"Resonant Guard","why":"Shield buat lo dan ally pas gank masuk; alternatif Attack Weight (game8) kalau lo sering score."}],"battleItem":{"name":"Eject Button","why":"Lo masuk dalam, butuh keluar setelah CC habis."},"combo":["Dateng dari grass/belakang (stealth)","Boosted attack dari stealth (fear)","Knock Off buat ngunci target","Confuse Ray ke target yang deket temennya","Chaos Glower kalau mereka berbalik menghadap lo"],"comboNote":"X Speed juga dipakai game8 kalau lo lebih suka ngejar daripada escape."},{"name":"Shadow Sneak + Feint Attack — Scout & Score","moves":["Shadow Sneak","Feint Attack"],"recommended":false,"style":"Vision control dan back-door scoring: pasang jebakan, tau posisi semua lawan, nyelinap score.","heldItems":[{"name":"Float Stone","why":"Rotasi cepet antar jebakan dan goal."},{"name":"Exp. Share","why":"Lo jarang farm."},{"name":"Curse Bangle","why":"Nurunin heal lawan pas lo nyerang dari stealth; alternatif Score Shield + Goal-Getter buat full scoring (game8)."}],"battleItem":{"name":"Full Heal","why":"Lo sering sendirian, CC = mati."},"combo":["Feint Attack di grass jalur lawan dan dekat objective","Liat mini-map, pilih target yang sendirian","Shadow Sneak dari belakang","Boosted attack (fear) lalu basic attack","Kalau aman: nyelinap ke goal lawan buat score"],"comboNote":"Sableye yang scoring diem-diem bikin lawan harus balik defend; itu value tersembunyi build ini."}],"situations":{"gank":"Dateng dari belakang supaya stealth lebih lama. Buka dengan boosted attack (fear), Knock Off buat kunci, Confuse Ray ke carry. Lo CC, carry lo yang bunuh.","escape":"Putus line of sight (grass/tembok) supaya Prankster aktif lagi, Shadow Sneak/Eject Button, Astonish buat slow pengejar.","objective":"Feint Attack di sekitar pit sebelum spawn buat vision. Pas last-hit war: Knock Off bikin lawan gak bisa ngambil energy dan diem, Confuse Ray ke yang mau secure. Chaos Glower dari depan ke rombongan mereka.","duel":"Lo bisa kill lawan tipis dari belakang (fear + Knock Off), tapi lawan tanky jangan; curi energy-nya lalu kabur.","teamfight":"Masuk dari sisi/belakang backline. Prioritas: CC carry lawan (Confuse Ray), bukan damage. Chaos Glower pas mereka ngumpul dan menghadap lo."},"mistakes":["Jalan di jalur pandang lawan sehingga stealth gak pernah aktif.","Chaos Glower dari belakang lawan: cuma slow, bukan lock.","Confuse Ray ke lawan yang sendirian.","Lupa Feint Attack = vision; main Sableye tanpa liat mini-map sama aja buang passive-nya."],"counters":{"hardFor":[{"name":"Inteleon","why":"Bisa ngebuka/nembak lo dari jauh sebelum lo nyampe, dan dia juga main dari stealth.","how":"Dateng dari belakang, Knock Off langsung pas dia pasang Snipe Shot."},{"name":"Umbreon","why":"Tanky, gak peduli fear/confuse, dan Foul Play ngehukum basic attack lo.","how":"Jangan duel; curi energy dia pakai Thief/Knock Off lalu pergi."},{"name":"Leafeon","why":"Burst-nya ngabisin Sableye sebelum CC kedua keluar.","how":"Confuse Ray dari jarak maksimal, Full Heal siap."}],"goodAgainst":[{"name":"Chandelure","why":"Immobile saat channel, gampang dikunci dari belakang."},{"name":"Decidueye","why":"HP tipis dan ngandelin posisi diem; fear + Knock Off bikin dia keluar posisi."},{"name":"Gardevoir","why":"Gak punya escape kalau lo dateng dari belakang grass."}]},"cinderace":{"similarity":3,"note":"Beda arah: Cinderace nunggu lawan masuk, Sableye yang masuk ke belakang mereka. Bawa dari Cinderace: kebiasaan baca posisi lawan dan main di pinggir fight. Ubah: damage lo bukan ukuran, CC dan vision yang lo kasih ke tim adalah ukuran; dan lo harus main sama mini-map lebih sering."},"sources":["https://serebii.net/pokemonunite/pokemon/sableye.shtml","https://bulbapedia.bulbagarden.net/wiki/Sableye_(UNITE)","https://www.dittobase.com/unite/pokemon/sableye","https://game8.co/games/Pokemon-UNITE/archives/396577","https://game8.co/games/Pokemon-UNITE/archives/337641"],"confidence":"medium","notes":"Unite move: Bulbapedia, dittobase, game8 sepakat 'Chaos Glower' Lv8 (ringkasan Serebii nyebut nama/level lain, diabaikan). Efek persis Chaos Glower ke lawan yang menghadap (immobilize lalu dipaksa mundur ke base) dari Serebii, belum dikonfirmasi 2 sumber. Deskripsi Shadow Sneak dan semua efek upgrade Lv10/12 gak dijabarkan sumber yang bisa diakses, ditulis umum. Gak ada balance change 2025-2026 yang ketemu (terakhir buff Des 2024, nerf Juli 2023). Counter dari game8.","image":"img/sableye.webp","status":"Owned"},{"name":"Talonflame","slug":"talonflame","role":"Pelari Cepat","damage":"Physical","range":"Melee","difficulty":"Menengah","evolutions":"Fletchling (Lv1) → Fletchinder (Lv5) → Talonflame (Lv7)","tagline":"Speedster paling mobile di game: masuk dari atas, hajar satu target rapuh, langsung keluar lagi.","passive":{"name":"Gale Wings","desc":"Selama HP lo tinggi (di atas sekitar 85%), movement speed naik. Jadi lo paling cepat pas HP penuh; begitu kena damage, bonusnya hilang."},"basicAttack":"Basic attack melee. Tiap serangan ke-3 boosted: bikin pusaran api yang ngasih damage area di sekitar target. Boosted ini penting karena berinteraksi dengan Brave Bird (reset cooldown move 1).","lanes":["Jungle"],"laneNote":"Jungle, hampir wajib. Talonflame butuh level cepat (Lv7 buat Fly/Brave Bird) dan nilainya ada di gank lane dari arah yang nggak diduga. Di lane dia lemah dan cuma ngabisin farm partner.","earlyGame":"Clear jungle lo secepat mungkin, pakai Peck + Acrobatics buat clear, jangan tukar HP sama jungler musuh kecuali tim lo di dekat. Begitu Lv5 (Flame Charge/Aerial Ace) lo bisa gank lane yang musuhnya udah tipis; tapi target utamanya tetap Lv7 secepatnya.","powerSpike":"Lv7 (jadi Talonflame + Fly/Brave Bird) itu spike-nya; sebelum itu lo cuma Speedster rapuh. Lv9 Flame Sweep nambah shield + CC buat masuk/keluar.","slot1":{"base":{"name":"Peck","level":1,"desc":"Terbang ke musuh dan matuk tiga kali."},"choices":[{"name":"Flame Charge","level":5,"upgradeLevel":11,"desc":"Dash ke arah yang lo pilih (nggak butuh target) sambil nyala; musuh yang kena dapet damage, dan movement speed lo naik.","when":"Buat mobilitas murni: masuk ke fight, lewatin tembok, atau kabur setelah Fly. Juga buat score cepat di goal kosong.","avoid":"Jangan buang Flame Charge buat damage di awal fight; simpan buat keluar, karena itu escape lo satu-satunya setelah Fly dipakai.","upgradeNote":"Lv11: move lo dapet defense penetration sebagian, jadi damage ke tank lebih kerasa."},{"name":"Aerial Ace","level":5,"upgradeLevel":11,"desc":"Dash ke target, damage, dan HP lo pulih sedikit tiap kena; serangan berikutnya langsung boosted.","when":"Build damage: tekan setelah mendarat dari Fly/Brave Bird buat tambahan burst + boosted langsung + heal kecil.","avoid":"Jangan pakai sebagai escape kalau nggak ada target; dia butuh target, beda dengan Flame Charge.","upgradeNote":"Lv11: damage naik."}]},"slot2":{"base":{"name":"Acrobatics","level":1,"desc":"Terbang ke area yang dipilih dan nyerang beberapa kali; setelahnya lo bisa langsung dash ke arah lain buat kabur."},"choices":[{"name":"Fly","level":7,"upgradeLevel":13,"desc":"Dua tahap: terbang ke atas (lo nggak bisa ditarget sebentar, dan bisa pindah jauh lintas tembok), lalu nukik ke area yang dipilih ngasih damage; kalau kena, cooldown-nya berkurang.","when":"Buka gank dari arah yang nggak kelihatan, ngehindari skill besar musuh (lo di udara), atau nyeberang tembok buat kabur/score. Ini move paling fleksibel lo.","avoid":"Jangan Fly ke tengah 4-5 musuh tanpa Flame Charge/Eject buat keluar; abis mendarat lo cuma Speedster tipis.","upgradeNote":"Lv13: nukiknya juga nge-throw musuh di area, jadi dapet CC."},{"name":"Brave Bird","level":7,"upgradeLevel":13,"desc":"Nyeruduk ke target dengan damage gede, tapi lo juga kena recoil. Setelahnya, boosted attack lo me-reset cooldown move slot 1.","when":"Build burst: Brave Bird ke target rapuh, Aerial Ace, boosted attack (reset), Aerial Ace lagi. Buat ngehabisin satu target cepat.","avoid":"Jangan pakai pas HP lo udah tipis (recoil bisa bikin lo mati sendiri), dan jangan ke Defender tebal yang nggak bakal mati.","upgradeNote":"Lv13: damage yang lo terima berkurang setelah Brave Bird kena, jadi dive-nya lebih aman."}]},"unite":{"name":"Flame Sweep","level":9,"desc":"Salto di udara lalu nyeruduk ke depan: damage dan ngedorong semua musuh yang kena; lo dapet shield dan movement speed selama efeknya.","when":"Buat ngedorong musuh keluar dari pit Rayquaza/goal, buat misahin backline mereka, atau sebagai shield + dash tambahan buat masuk/keluar fight.","avoid":"Jangan pakai buat damage doang ke satu target; CC dorongnya dan shield-nya yang bernilai."},"builds":[{"name":"Fly + Aerial Ace — Jungle Burst","moves":["Fly","Aerial Ace"],"recommended":true,"style":"Jungler assassin: Fly masuk dari atas ke Attacker/Supporter musuh, Aerial Ace + boosted buat ngehabisin, lalu keluar.","heldItems":[{"name":"Razor Claw","why":"Damage + slow di basic attack setelah move, bikin target nggak bisa kabur dari Aerial Ace."},{"name":"Attack Weight","why":"Attack numpuk tiap score; Talonflame paling gampang score karena mobilitasnya."},{"name":"Float Stone","why":"Movement speed + Attack, makin cepat muter map buat gank."}],"battleItem":{"name":"Eject Button","why":"Escape kedua setelah Fly; X Speed alternatif buat ngejar/kabur yang lebih lama."},"combo":["Fly ke atas, pindah ke belakang target","Nukik ke target rapuh","Aerial Ace (boosted langsung aktif)","Boosted attack, lalu Fly lagi kalau cooldown balik buat keluar / Eject"],"comboNote":"Pilih target yang HP-nya udah tipis atau yang sendirian; jangan dive Defender."},{"name":"Fly + Flame Charge — Scorer / Split Push","moves":["Fly","Flame Charge"],"recommended":false,"style":"Pengacau map: score terus di goal kosong, pancing musuh balik jaga, lalu kabur pakai dua dash.","heldItems":[{"name":"Attack Weight","why":"Score sering = Attack numpuk cepat."},{"name":"Score Shield","why":"Shield pas score, biar nggak gampang diputus."},{"name":"Float Stone","why":"Movement speed buat muter map lebih cepat."}],"battleItem":{"name":"Goal-Getter","why":"Score makin cepat; ganti Eject Button kalau sering ketangkep."},"combo":["Fly lintas tembok ke goal yang nggak dijaga","Score (Score Shield aktif)","Flame Charge keluar begitu musuh datang","Ulang di goal lain atau bantu objective"],"comboNote":"Build ini kuat kalau musuh suka ngumpul; kalau tim lo kalah fight terus, balik ke build Aerial Ace dan bantu fight."},{"name":"Brave Bird + Aerial Ace — Diver Burst","moves":["Brave Bird","Aerial Ace"],"recommended":false,"style":"Burst satu target paling tinggi, tapi recoil dan nggak ada 'di udara' Fly; buat yang udah pede target-selection-nya.","heldItems":[{"name":"Attack Weight","why":"Attack numpuk dari score."},{"name":"Razor Claw","why":"Burst + slow setelah tiap move."},{"name":"Focus Band","why":"Recoil Brave Bird bikin HP lo cepat turun; Focus Band ngebantu survive."}],"battleItem":{"name":"Eject Button","why":"Tanpa Fly, Eject jadi escape utama setelah dive."},"combo":["Brave Bird ke target rapuh","Aerial Ace","Boosted attack (reset cooldown Aerial Ace)","Aerial Ace lagi, lalu Eject keluar"],"comboNote":"Jangan Brave Bird kalau HP lo di bawah setengah."}],"situations":{"gank":"Datang dari belakang/atas lewat Fly, target Attacker atau Supporter yang berdiri paling belakang. Hajar sampai mati atau sampai 2 musuh nengok ke lo, lalu keluar pakai Flame Charge/Eject. Jangan ladenin Defender.","escape":"Fly ke atas (nggak bisa ditarget) lintas tembok, Flame Charge/Acrobatics dash, Flame Sweep shield + dorong, Eject Button. Dengan Gale Wings lo paling cepat pas HP tinggi, jadi mundur SEBELUM HP tipis.","objective":"Rayquaza/Regieleki: jangan berdiri di pit, lo bukan tank. Posisi di sayap, Fly ke backline musuh pas fight mulai, Flame Sweep buat ngedorong musuh keluar pit atau ngehalangin steal. Kalau tim kalah fight, lo yang paling bisa steal/score di goal lain.","duel":"Lo menang lawan ranged rapuh: Fly/Brave Bird masuk, Aerial Ace, boosted, selesai. Lawan Defender/All-Rounder tebal: jangan duel, poke sekali lalu pergi ngerjain hal lain di map.","teamfight":"Jangan masuk duluan. Tunggu Defender/All-Rounder tim lo nahan frontline musuh, baru Fly ke backline (Attacker/Supporter). Setelah satu target mati atau Fly habis, keluar. Prioritas: target rapuh yang terpisah."},"mistakes":["Fight sebelum Lv7 dan ngerasa kuat, padahal Fletchling/Fletchinder lemah.","Fly ke tengah tim musuh tanpa jalan keluar.","Dive Defender/tank, bukan Attacker/Supporter.","Diem di lane kayak Attacker; Talonflame harus muter map dan score."],"counters":{"hardFor":[{"name":"Slowbro","why":"Telekinesis + Amnesia ngunci lo di tempat, dan lo rapuh.","how":"Jangan dive kalau dia belum pakai CC; tunggu dia buang move, baru masuk ke target lain."},{"name":"Buzzwole / Machamp / Urshifu","why":"Tanky, punya grab/CC, dan ngehajar balik lebih sakit dari burst lo.","how":"Hindari sepenuhnya; target backline mereka, dan kabur begitu mereka nengok."},{"name":"Clefable / Trevenant","why":"CC area dan sustain yang ngalahin burst sekali masuk lo.","how":"Masuk lewat Fly pas mereka udah buang CC; jangan tunggu di dekat mereka."},{"name":"Blastoise","why":"Surf/Rapid Spin CC + tebal, lo nggak bisa nembus.","how":"Pergi, score di goal lain; fight di tempat dia nggak ada."}],"goodAgainst":[{"name":"Ranged rapuh (Pikachu, Glaceon, Gardevoir, Sylveon, Espeon, Venusaur, Cramorant)","why":"Fly dari atas ngehindarin skill mereka, lalu burst sebelum mereka sempat reaksi, dan mereka nggak bisa ngejar lo."},{"name":"Jungler yang lambat early (Dragonite, Dratini)","why":"Lo bisa invade dan curi farm mereka sebelum mereka berevolusi."}]},"cinderace":{"similarity":3,"note":"Ini kebalikan dari Cinderace: melee, hit-and-run, dan nilainya di mobilitas bukan DPS konstan. Yang bisa dibawa: insting target-selection (siapa yang rapuh dan sendirian) dan kebiasaan nggak nunggu HP tipis buat mundur. Yang harus diubah total: lo yang nge-dive duluan ke backline (bukan nembak dari belakang), dan lo harus muter map/score, bukan diem di satu lane."},"sources":["https://bulbapedia.bulbagarden.net/wiki/Talonflame_(UNITE)","https://serebii.net/pokemonunite/pokemon/talonflame.shtml","https://game8.co/games/Pokemon-UNITE/archives/335470","https://www.dittobase.com/unite/pokemon/talonflame"],"confidence":"high","notes":"Nama move, level (Lv5 slot 1, Lv7 slot 2, upgrade Lv11/Lv13, Unite Lv9) cocok antara Serebii, Bulbapedia, dan dittobase. Efek upgrade Flame Charge beda antar sumber: Serebii bilang 'slow', Bulbapedia & dittobase bilang 'defense penetration' (ditambahkan patch Feb 2025 menurut ringkasan Serebii patch); gw pakai versi defense penetration. Game8 build utama Fly + Aerial Ace, dittobase Aerial Ace + Brave Bird; gw masukin ketiganya. Game8 catat buff Gale Wings 10%→15% dan Flame Charge +10% di v1.15.1.2 (Jul 2024). Tier Game8 'B'. Difficulty: Serebii 'Novice', Bulbapedia 'Intermediate'.","image":"img/talonflame.webp","status":"Owned"},{"name":"Tsareena","slug":"tsareena","role":"Serba-Bisa","damage":"Physical","range":"Melee","difficulty":"Ahli","evolutions":"Bounsweet (Lv1) → Steenee (Lv4) → Tsareena (Lv6)","tagline":"All-Rounder bruiser yang nendang terus tanpa henti: tahan CC, sustain dari Queenly Majesty, dan ult yang bikin lo plus target kebal dari fight sekitar.","passive":{"name":"Queenly Majesty","desc":"Durasi semua CC yang kena ke lo dipotong. Setiap lo pakai 3 kombinasi boosted attack / move, move berikutnya dapat efek Queenly Majesty: Triple Axel / Stomp jadi nge-heal, Trop Kick / Grassy Glide jadi ngasih shield. Ritme 3-lalu-bonus ini inti main Tsareena."},"basicAttack":"Basic attack melee; tiap serangan ketiga jadi boosted: lo nerjang ke musuh, kasih damage, dan nurunin Defense mereka sebentar. Boosted dihitung ke stack Queenly Majesty, jadi auto lo bukan pengisi waktu, tapi bagian combo.","lanes":["Top","Bottom","Jungle"],"laneNote":"Top atau Bottom paling cocok: Tsareena bruiser yang bisa trade dan tahan lane, dan evolusi Lv6 datang cukup cepat. Jungle bisa (clear-nya oke) tapi tim biasanya lebih butuh dia di lane buat nge-peel dan nge-dive.","earlyGame":"Bounsweet lemah; last-hit pakai Razor Leaf (crit tinggi) dan Rapid Spin buat jarak. Lv4 Steenee udah bisa trade sedikit. Fokus nyampe Lv5 (Triple Axel / Stomp) dan Lv6 (Tsareena + Trop Kick / Grassy Glide), setelah itu lo lebih kuat dari kebanyakan laner dan bisa mulai nge-dive.","powerSpike":"Lv5-6 (slot 1 lalu evolusi + slot 2) lo berubah dari beban jadi bruiser; Lv9 Queen Ascendant ngasih eksekusi 1v1 yang kebal gangguan; Lv10/12 upgrade bikin loop Queenly Majesty makin sering.","slot1":{"base":{"name":"Razor Leaf","level":1,"desc":"Lempar daun ke arah musuh dengan crit rate lebih tinggi dari auto; poke early."},"choices":[{"name":"Triple Axel","level":5,"upgradeLevel":10,"desc":"Spin-kick 3 kali berturut-turut ke arah yang dipilih, damage tiap tendangan naik kalau yang sebelumnya kena, dan attack speed lo naik. Queenly Majesty: tiap tendangan yang kena nge-heal lo.","when":"Tekan saat lo udah nempel ke target biar ketiga tendangan kena (damage ketiga paling sakit). Pakai sebagai move keempat (Queenly Majesty aktif) kalau lo butuh heal di tengah fight.","avoid":"Jangan mulai Triple Axel dari jarak; tendangan pertama meleset = damage naik-nya hilang. Dan jangan pakai versi Queenly Majesty-nya pas HP lo masih penuh, heal-nya kebuang.","upgradeNote":"Lv10: damage dan attack speed bonus-nya naik, loop boosted attack lo jadi lebih cepat."},{"name":"Stomp","level":5,"upgradeLevel":10,"desc":"Lompat tinggi lalu injak musuh di area: damage + mereka nggak bisa bergerak sebentar (stun). Queenly Majesty: nge-heal lo pas kena.","when":"Tekan ke carry musuh buat ngunci sebelum Trop Kick / Grassy Glide, atau buat motong channel / ult musuh (Stomp adalah CC terbaik lo). Enak buat nge-peel teman yang dikejar.","avoid":"Jangan buang Stomp buat damage ke minion / tank saat carry musuh masih bisa lari; simpen buat target yang penting atau buat peel.","upgradeNote":"Lv10: damage naik dan stun-nya lebih lama."}]},"slot2":{"base":{"name":"Rapid Spin","level":1,"desc":"Muter dash ke arah yang dipilih; kalau kena, movement speed lo naik sebentar."},"choices":[{"name":"Trop Kick","level":6,"upgradeLevel":12,"desc":"Tendangan terbang ke arah yang dipilih: damage + nurunin Attack musuh. Queenly Majesty: lo dapat shield saat tekan.","when":"Tekan ke Attacker/All-Rounder musuh yang damage-nya physical buat ngerusak output mereka, atau sebagai dash masuk. Versi Queenly Majesty pas lo mau nge-dive (shield + Attack turun = trade lo menang).","avoid":"Jangan Trop Kick ke arah yang bikin lo mendarat di belakang tim musuh tanpa Stomp / Grassy siap; jarak terbangnya lumayan jauh.","upgradeNote":"Lv12: damage dan penurunan Attack-nya naik; shield Queenly Majesty-nya lebih tebal."},{"name":"Grassy Glide","level":6,"upgradeLevel":12,"desc":"Slide ke arah yang dipilih (damage + slow), lalu serangan kedua ke arah berlawanan. Queenly Majesty: dapat shield saat tekan.","when":"Pakai buat masuk-keluar: slide ke target, serangan balik ke arah lo dateng. Slow-nya bantu ngejar atau nge-kite. Lebih fleksibel dari Trop Kick buat yang masih belajar.","avoid":"Jangan lupa serangan keduanya ke arah berlawanan; kalau lo cuma mau damage ke satu arah, posisi serangan kedua bakal sia-sia.","upgradeNote":"Lv12: damage dan slow-nya naik, shield Queenly Majesty lebih tebal."}]},"unite":{"name":"Queen Ascendant","level":9,"desc":"Lo lompat ke satu musuh, nendang dia ke udara, lalu hujanin tendangan selama di udara; pas mendarat lo heal. Selama di udara, lo dan target NGGAK bisa kena move lain dari siapa pun.","when":"Pakai buat eksekusi 1v1 carry musuh (dia nggak bisa diselamatin temennya), buat nge-dodge ult besar musuh (lo kebal selama di udara), atau buat matiin target yang HP-nya sekitar setengah.","avoid":"Jangan ult ke tank / Defender full HP, damage-nya nggak cukup dan lo buang alat eksekusi. Jangan juga ult pas tim lo butuh lo buat secure objective, lo 'hilang' beberapa detik."},"builds":[{"name":"Triple Axel + Grassy Glide — Sustain Bruiser","moves":["Triple Axel","Grassy Glide"],"recommended":true,"style":"Nendang terus: slide masuk, Triple Axel, auto boosted, ulangi; heal dan shield dari Queenly Majesty bikin lo awet di garis depan.","heldItems":[{"name":"Attack Weight","why":"Tsareena sering menang lane dan score; stack Attack cepat penuh."},{"name":"Weakness Policy","why":"Lo bruiser yang dipukul terus; Attack bonusnya hampir selalu aktif."},{"name":"Scope Lens","why":"Tsareena punya crit alami (Razor Leaf dasar, boosted attack sering); crit damage dari Scope Lens nambah burst Triple Axel."}],"battleItem":{"name":"Eject Button","why":"Buat nyusul carry yang kabur atau keluar dari fokus musuh saat Queenly Majesty lagi nggak siap."},"combo":["Grassy Glide masuk (slow) → auto sampai boosted (Defense turun).","Triple Axel 3 tendangan (attack speed naik) → auto boosted lagi. Itu udah 3 stack.","Move keempat dapat Queenly Majesty: Triple Axel buat heal (kalau HP turun) atau Grassy Glide buat shield (kalau mau lanjut nge-dive). Queen Ascendant buat finishing."],"comboNote":"Hitung stack-nya: boosted, move, move, lalu pilih move keempat sesuai kebutuhan (heal atau shield)."},{"name":"Stomp + Trop Kick — Dive & Lockdown","moves":["Stomp","Trop Kick"],"recommended":false,"style":"Buat yang suka nge-dive carry musuh: Trop Kick masuk (shield + Attack turun), Stomp kunci, ult eksekusi. Lebih CC, lebih sedikit sustain.","heldItems":[{"name":"Attack Weight","why":"Stack Attack dari score setelah menang trade."},{"name":"Razor Claw","why":"Habis Stomp/Trop Kick, auto berikutnya tambah sakit + slow, target nggak bisa lari setelah stun habis."},{"name":"Focus Band","why":"Build ini kurang heal; Focus Band ngasih sustain saat HP tipis setelah dive."}],"battleItem":{"name":"X Attack","why":"Burst + attack speed buat ngabisin carry dalam satu window Stomp."},"combo":["Trop Kick ke carry musuh (Attack-nya turun, lo dapat shield kalau Queenly Majesty siap).","Auto boosted (Defense turun) → Stomp (stun) → auto boosted.","Queen Ascendant buat eksekusi kalau HP-nya di bawah setengah; kalau belum, Trop Kick lagi atau mundur."],"comboNote":"Simpan Stomp buat motong ult musuh kalau fight-nya udah menang tanpa itu."}],"situations":{"gank":"Saat nge-gank: Grassy Glide / Trop Kick masuk ke carry, boosted (Defense turun), Stomp / Triple Axel, ult kalau perlu. Saat dikeroyok: Queenly Majesty motong CC mereka, jadi lo bisa nahan sebentar; pakai Queen Ascendant ke satu target buat 'ngilang' dari fight sambil heal, lalu Grassy Glide keluar.","escape":"Grassy Glide / Trop Kick ke arah aman, Rapid Spin-style speed-nya nggak ada lagi tapi dash-nya cukup. Queen Ascendant adalah escape darurat: lo kebal selama di udara dan heal saat mendarat. Eject Button kalau semua cooldown. Ingat: CC ke lo lebih pendek, jadi sering lo masih sempat kabur.","objective":"Di Rayquaza / Regieleki: lo frontline kedua, bukan yang secure. Stomp buat motong Pokémon musuh yang lagi nyoba steal (stun pas HP objective mau habis), Trop Kick buat nurunin Attack carry mereka. Queen Ascendant ke carry musuh pas pit lagi ramai: dia keluar dari fight, tim lo secure lebih tenang.","duel":"1v1 adalah rumah Tsareena: boosted → move → move → move Queenly Majesty (heal/shield) → ult eksekusi. Lo menang lawan hampir semua melee dan speedster. Lawan ranged yang kiting (Cinderace, Decidueye) tutup jarak pakai Trop Kick / Grassy Glide dulu, jangan ngejar jalan kaki.","teamfight":"Posisi di depan bareng Defender, atau di sisi buat nge-dive. Prioritas: Attacker musuh yang physical (Trop Kick nurunin Attack mereka) dan Supporter. Stomp buat motong ult musuh (Blastoise, Gengar, Snorlax). Queen Ascendant ke carry yang paling bahaya buat ngeluarin dia dari fight."},"mistakes":["Nggak ngitung stack Queenly Majesty, jadi heal / shield keluar di waktu yang salah (heal pas HP penuh).","Triple Axel dari jarak jauh sehingga tendangan pertama meleset dan damage naik-nya hilang.","Queen Ascendant ke tank; ult-nya buat eksekusi carry atau buat kebal, bukan buat damage ke Defender.","Fight sebagai Bounsweet/Steenee; lo lemah sampai Lv6, sabar dulu.","Lupa kalau boosted attack nurunin Defense; main cuma spam move tanpa auto bikin damage lo jauh lebih kecil."],"counters":{"hardFor":[{"name":"Blastoise","why":"Lebih tanky dari lo, Surf / Hydro Pump nge-CC berulang (Queenly Majesty cuma motong, nggak nolak), dan lo nggak bisa nembus HP-nya.","how":"Jangan duel dia; Stomp buat motong Surf, lalu lewat ke carry di belakangnya."},{"name":"Umbreon","why":"Snarl nurunin Attack lo, Mean Look ngunci lo di dekat timnya, dan dia sustain lebih kuat dari lo.","how":"Jauhi dia; kalau ke-Mean Look, Queen Ascendant buat kebal dan heal."},{"name":"Cinderace","why":"Kiting ranged dengan Feint / Flame Charge; lo nggak pernah dapet 3 tendangan penuh dan dia nembak lo dari jauh.","how":"Tutup jarak pakai Trop Kick (Attack-nya turun) lalu Stomp sebelum dia pakai Feint; jangan ngejar lewat area terbuka."},{"name":"Greninja","why":"Smokescreen + Double Team bikin Triple Axel / Stomp lo meleset dan burst-nya ngalahin sustain lo.","how":"Tunggu dia buang Smokescreen, baru Stomp; Queen Ascendant pas dia nempel buat ngunci."}],"goodAgainst":[{"name":"Absol","why":"Speedster rapuh yang harus nempel; CC-nya pendek ke lo, dan Stomp / ult ngabisin dia."},{"name":"Zeraora","why":"Dia butuh duel panjang buat heal lewat boosted, tapi lo sustain lebih kuat dan Stomp motong combo-nya."},{"name":"Pikachu","why":"HP tipis, CC-nya kepotong Queenly Majesty, dan Trop Kick + Stomp nyampe sebelum dia kabur."}]},"cinderace":{"similarity":3,"note":"Beda dunia: Cinderace mukul dari jauh dan kabur, Tsareena masuk dan nggak pergi. Yang bisa lo bawa: kebiasaan ngitung boosted attack (di sini boosted = Defense turun + stack Queenly Majesty, sama pentingnya) dan nyari carry musuh sebagai target. Yang harus diubah: lo berdiri di depan, lo nerima damage dengan sengaja (Weakness Policy), dan lo harus mikir 'move keempat gw mau heal atau shield' tiap kali nge-engage."},"sources":["https://www.serebii.net/pokemonunite/pokemon/tsareena.shtml","https://bulbapedia.bulbagarden.net/wiki/Tsareena_(UNITE)","https://www.dittobase.com/unite/pokemon/tsareena","https://progameguides.com/pokemon/pokemon-unite-best-tsareena-builds/","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"high","notes":"Move level/upgrade konsisten di Serebii + Bulbapedia + dittobase (slot 1 Lv5/upgrade 10, slot 2 Lv6/upgrade 12, Unite Lv9). Tidak ada rework 2026; nerf Triple Axel dua kali di Feb 2025 (v1.17.2.10 dan v1.18.1.2). Dittobase nulis 'Stomp + Rapid Spin' sebagai build yang kayaknya salah parsing (Rapid Spin move dasar), gw abaikan. Efek upgrade Lv10/12 nggak dirinci di sumber, upgradeNote bersifat umum. Counter adalah inferensi mekanik, bukan tabel counter resmi.","image":"img/tsareena.webp","status":"Owned"},{"name":"Urshifu","slug":"urshifu","role":"Serba-Bisa","damage":"Physical","range":"Melee","difficulty":"Menengah","evolutions":"Kubfu (Lv1) → Urshifu Single Strike Style ATAU Rapid Strike Style (Lv5, ditentukan pilihan move slot 1)","tagline":"Bruiser melee yang nusuk shield lawan: Single Strike = satu pukulan super sakit, Rapid Strike = brawler lincah yang nyembuhin diri.","passive":{"name":"Unseen Fist","desc":"Serangan lo nembus sebagian shield lawan, jadi lawan yang ngandelin Buddy Barrier / shield move tetep kena damage HP. Waktu masih Kubfu passive-nya Inner Focus (durasi CC ke lo lebih pendek)."},"basicAttack":"Serangan ke-3 jadi boosted. Single Strike: boosted-nya lunge ke depan dan lo dapet shield pas kena. Rapid Strike: boosted-nya dua pukulan beruntun dan ngurangin cooldown move.","lanes":["Jungle","Bottom","Top"],"laneNote":"Paling enak di Jungle karena Urshifu butuh cepet Lv5 (pilih style) dan Lv7, lalu gank lane. Bisa lane juga kalau tim udah ada jungler.","earlyGame":"Kubfu lemah, jadi farm camp jungle dengan aman, jangan invade. Begitu Lv5 (pilih Wicked Blow atau Surging Strikes) baru mulai gank lane yang lawannya lagi maju jauh. Mundur kalau HP di bawah setengah, Kubfu gampang mati.","powerSpike":"Lv5 (evolusi + move utama) dan Lv7 (Throat Chop / Liquidation) ngubah lo dari lemah jadi predator; Lv9 Unite move bikin all-in lo mematikan.","slot1":{"base":{"name":"Rock Smash","level":1,"desc":"Charge sebentar lalu pukul ke depan; makin lama charge makin sakit."},"choices":[{"name":"Wicked Blow","level":5,"upgradeLevel":11,"desc":"(Single Strike) Charge lalu pukul satu arah. Saat charge, damage yang lo terima berkurang dan lo kebal CC tapi jalan lebih lambat. Kalau charge penuh dan lawan kena di tengah: critical hit + knockback, dan basic attack berikutnya jadi boosted. Ada bonus damage berdasarkan HP lawan yang udah hilang.","when":"Tekan dan tahan saat lawan udah di-CC ally atau lagi mundur lurus ke goal; lepas pas lawan pas di depan muka lo. Paling sakit ke lawan yang HP-nya udah kebakar.","avoid":"Jangan charge penuh di depan lawan yang masih punya dash, dia tinggal geser dan lo buang move paling penting.","upgradeNote":"Lv11: pukulan tengah juga nge-stun lawan dan damage yang lo terima selama charge makin kecil."},{"name":"Surging Strikes","level":5,"upgradeLevel":11,"desc":"(Rapid Strike) Dash + pukul, bisa dipakai 3x beruntun. Pukulan ke-3 pasti critical dan ngelempar lawan. Boosted attack yang kena lawan juga nyembuhin HP lo.","when":"Pakai dash 1-2 buat ngejar/ngatur posisi, simpan dash ke-3 buat finisher atau buat lempar lawan ke arah tim lo.","avoid":"Jangan buang ketiga dash cuma buat ngejar, lo bakal nyangkut di tengah musuh tanpa jalan keluar.","upgradeNote":"Lv11: damage yang lo terima selama pakai move ini berkurang."}]},"slot2":{"base":{"name":"Headbutt","level":1,"desc":"Nyeruduk ke arah tertentu, damage + stun singkat."},"choices":[{"name":"Throat Chop","level":7,"upgradeLevel":13,"desc":"(Single Strike) Dash pendek yang nge-stun lawan yang kena dan bikin basic attack berikutnya boosted.","when":"Ini setup-nya Wicked Blow: Throat Chop dulu buat stun, langsung charge Wicked Blow pas lawan diem.","avoid":"Jangan pakai buat kabur kalau Wicked Blow masih cooldown, lo kehilangan satu-satunya CC lo.","upgradeNote":"Lv13: cooldown Throat Chop berkurang tiap Wicked Blow kena lawan."},{"name":"Liquidation","level":7,"upgradeLevel":13,"desc":"(Rapid Strike) Damage area di sekitar lo, nurunin Defense lawan, dan lo dapet shield sesuai jumlah lawan yang kena.","when":"Tekan pas lo udah nempel di tengah 2-3 lawan: shield gede + mereka jadi lebih empuk buat Surging Strikes.","avoid":"Jangan tekan dari jauh pas belum ada lawan di jangkauan, shield-nya kecil dan debuff-nya sia-sia.","upgradeNote":"Lv13: cooldown lebih pendek."}]},"unite":{"name":"Ebon Fist (Single Strike) / Flowing Fists (Rapid Strike)","level":9,"desc":"Ebon Fist: dash ke satu lawan, pukul dan dorong/lempar dia (bisa diarahkan, lawan kena stun; nabrakin ke lawan lain nambah damage), lalu cooldown Wicked Blow di-reset. Flowing Fists: damage area + dorong lawan sekitar, lo dapet speed dan cooldown berkurang, lalu bisa ngeluarin sampai 10 pukulan beruntun ke satu target yang damage-nya naik sesuai damage yang lo kasih di antaranya.","when":"Ebon Fist: buat buka fight dengan ngelempar carry lawan ke arah tim lo, lalu langsung Wicked Blow lagi. Flowing Fists: pas lo udah di tengah lawan dan butuh reset cooldown + sustain buat brawl panjang.","avoid":"Jangan pakai Unite buat ngejar satu lawan yang udah hampir mati, simpan buat objective fight."},"builds":[{"name":"Wicked Blow + Throat Chop — Single Strike Burst","moves":["Wicked Blow","Throat Chop"],"recommended":true,"style":"Assassin melee: stun, charge, satu pukulan buat ngabisin carry lawan.","heldItems":[{"name":"Muscle Band","why":"Boosted attack dan basic attack jadi bagian penting combo."},{"name":"Attack Weight","why":"Stack Attack dari scoring, Wicked Blow makin sakit."},{"name":"Razor Claw","why":"Bonus damage + slow habis pakai move, cocok dengan Throat Chop lalu basic."}],"battleItem":{"name":"Eject Button","why":"Buat nutup jarak sebelum Throat Chop atau kabur habis all-in."},"combo":["Throat Chop ke target (stun)","Langsung tahan Wicked Blow, lepas pas lawan di tengah hitbox","Basic attack boosted (sudah otomatis boosted)","Kalau ada Unite: Ebon Fist buat lempar, lalu Wicked Blow lagi karena cooldown-nya di-reset"],"comboNote":"Alternatif item: Weakness Policy + Focus Band (game8) kalau lo sering kena fokus."},{"name":"Surging Strikes + Liquidation — Rapid Strike Brawler","moves":["Surging Strikes","Liquidation"],"recommended":false,"style":"Frontliner lincah: masuk, Liquidation buat shield, Surging Strikes 3x sambil heal dari boosted attack.","heldItems":[{"name":"Muscle Band","why":"Lo bakal banyak basic attack di antara dash."},{"name":"Razor Claw","why":"Tiap dash Surging Strikes bikin basic berikutnya nyakitin + slow."},{"name":"Weakness Policy","why":"Attack naik pas kena pukul, cocok buat gaya brawl lama."}],"battleItem":{"name":"Full Heal","why":"Lo bakal lama di tengah lawan, CC adalah pembunuh utama lo."},"combo":["Surging Strikes 1x buat masuk","Liquidation pas di tengah lawan (shield + Defense lawan turun)","Surging Strikes 2x sisanya, yang ke-3 crit + lempar","Basic attack boosted buat heal dan ngurangin cooldown","Flowing Fists kalau fight masih lanjut"],"comboNote":"Alternatif: Accel Bracer dari dittobase (sejak nerf April 2025 butuh 10 KO buat efek maksimal)."}],"situations":{"gank":"Dateng dari grass, Throat Chop (atau Surging Strikes) ke carry lawan, langsung Wicked Blow/Surging Strikes. Target yang HP-nya udah kurang karena Wicked Blow ada bonus damage dari missing HP.","escape":"Single Strike: Throat Chop ke arah lawan yang menghalangi buat stun lalu jalan, atau Eject Button. Rapid Strike: Surging Strikes dash ke arah tim, Full Heal kalau di-CC.","objective":"Jangan jadi yang pertama masuk. Tunggu tank lo buka, lalu Ebon Fist/Wicked Blow ke carry lawan yang mau secure. Rapid Strike bisa pakai pukulan ke-3 Surging Strikes buat ngelempar lawan jauh dari Rayquaza.","duel":"Single Strike menang 1v1 lawan hampir siapa pun yang gak punya CC. Rapid Strike lebih aman lawan bruiser karena heal + shield. Lawan yang nunggu lo charge, pancing dulu move mereka dengan basic attack.","teamfight":"Masuk dari samping/belakang ke backline. Prioritas: Attacker ranged yang HP-nya udah kurang. Jangan buang Wicked Blow ke Defender yang shield-nya tebal kecuali gak ada pilihan (passive lo nembus shield, tapi HP mereka tetep gede)."},"mistakes":["Charge Wicked Blow terlalu lama di depan lawan yang masih punya dash atau CC: lo bakal di-kite.","Invade atau fight pas masih Kubfu; Kubfu salah satu pre-evo paling lemah.","Rapid Strike: buang ketiga Surging Strikes buat ngejar satu target lalu kejebak tanpa escape.","Pakai Ebon Fist buat ngelempar lawan ke arah tim lawan, bukan ke arah tim lo."],"counters":{"hardFor":[{"name":"Slowbro","why":"Telekinesis dan Unite-nya ngunci lo sebelum combo jalan.","how":"Tunggu dia buang CC ke ally lain dulu, baru masuk; Full Heal membantu."},{"name":"Mr. Mime","why":"Barrier dan Confusion-nya ngehalangin dash dan nge-stun saat lo charge.","how":"Masuk dari sisi yang gak ada barrier, atau target dia duluan karena HP-nya rendah."},{"name":"Alolan Ninetales","why":"Freeze + slow dari jarak jauh bikin lo gak pernah nyampe.","how":"Pakai grass buat nutup jarak, Eject Button lalu Throat Chop."}],"goodAgainst":[{"name":"Gardevoir","why":"HP tipis, gampang mati satu Wicked Blow kalau lo nyampe."},{"name":"Zeraora","why":"Ngandelin shield dari Volt Switch, Unseen Fist nembus shield itu."},{"name":"Chandelure","why":"Immobile saat nge-channel, target empuk buat Throat Chop + Wicked Blow."}]},"cinderace":{"similarity":3,"note":"Kalau lo biasa Cinderace, lupain kiting dari jauh: Urshifu harus nempel. Yang bisa dibawa: kebiasaan ngincer backline dan nunggu dash lawan habis. Yang harus diubah: lo gak punya Feint buat kabur, jadi masuk cuma kalau yakin bisa bunuh, dan Wicked Blow butuh commit (charge), bukan spam Pyro Ball."},"sources":["https://serebii.net/pokemonunite/pokemon/urshifu.shtml","https://bulbapedia.bulbagarden.net/wiki/Urshifu_(UNITE)","https://www.dittobase.com/unite/pokemon/urshifu","https://game8.co/games/Pokemon-UNITE/archives/398542","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"high","notes":"Style ditentukan di Lv5 lewat pilihan slot 1 (Wicked Blow = Single Strike, Surging Strikes = Rapid Strike); slot 2 (Lv7) dan Unite mengikuti style. Patch Mei 2026: Wicked Blow bonus damage dari missing HP dinaikin (7-14%) dan Ebon Fist damage tabrakan +50%, jadi Single Strike sedang kuat. Item: Accel Bracer & Drive Lens di-nerf April/Des 2025, tetap ada di game. Counter dari game8; goodAgainst Zeraora adalah inferensi dari mekanik Unseen Fist.","image":"img/urshifu.webp","status":"Owned"},{"name":"Zoroark","slug":"zoroark","role":"Pelari Cepat","damage":"Physical","range":"Melee","difficulty":"Ahli","evolutions":"Zorua (Lv1) → Zoroark (Lv5)","tagline":"Assassin combo-heavy yang nyamar jadi Pokémon lain, lalu ngerantai dash sampai target hilang dari layar.","passive":{"name":"Illusion","desc":"Di luar combat lo berubah wujud jadi wild Pokémon acak atau salah satu Pokémon musuh. Wujudnya buyar begitu lo kena damage, auto, atau pakai move. Gunanya buat ngedeketin musuh tanpa ketahuan (mereka lihat 'Pikachu' di minimap, bukan Zoroark)."},"basicAttack":"Basic attack melee, tiap serangan ketiga jadi boosted yang lebih sakit. Di mode Night Slash, auto lo diganti jadi dash-attack dan boosted attack khusus yang masuk hitungan combo.","lanes":["Jungle"],"laneNote":"Jungle wajib: Zorua lemah dan butuh Lv5 (Night Slash / Feint Attack) secepatnya; dari jungle lo juga bisa manfaatin Illusion buat muncul dari arah yang nggak diduga. Di lane dia cuma beban sampai Lv7.","earlyGame":"Clear jungle pakai Slash + Fury Swipes (Fury Swipes bisa ditekan dua kali kalau kena). Jangan gank sebelum Lv5. Setelah Lv5, cari lane yang musuhnya maju sendirian, masuk pakai Illusion dari belakang, habisin, terus balik farm sampai Lv7 (Shadow Claw / Cut).","powerSpike":"Lv5 (Night Slash / Feint Attack) adalah spike pertama; Lv7 (Shadow Claw / Cut) ngelengkapin combo; Lv9 Nightfall Daze ngasih damage AoE + immune hindrance yang bikin lo bisa nyelesaiin fight.","slot1":{"base":{"name":"Slash","level":1,"desc":"Dash ke arah yang dipilih sambil kasih damage; alat clear dan reposisi awal."},"choices":[{"name":"Shadow Claw","level":7,"upgradeLevel":13,"desc":"Dash yang kasih damage dan bikin musuh nggak bisa bergerak sebentar; di ujung dash, musuh yang kena dilempar.","when":"Tekan buat ngunci target sebelum rantai Night Slash / Feint Attack, atau buat ngehentiin musuh yang mau kabur / lagi channel. Ini satu-satunya CC lo, pakai di awal combo.","avoid":"Jangan buang Shadow Claw buat dash kabur kalau masih ada musuh yang bisa lo kunci; dan jangan dash ke tank kalau carry musuh ada di jangkauan.","upgradeNote":"Lv13: durasi lemparannya lebih lama, jadi window lo buat nge-combo makin lebar."},{"name":"Cut","level":7,"upgradeLevel":13,"desc":"Dash yang kasih damage dan nge-heal HP lo; sustain tool buat bertahan di tengah combo.","when":"Tekan di tengah rantai dash pas HP lo mulai turun, atau buat finishing target yang lari karena cooldown-nya pendek. Enak buat yang suka duel panjang.","avoid":"Jangan simpan Cut buat 'nanti'; cooldown-nya pendek, kalau nggak dipakai lo buang heal gratis. Tapi jangan juga pakai buat masuk pertama kali, nggak ada CC-nya.","upgradeNote":"Lv13: jumlah heal-nya naik (ditambah buff Aug 2026: damage Cut naik juga)."}]},"slot2":{"base":{"name":"Fury Swipes","level":1,"desc":"Dash cakar; kalau kena, bisa ditekan lagi sekali sebelum masuk cooldown."},"choices":[{"name":"Night Slash","level":5,"upgradeLevel":11,"desc":"Masuk mode dash-attack: basic attack lo berubah jadi dash + boosted attack khusus. Setelah 6 hit (dash dan boosted digabung), lo lompat-slash ke target: damage besar + heal. Shadow Claw / Cut masih bisa dipakai di tengah lompatan.","when":"Tekan saat lo udah nempel ke target (idealnya habis Shadow Claw), lalu auto terus tanpa jeda sampai 6 hit biar lompatan keluarnya cepat. Jangan ganti target di tengah hitungan.","avoid":"Jangan aktifin Night Slash dari jauh atau pas target punya escape siap; kalau 6 hit-nya nggak kelar, lo buang move terkuat lo dan jadi sitting duck.","upgradeNote":"Lv11: cooldown-nya turun, jadi lo bisa ngulang mode dash lebih sering dalam satu fight."},{"name":"Feint Attack","level":5,"upgradeLevel":11,"desc":"Dash yang motong semua cooldown move lo dan nandain titik awal; tekan lagi buat balik ke titik itu. Kalau lo nge-hit 4 kali dalam rantai, Feint Attack berubah jadi versi kuat: lompat ke musuh yang lo pilih.","when":"Tekan buat masuk (titik awal jadi 'tali pengaman'), hit 4 kali, pakai versi kuatnya ke carry, lalu tekan lagi buat balik ke titik aman. Cocok buat yang suka main hit-and-run dari semak.","avoid":"Jangan tandain titik awal di tengah tim musuh; kalau lo balik ke situ pas kabur, lo cuma pindah dari masalah ke masalah yang sama.","upgradeNote":"Lv11: cooldown-nya turun, jadi rantai masuk-balik lo lebih rapat."}]},"unite":{"name":"Nightfall Daze","level":9,"desc":"Lo nembakin 3 gelombang kegelapan yang areanya makin melebar, kasih damage besar ke musuh di dalamnya; selama ngeluarin gelombang lo immune hindrance.","when":"Pakai pas 2+ musuh ngumpul di depan lo (objective pit, choke point), atau buat nyelesaiin combo pas carry udah ke-CC. Juga berguna reaktif: tekan pas lihat CC musuh datang, lo immune selama channel.","avoid":"Jangan tekan sendirian dari jauh buat 'poke'; gelombangnya cuma ke arah depan dan lo diem di tempat selama channel, jadi tanpa tim atau tanpa CC duluan, musuh tinggal jalan keluar."},"builds":[{"name":"Night Slash + Shadow Claw — Combo Assassin","moves":["Night Slash","Shadow Claw"],"recommended":true,"style":"Kunci target pakai Shadow Claw, masuk mode Night Slash, 6 hit, lompat-slash, selesai. Damage tertinggi, tapi butuh target yang nggak bisa kabur.","heldItems":[{"name":"Attack Weight","why":"Zoroark gampang score setelah kill di lane musuh; stack Attack cepat penuh."},{"name":"Weakness Policy","why":"Lo bakal dipukul selama rantai 6 hit, jadi Attack bonusnya hampir selalu aktif."},{"name":"Muscle Band","why":"Semua hit Night Slash dihitung sebagai basic attack, jadi damage persen HP-nya ikut tiap hit."}],"battleItem":{"name":"Full Heal","why":"Satu stun di tengah hitungan 6 hit = combo batal; Full Heal nyelametin rantai lo."},"combo":["Dekati target lewat Illusion (lo kelihatan kayak Pokémon lain), dari belakang atau semak.","Shadow Claw ke carry: dia nggak bisa gerak, lalu dilempar.","Night Slash → auto terus sampai 6 hit → lompat-slash (heal). Kalau belum mati, Shadow Claw lagi (bisa ditekan di tengah lompatan) atau Nightfall Daze."],"comboNote":"Hitungan 6 hit itu dash + boosted digabung; jangan jalan kaki di antara hit, biarin dash-attack-nya yang gerak."},{"name":"Feint Attack + Cut — Hit and Run","moves":["Feint Attack","Cut"],"recommended":false,"style":"Masuk dari semak, 4 hit, versi kuat Feint Attack ke carry, Cut buat heal, balik ke titik aman. Lebih aman tapi damage-nya lebih tipis.","heldItems":[{"name":"Razor Claw","why":"Lo pakai move tiap detik; auto bonus + slow-nya bantu rantai 4 hit tetep nempel."},{"name":"Focus Band","why":"Heal pas HP tipis, nambah waktu buat tekan Feint Attack balik."},{"name":"Scope Lens","why":"Crit bonus buat auto dan dash, nambah burst saat hit-and-run."}],"battleItem":{"name":"Eject Button","why":"Jalan keluar kedua kalau titik balik Feint Attack ternyata nggak aman."},"combo":["Feint Attack masuk (titik awal ditandai, cooldown lain kepotong).","Auto + Cut sampai 4 hit → Feint Attack berubah, lompat ke carry musuh.","Auto sampai mati atau HP lo setengah, lalu tekan Feint Attack buat balik ke titik awal."],"comboNote":"Pastikan titik awal lo ada di semak atau di belakang tembok."}],"situations":{"gank":"Saat nge-gank: jalan pakai Illusion dari belakang musuh, Shadow Claw ke carry, Night Slash sampai lompat. Saat dikeroyok: jangan paksa rantai; Cut / lompatan Night Slash buat heal, Nightfall Daze buat immune hindrance, lalu dash keluar.","escape":"Feint Attack balik ke titik awal (kalau pakai), atau Shadow Claw / Cut buat dash lewatin dinding tipis. Nightfall Daze bikin lo immune hindrance selama channel: bisa dipakai buat nahan stun sambil tim lo dateng. Setelah lepas, Illusion bakal nyamarin lo lagi kalau lo nggak kena damage beberapa detik.","objective":"Di Rayquaza / Regieleki: tunggu di semak dengan wujud Illusion. Begitu carry musuh maju buat last-hit, Shadow Claw + Night Slash ke dia. Nightfall Daze buat damage AoE ke yang ngumpul di pit atau buat steal kalau lo tau timing-nya; lompat-slash Night Slash juga bisa nge-secure.","duel":"1v1 lo menang lawan hampir semua squishy: Shadow Claw → Night Slash 6 hit → lompat (heal). Lawan Pokémon dengan escape (Greninja, Absol) tahan Shadow Claw sampai mereka buang dash-nya. Lawan tank jangan duel lama, nggak worth.","teamfight":"Masuk TERAKHIR. Biarin tank lo dan CC musuh keluar dulu, baru lo muncul dari sisi ke Attacker/Supporter mereka. Satu target, satu combo penuh, keluar. Nightfall Daze pas 2-3 musuh ngumpul dan lo udah aman dari CC."},"mistakes":["Masuk fight sebelum Lv5 atau sebelum CC musuh keluar; satu stun di tengah Night Slash dan lo mati.","Ganti target di tengah hitungan 6 hit Night Slash, jadi lompatan (dan heal-nya) nggak pernah keluar.","Pakai Shadow Claw buat kabur padahal itu satu-satunya CC lo buat nge-setup combo.","Buyarin Illusion sendiri dengan auto ke wild Pokémon pas lagi ngendap-endap ke lane musuh.","Nightfall Daze dari jauh tanpa setup; musuh tinggal jalan keluar dari gelombangnya."],"counters":{"hardFor":[{"name":"Snorlax","why":"Block + Yawn / Heavy Slam ngunci lo di tengah combo, dan lo nggak bisa nembus HP-nya.","how":"Jangan target dia; tunggu Yawn keluar, Shadow Claw lewatin ke carry di belakangnya. Full Heal wajib."},{"name":"Greninja","why":"Smokescreen + Double Team bikin dia lepas dari Shadow Claw dan hitungan Night Slash lo putus.","how":"Pancing dia buang Smokescreen dulu (masuk pakai Cut / Fury), baru Shadow Claw dan Night Slash."},{"name":"Mimikyu","why":"Disguise nyerap combo pertama lo, Play Rough ngunci lo balik, dan dia sustain.","how":"Jangan duel; hit sekali pakai Illusion dari belakang buat buyarin Disguise, lalu pergi dan balik lagi nanti."},{"name":"Blastoise","why":"Surf / Hydro Pump multi-CC dan HP tebal; combo lo nggak kelar sebelum dia ngelempar lo.","how":"Masuk dari sisi jauh dari dia, atau tekan Nightfall Daze buat immune pas Surf keluar."}],"goodAgainst":[{"name":"Pikachu","why":"HP tipis, tanpa dash; Shadow Claw + Night Slash kelar sebelum dia bisa bales."},{"name":"Decidueye","why":"Attacker ranged tanpa escape, sering sendirian di belakang; target ideal Illusion."},{"name":"Eldegoss","why":"Supporter rapuh yang ngandelin posisi; Shadow Claw dari semak langsung misahin dia dari tim."}]},"cinderace":{"similarity":3,"note":"Hampir kebalikan Cinderace: Cinderace nunggu dan nembak, Zoroark ngendap, masuk, dan harus nyelesaiin combo tanpa putus. Yang bisa lo bawa: insting target carry musuh dan sabar nunggu CC lawan keluar (di Cinderace lo nunggu buat Feint, di sini lo nunggu buat masuk). Yang harus diubah: lo nggak boleh 'auto sambil mundur' di mode Night Slash; sekali mulai, nempel terus sampai 6 hit, karena heal-nya ada di lompatan terakhir."},"sources":["https://www.serebii.net/pokemonunite/pokemon/zoroark.shtml","https://bulbapedia.bulbagarden.net/wiki/Zoroark_(UNITE)","https://www.dittobase.com/unite/pokemon/zoroark","https://gamewith.net/pokemon-unite/article/show/35789","https://www.pokemonunite.jp/en/topics/battle/20260415-1/","https://www.pokemonunite.jp/en/topics/battle/20260805-1/"],"confidence":"high","notes":"Urutan slot: Lv5 = Night Slash / Feint Attack (dari Fury Swipes), Lv7 = Shadow Claw / Cut (dari Slash); gamewith dan Bulbapedia sepakat, Serebii nulis kebalik (Shadow Claw Lv5) dan 'Night Slash upgrade L9' yang kayaknya typo. Upgrade: Night Slash / Feint Attack Lv11, Shadow Claw / Cut Lv13 (Bulbapedia + dittobase). Buff beruntun: Apr 2026 (Shadow Claw damage, lompatan Night Slash damage + heal, energi ult turun) dan Aug 2026 (HP/Def/SpDef naik, lemparan Shadow Claw lebih lama, cooldown Night Slash turun, damage Cut naik); Sep 2026 cuma bug fix exploit score saat Night Slash. Counter adalah inferensi mekanik, bukan tabel counter resmi.","image":"img/zoroark.webp","status":"Owned"},{"name":"Blissey","slug":"blissey","role":"Suporter","damage":"Special","range":"Melee","difficulty":"Pemula","evolutions":"Chansey (Lv1) → Blissey (Lv4)","tagline":"Perawat tim yang tebal: heal, buang CC dari carry, dan kasih shield + Attack lewat Unite.","passive":{"name":"Natural Cure","desc":"Otomatis ngilangin semua status/CC dari diri lo sendiri, lalu masuk cooldown. Artinya lo susah di-lock, tapi jangan andelin dua kali berturut-turut."},"basicAttack":"Melee. Boosted attack keluar tiap beberapa serangan (interval waktu, bukan hitungan ke-3) dan damage-nya lebih gede. Saat Helping Hand aktif semua basic attack lo jadi boosted.","lanes":["Bottom","Top"],"laneNote":"Bottom paling ideal karena lo nemenin carry (Attacker/All-Rounder) dari awal; Blissey hampir gak bisa farm sendiri jadi jangan jungle.","earlyGame":"Biarin carry lo ambil last hit, lo cukup Pound buat slow dan nemenin. Lv4 ambil Soft-Boiled/Safeguard langsung, itu spike pertama lo. Fight cuma kalau carry lo ikut, kalau sendirian mundur ke goal.","powerSpike":"Lv4 (evolusi + heal/cleanse) dan Lv6 (Egg Bomb/Helping Hand). Lv8 Unite move bikin carry lo jadi monster sesaat.","slot1":{"base":{"name":"Pound","level":1,"desc":"Pukul ke arah tertentu, damage area kecil + slow."},"choices":[{"name":"Egg Bomb","level":6,"upgradeLevel":12,"desc":"Lempar telur ke lokasi, meledak, damage area + lempar lawan. Bisa nyimpen 2 charge (berbagi charge dengan Soft-Boiled kalau lo pakai keduanya, jadi total 4).","when":"Buat matahin combo lawan (misal Buzzwole/Garchomp lagi masuk), buat ngelempar lawan dari goal lo, atau buat secure objective karena damage-nya lumayan.","avoid":"Jangan lempar sembarangan sampai charge habis, karena charge itu juga jatah heal Soft-Boiled lo.","upgradeNote":"Lv12: lawan yang kena ledakan juga di-slow."},{"name":"Helping Hand","level":6,"upgradeLevel":12,"desc":"Lo dan ally di sekitar dapet movement speed + attack speed besar sebentar, dan semua basic attack lo jadi boosted.","when":"Tekan pas carry basic-attack (Cinderace, Zacian, Dodrio) mau mulai fight, atau buat kejar/kabur rame-rame.","avoid":"Jangan tekan pas ally jauh di luar jangkauan, buff-nya cuma buat lo sendiri.","upgradeNote":"Lv12: damage basic attack ally juga naik selama buff."}]},"slot2":{"base":{"name":"Heal Pulse","level":1,"desc":"Nyembuhin HP lo dan satu ally yang dipilih secara bertahap."},"choices":[{"name":"Soft-Boiled","level":4,"upgradeLevel":10,"desc":"Lempar telur ke ally, nyembuhin dia dan lo. Bisa nyimpen 2 charge (4 kalau dipasangin Egg Bomb, charge-nya dibagi).","when":"Pas carry turun ke sekitar setengah HP di tengah fight, bukan pas udah hampir mati. Dua charge beruntun kalau dia difokus.","avoid":"Jangan buang semua charge ke ally yang cuma lecet di luar fight.","upgradeNote":"Lv10: jumlah charge maksimal nambah."},{"name":"Safeguard","level":4,"upgradeLevel":10,"desc":"Ngilangin semua status/CC dari lo dan ally yang dipilih, lalu keduanya dapet shield.","when":"Tekan PAS ally kena stun/freeze/sleep, atau sedetik sebelum CC lawan yang lo udah tau bakal dateng (Unite Slowbro, Hypnosis).","avoid":"Jangan tekan cuma buat shield doang pas gak ada ancaman CC, timing-nya sayang.","upgradeNote":"Lv10: shield-nya lebih tebal."}]},"unite":{"name":"Bliss Assistance","level":8,"desc":"Lo dash ke ally yang dipilih, kasih telur: dia dapet shield + Attack & Sp. Atk naik sebentar, dan sebagian damage yang dia terima dialihin ke lo.","when":"Pas carry lo mau all-in atau lagi difokus di objective fight; juga bisa dipakai buat nyusul ally yang jauh.","avoid":"Jangan kasih ke ally yang udah mau mati di tengah 5 lawan, lo ikut mati karena nyerap damage dia."},"builds":[{"name":"Soft-Boiled + Egg Bomb — Double Egg","moves":["Soft-Boiled","Egg Bomb"],"recommended":true,"style":"Support fleksibel: 4 charge yang bisa jadi heal atau CC sesuai kebutuhan.","heldItems":[{"name":"Exp. Share","why":"Carry lo level lebih cepet, lo gak perlu farm."},{"name":"Buddy Barrier","why":"Shield buat lo dan ally pas Unite, nambah value Bliss Assistance."},{"name":"Energy Amplifier","why":"Unite lebih sering dan lebih kuat; alternatif Sp. Atk. Specs (game8) atau Focus Band."}],"battleItem":{"name":"X Speed","why":"Blissey lambat; butuh buat nyusul ally atau kabur."},"combo":["Egg Bomb ke lawan yang mau masuk (lempar + damage)","Soft-Boiled ke carry pas HP-nya turun","Bliss Assistance ke carry pas dia mau all-in","Egg Bomb lagi buat matahin lawan yang ngejar"],"comboNote":"Charge Egg Bomb & Soft-Boiled dibagi (total 4). Selalu sisain minimal 1 buat heal."},{"name":"Safeguard + Helping Hand — Anti-CC Buffer","moves":["Safeguard","Helping Hand"],"recommended":false,"style":"Nempel ke carry basic-attack, buang CC lawan dan kasih attack speed.","heldItems":[{"name":"Exp. Share","why":"Standar support, carry cepet level."},{"name":"Focus Band","why":"Lo bakal nyerap damage buat carry, butuh sustain."},{"name":"Buddy Barrier","why":"Shield tim pas Unite."}],"battleItem":{"name":"X Speed","why":"Nyusul carry yang gesit; Slow Smoke juga oke buat peel."},"combo":["Helping Hand pas carry mulai fight","Safeguard ke carry pas dia kena CC","Bliss Assistance pas carry udah di tengah lawan","Basic attack boosted buat nambah damage kecil"],"comboNote":"Build ini paling enak dengan Cinderace, Zacian, Dodrio, atau Dragapult."}],"situations":{"gank":"Kalau tim lo nge-gank: Egg Bomb buat lempar target ke arah tim, Helping Hand buat ngejar. Kalau lo dikeroyok: Safeguard/Natural Cure buang CC, Egg Bomb ke jalur mereka, jalan ke goal.","escape":"Lo pelan dan gak punya dash kecuali Unite. X Speed, Egg Bomb buat lempar pengejar, atau Bliss Assistance ke ally terdekat buat dash kabur.","objective":"Berdiri di belakang carry, bukan di depan. Simpan Safeguard buat carry yang mau last hit, Egg Bomb buat ngelempar lawan yang mau secure, Unite ke carry pas Rayquaza hampir mati.","duel":"Hindari. Lo gak punya damage buat bunuh siapa pun. Kalau terpaksa: Egg Bomb terus slow Pound/basic, lalu jalan ke goal.","teamfight":"Nempel ke carry utama (jarak 1-2 body). Prioritas: heal/cleanse carry > shield lewat Unite > CC lawan yang masuk. Jangan ngejar kill."},"mistakes":["Jalan di depan tim seolah-olah tank; Blissey tebal tapi gak punya CC area buat ngelindungin diri.","Buang 4 charge telur buat damage, lalu gak punya heal pas carry butuh.","Safeguard dipakai telat (setelah ally udah mati) atau terlalu awal (shield doang).","Bliss Assistance ke ally yang salah (yang lagi kabur atau yang udah pasti mati)."],"counters":{"hardFor":[{"name":"Delphox","why":"Burst special dari jarak jauh, Blissey gak bisa bales dan heal gak ngejar.","how":"Jaga jarak di belakang carry, Egg Bomb pas dia Fire Spin."},{"name":"Zacian","why":"Nembus ke backline dan bunuh carry sebelum Soft-Boiled keluar.","how":"Safeguard pas dia masuk, Unite ke carry buat nyerap damage."},{"name":"Zoroark","why":"Ngejar lo yang pelan dan combo-nya cepet.","how":"Egg Bomb buat lempar pas dia mendarat, Natural Cure bantu lo gak di-lock."}],"goodAgainst":[{"name":"Buzzwole","why":"Combo Lunge-nya kebuka oleh Egg Bomb dan Safeguard cleanse ally yang kena Leech Life."},{"name":"Gengar","why":"Safeguard ngilangin poison/sleep dari Hex combo, dan Unite shield bikin carry survive."},{"name":"Garchomp","why":"Dig/Dragon Rush gampang dipatahin lemparan Egg Bomb."}]},"cinderace":{"similarity":2,"note":"Beda total: lo gak lagi jadi yang bunuh, lo jadi yang bikin orang lain bunuh. Bawa dari Cinderace: insting ngeliat siapa carry lawan dan kapan fight mulai. Ubah: fokus layar ke HP bar ally bukan ke lawan, dan posisi di belakang carry bukan di sayap."},"sources":["https://serebii.net/pokemonunite/pokemon/blissey.shtml","https://bulbapedia.bulbagarden.net/wiki/Blissey_(UNITE)","https://www.dittobase.com/unite/pokemon/blissey","https://game8.co/games/Pokemon-UNITE/archives/340261","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"high","notes":"Level choice: Bulbapedia/dittobase/game8 sepakat Soft-Boiled/Safeguard Lv4 dan Egg Bomb/Helping Hand Lv6 (ringkasan Serebii kebalik). Damage type Special (dittobase/Bulbapedia); Serebii nyebut physical, diabaikan. Difficulty: Serebii 'Novice', Bulbapedia/dittobase 'Intermediate'. Nerf Feb & Mei 2025 (Helping Hand cooldown, Safeguard shield, Bliss Assistance), buff Okt 2025 (detail tidak terverifikasi). Counter dari game8.","image":"img/blissey.webp","status":"Owned"},{"name":"Clefable","slug":"clefable","role":"Suporter","damage":"Special","range":"Melee","difficulty":"Pemula","evolutions":"Clefairy (Lv1) → Clefable (Lv4)","tagline":"Healer area yang dapet shield tiap nyembuhin, plus Gravity buat matiin dash lawan.","passive":{"name":"Magic Guard","desc":"Tiap kali lo nyembuhin HP ally, lo dapet shield sebanding dengan jumlah heal-nya. Jadi makin rajin heal, makin tebal lo sendiri."},"basicAttack":"Melee. Serangan ke-3 jadi boosted dengan damage lebih gede (boosted-nya dihitung special). Jarang jadi andalan, lebih buat last hit dan nambah Sp. Atk procs.","lanes":["Bottom","Top"],"laneNote":"Bottom paling cocok karena Clefable butuh nempel ke carry buat heal area; jangan jungle.","earlyGame":"Nemenin carry, Heal Pulse buat nyembuhin keduanya setelah trade, Disarming Voice buat slow lawan yang maju. Lv4 ambil Moonlight/Draining Kiss; mulai bisa trade lebih berani karena shield dari Magic Guard.","powerSpike":"Lv4 (evolusi + heal utama) dan Lv6 (Gravity/Follow Me). Lv8 Wonder Wish nyembuhin tim besar dan kasih move acak.","slot1":{"base":{"name":"Heal Pulse","level":1,"desc":"Langsung nyembuhin HP lo dan ally di sekitar."},"choices":[{"name":"Moonlight","level":4,"upgradeLevel":10,"desc":"Nyembuhin HP lo dan ally di sekitar secara terus-menerus sebentar, sambil nambah movement speed.","when":"Tekan pas 2+ ally lagi trade damage di dekat lo, atau buat ngejar/kabur bareng karena ada speed.","avoid":"Jangan tekan pas ally lagi jauh dari lo, heal-nya cuma buat diri sendiri.","upgradeNote":"Lv10: efek heal/speed ditingkatkan."},{"name":"Draining Kiss","level":4,"upgradeLevel":10,"desc":"Damage ke lawan di depan, dan hati yang muncul terbang buat nyembuhin ally terdekat yang HP-nya paling rendah.","when":"Pas lo bisa kena lawan DAN ada ally yang butuh heal; ini heal yang harus kena musuh dulu.","avoid":"Jangan maju sendirian cuma buat ngejar heal-nya, Clefable gak punya escape.","upgradeNote":"Lv10: efek ditingkatkan (heal/damage)."}]},"slot2":{"base":{"name":"Disarming Voice","level":1,"desc":"Damage area di sekitar lo + slow lawan."},"choices":[{"name":"Gravity","level":6,"upgradeLevel":12,"desc":"Bikin zona yang bikin lawan di dalamnya lambat dan GAK BISA dash/lompat. Juga nurunin efek move mobilitas mereka.","when":"Taruh di atas Rayquaza pit atau di goal lo pas lawan mau masuk; atau di atas Zeraora/Talonflame/Greninja yang mau kabur.","avoid":"Jangan taruh di belakang lawan yang udah lewat, dan jangan buang sebelum lawan commit masuk.","upgradeNote":"Lv12: efek zona ditingkatkan (durasi/slow). Start-up Gravity dipercepat di patch Juli 2026."},{"name":"Follow Me","level":6,"upgradeLevel":12,"desc":"Taunt: lawan di sekitar dipaksa nyerang lo, dan lo dapet shield.","when":"Pas carry lo difokus: tekan supaya semua serangan pindah ke lo yang punya shield.","avoid":"Jangan taunt pas HP lo udah tipis dan gak ada heal ready, lo bakal mati sia-sia.","upgradeNote":"Lv12: shield/taunt ditingkatkan."}]},"unite":{"name":"Wonder Wish","level":8,"desc":"Nyembuhin HP ally di area; makin rendah HP ally, makin gede heal-nya. Setelah itu lo dapet satu move acak (Metronome) buat dipakai: bisa Fly, Hydro Pump, Hyper Beam, Explosion, Close Combat, Block, atau Splash.","when":"Pas 2-3 ally HP-nya rendah di tengah objective fight; heal-nya skala dengan HP yang hilang jadi makin telat makin gede, tapi jangan sampai ada yang mati dulu.","avoid":"Jangan pakai cuma buat dapet move acak; dan hati-hati Explosion yang ngabisin HP lo sendiri."},"builds":[{"name":"Moonlight + Gravity — Full Support","moves":["Moonlight","Gravity"],"recommended":true,"style":"Nempel ke tim, heal terus, Gravity buat ngunci lawan di objective.","heldItems":[{"name":"Exp. Share","why":"Carry level duluan, lo gak perlu farm."},{"name":"Energy Amplifier","why":"Wonder Wish lebih sering, dan dittobase/game8 sama-sama rekomen."},{"name":"Buddy Barrier","why":"Shield tim pas Unite; alternatif Sp. Atk. Specs (dittobase) buat heal lebih gede."}],"battleItem":{"name":"X Speed","why":"Clefable pelan dan gak punya dash."},"combo":["Gravity di jalur masuk lawan / di objective","Moonlight pas ally mulai trade (speed + heal)","Basic attack boosted ke lawan yang kejebak di Gravity","Wonder Wish pas tim HP rendah, lalu pakai move acaknya (Block buat halangin, Hyper Beam buat secure)"],"comboNote":"Shield dari Magic Guard muncul tiap Moonlight tick, jadi lo surprisingly tebal."},{"name":"Draining Kiss + Follow Me — Frontline Kiss","moves":["Draining Kiss","Follow Me"],"recommended":false,"style":"Support agresif yang ikut ngasih damage dan narik aggro dari carry.","heldItems":[{"name":"Energy Amplifier","why":"Unite lebih sering."},{"name":"Shell Bell","why":"Draining Kiss sering dipakai, Shell Bell nyembuhin lo tiap move kena."},{"name":"Slick Spoon","why":"Nembus Sp. Def, damage Draining Kiss naik; alternatif Drive Lens (dittobase)."}],"battleItem":{"name":"Eject Button","why":"Satu-satunya escape lo setelah Follow Me habis."},"combo":["Follow Me pas carry difokus (taunt + shield)","Draining Kiss ke lawan yang nyerang lo (heal ke ally terendah)","Basic attack boosted","Wonder Wish pas HP tim rendah"],"comboNote":"Draining Kiss damage-nya di-nerf Feb 2025 tapi heal-nya dinaikin; build ini lebih tanky daripada bursty."}],"situations":{"gank":"Kalau tim lo gank: Gravity di jalur kabur target supaya dia gak bisa dash. Kalau lo digank: Follow Me/shield, Moonlight buat speed, jalan ke goal.","escape":"Gak ada dash. Moonlight buat speed, Gravity di belakang lo supaya pengejar gak bisa dash, X Speed/Eject Button.","objective":"Gravity di atas pit sebelum last-hit war: lawan yang masuk gak bisa dash keluar/masuk. Moonlight buat tim yang nge-DPS, Wonder Wish pas HP tim rendah.","duel":"Hindari; damage lo kecil. Kalau terpaksa, Disarming Voice/Gravity buat slow lalu jalan ke tower.","teamfight":"Posisi di tengah tim (bukan depan, bukan belakang) supaya heal area kena semua. Prioritas: Gravity ke lawan mobile yang masuk, heal pas 2+ ally turun HP, Unite pas HP tim rendah."},"mistakes":["Buang Gravity sebelum lawan commit, lalu Zeraora/Talonflame lewat bebas.","Berdiri terlalu jauh dari tim; semua heal Clefable area kecil di sekitar lo.","Pakai Wonder Wish pas tim masih full HP, heal-nya kecil.","Dapet Explosion dari Wonder Wish dan nekan di posisi HP tipis."],"counters":{"hardFor":[{"name":"Glaceon","why":"Burst special dari jauh ngelewatin heal lo dan dia gak butuh dash buat kabur.","how":"Jaga carry di belakang tank, Follow Me pas dia buang Icicle Spear."},{"name":"Zacian","why":"Damage-nya ngelebihin heal rate lo dan dia nembus ke carry.","how":"Gravity pas dia masuk (Agility kebatalin), Follow Me buat narik aggro."},{"name":"Leafeon","why":"Cepet, burst, dan bisa ngabisin carry sebelum Moonlight tick.","how":"Gravity di sekitar carry; dia kehilangan Aerial Ace/Leaf Blade dash."}],"goodAgainst":[{"name":"Greninja","why":"Gravity matiin Double Team dan Smokescreen jump, dia jadi sitting duck."},{"name":"Zeraora","why":"Volt Switch dan Spark gak jalan di Gravity."},{"name":"Talonflame","why":"Fly dan Brave Bird kebatalin di zona Gravity."}]},"cinderace":{"similarity":2,"note":"Jauh dari Cinderace: melee, pelan, gak punya dash. Bawa dari Cinderace: insting lawan mobile mana yang bakal dash ke carry lo, itu target Gravity. Ubah: lo harus berdiri DI DALAM tim, bukan kiting di pinggir, dan ukuran sukses lo adalah HP bar ally."},"sources":["https://serebii.net/pokemonunite/pokemon/clefable.shtml","https://bulbapedia.bulbagarden.net/wiki/Clefable_(UNITE)","https://www.dittobase.com/unite/pokemon/clefable","https://game8.co/games/Pokemon-UNITE/archives/393362","https://www.pokemonunite.jp/en/topics/battle/20260715-1/"],"confidence":"medium","notes":"Level Unite: Serebii, dittobase, game8 bilang Lv8; Bulbapedia bilang Lv9 — dipakai Lv8. Detail efek upgrade Lv10/12 (Moonlight+, Draining Kiss+, Gravity+, Follow Me+) gak dijabarkan sumber, ditulis umum. Daftar move acak Wonder Wish dari Bulbapedia saja (Splash, Explosion, Hydro Pump, Hyper Beam, Block, Close Combat, Fly) — belum dikonfirmasi sumber ke-2. Patch: Draining Kiss damage turun/heal naik (Feb 2025), Moonlight cooldown bolak-balik (Apr/Mei 2025), Wonder Wish heal naik (Mei 2025), nerf Okt 2025 (detail gak dikonfirmasi), Gravity start-up dipercepat (Juli 2026). Counter dari game8.","image":"img/clefable.webp","status":"Owned"},{"name":"Comfey","slug":"comfey","role":"Suporter","damage":"Special","range":"Ranged","difficulty":"Pemula","evolutions":"Comfey (tidak berevolusi)","tagline":"Support yang nempel ke carry: lo jadi 'item hidup' yang heal, shield, dan CC dari punggung temen tanpa bisa ditarget.","passive":{"name":"Triage","desc":"Lo ngumpulin bunga (1 tiap beberapa detik, +4 pas masuk grass, maks 8); bunga dipakai buat nguatin move heal/CC. Lo bisa NEMPEL ke ally lewat move slot 1: selama nempel lo gak bisa ditarget/kena damage, HP lo pulih pelan, energy berlebih ally pindah ke lo, dan pas ally score lo ikut score jumlah yang sama. Lepas nempel dengan tombol release (Switch: D-pad bawah). Nempel otomatis putus kalau ally mati. Lo juga lebih cepet pas deket ally yang HP-nya di bawah setengah."},"basicAttack":"Ranged. Serangan ke-3 jadi boosted: damage + lo dapet 2 bunga. Pas nempel lo tetep bisa basic attack dari posisi ally.","lanes":["Bottom","Top"],"laneNote":"Lane mana pun yang punya carry yang suka fight panjang (All-Rounder/Speedster melee). Comfey sendirian gak berguna, jadi jangan jungle.","earlyGame":"Masuk grass dulu buat 4 bunga, lalu nempel ke carry pas dia mulai trade. Synthesis buat heal/shield, Vine Whip buat slow lawan yang maju. Kalau carry mau score, tetep nempel: lo ikut score.","powerSpike":"Lv4 (Floral Healing/Sweet Kiss) dan Lv6 (Magical Leaf/Grass Knot). Lv8 Flowery Fields Forever bikin tim lo heal + invisible di grass raksasa.","slot1":{"base":{"name":"Synthesis","level":1,"desc":"Nempel ke ally; heal + shield ke ally sesuai jumlah bunga yang dipakai."},"choices":[{"name":"Floral Healing","level":4,"upgradeLevel":10,"desc":"Nempel ke ally dan nyembuhin dia; makin banyak bunga makin gede heal-nya, dan heal berlebih jadi shield.","when":"Simpan sampai 6-8 bunga lalu tekan pas carry turun ke sekitar setengah HP; heal berlebih jadi shield jadi gak rugi walau HP-nya belum rendah banget.","avoid":"Jangan spam pas bunga 0-1, heal-nya kecil dan cooldown kebuang.","upgradeNote":"Lv10: ally juga dapet movement speed setelah di-heal."},{"name":"Sweet Kiss","level":4,"upgradeLevel":10,"desc":"Nempel ke ally lalu charge; pas dilepas, lawan di sekitar ally kena infatuate (jalan pelan ke arah lo, gak bisa nyerang) dengan durasi sesuai bunga yang dipakai, plus shield ke ally.","when":"Pas carry melee lo udah di tengah lawan: charge dengan bunga banyak, lepas pas 2+ lawan di jangkauan.","avoid":"Jangan lepas dengan bunga sedikit; sejak nerf Juni 2026 durasi dasarnya pendek banget, bunga yang bikin lama.","upgradeNote":"Lv10: ally dapet movement speed selama lo charge."}]},"slot2":{"base":{"name":"Vine Whip","level":1,"desc":"Cambuk ke arah tertentu, damage + slow."},"choices":[{"name":"Magical Leaf","level":6,"upgradeLevel":12,"desc":"Nembakin 3 daun per detik otomatis ke lawan terdekat selama beberapa detik; setelah 6 daun kena target yang sama, dia kena stun.","when":"Tekan pas lawan nempel ke carry lo (daun nyari target terdekat), terutama 1v1 supaya semua daun ke satu orang dan stun cepat.","avoid":"Jangan tekan pas banyak minion/wild di sekitar, daun kebuang ke target yang salah.","upgradeNote":"Lv12: 4 daun per detik, stun lebih cepet."},{"name":"Grass Knot","level":6,"upgradeLevel":12,"desc":"Tanaman menjalar ke arah tertentu, damage + bikin lawan gak bisa gerak; kena sampai 2 lawan, dan lawan ke-2 ditarik ke posisi lawan ke-1.","when":"Buat ngunci lawan yang mau kabur atau nyatuin 2 lawan buat AoE carry lo; di objective buat nahan lawan yang mau secure.","avoid":"Jangan tembak lurus ke lawan yang masih punya dash, dia bakal lewat.","upgradeNote":"Lv12: area efek lebih lebar."}]},"unite":{"name":"Flowery Fields Forever","level":8,"desc":"Bikin grass raksasa di sekitar lo: ally di dalam heal terus dan gak kelihatan lawan; lo dapet bunga spesial yang nguatin Floral Healing/Sweet Kiss.","when":"Pas teamfight di objective: tim lo jadi invisible + heal, lawan bingung, dan lo bisa support terus tanpa harus lepas nempel.","avoid":"Jangan pakai pas tim lo udah bubar atau buat heal diri sendiri doang."},"builds":[{"name":"Floral Healing + Grass Knot — Healer Lock","moves":["Floral Healing","Grass Knot"],"recommended":true,"style":"Nempel ke frontliner, heal gede pas HP turun, Grass Knot buat ngunci target dia.","heldItems":[{"name":"Exp. Share","why":"Carry lo level duluan; lo tetep dapet exp."},{"name":"Buddy Barrier","why":"Shield ke lo dan ally pas Unite."},{"name":"Resonant Guard","why":"Shield tambahan buat ally di sekitar; alternatif Rescue Hood (game8, dibuff Juli 2026) buat heal lebih gede."}],"battleItem":{"name":"Slow Smoke","why":"Peel buat carry lo; semua sumber sepakat."},"combo":["Masuk grass buat 4 bunga, nempel (Synthesis/Floral Healing) ke carry","Carry masuk fight, lo basic attack buat nambah bunga","Grass Knot ke target carry (lock, tarik target ke-2)","Floral Healing pas carry turun HP (bunga banyak)","Flowery Fields Forever pas fight panjang"],"comboNote":"Grass Knot di-nerf Sep 2025 (cooldown, damage 2 target) tapi lock-nya tetep bagus."},{"name":"Sweet Kiss + Magical Leaf — Disabler","moves":["Sweet Kiss","Magical Leaf"],"recommended":false,"style":"Nempel ke melee carry dan jadi mesin CC: infatuate rombongan, stun lewat daun.","heldItems":[{"name":"Exp. Share","why":"Standar support."},{"name":"Wise Glasses","why":"Magical Leaf damage-nya scaling Sp. Atk."},{"name":"Slick Spoon","why":"Nembus Sp. Def buat daun; alternatif Buddy Barrier kalau butuh survival tim."}],"battleItem":{"name":"Slow Smoke","why":"Tambahan slow buat ngejar/peel."},"combo":["Nempel ke carry melee (Urshifu, Tsareena, Machamp)","Magical Leaf pas lawan deket carry (6 daun = stun)","Sweet Kiss charge dengan bunga banyak, lepas pas 2+ lawan dekat","Carry lo bebas pukul lawan yang infatuated"],"comboNote":"Sweet Kiss di-nerf Juni 2026 (cooldown naik, durasi dasar turun), jadi bunga jadi lebih penting."}],"situations":{"gank":"Lo ikut gank secara otomatis karena nempel ke carry. Pas ketemu target: Grass Knot/Magical Leaf dulu buat lock, Floral Healing kalau carry mulai turun.","escape":"Kalau nempel: lo aman selama ally hidup. Kalau lepas/ally mati: lari ke grass (Prankster-nya gak ada, tapi lo dapet 4 bunga), Vine Whip/Grass Knot buat slow pengejar, lalu nempel ke ally terdekat.","objective":"Nempel ke tank/All-Rounder yang masuk pit. Simpan bunga 6-8 sebelum fight. Grass Knot ke lawan yang mau last hit, Floral Healing ke carry yang nge-DPS, Unite pas fight pecah supaya tim invisible di pit.","duel":"Hindari. Comfey sendirian gak punya damage buat bunuh; nempel ke ally atau kabur.","teamfight":"Lo ada di mana carry lo ada. Prioritas: lock lawan yang nyerang carry > heal carry > pindah nempel ke ally lain yang lebih butuh (lepas lalu nempel lagi)."},"mistakes":["Nempel terus ke satu ally yang lagi back/farm, padahal ally lain lagi fight.","Buang Floral Healing/Sweet Kiss pas bunga 0-2.","Nempel ke Attacker ranged yang berdiri jauh; CC lo gak nyampe ke lawan.","Lupa lepas pas ally mau mati, lalu lo ikut mati di tengah lawan setelah dia tumbang."],"counters":{"hardFor":[{"name":"Darkrai","why":"Bisa one-shot carry yang lo tempelin, dan sleep ngelewatin heal lo.","how":"Nempel ke frontliner yang lebih tanky, Grass Knot pas dia mendekat."},{"name":"Zacian","why":"Burst-nya ngelebihin heal rate, dan dia nembus ke host lo.","how":"Floral Healing dengan 8 bunga tepat sebelum dia Sacred Sword, Grass Knot buat lock dia."},{"name":"Pikachu","why":"Damage area + stun bikin host lo mati sebelum lo sempet heal.","how":"Jauhin host dari Thunder; Magical Leaf buat stun Pikachu yang diem channel."}],"goodAgainst":[{"name":"Machamp","why":"Carry lo bisa tahan combo-nya pakai shield/heal lo, dan Grass Knot ngehentiin Submission-nya."},{"name":"Tsareena","why":"Melee yang butuh waktu buat bunuh; Sweet Kiss + Magical Leaf stun bikin dia gak pernah nyelesaiin combo (inferensi dari mekanik)."}]},"cinderace":{"similarity":2,"note":"Komplet beda: lo gak jalan sendiri, lo nebeng carry. Bawa dari Cinderace: ritme basic attack ke-3 (boosted = bunga) dan feel ranged. Ubah: layar lo fokus ke HP host dan jumlah bunga, bukan ke posisi lo sendiri; dan lo pilih SIAPA yang lo tempelin seperti Cinderace milih target."},"sources":["https://serebii.net/pokemonunite/pokemon/comfey.shtml","https://bulbapedia.bulbagarden.net/wiki/Comfey_(UNITE)","https://www.dittobase.com/unite/pokemon/comfey","https://game8.co/games/Pokemon-UNITE/archives/403757","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"high","notes":"Level: Floral Healing/Sweet Kiss Lv4 (up 10), Magical Leaf/Grass Knot Lv6 (up 12), Unite Lv8 — konsisten antar Serebii, Bulbapedia, dittobase (dittobase nulis 'Lv 88' typo). Nempel: Synthesis/Floral Healing/Sweet Kiss semuanya nempel; lepas manual lewat tombol release; putus otomatis kalau host mati atau pakai move tertentu (game8 nyebut Illusion Zoroark). Nerf Juni 2026: Sweet Kiss cooldown 6→7 dan durasi dasar infatuate turun; nerf Sep 2025: Grass Knot & shield Floral/Sweet. Buff Jan 2026 (detail gak dikonfirmasi). Counter hardFor dari game8 (game8 nyebut Zacian di dua sisi; dipakai di hardFor); goodAgainst sebagian inferensi.","image":"img/comfey.webp","status":"Owned"},{"name":"Goodra","slug":"goodra","role":"Defender","damage":"Special","range":"Melee","difficulty":"Menengah","evolutions":"Goomy (Lv1) → Sliggoo (Lv5) → Goodra (Lv8)","tagline":"Tank lendir yang bikin musuh lambat dan lemah: nempel, slow mereka pakai Gooey, lalu heal lewat Dragon Pulse atau nurunin damage mereka pakai Muddy Water.","passive":{"name":"Gooey","desc":"Tiap lo kena serangan, ada peluang lendir nyebar di sekitar lo: damage kecil dan slow yang numpuk sampai empat kali. Lo juga heal pelan saat masuk ke tall grass (ada cooldown). Makin lo dipukul, makin lambat musuh di sekitar lo."},"basicAttack":"Basic attack melee; tiap serangan ketiga jadi boosted yang nge-slow dan lempar lendir ke musuh sekitar. Kalau boosted kena musuh yang udah slow, semua cooldown move lo berkurang; jadi auto ke musuh yang slow adalah mesin cooldown lo.","lanes":["Top","Bottom"],"laneNote":"Top atau Bottom sebagai tank lane; Goodra lama evolusinya (Lv8), jadi butuh partner lane yang bisa nutupin sampai dia jadi.","earlyGame":"Goomy pelan dan lemah: Bubble buat shield + slow pas trade, Tackle buat lempar musuh yang terlalu maju. Jangan trade panjang, masuk grass buat heal Gooey kalau HP turun. Lv5 (Muddy Water/Dragon Pulse) mulai bisa tahan, Lv8 baru tank beneran.","powerSpike":"Lv5 dapat Muddy Water/Dragon Pulse, Lv7 dapat Power Whip/Acid Spray, Lv8 jadi Goodra (stat loncat); Lv9 Right as Rain bikin lo nyaris nggak bisa mati sebentar.","slot1":{"base":{"name":"Bubble","level":1,"desc":"Lo dapat shield; pas shield pecah, musuh sekitar kena damage dan slow."},"choices":[{"name":"Muddy Water","level":5,"upgradeLevel":11,"desc":"Semprot air lumpur ke area: damage, damage output musuh yang kena turun, dan Defense/Sp. Def lo naik (numpuk sampai empat kali).","when":"Tekan ke musuh yang nempel di tengah fight dan terus ulang buat numpuk defense; paling kuat saat lawan banyak melee.","avoid":"Jangan tekan dari jauh ke udara kosong buat 'numpuk defense'; buff-nya kecil tanpa kena musuh dan lo buang cooldown.","upgradeNote":"Lv11: kenaikan Defense/Sp. Def per stack makin besar."},{"name":"Dragon Pulse","level":5,"upgradeLevel":11,"desc":"Lepas gelombang kejut ke depan: damage, dan lo heal kalau bagian tengahnya kena musuh atau musuh itu udah slow.","when":"Tekan ke musuh yang udah lo slow (Gooey/boosted/Acid Spray) dan usahain bagian tengahnya kena; itu sumber heal utama lo.","avoid":"Jangan tembak ke musuh yang nggak slow dari pinggir; damage ada tapi heal-nya kecil.","upgradeNote":"Lv11: heal lebih besar terhadap musuh yang slow."}]},"slot2":{"base":{"name":"Tackle","level":1,"desc":"Nabrak satu musuh: damage dan dia dilempar."},"choices":[{"name":"Power Whip","level":7,"upgradeLevel":13,"desc":"Cambuk pakai tanduk ke satu arah: damage dan slow; musuh yang jauh ditarik mendekat ke lo.","when":"Tekan ke carry musuh yang jaga jarak buat narik dia ke tim lo, lalu Muddy Water/Dragon Pulse.","avoid":"Jangan tarik tank musuh ke tengah tim lo; dan jangan buang pas lo nggak siap follow-up.","upgradeNote":"Lv13: efek slow tambahan ke musuh yang kena."},{"name":"Acid Spray","level":7,"upgradeLevel":13,"desc":"Semprot asam yang nandain musuh dan slow; tekan lagi buat dash ke musuh yang ditandai dan lempar mereka.","when":"Tekan buat engage: tandai carry musuh, dash ke dia, lempar, lalu Dragon Pulse; juga mobilitas buat nyusul atau kabur.","avoid":"Jangan dash ke tengah 5 musuh tanpa Right as Rain/Eject; dash-nya cuma satu arah.","upgradeNote":"Lv13: efek slow berlaku di kedua serangan (semprot dan dash)."}]},"unite":{"name":"Right as Rain","level":9,"desc":"Hujan turun di sekitar lo: HP lo pulih terus-menerus, lo dapat shield dan speed, dan semua basic attack jadi boosted selama efek aktif.","when":"Pakai pas lo udah di tengah musuh dan HP mulai turun; semua auto boosted = slow terus + cooldown berkurang terus, jadi spam move.","avoid":"Jangan pakai jauh dari musuh buat heal doang; nilainya di boosted attack beruntun ke musuh yang slow."},"builds":[{"name":"Dragon Pulse + Acid Spray — Sustain Brawler","moves":["Dragon Pulse","Acid Spray"],"recommended":true,"style":"Tank yang masuk dan heal sendiri: Acid Spray dash + lempar, Dragon Pulse heal ke musuh yang slow; set paling seimbang (dittobase guide, game8).","heldItems":[{"name":"Slick Spoon","why":"Nembus Sp. Def biar Dragon Pulse sakit dan heal-nya kerasa (semua sumber)."},{"name":"Resonant Guard","why":"Shield buat lo dan sekutu pas engage (dittobase)."},{"name":"Focus Band","why":"Sustain tambahan di HP rendah (game8); Exp. Share alternatif dittobase buat full tank."}],"battleItem":{"name":"Potion","why":"Heal cepat buat nambal jeda Dragon Pulse (game8/dittobase); X Speed/Eject Button alternatif."},"combo":["Acid Spray tandai carry musuh, tekan lagi buat dash + lempar.","Dragon Pulse (tengah) ke dia selagi slow → heal.","Auto 3x: boosted ke musuh slow = cooldown turun.","Right as Rain kalau HP turun, lalu ulang Pulse dan auto."],"comboNote":"Game8 nyebut 'Gooey Beam Combo'. Kuncinya: tembak Dragon Pulse ke musuh yang UDAH slow."},{"name":"Muddy Water + Power Whip — Frontline Tank","moves":["Muddy Water","Power Whip"],"recommended":false,"style":"Tank beneran: tarik musuh, Muddy Water bikin mereka lemah dan lo makin tebal; paling kuat lawan tim melee.","heldItems":[{"name":"Slick Spoon","why":"Muddy Water tetap butuh damage biar dianggep ancaman."},{"name":"Exp. Share","why":"Lo tank lane, carry lo level lebih cepat (game8/dittobase)."},{"name":"Focus Band","why":"Sustain standar; Resonant Guard alternatif dittobase."}],"battleItem":{"name":"X Speed","why":"Lo nggak punya dash di build ini; X Speed buat nyusul atau kabur (game8/dittobase)."},"combo":["Power Whip tarik carry musuh ke lo.","Muddy Water langsung (damage mereka turun, defense lo naik).","Auto 3x: boosted ke musuh slow → cooldown turun.","Ulang Power Whip → Muddy Water; Right as Rain kalau dikeroyok."],"comboNote":"Game8 nyebut 'Fly Trap Combo' dan bilang loop-nya bisa terus jalan lewat boosted attack. Build ini kurang heal, jadi jalan bareng tim."}],"situations":{"gank":"Saat nge-gank: Acid Spray dash + lempar target, atau Power Whip tarik dia ke tim, lalu Muddy Water/Dragon Pulse. Saat dikeroyok: biarin mereka mukul (Gooey slow mereka), Muddy Water buat defense + nurunin damage mereka, Right as Rain, lalu jalan ke tim sambil auto boosted.","escape":"Acid Spray dash ke arah musuh terdekat yang ditandai kalau itu arah tim, Eject/X Speed, masuk tall grass buat heal Gooey. Boosted attack ke pengejar yang slow buat potong cooldown. Lo pelan, jadi mulai mundur lebih awal.","objective":"Berdiri di pit, nerima damage (Gooey slow semua yang nempel), Muddy Water biar damage mereka ke boss/ke tim lo turun. Power Whip tarik jungler musuh yang mau nyuri. Right as Rain saat fight pecah di pit biar lo nggak bisa digeser.","duel":"Lawan melee: lo menang trade panjang; biarin dia mukul (slow), Muddy Water/Dragon Pulse, auto boosted. Lawan ranged kiting: Acid Spray/Power Whip buat nutup jarak sekali, kalau miss mundur; jangan dikejar.","teamfight":"Frontline. Prioritas: tarik/lempar satu carry musuh ke tim lo, lalu berdiri di tengah musuh biar Gooey nge-slow sebanyak mungkin orang. Muddy Water ke yang paling sakit (damage dia turun). Jangan ngejar; biarin mereka datang ke lendir lo."},"mistakes":["Dragon Pulse ke musuh yang belum slow (heal kecil).","Lupa auto 3x ke musuh yang slow (itu cara potong cooldown).","Power Whip narik tank musuh ke tengah tim sendiri.","Right as Rain jauh dari musuh cuma buat heal.","Fight panjang sebelum Lv8; Sliggoo masih lemah."],"counters":{"hardFor":[{"name":"Inteleon","why":"Kite dari jauh dengan crit tinggi; lo pelan dan nggak bisa nyusul (game8).","how":"Tahan posisi dekat tim; Power Whip/Acid Spray cuma pas dia maju, selebihnya biarin carry lo."},{"name":"Buzzwole","why":"Stun berulang bikin lo nggak bisa mulai loop Pulse/auto (game8).","how":"Full Heal/Eject saat dia Lunge, Muddy Water biar damage dia turun, fight bareng tim."},{"name":"Mamoswine","why":"Freeze dan CC area ngunci lo di tempat (game8).","how":"Jangan masuk duluan ke dia; tunggu dia buang Icicle Crash, lalu Acid Spray."}],"goodAgainst":[{"name":"Cramorant","why":"Ranged rapuh; Acid Spray/Power Whip nutup jarak dan Gooey nge-slow dia (game8)."},{"name":"Decidueye","why":"Immobile; sekali ketarik Power Whip dia nggak lolos (game8)."},{"name":"Hoopa","why":"Suporter tanpa ancaman langsung; lo tahan damage-nya dan ganggu formasinya (game8)."}]},"cinderace":{"similarity":2,"note":"Beda jauh: Goodra melee, pelan, dan kuat justru pas dipukul (Gooey). Yang kebawa dari Cinderace cuma disiplin auto 3x (di Goodra boosted ke musuh slow = cooldown turun) dan kesadaran siapa carry musuh (target Power Whip/Acid Spray). Yang harus diubah: lo masuk dan diem di tengah musuh, bukan kiting; dan heal lo bergantung Dragon Pulse kena musuh yang slow, bukan dari jarak."},"sources":["https://serebii.net/pokemonunite/pokemon/goodra.shtml","https://bulbapedia.bulbagarden.net/wiki/Goodra_(UNITE)","https://www.dittobase.com/unite/pokemon/goodra","https://www.dittobase.com/unite/news/goodra-guide","https://game8.co/games/Pokemon-UNITE/archives/408002","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"high","notes":"Beda antar sumber: Serebii nyebut Goodra 'Ranged'; Bulbapedia dan dittobase nyebut Melee (benar: melee). Serebii nyebut Bubble sebagai salah satu pilihan Lv5 (salah; Bubble adalah base move, Lv5 pilihannya Muddy Water/Dragon Pulse). Halaman build dittobase nulis 'Muddy Water + Tackle' dan 'Dragon Pulse + Tackle' (kelihatan data error karena Tackle wajib di-upgrade di Lv7); guide dittobase sendiri rekomendasi Dragon Pulse + Acid Spray, sama dengan game8. Level cocok: Muddy Water/Dragon Pulse Lv5 (upgrade Lv11), Power Whip/Acid Spray Lv7 (upgrade Lv13), evolusi Lv5 dan Lv8, Unite Lv9. Patch: 1.18.2.6 (Apr 2025) HP naik tapi boosted dan Muddy Water damage turun; 1.19.2.8 (Jul 2025) Def/Sp. Def naik, Power Whip buff; 1.21.1.5 (Mei 2026) Gooey cooldown 12→10s, Tackle cooldown turun, Muddy Water damage reduction 15→20%, Right as Rain heal +15% (buff). Counter dari game8.","image":"img/goodra.webp","status":"Owned"},{"name":"Greedent","slug":"greedent","role":"Defender","damage":"Physical","range":"Melee","difficulty":"Ahli","evolutions":"Skwovet (Lv1) → Greedent (Lv5)","tagline":"Tank tupai yang hidup dari berry: makan berry buat heal/shield, numpuk berry buat potong cooldown, dan nyolong goal pakai mobilitas.","passive":{"name":"Cheek Pouch","desc":"Tiap lo makan berry (termasuk Sitrus Berry di map, yang bisa lo ambil walau HP penuh), lo heal tambahan dan satu berry disimpan di ekor (maksimal lima). Berry simpanan ini yang ngasih makan semua move lo."},"basicAttack":"Basic attack melee; tiap serangan ketiga jadi boosted yang damage lebih besar dan jatuhin satu berry dari ekor. Boosted = cara lo 'ngeluarin' berry buat dimakan lagi, jadi auto bukan cuma buat damage.","lanes":["Top","Bottom"],"laneNote":"Top atau Bottom; Greedent paling nyaman di lane karena ada Sitrus Berry di bush dan goal buat ngisi ekor, dan dia bisa sneak buat score.","earlyGame":"Skwovet lemah tapi licin: Tackle buat poke/slow dan buat lompat lewat musuh, Defense Curl buat shield pas trade. Ambil tiap Sitrus Berry yang lo lihat (walau HP penuh) biar ekor lo penuh sebelum Lv5. Jangan fight panjang tanpa berry di ekor.","powerSpike":"Lv5 jadi Greedent dan dapat Stuff Cheeks/Covet (sustain beneran mulai); Lv7 dapat Belch/Bullet Seed; Lv9 Berry Belly Flop bikin berry nggak habis sebentar dan reset semua cooldown.","slot1":{"base":{"name":"Tackle","level":1,"desc":"Lompat ke area, damage dan slow; cooldown-nya dipotong tiap berry yang lo simpan."},"choices":[{"name":"Bullet Seed","level":7,"upgradeLevel":13,"desc":"Muntahin biji ke satu arah sambil lo tetap bisa gerak: damage beruntun dan slow; makin banyak berry di ekor, makin lama/kuat.","when":"Tekan ke musuh yang lagi nempel atau ngejar lo, sambil jalan (ke goal buat score, atau mundur ke tim).","avoid":"Jangan tekan pas ekor kosong; damage dan durasinya jadi kecil.","upgradeNote":"Lv13: damage Bullet Seed naik."},{"name":"Belch","level":7,"upgradeLevel":13,"desc":"Sendawa ke area: damage besar dan slow; ini burst utama Greedent, makin banyak berry makin sakit.","when":"Tekan ke kerumunan di pit atau ke carry musuh yang abis lo slow pakai Covet; idealnya pas ekor penuh.","avoid":"Jangan Belch pas berry tinggal 1-2; itu kerja setengah hati dan lo kehilangan sustain.","upgradeNote":"Lv13: damage Belch naik."}]},"slot2":{"base":{"name":"Defense Curl","level":1,"desc":"Lo dapat shield dan satu berry jatuh dari ekor."},"choices":[{"name":"Stuff Cheeks","level":5,"upgradeLevel":11,"desc":"Jatuhin beberapa berry sekaligus dari ekor dan makan: heal besar, kelebihan HP jadi shield.","when":"Tekan pas HP lo turun di tengah fight dan ekor penuh, atau sebelum Belch biar dapat shield + makan ulang berry.","avoid":"Jangan tekan pas HP penuh; heal-nya kebuang dan ekor lo kosong.","upgradeNote":"Lv11: jumlah HP yang dipulihkan naik."},{"name":"Covet","level":5,"upgradeLevel":11,"desc":"Lo lari ke segala arah dalam waktu tertentu: damage ke musuh yang lo tabrak, tahan CC, dan berry jatuh dari ekor sepanjang jalan.","when":"Tekan buat masuk ke tim musuh dan muter-muter di antara mereka (stun/disrupt), buat lari ngejar scorer, atau buat kabur.","avoid":"Jangan lari lurus; muter di antara musuh biar tabrakan dan gangguannya maksimal, lalu makan berry yang jatuh.","upgradeNote":"Lv11: cooldown Covet berkurang."}]},"unite":{"name":"Berry Belly Flop","level":9,"desc":"Lo makan berry (heal), lompat ke area dan damage, lalu makan berry spesial: beberapa saat berry lo nggak habis dan semua cooldown move di-reset.","when":"Pakai buat engage ke kerumunan di pit, lalu langsung spam Belch/Covet selama berry nggak habis.","avoid":"Jangan pakai cuma buat heal darurat sendirian jauh dari fight; nilainya di reset cooldown dan spam move."},"builds":[{"name":"Covet + Belch — Disruptor Burst","moves":["Covet","Belch"],"recommended":true,"style":"Masuk muter-muter di tengah musuh, bikin kacau, lalu Belch burst ke yang numpuk.","heldItems":[{"name":"Attack Weight","why":"Attack numpuk tiap score; Greedent sering score karena mobilitasnya (game8/dittobase)."},{"name":"Weakness Policy","why":"Attack naik tiap lo kena damage, dan lo selalu kena damage (game8/dittobase)."},{"name":"Focus Band","why":"Sustain tambahan di HP rendah, numpuk sama berry."}],"battleItem":{"name":"Eject Button","why":"Nyambung jarak Covet atau kabur setelah Belch (game8/dittobase)."},"combo":["Isi ekor dulu (Sitrus Berry, boosted attack, Defense Curl).","Covet masuk, muter di antara musuh (disrupt + berry jatuh).","Belch ke yang numpuk pas ekor masih penuh.","Berry Belly Flop → Covet → Belch berkali-kali selama berry nggak habis."],"comboNote":"Game8: 'Berry Belly Flop → Covet → continuous Belch spam'. Kuncinya ekor penuh sebelum masuk."},{"name":"Stuff Cheeks + Bullet Seed — Scorer Sustain","moves":["Stuff Cheeks","Bullet Seed"],"recommended":false,"style":"Tank yang susah mati dan nyolong goal: heal besar pakai Stuff Cheeks, Bullet Seed sambil jalan ke goal.","heldItems":[{"name":"Attack Weight","why":"Lo bakal sering score; stack Attack-nya cepat."},{"name":"Aeos Cookie","why":"HP numpuk tiap score; cocok buat build scorer (game8)."},{"name":"Focus Band","why":"Sustain standar."}],"battleItem":{"name":"X Speed","why":"Buat lari ke goal dan kabur setelah score (game8); Potion alternatif (dittobase)."},"combo":["Isi ekor penuh.","Stuff Cheeks sebelum trade (shield + heal + makan ulang).","Bullet Seed ke pengejar sambil jalan ke goal.","Score, lalu Berry Belly Flop kalau dikeroyok."],"comboNote":"Build ini kurang damage; nilainya di score dan nahan musuh, bukan membunuh."}],"situations":{"gank":"Saat nge-gank: Covet masuk dan muter di sekitar target biar dia keganggu, Belch pas tim lo nyusul. Saat dikeroyok: Stuff Cheeks/Defense Curl buat shield, Covet (tahan CC) buat keluar, makan berry yang jatuh di jalan.","escape":"Covet arah tim (tahan CC + kecepatan), Bullet Seed ke pengejar sambil jalan, makan berry yang jatuh. Kalau ekor kosong, lo nggak punya apa-apa; itu alasan kenapa jangan fight dengan ekor kosong.","objective":"Isi ekor penuh sebelum objective spawn. Berdiri di pit, Berry Belly Flop saat musuh numpuk lalu spam Belch/Covet. Lo juga pilihan bagus buat 'nyolong' goal musuh di sisi lain pas semua lagi sibuk di objective.","duel":"Lawan melee: Stuff Cheeks buat shield, auto + boosted buat ngisi berry, Belch pas ekor penuh; lo menang trade panjang. Lawan ranged: Covet nutup jarak dan ganggu dia, Bullet Seed kalau dia kabur; kalau ekor kosong jangan duel.","teamfight":"Frontline-ish tapi licin: Covet masuk ke backline musuh buat ganggu carry mereka, Belch ke yang numpuk, lalu keluar lagi makan berry. Prioritas: carry musuh yang ngerasa aman di belakang. Jangan diam di satu tempat."},"mistakes":["Fight dengan ekor kosong (semua move jadi lemah).","Ngelewatin Sitrus Berry di map karena HP penuh (Greedent tetap harus ambil).","Covet lari lurus bukannya muter di antara musuh.","Stuff Cheeks di HP penuh (heal kebuang).","Berry Belly Flop cuma buat heal sendirian jauh dari fight."],"counters":{"hardFor":[{"name":"Glaceon","why":"Nguras HP lo dari jauh pakai Icicle Spear/Icy Wind sambil kite (game8).","how":"Jangan dikejar jauh; Covet masuk cuma kalau tim lo ikut, selebihnya fokus score di sisi lain."},{"name":"Mr. Mime","why":"Barrier-nya matiin Covet dan Power Swap nekan lo terus (game8).","how":"Hindari lari lewat barrier, tunggu dia buang Light Screen, lalu Covet."},{"name":"Umbreon","why":"Mean Look ngunci lo di tempat dan dia nyuri shield lo (game8).","how":"Jangan masuk sendirian ke area dia; Stuff Cheeks setelah Mean Look habis, bukan sebelum."}],"goodAgainst":[{"name":"Decidueye","why":"Ranged rapuh tanpa escape; Covet masuk dan dia nggak bisa ngapa-ngapain (game8)."},{"name":"Delphox","why":"Rapuh dan pelan; Covet nutup jarak, Belch habisin (game8)."},{"name":"Comfey","why":"Suporter yang ngandelin nempel ke sekutu; Covet ganggu formasinya (game8)."}]},"cinderace":{"similarity":2,"note":"Beda jauh dari Cinderace: melee, dan 'ammo' lo adalah berry, bukan cooldown. Yang kebawa: kebiasaan auto 3x (di Greedent boosted ngeluarin berry) dan kesadaran buat sneak score. Yang harus diubah: lo masuk ke tengah musuh dan muter, bukan mundur; dan sebelum tiap fight lo cek ekor, bukan HP."},"sources":["https://serebii.net/pokemonunite/pokemon/greedent.shtml","https://bulbapedia.bulbagarden.net/wiki/Greedent_(UNITE)","https://www.dittobase.com/unite/pokemon/greedent","https://game8.co/games/Pokemon-UNITE/archives/346813","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"medium","notes":"Ringkasan Serebii nyebut level yang nggak konsisten (Tackle Lv5, Bullet Seed Lv7, Belch Lv13, Covet Lv11); Bulbapedia jelas: Defense Curl → Stuff Cheeks/Covet Lv5 (upgrade Lv11), Tackle → Bullet Seed/Belch Lv7 (upgrade Lv13). Serebii nyebut Belch 'Ranged/Physical' dan Covet 'Hindrance'. Patch terakhir 1.23.2.9 (3 Sep 2026): Defense dan Sp. Def turun, energi Berry Belly Flop naik (nerf). Build dittobase (Covet+Belch, Stuff Cheeks+Bullet Seed, Attack Weight/Weakness Policy/Focus Band) dan game8 cocok. Deskripsi upgradeNote untuk Bullet Seed/Belch/Stuff Cheeks/Covet tidak ditemukan eksplisit di sumber yang bisa diakses, jadi itu perkiraan umum (damage/heal naik, cooldown turun); confidence medium.","image":"img/greedent.webp","status":"Owned"},{"name":"Slowbro","slug":"slowbro","role":"Defender","damage":"Special","range":"Ranged","difficulty":"Pemula","evolutions":"Slowpoke (Lv1) → Slowbro (Lv4)","tagline":"Tank ranged yang kerjanya ngunci satu target (Telekinesis/Slowbeam) dan nyusahin musuh pakai slow, bukan ngebunuh sendiri.","passive":{"name":"Oblivious","desc":"Damage yang lo terima disimpan sebentar sebagai 'HP biru'; tiap move lo kena musuh, sebagian HP itu balik. Jadi makin sering lo kena move ke musuh, makin susah lo mati."},"basicAttack":"Basic attack ranged biasa; tiap serangan ketiga jadi boosted yang damage area kecil dan nge-slow musuh sekitar. Boosted-nya enak buat ngejar/nahan musuh, tapi damage utama bukan dari sini.","lanes":["Top","Bottom"],"laneNote":"Top atau Bottom sebagai tank lane; paling enak jaga lane bareng attacker ranged (Cinderace, Glaceon) karena Slowbro ngunci target dan mereka yang ngebunuh.","earlyGame":"Slowpoke lemah dan pelan: jangan trade keras sebelum Lv4. Biarin partner lo yang ambil last hit wild, lo cukup Water Gun buat slow dan poke. Lv4 (Slowbro + Scald/Surf) baru boleh mulai nekan, dan Lv6 (Amnesia/Telekinesis) baru berani frontline.","powerSpike":"Lv4 jadi Slowbro (dapat Scald/Surf) dan Lv6 dapat Amnesia/Telekinesis; Lv9 Slowbeam bikin lo bisa ngunci satu carry musuh total.","slot1":{"base":{"name":"Water Gun","level":1,"desc":"Semprot air ke depan, damage dan slow; bisa ditahan buat area dan damage lebih besar."},"choices":[{"name":"Scald","level":4,"upgradeLevel":11,"desc":"Semprot air panas yang ninggalin uap: musuh kena burn dan Attack mereka turun; move ini sumber damage utama Slowbro.","when":"Tekan ke musuh yang lagi nempel/terkunci (habis Telekinesis atau di pit objective) biar burn dan debuff-nya kena banyak orang.","avoid":"Jangan buang cuma buat farm wild saat fight sebentar lagi; cooldown-nya lo butuh di fight.","upgradeNote":"Lv11: efek penurunan Attack musuh makin kuat."},{"name":"Surf","level":4,"upgradeLevel":11,"desc":"Lo naik ombak ke depan, musuh yang kena dilempar dan di-slow; sekaligus dash buat masuk atau kabur.","when":"Tekan buat engage ke carry musuh yang terlalu maju, atau buat gusur musuh dari posisi scoring/pit.","avoid":"Jangan Surf masuk ke tengah 5 musuh tanpa Amnesia/Eject siap; ini satu-satunya mobilitas lo.","upgradeNote":"Lv11: cooldown Surf berkurang."}]},"slot2":{"base":{"name":"Slack Off","level":1,"desc":"Lo istirahat dan HP pulih bertahap; dipotong kalau lo gerak."},"choices":[{"name":"Amnesia","level":6,"upgradeLevel":13,"desc":"Lo pulihin HP dari damage yang tersimpan (Oblivious), kebal CC, dan Defense naik sebentar.","when":"Tekan SETELAH lo nerima damage besar (biar HP yang balik banyak), atau pas musuh mau nge-CC lo di tengah fight.","avoid":"Jangan tekan di awal fight saat HP masih penuh; heal-nya nol dan lo buang tombol kebal CC.","upgradeNote":"Lv13: durasi efeknya lebih lama."},{"name":"Telekinesis","level":6,"upgradeLevel":13,"desc":"Angkat satu musuh ke udara (nggak bisa gerak), tekan lagi buat tarik dia ke lo.","when":"Tekan ke carry musuh yang jalan sendirian atau yang mau kabur, lalu tarik ke tim lo buat dibunuh.","avoid":"Jangan tarik tank musuh ke tengah tim lo; lo cuma ngasih mereka engage gratis.","upgradeNote":"Lv13: cooldown berkurang."}]},"unite":{"name":"Slowbeam","level":9,"desc":"Lo nembak sinar terus-menerus ke satu musuh: dia nggak bisa gerak selama sinar jalan, lo dapat shield dan kebal CC.","when":"Pakai ke carry musuh yang paling bahaya (attacker/speedster) tepat saat fight mulai, biar tim lo bunuh dia duluan.","avoid":"Jangan tembak ke tank atau ke musuh yang teman lo nggak bisa jangkau; dan jangan kena bait sampai lo berdiri di tengah 5 musuh."},"builds":[{"name":"Scald + Amnesia — Tank Sustain","moves":["Scald","Amnesia"],"recommended":true,"style":"Frontline yang susah mati: debuff musuh pakai Scald, serap damage, heal balik pakai Amnesia.","heldItems":[{"name":"Focus Band","why":"Heal saat HP rendah, numpuk sama Amnesia dan Oblivious."},{"name":"Resonant Guard","why":"Shield berkala buat lo dan sekutu di sekitar; item tank standar sekarang (dittobase)."},{"name":"Exp. Share","why":"Partner lane lo level lebih cepat; lo tank, biarin carry yang farm."}],"battleItem":{"name":"Eject Button","why":"Slowbro pelan banget; Eject satu-satunya cara reposisi cepat kalau Surf nggak diambil."},"combo":["Water Gun/boosted buat slow musuh yang mendekat.","Scald ke musuh yang numpuk (burn + Attack turun).","Tahan damage; pas HP udah turun, Amnesia buat heal besar dan kebal CC.","Slowbeam ke carry musuh saat tim lo siap follow-up."],"comboNote":"Kunci build ini: Amnesia ditekan setelah kena damage, bukan sebelum."},{"name":"Surf + Telekinesis — Lockdown","moves":["Surf","Telekinesis"],"recommended":false,"style":"Playmaker: angkat satu target, tarik, lalu Surf buat lempar dia ke tim lo.","heldItems":[{"name":"Focus Band","why":"Lo bakal masuk tanpa Amnesia, butuh sustain."},{"name":"Resonant Guard","why":"Shield buat lo dan tim pas lo engage."},{"name":"Choice Specs","why":"Bikin Surf dan Water Gun cukup sakit buat ngancem (game8/dittobase pakai di build ofensif)."}],"battleItem":{"name":"Eject Button","why":"Buat kabur setelah combo, atau buat ngejar target Telekinesis."},"combo":["Telekinesis ke carry musuh (dia terangkat, nggak bisa gerak).","Tekan lagi buat tarik dia ke arah lo.","Surf lewat dia buat lempar + slow, tim lo bunuh.","Kalau dia masih hidup: Slowbeam buat kunci total."],"comboNote":"Game8 nyebut combo ini 'Lift and Surf'; Surf + Telekinesis + Slowbeam bisa matiin satu speedster/attacker tanpa dia bisa apa-apa."}],"situations":{"gank":"Saat nge-gank: Telekinesis/Slowbeam ke target yang dikejar duluan, baru Scald. Saat dikeroyok: Amnesia pas CC mereka mulai masuk (kebal CC + heal), Water Gun/boosted buat slow, mundur ke tim.","escape":"Amnesia dulu (kebal CC) lalu jalan ke tim; Surf atau Eject Button buat jarak; boosted attack buat slow pengejar. Jangan Slack Off saat masih dikejar.","objective":"Berdiri di depan carry lo, di bibir pit. Simpan Telekinesis/Slowbeam buat carry musuh yang mau masuk nyuri; Scald ke pit biar damage mereka turun. Kalau pakai Surf, pakai buat gusur musuh keluar pit, bukan buat ngejar.","duel":"Lawan melee: Scald (Attack mereka turun) + boosted slow, Amnesia saat HP setengah; lo biasanya menang trade panjang. Lawan ranged kiting: jangan dikejar, mundur ke goal atau tunggu Telekinesis buat tarik dia.","teamfight":"Frontline di depan carry. Prioritas: kunci satu carry musuh (Telekinesis/Slowbeam) saat tim lo siap, bukan sembarang target. Lo nggak harus bunuh siapa-siapa; tugas lo bikin satu musuh 'hilang' dari fight."},"mistakes":["Amnesia ditekan pas HP penuh (nggak heal apa-apa).","Slowbeam ke tank atau ke target yang tim lo nggak bisa follow-up.","Telekinesis narik tank musuh ke tengah tim sendiri.","Ngejar musuh ranged jauh dari tim; Slowbro paling pelan di game.","Lupa kalau Oblivious cuma balikin HP kalau move kena musuh, jadi jangan diam di tengah fight tanpa nembak."],"counters":{"hardFor":[{"name":"Cinderace","why":"Kite dari jauh, lo nggak bisa nyusul (game8).","how":"Jangan dikejar; tunggu dia masuk jangkauan Telekinesis atau Slowbeam, lalu tarik ke tim."},{"name":"Alolan Ninetales","why":"Slow + freeze dari jarak jauh; lo pelan dan gampang di-kite (game8).","how":"Amnesia saat freeze mau masuk; tahan posisi dekat goal, poke pakai Water Gun."},{"name":"Inteleon","why":"Crit ranged dari jauh, kabur gampang (game8).","how":"Jalan di grass/arah dia nggak lihat, Telekinesis begitu dia maju; jangan solo."},{"name":"Delphox","why":"Burn area dari jauh, lo nggak bisa nutup jarak (game8).","how":"Minta carry lo yang nekan, lo cuma nutup dengan Slowbeam saat dia masuk."}],"goodAgainst":[{"name":"Zeraora","why":"Dia harus nempel buat damage; Telekinesis/Slowbeam matiin combo-nya (game8)."},{"name":"Machamp","why":"All-rounder melee; Scald nurunin Attack dia dan lo menang trade panjang (game8)."},{"name":"Gengar","why":"Begitu dia nongol buat burst, Slowbeam kunci dia dan tim lo bunuh (game8)."}]},"cinderace":{"similarity":2,"note":"Hampir kebalikan Cinderace: lo paling pelan, nggak punya burst, dan menang bukan dari damage tapi dari ngunci satu orang. Yang kebawa dari Cinderace cuma kebiasaan 'lihat siapa carry musuh' karena itu target Telekinesis/Slowbeam lo. Yang harus diubah: berhenti kiting mundur sambil auto; lo berdiri di depan carry lo, nerima damage, dan baru Amnesia setelah HP turun."},"sources":["https://serebii.net/pokemonunite/pokemon/slowbro.shtml","https://bulbapedia.bulbagarden.net/wiki/Slowbro_(UNITE)","https://www.dittobase.com/unite/pokemon/slowbro","https://game8.co/games/Pokemon-UNITE/archives/335474","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"high","notes":"Beda antar sumber: Serebii nyebut 'Physical Attacker' dan difficulty Intermediate, Bulbapedia/dittobase nyebut Sp. Atk dan Novice; item Sp. Atk (Choice Specs/Slick Spoon) dipakai semua build, jadi Special benar. Level cocok semua sumber: Scald/Surf Lv4 (upgrade Lv11), Amnesia/Telekinesis Lv6 (upgrade Lv13), Slowbeam Lv9. Patch terakhir: 1.19.2.6 (Jul 2025) Scald damage naik, Surf slow naik, Water Gun slow turun; 1.18.2.6 (Apr 2025) HP naik. Tidak ada rework 2026. Build ofensif game8 (Choice Specs + Slick Spoon + Focus Band) dan tank dittobase (Exp. Share + Resonant Guard + Focus Band) dua-duanya valid.","image":"img/slowbro.webp","status":"Owned"},{"name":"Tyranitar","slug":"tyranitar","role":"Serba-Bisa","damage":"Physical","range":"Melee","difficulty":"Menengah","evolutions":"Larvitar (Lv1) → Pupitar (Lv5) → Tyranitar (Lv9)","tagline":"Monster late game yang lemah di awal tapi jadi mesin execute begitu Lv9 dan dapat Unite.","passive":{"name":"Sand Stream","desc":"Sebagai Tyranitar: tiap habis pakai move, badai pasir muncul di sekitar lo yang naikin Def/Sp. Def dan ngasih damage ke musuh di dekat. (Larvitar: Guts, Attack naik pas kena damage. Pupitar: Shed Skin, status dihapus + shield pas kena damage.)"},"basicAttack":"Melee biasa. Tiap serangan ketiga jadi boosted: damage lebih gede dan bikin musuh paralyzed (gak bisa gerak sebentar). Pas Unite aktif, pola basic attack berubah jadi hentakan area.","lanes":["Top","Jungle"],"laneNote":"Top paling aman karena Larvitar lemah dan lo butuh waktu buat Lv9. Jungle bisa kalau lo pede farm cepat, tapi gank sebelum Lv9 lemah.","earlyGame":"Lv1 ambil Bite (damage + stun kalau HP target rendah) dan Rock Polish (dash + Attack buff). Jangan fight serius, fokus farm dan jangan mati. Minta partner yang bisa carry awal. Kalau dikeroyok, Rock Polish buat kabur.","powerSpike":"Lv5 Pupitar sedikit lebih tahan dan dapat Dark Pulse/Stone Edge. Spike besar di Lv9: evolve ke Tyranitar, dapat Ancient Power/Sand Tomb, Sand Stream, dan Unite Tyrannical Rampage sekaligus. Lv11/13 upgrade bikin lo makin gila.","slot1":{"base":{"name":"Bite","level":1,"desc":"Gigit musuh di depan, damage; kalau HP target di bawah batas tertentu, dia gak bisa gerak sebentar."},"choices":[{"name":"Dark Pulse","level":5,"upgradeLevel":11,"desc":"Hembus kabut gelap ke area depan, damage; musuh ber-HP rendah gak bisa gerak. Kena target yang sama lagi dalam waktu singkat = bonus damage. Kalau dipakai setelah Ancient Power, Defense musuh diabaikan lebih lama.","when":"Tekan ke musuh yang HP-nya udah turun buat ngunci dia, atau dua kali berturut ke target yang sama buat bonus damage.","avoid":"Jangan buang ke target HP penuh cuma buat poke, nilainya ada di stun HP rendah dan bonus hit kedua.","upgradeNote":"Lv11 bonus damage dan efek kuncinya naik. Patch Des 2025 buff bonus damage-nya."},{"name":"Stone Edge","level":5,"upgradeLevel":11,"desc":"Serangan area yang bisa ditekan 3 kali berturut, makin dekat musuh ke lo makin sakit.","when":"Tekan pas lo udah nempel musuh (jarak nol = damage maksimal), 3 kali cepat buat burst.","avoid":"Jangan tekan dari jarak jauh, damage-nya kecil banget kalau musuh di tepi area.","upgradeNote":"Lv11 damage naik."}]},"slot2":{"base":{"name":"Rock Polish","level":1,"desc":"Nerjang ke satu arah, damage; kalau kena, Attack lo naik sebentar."},"choices":[{"name":"Ancient Power","level":9,"upgradeLevel":13,"desc":"Ngecas sebentar (speed naik, dapat shield, tahan hindrance), lalu lepas gelombang yang damage dan bikin musuh gak bisa gerak. Kena musuh = lo bisa nembus Def/shield. Bisa ditekan lagi buat gelombang kedua yang slow.","when":"Tekan buat engage ke musuh yang ngumpul (shield + stun area), lalu lanjut Dark Pulse selagi mereka kekunci.","avoid":"Jangan tekan pas gak ada yang bisa kena, gelombang keduanya baru keluar kalau yang pertama kena.","upgradeNote":"Lv13 shield dan efek tembus Def-nya lebih kuat."},{"name":"Sand Tomb","level":9,"upgradeLevel":13,"desc":"Lompat ke satu arah, musuh yang kelindas gak bisa gerak; pas mendarat muncul awan debu yang damage berkala dan slow. Tekan lagi buat narik musuh di sekitar ke tengah. Selama lo di dalam debu, damage yang lo terima berkurang dan lo nembus Def/shield.","when":"Tekan ke pit objective atau ke kerumunan: lompat, tarik, dan jangan keluar dari debu selama fight.","avoid":"Jangan lompat lalu keluar dari awan debu buat ngejar, bonus pengurangan damage lo hilang.","upgradeNote":"Lv13 durasi debu dan tarikannya lebih kuat."}]},"unite":{"name":"Tyrannical Rampage","level":9,"desc":"Lo ngamuk: speed naik, CC yang kena lo cepat hilang, dan basic attack berubah jadi hentakan area yang lebih sakit. Musuh yang kena hentakan dan HP-nya di bawah batas tertentu langsung KO.","when":"Pakai pas musuh udah pada setengah HP di teamfight atau di pit Rayquaza, lalu kejar dan hentak siapa pun yang tipis.","avoid":"Jangan tekan buat buka fight pas semua musuh HP penuh, execute-nya gak kepake dan durasinya kebuang."},"builds":[{"name":"Dark Pulse + Sand Tomb — Objective Monster","moves":["Dark Pulse","Sand Tomb"],"recommended":true,"style":"Lompat ke pit, tarik musuh ke debu, Dark Pulse ngunci yang HP rendah, Unite buat execute.","heldItems":[{"name":"Attack Weight","why":"Scaling Attack dari score, cocok buat late-game carry."},{"name":"Muscle Band","why":"Basic attack lo penting (paralyze + execute pas Unite), Muscle Band nambah damage tiap hit."},{"name":"Focus Band","why":"Biar lo gak mati selama fase Larvitar/Pupitar dan tahan di tengah fight."}],"battleItem":{"name":"Eject Button","why":"Reposisi buat nyusul target execute atau kabur pas belum Lv9."},"combo":["Sand Tomb lompat ke kerumunan, tekan lagi buat narik.","Dark Pulse ke yang HP-nya turun, ulangi ke target sama buat bonus damage.","Tyrannical Rampage, hentak semua yang tipis buat execute, basic attack boosted buat paralyze yang kabur."],"comboNote":"Resonant Guard bisa gantiin Focus Band kalau tim butuh shield."},{"name":"Dark Pulse + Ancient Power — Teamfight Engage","moves":["Dark Pulse","Ancient Power"],"recommended":false,"style":"Engage pakai shield dan stun area Ancient Power, lalu Dark Pulse yang nembus Def.","heldItems":[{"name":"Attack Weight","why":"Scaling dari score."},{"name":"Muscle Band","why":"Damage basic attack."},{"name":"Weakness Policy","why":"Attack naik pas kena damage, cocok sama engage pakai shield."}],"battleItem":{"name":"Eject Button","why":"Reposisi."},"combo":["Ancient Power ngecas sambil maju (shield + tahan CC), lepas gelombang ke kerumunan.","Dark Pulse langsung setelahnya (Defense musuh diabaikan lebih lama).","Tekan Ancient Power lagi buat gelombang kedua yang slow, Unite buat execute."],"comboNote":"Patch Des 2025 turunin cooldown Ancient Power dan naikin shield-nya."},{"name":"Stone Edge + Sand Tomb — Burst Brawler","moves":["Stone Edge","Sand Tomb"],"recommended":false,"style":"Nempel sedekat mungkin, Stone Edge 3 kali buat burst, Sand Tomb buat tahan dan narik.","heldItems":[{"name":"Muscle Band","why":"Damage basic attack."},{"name":"Razor Claw","why":"Basic attack setelah move dapat bonus damage + slow, Tyranitar sering gantian move dan basic."},{"name":"Focus Band","why":"Sustain."}],"battleItem":{"name":"Eject Button","why":"Reposisi."},"combo":["Sand Tomb ke target, tarik.","Stone Edge 3 kali dari jarak nol.","Basic attack boosted buat paralyze, Unite buat execute."],"comboNote":""}],"situations":{"gank":"Sebelum Lv9: jangan nge-gank, ikut aja kalau partner mulai. Setelah Lv9: Sand Tomb/Ancient Power buat ngunci, Dark Pulse, Unite buat execute. Dikeroyok: Ancient Power shield + Rock Polish/Eject buat kabur; di debu Sand Tomb lo lebih tahan.","escape":"Rock Polish (sebelum Lv9) atau Eject Button. Ancient Power ngasih shield + tahan hindrance pas ngecas, bisa dipakai buat jalan keluar. Tyrannical Rampage juga ngasih speed dan motong durasi CC.","objective":"Di Rayquaza: Sand Tomb ke pit, tarik musuh ke debu, stay di dalam debu. Simpan Tyrannical Rampage buat pas tim musuh udah ketarik dan HP mereka turun, lalu execute berantai. Basic attack boosted buat paralyze jungler yang mau steal.","duel":"Sebelum Lv9 kalah hampir lawan siapa pun, hindari. Setelah Lv9 lo menang hampir semua 1v1: Dark Pulse ngunci pas HP dia turun, basic attack boosted paralyze, Unite execute.","teamfight":"Masuk setelah tank tim lo engage. Target: siapa pun yang HP-nya udah turun, bukan yang paling penting. Dengan Unite, lo keliling area dan hentak semua yang di bawah batas execute."},"mistakes":["Fight serius pas masih Larvitar/Pupitar dan mati berulang, lo kehilangan waktu ke Lv9.","Unite ditekan pas semua musuh HP penuh, execute-nya gak kepake.","Keluar dari awan debu Sand Tomb buat ngejar, lo kehilangan pengurangan damage.","Ngejar tank musuh padahal Dark Pulse dan Unite cuma efektif ke target HP rendah."],"counters":{"hardFor":[{"name":"Cinderace","why":"Dia bully lo di lane pas masih Larvitar, dan setelah Lv9 dia kiting dan Feint buat kabur dari Unite lo.","how":"Farm aman sampai Lv9, lalu masuk cuma pas dia udah buang Feint."},{"name":"Lapras","why":"Slow terus-terusan bikin lo gak nyampe, Shell Armor motong burst Stone Edge.","how":"Jangan buang move ke dia, fokus carry di belakangnya."},{"name":"Umbreon","why":"Inner Focus batalin stun lo, Mean Look ngunci lo di tempat yang salah, dan dia gak pernah di bawah batas execute.","how":"Abaikan dia, Ancient Power buat shield dan tembus ke carry mereka."}],"goodAgainst":[{"name":"Delphox","why":"Rapuh dan lambat, sekali kena Dark Pulse/Sand Tomb dia udah di zona execute."},{"name":"Zacian","why":"Setelah Lv9 lo lebih tebal (Sand Stream), dan execute Unite ngabisin dia pas dia turun HP."},{"name":"Scizor","why":"Melee tipis yang andelin nempel; Sand Tomb debuff + Sand Stream bikin trade-nya kalah."}]},"cinderace":{"similarity":2,"note":"Beda jauh: melee, lambat, dan lo justru harus sabar farm sampai Lv9 (Cinderace udah jadi di Lv7). Yang kebawa cuma kebiasaan nyari target HP rendah buat finisher, karena Dark Pulse dan Unite lo semua tentang execute. Ubah kebiasaan 'kiting di belakang' jadi 'masuk bareng tank, hentak yang tipis'."},"sources":["https://serebii.net/pokemonunite/pokemon/tyranitar.shtml","https://bulbapedia.bulbagarden.net/wiki/Tyranitar_(UNITE)","https://www.dittobase.com/unite/pokemon/tyranitar","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"medium","notes":"Beda sumber soal level Unite: Serebii bilang Lv10, Bulbapedia dan Dittobase bilang Lv9; gw pakai Lv9 (konsisten dengan evolusi di Lv9). Level upgrade move: Bulbapedia Lv11 (slot 1) dan Lv13 (slot 2). Patch 1.21.1.2 (Des 2025) buff Dark Pulse bonus damage dan Ancient Power (cooldown turun, shield naik). Tier list Oktober 2026 (gfinity) naruh Tyranitar rendah, jadi ini pick late-game yang butuh tim ngelindungin awal. Counter adalah inferensi dari mekanik.","image":"img/tyranitar.webp","status":"Owned"},{"name":"Crustle","slug":"crustle","role":"Defender","damage":"Physical","range":"Melee","difficulty":"Pemula","evolutions":"Dwebble (Lv1) → Crustle (Lv4)","tagline":"Tank batu yang makin tebal makin dipukul; kerjanya bikin tembok (Rock Tomb) dan nge-stun kerumunan, atau berubah jadi bruiser pakai Shell Smash.","passive":{"name":"Sturdy","desc":"Tiap lo kehilangan sejumlah HP, Defense dan Sp. Def lo naik (numpuk sampai beberapa stack). Artinya lo justru paling tebal saat HP udah setengah ke bawah."},"basicAttack":"Basic attack melee; tiap serangan ketiga jadi boosted yang damage area dan nge-slow musuh yang kena. Boosted kepake buat nahan musuh yang mau kabur, tapi damage Crustle datang dari move.","lanes":["Top","Bottom"],"laneNote":"Top atau Bottom sebagai tank lane; Crustle paling enak di lane sempit tempat Rock Tomb bisa nutup jalan dan Stealth Rock nutup pit.","earlyGame":"Dwebble lemah: Rock Slide buat stun kecil dan bantu partner ambil wild, Fury Cutter buat last hit. Jangan solo trade, lo belum tebal. Lv4 (Crustle + Rock Tomb/Shell Smash) baru mulai berani nekan, dan Lv6 (Stealth Rock/X-Scissor) baru lengkap.","powerSpike":"Lv4 jadi Crustle dan dapat Rock Tomb/Shell Smash; Lv6 dapat X-Scissor/Stealth Rock; Lv9 Rubble Rouser bikin lo bisa engage ke tengah musuh.","slot1":{"base":{"name":"Rock Slide","level":1,"desc":"Jatuhin batu ke area, musuh yang kena stun sebentar."},"choices":[{"name":"Rock Tomb","level":4,"upgradeLevel":11,"desc":"Bikin tembok batu di area yang nge-slow musuh dan ngeblok jalan; bisa buat misahin musuh atau nutup jalur kabur.","when":"Tekan di BELAKANG musuh yang tim lo lagi kejar (dia nggak bisa mundur), atau di pintu masuk pit buat ngehalangin musuh nyuri objective.","avoid":"Jangan taruh tembok di antara tim lo dan target; tembok lo juga ngeblok teman sendiri.","upgradeNote":"Lv11: efek slow Rock Tomb makin kuat (dan durasi slow-nya baru dinaikin di patch Sep 2026)."},{"name":"Shell Smash","level":4,"upgradeLevel":11,"desc":"Tuker sebagian Defense/Sp. Def jadi Attack dan movement speed naik; Crustle jadi bruiser cepat sebentar.","when":"Tekan sebelum X-Scissor buat masuk ke carry musuh, atau buat ngejar/kabur karena speed-nya besar.","avoid":"Jangan tekan pas lo satu-satunya tank dan musuh lagi fokus ke lo; lo lagi buang pertahanan.","upgradeNote":"Lv11: rasio konversi Defense ke Attack naik (Attack bonusnya lebih besar)."}]},"slot2":{"base":{"name":"Fury Cutter","level":1,"desc":"Tebas berturut-turut; tiap tebasan beruntun damage-nya naik."},"choices":[{"name":"Stealth Rock","level":6,"upgradeLevel":13,"desc":"Lempar batu melayang ke area yang ngasih damage terus-menerus ke musuh di dalamnya.","when":"Tekan ke pit objective atau ke area yang udah lo tutup pakai Rock Tomb biar musuh kejebak di dalam damage zone.","avoid":"Jangan lempar ke satu musuh yang bebas gerak di lapangan terbuka; dia tinggal jalan keluar.","upgradeNote":"Lv13: durasi lebih lama dan ada efek slow buat musuh di dalam zona."},{"name":"X-Scissor","level":6,"upgradeLevel":13,"desc":"Dash ke depan sambil nyilangin capit, musuh yang kena didorong; kalau kedorong ke tembok (termasuk Rock Tomb) mereka stun.","when":"Tekan buat dorong carry musuh ke arah tim lo, atau dorong dia ke Rock Tomb buat stun; juga bisa buat kabur.","avoid":"Jangan dorong musuh menjauh dari tim lo (lo nyelametin dia); arah dash itu segalanya.","upgradeNote":"Lv13: cooldown X-Scissor berkurang."}]},"unite":{"name":"Rubble Rouser","level":9,"desc":"Lo dapat shield besar dan musuh di sekitar lo nggak bisa bertindak sambil kena damage bertahap; tiap lo kena damage selama efek ini, move-nya mukul tambahan.","when":"Pakai saat lo udah di tengah 2-3 musuh (habis X-Scissor/Shell Smash masuk), terutama di pit objective biar mereka nggak bisa secure.","avoid":"Jangan tekan pas nggak ada musuh di sekitar lo atau cuma kena satu tank; dan jangan nunggu HP kritis, shield-nya lebih berguna di awal engage."},"builds":[{"name":"Rock Tomb + X-Scissor — Wall Tank","moves":["Rock Tomb","X-Scissor"],"recommended":true,"style":"Tank playmaker: bikin tembok, dorong musuh ke tembok, stun, tim bunuh.","heldItems":[{"name":"Resonant Guard","why":"Shield buat lo dan sekutu sekitar; item tank standar (dittobase/game8)."},{"name":"Focus Band","why":"Heal saat HP rendah, pas banget sama Sturdy yang juga aktif di HP rendah."},{"name":"Exp. Share","why":"Lo tank lane, biarin carry lo level lebih cepat."}],"battleItem":{"name":"Eject Button","why":"Buat reposisi sebelum X-Scissor atau kabur setelah engage (dittobase); X Speed alternatif game8."},"combo":["Rock Tomb di belakang target.","X-Scissor dorong target ke tembok → stun.","Boosted attack buat slow kalau dia lolos.","Rubble Rouser kalau 2+ musuh ikut masuk."],"comboNote":"Game8 nyebut ini 'Rock Tomb → X-Scissor: wall behind opponent, shove into stun'. Latihan arah dash-nya; salah arah = nyelametin musuh."},{"name":"Rock Tomb + Stealth Rock — Zone Control","moves":["Rock Tomb","Stealth Rock"],"recommended":false,"style":"Nutup area: jebak musuh di antara tembok dan zona damage, paling kuat di pit objective.","heldItems":[{"name":"Resonant Guard","why":"Lo berdiri di depan zona, butuh shield."},{"name":"Focus Band","why":"Sustain standar tank."},{"name":"Attack Weight","why":"Nambah damage Stealth Rock seiring lo score (game8); Exp. Share juga oke."}],"battleItem":{"name":"X Speed","why":"Lo nggak punya dash di build ini; X Speed buat nyusul posisi atau kabur."},"combo":["Rock Tomb nutup jalur keluar pit.","Stealth Rock ke dalam area yang tertutup.","Boosted attack ke musuh yang mau keluar (slow).","Rubble Rouser di tengah pit saat mereka numpuk."],"comboNote":"Build ini lemah 1v1 di lapangan terbuka; nilainya ada di objective."},{"name":"Shell Smash + X-Scissor — Bruiser","moves":["Shell Smash","X-Scissor"],"recommended":false,"style":"Crustle agresif: tuker defense jadi attack, dash ke carry musuh, pukul.","heldItems":[{"name":"Attack Weight","why":"Attack numpuk tiap score; Shell Smash bikin lo cepat buat ngejar score (game8)."},{"name":"Weakness Policy","why":"Attack naik tiap lo kena damage; lo tetap sering dipukul (game8)."},{"name":"Focus Band","why":"Lo buang defense pakai Shell Smash, butuh jaring pengaman."}],"battleItem":{"name":"Eject Button","why":"Buat nyambung jarak X-Scissor atau kabur setelah Shell Smash habis."},"combo":["Shell Smash (Attack + speed naik).","X-Scissor ke carry musuh, dorong ke tembok/tim lo.","Boosted attack dan auto selama Shell Smash aktif.","Rubble Rouser kalau dikeroyok."],"comboNote":"Build ini bukan tank; kalau tim lo nggak punya tank lain, pakai build Rock Tomb."}],"situations":{"gank":"Saat nge-gank: Rock Tomb di jalur kabur target dulu, baru X-Scissor dorong dia ke tembok. Saat dikeroyok: Rubble Rouser kalau ada (shield + stun area), Rock Tomb di antara lo dan musuh, lalu jalan ke tim; Sturdy bikin lo lebih tebal makin lama.","escape":"Rock Tomb di belakang lo buat ngeblok pengejar (paling efektif di jalan sempit), X-Scissor/Shell Smash buat jarak, Eject Button kalau ada. Jangan panik di HP setengah; Sturdy justru aktif.","objective":"Rock Tomb nutup pintu pit sebelum musuh masuk, Stealth Rock ke pit, berdiri di dalam pit buat ngeblok jungler musuh. Rubble Rouser saat musuh numpuk di pit biar mereka nggak bisa secure. X-Scissor buat dorong stealer keluar.","duel":"Lawan melee/all-rounder: lo biasanya tahan; auto + boosted, Rock Tomb buat ngeblok dia kabur, tunggu Sturdy numpuk. Lawan ranged: jangan dikejar jauh; Rock Tomb di belakang dia, X-Scissor dorong ke tembok, kalau miss mundur.","teamfight":"Frontline, berdiri di antara carry lo dan musuh. Prioritas: bikin tembok yang misahin carry musuh dari tank-nya, dorong carry ke tim lo. Rubble Rouser pas 2-3 musuh nempel. Jangan Shell Smash kalau lo satu-satunya tank."},"mistakes":["Rock Tomb di antara tim sendiri dan target (ngeblok teman).","X-Scissor ke arah yang salah sehingga musuh kedorong menjauh dari tim lo.","Shell Smash saat lo lagi jadi target utama (buang defense).","Rubble Rouser pas nggak ada musuh di sekitar atau cuma kena tank.","Panik dan mundur di HP setengah padahal Sturdy baru numpuk."],"counters":{"hardFor":[{"name":"Venusaur","why":"Nguras HP lo dari jauh pakai Solar Beam dan menang trade langsung (game8).","how":"Jangan trade dari jauh; pakai Rock Tomb buat ngeblok garis Beam dan masuk lewat samping, atau biarin carry lo yang nekan."},{"name":"Garchomp","why":"Menang brawl 1v1 pakai boosted attack dan displacement-nya (game8).","how":"Jangan duel sendirian; Rock Tomb buat misahin dia dari tim-nya, fight dekat tim lo."},{"name":"Glaceon","why":"Ranged yang nguras tank pelan-pelan sambil kite (inferensi dari matchup Glaceon vs defender lain di game8).","how":"Tunggu dia maju, Rock Tomb di belakangnya, X-Scissor dorong ke tembok; kalau nggak kena, mundur."}],"goodAgainst":[{"name":"Gardevoir","why":"Ranged rapuh; Shell Smash + X-Scissor nutup jarak dan dia nggak punya escape (game8)."},{"name":"Absol","why":"Burst dealer mobile; lo tank damage-nya pakai Sturdy lalu balas pas dia nempel (game8)."},{"name":"Delphox","why":"Ranged rapuh tanpa dash; Rock Tomb di belakangnya dan dia habis (game8)."}]},"cinderace":{"similarity":1,"note":"Ini kebalikan total Cinderace: melee, pelan, dan menang bukan dari damage tapi dari tembok dan arah dorongan. Nggak ada kebiasaan Cinderace yang bisa dibawa kecuali kesadaran posisi carry musuh (itu target X-Scissor lo). Yang harus diubah: lo justru harus berdiri di depan dan dipukul, karena Sturdy bikin lo makin tebal; dan tiap move punya 'arah' yang kalau salah malah bantu musuh."},"sources":["https://serebii.net/pokemonunite/pokemon/crustle.shtml","https://bulbapedia.bulbagarden.net/wiki/Crustle_(UNITE)","https://www.dittobase.com/unite/pokemon/crustle","https://game8.co/games/Pokemon-UNITE/archives/335467","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"high","notes":"Beda antar sumber: Serebii bilang difficulty Novice, Bulbapedia/dittobase Intermediate; gw pakai Pemula. Ringkasan Serebii nyebut Shell Smash Lv11 dan X-Scissor Lv13 (itu level upgrade, bukan level dapat); Bulbapedia jelas: Rock Tomb/Shell Smash Lv4 (upgrade Lv11), Stealth Rock/X-Scissor Lv6 (upgrade Lv13). Patch terakhir 1.23.2.9 (3 Sep 2026): durasi slow Rock Tomb 2→3 detik dan energi Rubble Rouser turun (buff). Counter Glaceon adalah inferensi; counter lain dari game8.","image":"img/crustle.webp","status":"Owned"},{"name":"Trevenant","slug":"trevenant","role":"Defender","damage":"Physical","range":"Melee","difficulty":"Menengah","evolutions":"Phantump (Lv1) → Trevenant (Lv5)","tagline":"Tank pohon yang nggak mau mati: heal dari boosted attack dan passive, lalu narik/lempar musuh ke tim lo pakai Wood Hammer dan Horn Leech.","passive":{"name":"Natural Cure","desc":"Saat HP lo rendah, lo heal terus-menerus sebentar dan cooldown move lo berkurang. Ada jeda sebelum bisa aktif lagi, tapi jedanya dipotong tiap move lo kena musuh; jadi tetap mukul saat sekarat."},"basicAttack":"Basic attack melee; tiap serangan ketiga jadi boosted yang damage lebih besar dan heal lo saat kena. Di Trevenant, auto itu bagian dari sustain, bukan cuma pengisi waktu.","lanes":["Top","Bottom"],"laneNote":"Top atau Bottom sebagai tank lane; Trevenant kuat di lane karena Branch Poke/Will-O-Wisp poke lumayan dan dia susah dibunuh.","earlyGame":"Phantump cukup kuat buat trade: Will-O-Wisp poke dari jauh, Branch Poke buat slow + heal. Bantu partner ambil wild, trade saat HP partner lo lebih tinggi dari lawan. Lv5 (Trevenant + Wood Hammer/Curse) lo udah bisa nekan.","powerSpike":"Lv5 jadi Trevenant dan dapat Wood Hammer/Curse (CC beneran); Lv7 dapat Horn Leech/Pain Split (sustain + engage); Lv9 Phantom Forest buat lempar kerumunan.","slot1":{"base":{"name":"Will-O-Wisp","level":1,"desc":"Tembak api ke depan: damage dan burn."},"choices":[{"name":"Wood Hammer","level":5,"upgradeLevel":11,"desc":"Tarik musuh ke lo dan stun mereka (makin rendah HP lo, makin lama stun-nya); kalau kena, bisa tekan lagi buat hantaman lanjutan. Move ini makan HP lo sendiri.","when":"Tekan ke carry musuh yang terlalu maju buat narik dia ke tim lo, atau buat stun kerumunan di pit.","avoid":"Jangan tekan pas HP lo udah tipis banget dan nggak ada heal; move ini ngurangin HP lo sendiri.","upgradeNote":"Lv11: musuh yang kena damage output-nya turun sebentar."},{"name":"Curse","level":5,"upgradeLevel":11,"desc":"Bikin zona kutukan yang damage bertahap dan slow; tahan tombol buat ngisi 'kekuatan kutukan', dan kalau dilepas di maksimum, cooldown move lo di-reset.","when":"Tekan dari jauh ke area yang musuh harus lewati (pit, jalur mundur), lalu lepas pas penuh buat reset Horn Leech.","avoid":"Jangan lepas kutukan sebelum penuh kalau lo butuh reset cooldown; dan jangan taruh zona di tempat musuh nggak akan masuk.","upgradeNote":"Lv11: efek slow Curse lebih kuat."}]},"slot2":{"base":{"name":"Branch Poke","level":1,"desc":"Tusuk ke depan: slow musuh dan heal lo."},"choices":[{"name":"Horn Leech","level":7,"upgradeLevel":13,"desc":"Dash ke depan sambil dorong musuh dan heal; heal-nya lebih besar saat HP lo rendah.","when":"Tekan buat engage (dorong carry musuh ke tim lo), buat kabur, atau pas HP lo rendah buat heal besar.","avoid":"Jangan dash sembarangan ke tengah tim musuh tanpa Wood Hammer/Unite siap; ini mobilitas dan heal lo sekaligus.","upgradeNote":"Lv13: movement speed lo naik setelah move kena."},{"name":"Pain Split","level":7,"upgradeLevel":13,"desc":"Kaitkan diri ke satu musuh: sebagian damage yang lo terima dialihkan ke dia selama terhubung.","when":"Tekan ke carry musuh yang bakal fokus ke lo, atau ke tank mereka sebelum lo nerima burst; lo jadi 'cermin' damage.","avoid":"Jangan tekan ke musuh yang mau kabur jauh (link putus) atau pas nggak ada yang nyerang lo.","upgradeNote":"Lv13: durasi link lebih lama."}]},"unite":{"name":"Phantom Forest","level":9,"desc":"Bikin hutan kutukan di area: musuh di dalamnya kena damage, dilempar, dan di-slow; lo dapat shield dan speed.","when":"Pakai buat engage ke kerumunan di pit (lempar mereka keluar dari objective) atau buat nutup musuh yang kabur.","avoid":"Jangan buang ke satu musuh atau pas tim lo jauh; lemparannya singkat dan tanpa follow-up mereka balik lagi."},"builds":[{"name":"Wood Hammer + Horn Leech — CC Tank","moves":["Wood Hammer","Horn Leech"],"recommended":true,"style":"Tank playmaker: dash dorong, tarik dan stun, tim lo ngebunuh; lo heal lewat Horn Leech dan boosted.","heldItems":[{"name":"Focus Band","why":"Sustain di HP rendah, numpuk sama Natural Cure dan Horn Leech."},{"name":"Resonant Guard","why":"Shield buat lo dan sekutu pas engage (dittobase); Aeos Cookie alternatif game8."},{"name":"Attack Weight","why":"Attack numpuk tiap score, bikin Wood Hammer/Horn Leech ngancem (game8); Exp. Share kalau mau full tank (dittobase)."}],"battleItem":{"name":"Eject Button","why":"Reposisi sebelum Wood Hammer atau kabur setelah engage (semua sumber)."},"combo":["Horn Leech masuk, dorong carry musuh ke arah tim lo.","Wood Hammer tarik + stun, tekan lagi buat hantaman lanjutan.","Auto 3x (boosted heal).","Horn Leech lagi buat dorong lebih jauh atau keluar."],"comboNote":"Game8 nyebut ini 'Push and Smash'. Makin rendah HP lo, makin lama stun Wood Hammer, jadi jangan buru-buru mundur."},{"name":"Curse + Horn Leech — Spam Leech","moves":["Curse","Horn Leech"],"recommended":false,"style":"Bruiser tebal: Curse buat slow dan reset cooldown, Horn Leech berkali-kali buat heal dan dorong.","heldItems":[{"name":"Focus Band","why":"Sustain standar."},{"name":"Attack Weight","why":"Damage Horn Leech/Curse naik seiring score (game8)."},{"name":"Weakness Policy","why":"Attack naik tiap lo kena damage; lo bakal sering kena (game8). Big Root/Curse Bangle alternatif dittobase."}],"battleItem":{"name":"X Speed","why":"Nyusul target dan muter di zona Curse (game8/dittobase)."},"combo":["Curse dari jauh ke area musuh (tahan tombol).","Horn Leech masuk.","Auto 3x buat boosted heal.","Lepas Curse di maksimum → Horn Leech reset, dash lagi."],"comboNote":"Game8 nyebut 'Curse Sustain Combo'. Build ini lebih sakit tapi CC-nya cuma slow, jadi butuh tank lain yang punya stun."},{"name":"Curse + Pain Split — Mirror Tank","moves":["Curse","Pain Split"],"recommended":false,"style":"Full tank yang mantulin damage: link ke musuh yang nyerang lo, berdiri di zona Curse.","heldItems":[{"name":"Focus Band","why":"Lo bakal nerima banyak damage; Focus Band jaring pengaman."},{"name":"Aeos Cookie","why":"HP maksimal naik tiap score; Pain Split lebih kuat kalau HP lo besar (game8)."},{"name":"Resonant Guard","why":"Shield buat lo dan sekutu; Muscle Band alternatif game8."}],"battleItem":{"name":"Potion","why":"Heal cepat buat nahan burst selama link aktif (game8)."},"combo":["Curse ke area fight.","Pain Split ke carry musuh yang fokus ke lo.","Auto 3x buat boosted heal.","Lepas Curse penuh buat reset Pain Split, link lagi."],"comboNote":"Build ini nggak punya dash; jalan bareng tim dan simpan Eject/Potion."}],"situations":{"gank":"Saat nge-gank: Horn Leech dari samping dorong target ke tim lo, Wood Hammer tarik + stun. Saat dikeroyok: Phantom Forest kalau ada (lempar + shield), Wood Hammer stun yang paling dekat, Horn Leech keluar; ingat Natural Cure aktif di HP rendah, jadi tetap mukul.","escape":"Horn Leech arah tim (dash + heal besar saat HP rendah), Branch Poke/Curse buat slow pengejar, Eject Button. Jangan berhenti auto; boosted dan move yang kena musuh ngisi heal lo.","objective":"Berdiri di pit, Curse di pit kalau pakai (slow stealer), Wood Hammer tarik jungler musuh yang mau nyuri lalu stun. Phantom Forest buat lempar musuh keluar pit tepat sebelum objective mati. Horn Leech buat dorong stealer menjauh dari boss.","duel":"Lawan melee/all-rounder: lo biasanya menang trade panjang; auto + boosted, Wood Hammer stun pas HP lo udah turun (stun lebih lama), Horn Leech heal. Lawan ranged kiting: jangan dikejar jauh; Horn Leech cuma kalau yakin kena, kalau nggak tahan di goal.","teamfight":"Frontline. Prioritas: tarik carry musuh ke tim lo pakai Wood Hammer, atau dorong dia pakai Horn Leech; Phantom Forest ke kerumunan di awal fight. Jangan takut HP rendah; itu saat lo paling berbahaya (stun lebih lama, Natural Cure aktif)."},"mistakes":["Wood Hammer pas HP udah kritis tanpa heal (move-nya ngurangin HP lo).","Mundur kepagian di HP rendah padahal Natural Cure dan stun panjang baru aktif.","Horn Leech dorong musuh menjauh dari tim lo.","Lepas Curse sebelum penuh (nggak dapat reset cooldown).","Phantom Forest ke satu target atau pas tim nggak bisa follow-up."],"counters":{"hardFor":[{"name":"Glaceon","why":"Icicle Spear/Icy Wind nguras HP lo dari jauh sambil kite (game8).","how":"Jangan dikejar jauh; Wood Hammer cuma kalau dia maju ke jangkauan, selebihnya biarin carry lo yang trade."},{"name":"Inteleon","why":"Crit damage tinggi dari jauh dan dia kite terus (game8).","how":"Jalan lewat grass, Horn Leech dorong dia ke tim lo saat dia maju; jangan solo."},{"name":"Mega Mewtwo Y","why":"Jaga jarak dan teleport ngehindar dari tarikan lo (game8).","how":"Fokus peel buat carry lo, jangan buang Wood Hammer ke dia."}],"goodAgainst":[{"name":"Decidueye","why":"Ranged rapuh tanpa escape; Wood Hammer tarik, dia habis (game8: 'ranged fragile Pokémon')."},{"name":"Machamp","why":"All-rounder melee; Horn Leech dan Wood Hammer ganggu combo-nya dan lo menang sustain (game8: 'all-rounders')."},{"name":"Comfey","why":"Suporter tanpa ancaman; tarik dia pakai Wood Hammer dan tim lo bunuh (game8: 'supporters')."}]},"cinderace":{"similarity":1,"note":"Nyaris nggak ada yang mirip: melee, pelan, dan menang dari sustain plus CC. Yang kebawa dari Cinderace cuma kebiasaan auto terus (di Trevenant boosted = heal) dan kesadaran siapa carry musuh (target Wood Hammer). Yang harus diubah total: insting kabur di HP rendah; Trevenant justru paling kuat saat sekarat."},"sources":["https://serebii.net/pokemonunite/pokemon/trevenant.shtml","https://bulbapedia.bulbagarden.net/wiki/Trevenant_(UNITE)","https://www.dittobase.com/unite/pokemon/trevenant","https://game8.co/games/Pokemon-UNITE/archives/354161","https://www.serebii.net/pokemonunite/patch.shtml"],"confidence":"high","notes":"Level cocok semua sumber: Wood Hammer/Curse Lv5 (upgrade Lv11), Horn Leech/Pain Split Lv7 (upgrade Lv13), Unite Lv9. Patch: 1.17.2.10 (Feb 2025) Pain Split buff; 1.18.2.6 (Apr 2025) Wood Hammer dan Curse damage turun, Horn Leech throw dipendekkan; 1.20.1.2 (Sep 2025) Curse slow naik, Pain Split damage naik, Horn Leech heal naik. Tidak ada perubahan 2026. Beda build: dittobase rekomendasi Branch Poke dipertahankan (Wood Hammer + Branch Poke, Curse + Branch Poke) sebagai 'Path Tank', game8 pakai Horn Leech; gw pakai Horn Leech karena dua sumber (game8, Serebii) jelasin mekaniknya dan dittobase menyebut Branch Poke tanpa penjelasan (bisa jadi data tidak lengkap). Counter dari game8.","image":"img/trevenant.webp","status":"Owned"},{"name":"Umbreon","slug":"umbreon","role":"Defender","damage":"Physical","range":"Melee","difficulty":"Pemula","evolutions":"Eevee (Lv1) → Umbreon (Lv4)","tagline":"Tank anti-CC yang ngunci satu target, ngelemahin musuh, dan jagain carry pakai heal.","passive":{"name":"Inner Focus","desc":"Pas lo mau kena lempar, dorong, atau stun, efeknya dibatalkan dan lo jadi kebal hindrance sebentar plus Def/Sp. Def naik. Ada cooldown, jadi gak tiap saat. (Sebagai Eevee namanya Anticipation, cuma negate hindrance.)"},"basicAttack":"Melee biasa. Tiap serangan ketiga jadi boosted: lo nerjang ke depan, damage, dan heal HP berdasarkan HP lo yang hilang (makin sekarat makin gede heal-nya).","lanes":["Top","Bottom"],"laneNote":"Bottom bareng attacker yang butuh dilindungi paling pas (Wish buat heal mereka). Top juga oke buat body block di Regieleki.","earlyGame":"Lv1 ambil Swift (poke + mark) dan Fake Tears (shield + turunin Def musuh). Lo evolve cepat di Lv4, jadi farm 2-3 wild dulu lalu mulai contest. Nempel carry lo, Fake Tears pas musuh deket biar partner lo ngehajar lebih sakit.","powerSpike":"Lv4 (evolve + Mean Look/Foul Play) lo udah bisa ngunci target buat partner. Lv6 dapet Wish/Snarl, Lv8 Unite Moonlight Prance buat stun area dan nyedot shield musuh.","slot1":{"base":{"name":"Swift","level":1,"desc":"Tembak bintang ke depan, damage dan ngasih mark; lo lebih cepat ke arah musuh yang di-mark dan basic attack berikutnya jadi boosted."},"choices":[{"name":"Mean Look","level":4,"upgradeLevel":10,"desc":"Tatap satu musuh, dia dikurung di zona hitam yang gak bisa dia tinggalkan. Selama di dalam, basic attack lo jadi boosted dan damage ke dia naik.","when":"Tekan ke carry musuh yang kelewat maju atau ke musuh yang mau kabur dari gank. Pasti ada teman lo yang siap ngehajar, karena lo sendiri damage-nya kecil.","avoid":"Jangan Mean Look ke tank atau pas teman lo gak ada, lo cuma ngurung diri sendiri bareng musuh.","upgradeNote":"Lv10 efek kurungannya lebih kuat (durasi/damage naik)."},{"name":"Foul Play","level":4,"upgradeLevel":10,"desc":"Nerjang ke depan, damage + slow. Kalau kena, bisa ditekan lagi buat sapuan ekor yang damage-nya nambah dan ngedorong musuh. Damage-nya ngikut stat Attack musuh.","when":"Tekan buat engage atau kejar musuh melee yang Attack-nya tinggi (Zacian, Buzzwole), karena damage-nya ikut naik.","avoid":"Jangan dipakai buat kabur ke arah kosong, dash-nya pendek dan dua tahap itu kebuang.","upgradeNote":"Lv10 damage/slow-nya naik. Catatan: patch April 2026 nurunin damage Foul Play."}]},"slot2":{"base":{"name":"Fake Tears","level":1,"desc":"Pura-pura nangis: musuh di dekat kena damage dan Def/Sp. Def-nya turun, lo dapat shield."},"choices":[{"name":"Wish","level":6,"upgradeLevel":12,"desc":"Pilih satu teman: dia nerima damage lebih kecil sebentar, lalu HP-nya dipulihkan.","when":"Tekan ke carry lo tepat SEBELUM atau pas dia di-dive, bukan setelah dia sekarat. Bisa ke diri sendiri kalau gak ada teman.","avoid":"Jangan di-spam ke teman yang HP-nya penuh atau yang lagi aman di belakang.","upgradeNote":"Lv12 heal/pengurangan damage lebih besar."},{"name":"Snarl","level":6,"upgradeLevel":12,"desc":"Teriak ke area: damage berulang, Attack/Sp. Atk/speed musuh turun, lalu teriakan terakhir bikin musuh di area gak bisa gerak.","when":"Tekan pas 2-3 musuh ngumpul (pit objective, teamfight), biar damage mereka turun dan stun terakhirnya kena rame-rame.","avoid":"Jangan tekan dari jauh ke satu musuh, areanya kecil dan lo kehilangan debuff buat teamfight.","upgradeNote":"Lv12 debuff dan durasi stun terakhirnya naik."}]},"unite":{"name":"Moonlight Prance","level":8,"desc":"Di luar combat HP lo pulih terus. Pas ditekan: lo lompat, nyedot shield musuh di area, mendarat ngasih damage dan bikin musuh gak bisa gerak. Setelahnya shield yang mereka dapat juga ikut kesedot ke lo.","when":"Pakai pas musuh ngumpul dan baru pakai Unite/shield (Buddy Barrier, Blissey, dkk), lo makan shield-nya dan stun area sekaligus.","avoid":"Jangan lompat ke 1 musuh di tempat kosong, ini stun area buat teamfight."},"builds":[{"name":"Mean Look + Wish — Bodyguard Carry","moves":["Mean Look","Wish"],"recommended":true,"style":"Nempel carry lo terus: kurung musuh yang nekat maju, Wish carry pas dia kena fokus.","heldItems":[{"name":"Resonant Guard","why":"Shield buat lo dan carry di dekat, cocok sama gaya nempel."},{"name":"Buddy Barrier","why":"Shield pas Unite ke diri sendiri dan teman terdekat."},{"name":"Focus Band","why":"Heal pas kritis, bikin lo bisa stay di depan."}],"battleItem":{"name":"Eject Button","why":"Buat nyusul target Mean Look atau kabur setelah ngurung musuh."},"combo":["Fake Tears/Swift buat dekat, Mean Look ke carry musuh yang maju.","Basic attack boosted ke dia sambil teman lo ngehajar.","Wish ke carry lo begitu dia mulai kena fokus, Moonlight Prance kalau musuh ngumpul."],"comboNote":""},{"name":"Foul Play + Snarl — Disruptor","moves":["Foul Play","Snarl"],"recommended":false,"style":"Lebih agresif: engage pakai Foul Play, debuff rame-rame pakai Snarl, cocok lawan tim yang banyak melee.","heldItems":[{"name":"Resonant Guard","why":"Shield area pas lo masuk duluan."},{"name":"Buddy Barrier","why":"Shield tambahan pas Unite."},{"name":"Attack Weight","why":"Nambah Attack tiap score, bikin Foul Play dan basic attack lo lebih kerasa."}],"battleItem":{"name":"Eject Button","why":"Reposisi setelah Snarl, atau buat ngejar target Foul Play."},"combo":["Foul Play ke musuh, tekan lagi buat sapuan ekor dan dorong.","Snarl pas musuh ngumpul, tunggu teriakan terakhir buat stun.","Moonlight Prance kalau mereka pakai shield, Fake Tears buat shield diri."],"comboNote":"Dittobase juga list Mean Look + Snarl dan Foul Play + Wish sebagai kombinasi yang jalan."}],"situations":{"gank":"Nge-gank: Mean Look/Foul Play ke target yang mau kabur, biar teman lo yang ngabisin. Dikeroyok: Fake Tears buat shield, Inner Focus bakal ngebatalin satu CC, mundur sambil basic attack boosted (heal makin gede pas HP rendah).","escape":"Umbreon gak punya dash kabur yang bagus. Andelin Inner Focus (satu CC dibatalin), Fake Tears shield, Eject Button, dan heal boosted attack. Mean Look ke musuh yang ngejar justru bikin lo gak bisa lari, hati-hati.","objective":"Di Rayquaza/Regieleki, berdiri di antara musuh dan carry. Simpan Mean Look buat jungler musuh yang mau steal, Snarl pas mereka ngumpul di pit. Moonlight Prance sedot shield Buddy Barrier mereka.","duel":"1v1 lo jarang bisa bunuh, tapi hampir gak bisa dibunuh. Fake Tears terus, basic attack, jangan ngejar. Lawan melee ber-Attack tinggi, Foul Play malah sakit.","teamfight":"Posisi di depan carry, muka ke musuh. Prioritas: kurung/debuff carry musuh yang masuk, Wish ke carry lo pas dia difokus, Moonlight Prance pas musuh ngumpul dan punya shield."},"mistakes":["Mean Look ke tank atau pas teman gak ada, lo malah ngurung diri sendiri.","Wish ditekan telat (teman udah mati) atau ke teman yang HP full.","Nyoba jadi damage dealer; damage lo kecil, nilai lo di CC, debuff, dan body.","Lupa kalau Inner Focus ada cooldown, lo gak selalu kebal CC."],"counters":{"hardFor":[{"name":"Delphox","why":"Ranged dengan damage berkala dan slow dari jauh, lo gak pernah nyampe buat Mean Look.","how":"Tunggu dia maju buat ngejar, atau pakai Foul Play buat tutup jarak pas dia salah posisi."},{"name":"Mewtwo Y","why":"Burst special gede dan mobile, debuff Attack Snarl gak banyak ngurangin, dan dia bisa teleport keluar zona Mean Look timing.","how":"Simpan Mean Look buat momen setelah dia pakai mobility-nya; nempel carry lo biar dia gak bisa one-shot."},{"name":"Blissey","why":"Safeguard dan heal-nya bikin CC lo ke carry mereka gak jalan dan debuff Snarl keburu diilangin.","how":"Moonlight Prance buat nyedot shield yang dia kasih, lalu baru Mean Look."}],"goodAgainst":[{"name":"Zacian","why":"Foul Play ngambil damage dari Attack-nya yang tinggi, dan Inner Focus negate CC dia; Mean Look ngunci dia buat tim lo."},{"name":"Scizor","why":"Melee physical yang harus nempel; Fake Tears turunin Def-nya dan Mean Look ngunci dia yang andelin dash."},{"name":"Absol","why":"Burst assassin yang bergantung CC/dash; Inner Focus batalin, dan lo tank-nya sementara teman ngabisin."}]},"cinderace":{"similarity":1,"note":"Hampir gak ada yang mirip: melee, lambat, damage kecil, kerjaannya ngelindungin orang kayak lo waktu main Cinderace. Yang bisa dibawa cuma kesadaran 'carry berdiri di mana', karena sekarang lo yang harus nempelin mereka. Ubah kebiasaan kiting jadi kebiasaan body block, dan tekan Wish sebelum teman sekarat, bukan setelah."},"sources":["https://serebii.net/pokemonunite/pokemon/umbreon.shtml","https://bulbapedia.bulbagarden.net/wiki/Umbreon_(UNITE)","https://www.dittobase.com/unite/pokemon/umbreon","https://www.serebii.net/pokemonunite/patch.shtml","https://www.gfinityesports.com/article/tier-list-best-pokemon"],"confidence":"high","notes":"Level move konsisten (Mean Look/Foul Play Lv4 → Lv10, Wish/Snarl Lv6 → Lv12, Unite Lv8). Patch 1.21.1.5 (April 2026) buff Def/Sp. Def tapi nerf damage Foul Play dan Moonlight Prance cuma nyedot 50% shield (sebelumnya 100%). Tier list Oktober 2026 masih naruh Umbreon di tier atas. Counter adalah inferensi dari mekanik (game8 gak bisa diakses).","image":"img/umbreon.webp","status":"Owned"}];
window.UNITE_VERSION="2026-10-03";
